          return {
            "I'm Iola. I was Velthe's last apprentice.",
            "Diegues, if he's with you, knows my name.",
          }
        end
      end,
      scene = function()
        local lead = party[active] and party[active].class
        if lead == "mage" and count_shards and count_shards() >= 3 and not flag.iolas_letter_received then
          if start_academy_iolas_letter_scene then  -- Task 3.7 will define this
            return start_academy_iolas_letter_scene()
          end
        end
      end,
    },
    -- Master Theron — Academy headmaster (new character)
    {
      x = 5, y = 2, name = "Theron", kind = "npc",
      -- Hide during scripted scenes: choir/intro/epilogue stage actors
      -- in the lecture hall and he otherwise stands frozen in frame
      -- (choir-Diegues at (5,2) would stack directly on him).
      visible = function() return not (SCENE and SCENE.active) end,
      dialogue = function()
        local lead = party[active] and party[active].class
        if lead == "mage" then
          return {
            "(he peers at your notation)",
            "That's a Velthe hand. I taught you to write",
            "like that. I take it the cave was kind.",
          }
        elseif lead == "cleric" then
          return {
            "Princess. The Academy stands with Lirael.",
            "What's left of it. (he bows formally)",
          }
        else
          return {
            "Welcome to the Sage Circle's Academy.",
            "Quiet voices, slow questions.",
          }
        end
      end,
      -- The Threefold attunement: Paj (mathwiz lead) attunes here, where the
      -- Academy keeps the lore of the three sisters.
      scene = function()
        local lead = party[active] and party[active].class
        if lead == "mathwiz" and CONTENT.resonances and CONTENT.resonances.threefold
           and not CONTENT.resonances.threefold.attuned
           and build_resonance_attunement_script then
          CONTENT.resonances.threefold.item = true
          return build_resonance_attunement_script("threefold")
        end
      end,
    },
    -- Aurin — junior scholar (from bible stub)
