      visible = function() return not (SCENE and SCENE.active) end,
      dialogue = function()
        local lead = party[active] and party[active].class
        if lead == "bard" then
          return {
            "Are you a bard? A real one? I'm writing a",
            "treatise on troupe music — would you sit",
            "for two questions?",
