-- Global jam controls (root-note transposition in semitones; bpm offset).
-- Adjusted via dpad while in JAM mode; persisted in save.
-- Build a 25-note scale array from a list of semitone intervals (one octave),
-- starting at MIDI base (A1 = 33).
local function build_scale(intervals)
  local out = {}
  local base = 33  -- A1
  local oct = 0
  while #out < 25 do
    for _, semi in ipairs(intervals) do
      out[#out + 1] = base + semi + oct * 12
      if #out >= 25 then break end
    end
    oct = oct + 1
  end
  return out
end

local JAM = {
  root = 0,                 -- semitones (-12 .. +12)
  mode = "pentatonic",       -- which scale is active
  note_names = {"A","A#","B","C","C#","D","D#","E","F","F#","G","G#"},
  -- Scales in A. Pentatonic is the always-available default; modes unlock
  -- as their shards are collected (lydian → Cave 1 boss, etc.).
  scales = {
    pentatonic = build_scale({0, 3, 5, 7, 10}),
    lydian     = build_scale({0, 2, 4, 6, 7, 9, 11}),
    dorian     = build_scale({0, 2, 3, 5, 7, 9, 10}),
    mixolydian = build_scale({0, 2, 4, 5, 7, 9, 10}),
    phrygian   = build_scale({0, 1, 3, 5, 7, 8, 10}),
    aeolian    = build_scale({0, 2, 3, 5, 7, 8, 10}),
    locrian    = build_scale({0, 1, 3, 5, 6, 8, 10}),
    ionian     = build_scale({0, 2, 4, 5, 7, 9, 11}),
  },
  -- Display order for cycling (only entries whose shard is held are picked).
  mode_order = {"pentatonic", "lydian", "dorian", "mixolydian", "phrygian",
                "aeolian", "locrian", "ionian"},
}

-- Current SCALE used by every fire_*_voice — looks up the active mode.
local function active_scale()
  return JAM.scales[JAM.mode] or JAM.scales.pentatonic
end

-- Snap an absolute MIDI note to the nearest pitch of the sounding scale
-- (JAM.mode transposed by JAM.root), preserving register — enemy attack
-- signatures, the encounter sting, item chimes, and Resonance signatures
-- were authored as fixed A-pentatonic notes and went dissonant the moment
-- the player selected another mode or shifted the jam root. Ties resolve
-- downward. Deliberately-sour sounds (denial chords, Sergei's Bb, Mira's
-- C#, ECHO's chromatic Disperse, act-3 detune) do NOT route through this.
function snap_note_to_scale(note)
  local sc = active_scale()
  local root = JAM.root or 0
  local pcs = {}
  for _, v in ipairs(sc) do pcs[(v + root) % 12] = true end
  local best, bestd = note, 99
  for pc in pairs(pcs) do
    local base = note - ((note - pc) % 12)   -- candidate at/below note
    local up = base + 12
    local d = note - base
    if d < bestd or (d == bestd and base < best) then best, bestd = base, d end
    d = up - note
    if d < bestd or (d == bestd and up < best) then best, bestd = up, d end
  end
  return best
end

-- Audible feedback when the mode changes in JAM: strum degrees 1-3-5
-- of the NEW scale on the active voice. Without this, cycling modes
-- was inaudible in JAM (MIDI notes are deliberately chromatic
-- passthrough, and the zone theme only follows the mode after exit —
-- or never, in scale-locked zones like the castle raid).
function jam_audition_scale()
  local sc = JAM.scales[JAM.mode] or JAM.scales.pentatonic
  local p = party and party[active]
  local voice = (p and p.class) or "cleric"
  -- Recruits alias to their engine voice family (same mapping the
  -- battle layer uses) so auditioning as Sergei/Paj/Niko plays their
  -- own timbre, not Miel's.
  voice = (voice == "engineer" and "mage")
       or (voice == "mathwiz"  and "bard")
       or (voice == "drummer"  and "warrior")
       or voice
  if voice ~= "warrior" and voice ~= "cleric" and voice ~= "bard"
     and voice ~= "mage" and voice ~= "wraith" then
    voice = "cleric"
  end
  clock.run(function()
    for k, deg in ipairs({1, 3, 5}) do
      local v = sc[deg]
      if v then
        sq_trig(voice, midi_to_freq(v + (JAM.root or 0)),
                0.45, 0.005, 0.8, 0.35)
      end
      clock.sleep(0.09)
    end
  end)
end

