-- Cave 5 (Snowgaunt) interior NPCs. A frostbitten singer trapped by the cold.
CONTENT.cave5_npcs = {
  { x = 2, y = 8, name = "Wenna",
    dialogue = function()
      if cave_state[5].cleared then
        return with_shard_react("Wenna", {
          "Oh -- the cold's gone. Just regular cold. Plain, kind cold.",
