local npcs = MAINLAND_NPCS  -- active NPC list (mutable; swaps on travel_to)

-- ============================================================ HELPERS

-- Global (was local) so NPC dialogue functions defined EARLIER in the
-- file can call midi_to_freq without falling through to a nil global
-- lookup. e.g. Anvel's anvil-ring SFX (village smith NPC) fires
-- sq_trig(..., midi_to_freq(72), ...) and the local midi_to_freq
-- isn't yet in lexical scope at the NPC's definition point.
function midi_to_freq(n)
  return 440 * 2 ^ ((n - 69) / 12)
end

-- Per-voice octave-shifted trig. SQ_VOICE_OCT is a global table populated
-- by the per-voice octave params (see init's PARAMS section). All voice
-- triggers route through here so combat, music tables, MIDI, inn-rest
-- chords, and tile sounds all pick up the shift.
-- Convert a frequency to nearest MIDI note (A4=440Hz=69). Used by
-- the MIDI-out hook below; freq comes in as the actual playback freq.
local function sq_freq_to_midi(freq)
  if not freq or freq <= 0 then return 60 end
  return math.max(0, math.min(127, math.floor(69 + 12 * math.log(freq / 440) / math.log(2) + 0.5)))
end

-- Per-class MIDI channel mapping. 1-based; user can override via PARAMS.
-- Default: each voice gets its own channel so external gear can route
-- e.g. cleric-only to a pad synth, warrior-only to a bass.
SQ_MIDI_CHANNEL = {warrior = 1, cleric = 2, mage = 3, bard = 4, wraith = 5}

function sq_trig(class, freq, vel, attack, release, ...)
  local oct = (SQ_VOICE_OCT and SQ_VOICE_OCT[class]) or 0
  local out_freq = freq * (2 ^ oct)
  -- MIDI-out hook: when CONTENT.midi_out_enabled is true and the
  -- midi_out connection has been opened, emit a note_on with a short
  -- scheduled note_off. Velocity scaled from 0..1 to 1..127. Channel
  -- comes from SQ_MIDI_CHANNEL[class] (defaults to 1 for unknown).
  if midi_out and CONTENT.midi_out_enabled then
    local note = sq_freq_to_midi(out_freq)
    local mvel = math.max(1, math.min(127, math.floor((vel or 0.5) * 127)))
    local ch = SQ_MIDI_CHANNEL[class] or 1
    -- pcall so a closed/disconnected port doesn't crash the clock thread
    pcall(function() midi_out:note_on(note, mvel, ch) end)
    -- Schedule a note_off after the release tail so external gear
    -- doesn't stick. clock.run yields cleanly inside the engine tick.
    clock.run(function()
      clock.sleep(math.max(0.05, (release or 0.2) + (attack or 0.01) + 0.1))
      pcall(function() if midi_out then midi_out:note_off(note, 0, ch) end end)
    end)
  end
  -- Guard the engine lookup: an unknown class (unaliased recruit) or a
  -- not-yet-registered command (wraith voice before SYSTEM > RESTART)
  -- would otherwise call nil INSIDE the music/battle clock coroutine
  -- and kill it — hard freeze. Silence beats death.
  local fn = engine["trig_" .. class]
  if not fn then return end
  return fn(out_freq, vel, attack, release, ...)
end

local function tile_at(tx, ty)
  if tx < 1 or tx > MAP_W or ty < 1 or ty > MAP_H then return 1 end
  return map[ty][tx]
end

local function is_walkable(tx, ty)
  local t = tile_at(tx, ty)
  -- 0 grass/floor, 2 path, 5 door, 23 rug (interior), 45 pier (over water),
  -- 47 region-transition door, 48 tapestry door (castle escape),
  -- 49 cave mouth (escape cave exit), 50 academy entry (Western Region).
  return t == 0 or t == 2 or t == 5 or t == 23 or t == 45
      or t == 47 or t == 48 or t == 49 or t == 50
      or t == 51   -- Lirael Ruins arch (Western Region → map 23)
      or t == 52   -- Velthe's Observatory door (Northern Wilds → map 24)
      or t == 56   -- Far Hills cave-mouth (mainland → map 26)
      or t == 58   -- Castle interior door (throne hall ↔ hallway ↔ rooms)
      or t == 60   -- wood_dock (walkable; planks over water)
      or t == 62   -- bandstand (walkable; raised platform — legend always
                   -- said walkable but it was never added; Coral stood
                   -- on it unreachable, same bug class as tile 60)
      or t == 65   -- Sunward Coast signpost (MAINLAND east coast ↔ Sunward Coast Town)
      or t == 68   -- Phrygian Night City prayer alcove (walkable; archway interior)
      or t == 69   -- Phrygian Night City desert sand path (walkable; lighter sand)
      or t == 71   -- Phrygian City entry waypost (EASTERN_REACHES → Phrygian Night City)
      or t == 74   -- Sage Hub desk_with_papers (walkable interactable; Velthe's desk)
      or t == 77   -- Sage Hub crypt_stair (walkable; lock enforced in routing handler)
      or t == 78   -- academy_entry (walkable; Western Region → Academy expanded interior)
      or t == 79   -- observatory_entry (walkable; Northern Wilds → Observatory expanded interior)
      or t == 80   -- ash (walkable; ash-covered ground)
      or t == 86   -- child_toy (walkable; Lirael blue paint memento)
      or t == 88   -- cathedral_door (walkable threshold)
      or t == 89   -- lirael_entry (walkable; gate enforced in routing handler)
      or t == 92   -- drumhall door (Phrygian 36 <-> Ruined Drum-Hall 37)
      or t == 103  -- flowers_walk (walkable; sparse blossoms on open grass)
      or t == 110  -- bridge_h (walkable; plank bridge over water)
      or t == 113  -- cottage (walkable; stepping onto it enters via CONTENT.HOUSES)
end

-- True when an NPC is currently rendered + interactable. NPCs may have
-- a `visible` function that returns false to hide them (e.g. story-gated
-- antagonists who only show up after a specific milestone).
local function npc_visible(n)
  return (type(n.visible) ~= "function") or n.visible()
end

local function npc_at(tx, ty)
  for _, n in ipairs(npcs) do
    if n.x == tx and n.y == ty and npc_visible(n) then return n end
  end
  return nil
end

local function alive_party()
  local out = {}
  for i, p in ipairs(party) do if p.alive then table.insert(out, i) end end
  return out
end

-- Global (not local): an NPC scene closure inside the CONTENT literal
-- (Iola, ~line 3004) references count_shards before this point in source
-- order. A local would bind there as a nil global; promoting it to a true
-- global lets that early closure resolve it at call time.
function count_shards()
  local n = 0
  for _, has in pairs(shards) do if has then n = n + 1 end end
  return n
end

-- forward-decl so obtain_shard can auto-save when a shard is gained
local save_game

local function obtain_shard(name)
  if shards[name] then return end
  shards[name] = true
  last_obtained_shard = name
  -- Mode-specific 4-note "shard sting": play a quick chord/arpeggio in
  -- the mode's scale to musically announce which shard you just earned.
  local sc = JAM.scales[name] or JAM.scales.pentatonic
  local idxs = {1, 3, 5, 8}
  for k, idx in ipairs(idxs) do
    local pitch = (sc[idx] or 60) + (JAM.root or 0)
    local f = midi_to_freq(pitch)
    clock.run(function()
      clock.sleep((k - 1) * 0.08)
      local _crm = CONTENT.combat_reverb_mix or 1.0
      sq_trig("mage", f, 0.65, 0.005, 0.8, math.min(1, 0.7 * _crm))
      sq_trig("bard", f * 2, 0.5, 0.003, 0.5, math.min(1, 0.6 * _crm))
    end)
  end
  -- Visual punch: a particle burst at center-screen + screen shake +
  -- bright wash. Reads as "the chord just gained a note." Scales the
  -- count by total shards owned (more shards → bigger ring).
  local n = 0; for _, v in pairs(shards) do if v then n = n + 1 end end
  ANIM.burst(64, 32, 8 + n, 15)
  ANIM.burst(64, 32, 6 + n, 13)
  ANIM.shake(2, 12)
  -- Late-game: starting at shard 5, an additional rising arpeggio
  -- across cleric (so the moment escalates as the chord nears whole).
  if n >= 5 then
    for k, idx in ipairs({1, 5, 8, 12}) do
      local pitch = (sc[idx] or 60) + (JAM.root or 0) + 12
      clock.run(function()
        clock.sleep(0.40 + (k - 1) * 0.10)
        sq_trig("cleric", midi_to_freq(pitch), 0.55, 0.005, 1.5,
                math.min(1, 0.85 * (CONTENT.combat_reverb_mix or 1.0)))
      end)
    end
  end
  if n >= 7 then
    -- All seven: the chord is whole. A held cleric tone rings under
    -- the existing arpeggio, plus a flash banner.
    sq_trig("cleric", midi_to_freq(60 + (JAM.root or 0)), 0.85, 0.001, 8.0,
            math.min(1, 1.0 * (CONTENT.combat_reverb_mix or 1.0)))
    CONTENT.banner_text  = "* THE CHORD IS WHOLE *"
    CONTENT.banner_ticks = 90
    if unlock_achievement then unlock_achievement("all_shards", "Whole Chord") end
    -- (No queued_scene here anymore: the ENDING-dismiss handlers now
    -- chain start_endgame_scene()/CREDITS directly, so queueing the
    -- endgame beat for a later battle exit was redundant.)
  end
  -- Stash a "fire on next overworld entry" flag so the choreographed
  -- six-shards convergence scene plays right after BATTLE_END dismiss.
  -- exit_battle reads CONTENT.queued_scene and clears it.
  if n == 6 and not (CONTENT.scene_seen and CONTENT.scene_seen.six_shards) then
    CONTENT.queued_scene = "six_shards"
  end
  -- (The shard autosave moved to the END of clear_boss — saving here
  -- captured cleared=true but NOT the boss instrument drop, the
  -- aftermath queue, or the shard achievements, all granted after
  -- this returns: a crash right after the save lost the unique
  -- instrument forever, since cleared bosses don't respawn.)
end

-- adjust tempo settings; immediately apply if relevant state is active
local function adjust_battle_bpm(delta)
  BATTLE_BPM = math.max(BPM_MIN, math.min(BPM_MAX, BATTLE_BPM + delta))
  if game_state == "BATTLE" then params:set("clock_tempo", BATTLE_BPM) end
end

local function adjust_journey_bpm(delta)
  OVERWORLD_BPM = math.max(BPM_MIN, math.min(BPM_MAX, OVERWORLD_BPM + delta))
  -- Apply live only when we're truly on the overworld clock: not in
  -- battle, and not in a JAM overlay opened FROM a battle (SELECT
  -- mid-fight) — the fight would resume at the wrong tempo. Themed
  -- zones keep their own bpm (overworld_tempo falls back to the
  -- global only when the zone defines none).
  if game_state ~= "BATTLE" and jam_prev_state ~= "BATTLE" then
    params:set("clock_tempo", overworld_tempo())
  end
end

-- ============================================================ SAVE / LOAD

-- ── Story flags ──────────────────────────────────────────────────────────────
-- Flat table of boolean story gates. Persisted in save data under data.flag.
-- The `or false` idiom gives old saves safe defaults on load.
flag = flag or {}
-- Region expansion flags (2026-05-14)
flag.lirael_unlocked       = flag.lirael_unlocked       or false
flag.veiled_mystic_spoken  = flag.veiled_mystic_spoken  or false
flag.iolas_letter_received = flag.iolas_letter_received or false
flag.velthes_entry_heard   = flag.velthes_entry_heard   or false
flag.broken_cadence_done   = flag.broken_cadence_done   or false
flag.bandstand_done        = flag.bandstand_done        or false
flag.strom_confronted      = flag.strom_confronted      or false
flag.diegues_returned      = flag.diegues_returned      or false
-- Prologue infirmary: Ymra-shelf hand-off.
flag.ymra_spoken           = flag.ymra_spoken           or false
flag.ymra_shelf_taken      = flag.ymra_shelf_taken      or false
flag.unlock_all            = flag.unlock_all            or false  -- debug toggle
-- Per-scene completion flags (added incrementally per phase, listed here for index)
flag.sunward_arrival_done    = flag.sunward_arrival_done    or false
flag.phrygian_arrival_done   = flag.phrygian_arrival_done   or false
flag.observatory_tour_done   = flag.observatory_tour_done   or false
flag.miel_walks_alone_done   = flag.miel_walks_alone_done   or false
flag.lirael_theme_shifted    = flag.lirael_theme_shifted    or false
flag.captain_insignia_given  = flag.captain_insignia_given  or false

-- Unlock gate for Lirael Ruins (map_id 23).
-- Requires 4+ shards AND the Veiled Mystic conversation, OR the debug
-- unlock_all toggle. Centralises this condition for tile renderer and
-- step_player; all call sites are defined later in the file.
-- global: hitting Lua's 200-local limit in this chunk
function lirael_is_unlocked()
  if flag.unlock_all then return true end
  return (count_shards() >= 4) and flag.veiled_mystic_spoken
end

-- Single save file (Pass 49 multi-slot reverted Pass 54).
local function SAVE_PATH()
  return _path.data .. "synth-quest/save.data"
end
-- (update_camera forward decl pulled to the top of file scope; see
-- the local declaration right after `player`/`cam` so all earlier-
-- defined scene functions can capture it as an upvalue.)
local travel_to       -- forward decl (defined later)

-- ── SAVE FORMAT VERSIONING ─────────────────────────────────────────────
-- Bump SAVE_VERSION every time a scene/script/flag-shape change makes an
-- older save load into stale content. Add a corresponding entry to
-- SAVE_MIGRATIONS that mutates `data` (the raw loaded table) to bring
-- it forward. Each migration runs once, in order, from the saved
-- version + 1 up to SAVE_VERSION.
--
-- Example pattern for a future migration:
--   SAVE_MIGRATIONS[2] = function(data)
--     -- chamber-wake scene was rewritten -- let it replay
--     if data.scene_seen then data.scene_seen.chamber_wake = nil end
--   end
SAVE_VERSION = 3
SAVE_MIGRATIONS = {
  -- v0 -> v1: page_warning scene was rewritten (Page now ends at his
  -- static post at (8,8) instead of running back to the door), and the
  -- courtyard breach scene was rewritten (Hova + Borin emerge from the
  -- barracks). Both are gated by `scene_seen.page_warning` and the
  -- one-shot `CONTENT.courtyard_breach_done` flag respectively. Clear
  -- them so old saves get the new versions on next playthrough.
  [1] = function(data)
    if data.scene_seen then
      data.scene_seen.page_warning = nil
    end
    -- (CONTENT.courtyard_breach_done isn't currently saved, so the
    -- breach already replays on load — no migration needed for it.)
  end,
  -- v1 -> v2: the World of Silence beat landed (CONTENT.act3_silence,
  -- set at the end of the six-shards scene, cleared by ECHO's
  -- recruitment or the ending). Saves taken between six-shards and
  -- ECHO/ending predate the beat entirely — re-arm the flag so ECHO's
  -- recruitment is reachable on those saves.
  [2] = function(data)
    if data.act3_silence == nil then
      local seen = data.scene_seen or {}
      -- The ionian-shard check covers finished games from BEFORE
      -- endgame_done was persisted (v0 saves): a returned seventh
      -- shard means the world is already re-tuned.
      data.act3_silence = (seen.six_shards and not seen.echo_recruit
                           and not data.endgame_done
                           and not (data.shards and data.shards.ionian)) or false
    end
  end,
  -- v3 (wave 9): Cave 7's chamber door now requires six shards, but the
  -- door gate can't reach a save made INSIDE the antechamber (map 14)
  -- before the gate existed. Relocate such saves to the door's outside
  -- (their stashed return point, or the Tower base) so the gate binds.
  [3] = function(data)
    if data.current_map_id == 14 and not data.endgame_done then
      local n = 0
      for _, v in pairs(data.shards or {}) do if v then n = n + 1 end end
      if n < 6 then
        data.current_map_id = data.return_map or 4
        data.player = {x = data.return_x or 12, y = data.return_y or 12,
                       facing = "down"}
        data.return_map = nil; data.return_x = nil; data.return_y = nil
      end
    end
  end,
}

save_game = function()
  os.execute("mkdir -p " .. _path.data .. "synth-quest/")
  local data = {
    version = SAVE_VERSION,
    player = {x=player.x, y=player.y, facing=player.facing},
    party = {},
    shards = shards,
    cave_state = cave_state,
    current_map_id = current_map_id,
  }
  -- Legacy data.party still saved for any older code paths, but the
  -- canonical truth is data.characters (per-class) + data.party_classes
  -- (which class is in each slot) + data.active.
  for i, p in ipairs(party) do
    data.party[i] = {
      hp = p.hp, mp = p.mp, alive = p.alive, queued = p.queued,
      level = p.level, xp = p.xp, xp_total = p.xp_total,
      hp_max = p.hp_max, mp_max = p.mp_max,
      atk = p.atk, def = p.def, mag = p.mag, spd = p.spd,
    }
  end
  data.characters = {}
  for cls, ch in pairs(CHARACTERS or {}) do
    data.characters[cls] = {
      hp = ch.hp, mp = ch.mp, alive = ch.alive, queued = ch.queued,
      level = ch.level, xp = ch.xp, xp_total = ch.xp_total,
      hp_max = ch.hp_max, mp_max = ch.mp_max,
      atk = ch.atk, def = ch.def, mag = ch.mag, spd = ch.spd,
      ever_joined = ch.ever_joined or nil,
    }
  end
  data.party_classes = {}
  for i, p in ipairs(party) do data.party_classes[i] = p.class end
  data.active = active
  data.battle_bpm = BATTLE_BPM
  data.journey_bpm = OVERWORLD_BPM
  -- equipment: list of owned ids + map of class→equipped id
  local owned_list = {}
  for id, _ in pairs(instruments_owned) do owned_list[#owned_list+1] = id end
  data.instruments_owned = owned_list
  data.equipped = {}
  for cls, id in pairs(equipped) do data.equipped[cls] = id end
  -- economy
  data.gold = SHOP.gold
  data.inv = {salve = SHOP.inv.salve, vial = SHOP.inv.vial, star = SHOP.inv.star,
              ether = SHOP.inv.ether, tonic = SHOP.inv.tonic, key = SHOP.inv.key}
  -- sidequests
  data.quests = {
    hens = {wins = QUESTS.hens.wins, discount = QUESTS.hens.discount},
    brann = {wins = QUESTS.brann.wins, claimed = QUESTS.brann.claimed},
    tova = {spoke = {}, claimed = QUESTS.tova.claimed},
    pith = {claimed = QUESTS.pith.claimed},
  }
  for k, v in pairs(QUESTS.tova.spoke) do data.quests.tova.spoke[k] = v end
  -- party-story scenes seen
  data.story_seen = {}
  for k, v in pairs(STORY.seen) do data.story_seen[k] = v end
  -- jam settings (root key offset + active mode)
  data.jam_root = JAM.root
  data.jam_mode = JAM.mode
  -- bestiary
  data.bestiary = {}
  for k, v in pairs(CONTENT.bestiary) do data.bestiary[k] = v end
  -- chests
  data.chests_opened = {}
  for k, v in pairs(CONTENT.opened) do data.chests_opened[k] = v end
  -- recruits joined-flags + Sergei intervention one-shot
  data.recruits_joined = {CONTENT.recruits[1].joined, CONTENT.recruits[2].joined,
                          CONTENT.recruits[3] and CONTENT.recruits[3].joined or false,
                          CONTENT.recruits[4] and CONTENT.recruits[4].joined or false}
  -- Pass 52: persist unlocked achievements.
  data.achievements = {}
  for k, v in pairs(CONTENT.achievements or {}) do data.achievements[k] = v end
  data.sergei_intervened = CONTENT.sergei_intervened
  data.academy_state = CONTENT.academy_state
  data.prologue_state = CONTENT.prologue_state
  data.prologue_scene_done = CONTENT.prologue_scene_done
  data.prologue_intro_done = CONTENT.prologue_intro_done
  data.scene_seen = {}
  for k, v in pairs(CONTENT.scene_seen or {}) do data.scene_seen[k] = v end
  data.silencer_defeated = CONTENT.silencer_defeated
  data.cave_monster_defeated = CONTENT.cave_monster_defeated
  -- Gameplay-gating CONTENT flags that previously weren't persisted, so
  -- they reset on Continue (e.g. courtyard reverted to pre-breach, the
  -- post-game VoidEcho vanished, first-cave-entry scenes replayed).
  data.courtyard_breached    = CONTENT.courtyard_breached or false
  data.courtyard_breach_done = CONTENT.courtyard_breach_done or false
  data.pell_seen             = CONTENT.pell_seen or false
  data.senna_seen            = CONTENT.senna_seen or false
  data.endgame_done          = CONTENT.endgame_done or false
  data.act3_silence          = CONTENT.act3_silence or false
  -- Pending story beat (e.g. "six_shards" between the 6th-shard drop
  -- and the next battle exit). Without this, reloading the 6th-shard
  -- autosave lost the World of Silence + ECHO for the whole run.
  data.queued_scene          = CONTENT.queued_scene
  data.total_wins            = CONTENT.total_wins or 0
  data.tess_defected         = CONTENT.tess_defected or false
  data.tilde_paid            = CONTENT.tilde_paid or false
  data.wisp_paid             = CONTENT.wisp_paid or false
  -- Interior return-door target: persists so cave/interior exit doors
  -- still return correctly after save + Continue inside an interior.
  data.return_map            = CONTENT.return_map
  data.return_x              = CONTENT.return_x
  data.return_y              = CONTENT.return_y
  -- Stashed outer return trio (set when an interior is entered while a
  -- region-warp return is pending) — persists alongside return_map.
  data.outer_return          = CONTENT.outer_return
  -- House-interior registry key (map 38 is shared by every home; the
  -- key is what tells load_game WHICH home the player saved inside).
  data.house_key             = CONTENT.house_key
  data.cave_entered = {}
  for k, v in pairs(CONTENT.cave_entered or {}) do data.cave_entered[k] = v end
  data.fire_seen = CONTENT.fire_seen or {}   -- table of campfire indices (not a boolean)
  -- Resonances state (per-Resonance item-collected + attuned flags).
  data.resonances = {}
  for id, r in pairs(CONTENT.resonances or {}) do
    data.resonances[id] = { item = r.item or false, attuned = r.attuned or false }
  end
  -- story flags
  data.flag = {}
  for k, v in pairs(flag) do data.flag[k] = v end
  -- Atomic write: tab.save writes in place; a power-off mid-write left
  -- a truncated file that tab.load rejects -> "No save found" and the
  -- whole run silently gone. rename(2) is atomic on the norns fs.
  local sp = SAVE_PATH()
  tab.save(data, sp .. ".tmp")
  os.rename(sp .. ".tmp", sp)
  save_flash_ticks = 24
  save_flash_text = "Game Saved"
end
-- Mirror to _ENV so closures created BEFORE the `local save_game`
-- forward decl (e.g. start_new_game_plus's `if save_game then ...`)
-- can resolve it at call time. Without this, NG+ silently skips its
-- auto-save and the player can lose the reset state.
_G.save_game = save_game

local function load_game()
  local data = tab.load(SAVE_PATH())
  if not data then
    save_flash_ticks = 24
    save_flash_text = "No save found"
    return false
  end
  -- Apply save-format migrations. Saves written before SAVE_VERSION was
  -- introduced carry no `version` key — treat as 0. Each migration
  -- runs once, in order, with a pcall so a broken migration can't soft-
  -- lock the load. After running we stamp `data.version = SAVE_VERSION`
  -- so the next save writes the current schema.
  do
    local v = tonumber(data.version) or 0
    for ver = v + 1, (SAVE_VERSION or 0) do
      local mig = SAVE_MIGRATIONS and SAVE_MIGRATIONS[ver]
      if type(mig) == "function" then
        local ok, err = pcall(mig, data)
        if not ok then
          print("synth-quest: save migration v" .. ver .. " err: " .. tostring(err))
        end
      end
    end
    data.version = SAVE_VERSION
  end
  -- Type normalizer: a hand-edited/corrupt save with a non-table block
  -- (data.shards = "yes" etc.) crashed the restore loops. Nil out any
  -- block that isn't the shape the loops expect; every consumer below
  -- already guards against absence.
  do
    local function T(x) return type(x) == "table" and x or nil end
    data.shards        = T(data.shards)
    data.cave_state    = T(data.cave_state)
    data.characters    = T(data.characters)
    data.party         = T(data.party)
    data.party_classes = T(data.party_classes)
    data.quests        = T(data.quests)
    data.scene_seen    = T(data.scene_seen)
    data.story_seen    = T(data.story_seen)
    data.flag          = T(data.flag)
    data.inv           = T(data.inv)
    data.resonances    = T(data.resonances)
    data.bestiary      = T(data.bestiary)
    data.player        = T(data.player)
    data.active        = tonumber(data.active)
    data.current_map_id = tonumber(data.current_map_id)
  end
  -- Wipe any in-progress scene state so a load mid-cutscene doesn't leave
  -- stale actors/fades on screen. PARTICLES pool is similarly cleared.
  if SCENE then
    SCENE.active = false; SCENE.script = nil; SCENE.step = 1
    SCENE.wait = 0; SCENE.actors = {}
    SCENE.fade = 0; SCENE.fade_target = 0; SCENE.fade_speed = 0
    SCENE.hide_player = false; SCENE.cam_tween = nil
    SCENE.letterbox = 0; SCENE.letterbox_target = 0
    SCENE.panel = nil; SCENE.panel_t = 0; SCENE.on_complete = nil
  end
  if PARTICLES then PARTICLES.pool = {} end
  -- Reset dialogue typewriter state so a load mid-dialogue doesn't show
  -- a partially-revealed line.
  if dlg then
    dlg.lines = nil; dlg.line = 1; dlg.npc = nil
    dlg.line_start_tick = nil; dlg.line_start_time = nil
    dlg.complete = false; dlg.snap_to_complete = false
  end
  -- Tolerate a truncated/hand-edited save missing the player block —
  -- indexing nil here crashed the title-screen key handler.
  data.player = data.player or {}
  -- Field-level defaults (a present-but-partial block otherwise poisons
  -- player.x with nil): new-game spawn, walkable on map 1.
  data.player.x = tonumber(data.player.x) or 6
  data.player.y = tonumber(data.player.y) or 6
  data.player.facing = data.player.facing or "down"
  player.x = data.player.x
  player.y = data.player.y
  player.facing = data.player.facing
  -- New saves: restore CHARACTERS by class, then rebuild party from
  -- saved class-per-slot order. Old saves (no data.characters) fall back
  -- to slot-indexed loading — slightly lossy if a recruit was swapped in,
  -- but at least preserves what we have.
  if data.characters then
    -- Make sure recruit-class records exist (they're built lazily on swap;
    -- a save with a leveled recruit may reference a class CHARACTERS doesn't yet have).
    for cls, _ in pairs(data.characters) do
      if not CHARACTERS[cls] then
        for _, r in ipairs(CONTENT.recruits) do
          if r.class == cls then
            CHARACTERS[cls] = build_recruit_record(r)
            break
          end
        end
      end
    end
    -- Apply saved values onto each character record.
    for cls, sp in pairs(data.characters) do
      local ch = CHARACTERS[cls]
      if ch then
        ch.hp      = sp.hp or ch.hp
        ch.mp      = sp.mp or ch.mp
        ch.alive   = (sp.alive ~= nil) and sp.alive or ch.alive
        ch.queued  = sp.queued or ch.queued
        ch.level   = sp.level or 1
        ch.xp      = sp.xp or 0
        ch.xp_total= sp.xp_total or 0
        ch.hp_max  = sp.hp_max or ch.hp_max
        ch.mp_max  = sp.mp_max or ch.mp_max
        ch.atk     = sp.atk or ch.atk
        ch.def     = sp.def or ch.def
        ch.mag     = sp.mag or ch.mag
        ch.spd     = sp.spd or ch.spd
        -- Sanity clamps for edited/corrupt saves: level >= 1, hp/mp
        -- within max (an over-max hp overdraws the HP bar past its box).
        ch.level = math.max(1, tonumber(ch.level) or 1)
        ch.hp = math.min(ch.hp or ch.hp_max, ch.hp_max)
        ch.mp = math.min(ch.mp or ch.mp_max, ch.mp_max)
        ch.ever_joined = sp.ever_joined or ch.ever_joined
          or (ch.xp_total or 0) > 0 or ch.level > 1
      end
    end
    -- Rebuild party slots from the saved class order.
    if data.party_classes then
      for i, cls in ipairs(data.party_classes) do
        if CHARACTERS[cls] then
          party[i] = CHARACTERS[cls]
          CHARACTERS[cls].ever_joined = true
        end
      end
    end
    -- Pre-flag-save backstop: recruits only ever join after all four
    -- starters have, so any joined recruit proves the starters joined —
    -- keeps a benched L1/0-xp starter from vanishing off the reserve list.
    for _, r in ipairs((CONTENT and CONTENT.recruits) or {}) do
      if r.joined then
        for _, cls in ipairs({"cleric", "bard", "warrior", "mage"}) do
          if CHARACTERS[cls] then CHARACTERS[cls].ever_joined = true end
        end
        break
      end
    end
    if data.active then active = math.max(1, math.min(#party, data.active)) end
  else
    -- Legacy slot-indexed load (best-effort migration).
    for i, sp in ipairs(data.party or {}) do
      if party[i] then
        party[i].hp = sp.hp
        party[i].mp = sp.mp
        party[i].alive = sp.alive
        party[i].queued = sp.queued
        if sp.level then party[i].level = sp.level end
        if sp.xp then party[i].xp = sp.xp end
        if sp.xp_total then party[i].xp_total = sp.xp_total end
        if sp.hp_max then party[i].hp_max = sp.hp_max end
        if sp.mp_max then party[i].mp_max = sp.mp_max end
        if sp.atk then party[i].atk = sp.atk end
        if sp.def then party[i].def = sp.def end
        if sp.mag then party[i].mag = sp.mag end
        if sp.spd then party[i].spd = sp.spd end
      end
    end
  end
  for k, v in pairs(data.shards or {}) do shards[k] = v end
  if data.cave_state then
    for i, st in pairs(data.cave_state) do
      if cave_state[i] then
        cave_state[i].victories = st.victories or 0
        cave_state[i].cleared   = st.cleared or false
      end
    end
  end
  -- NOTE: travel_to is deliberately DEFERRED to the end of load_game.
  -- travel_to fires map-entry story triggers (academy intro, ECHO
  -- recruit, prologue beats) gated on flags that are only restored
  -- below — calling it here replayed the whole academy intro + Strom
  -- fight when Continuing a save made inside map 19. Position/facing
  -- are stashed in locals and applied by the deferred call.
  local ld_map_id = data.current_map_id
  local ld_x, ld_y = data.player.x, data.player.y
  local ld_facing  = data.player.facing
  if data.battle_bpm then BATTLE_BPM = data.battle_bpm end
  if data.journey_bpm then OVERWORLD_BPM = data.journey_bpm end
  -- equipment (gracefully no-op for older saves; migrate cleric instrument names)
  local INST_MIGRATE = {
    -- Mage staves -> samplers
    ash_staff = "cassette_sampler", ember_rod = "sp404", astral_wand = "norns_sampler",
    -- Warrior swords -> tuning forks
    iron_edge = "iron_fork", hymnsword = "bell_fork", stormbrand = "storm_fork",
    -- Cleric: violin (start), singing_bowl (Cave 2), lyre (Cave 6), moog
    -- (rare). Map every retired ID forward.
    prayer_bell = "violin",     pilgrim_lyre = "violin",
    silver_censer = "singing_bowl", silver_lyre = "singing_bowl", harp = "singing_bowl",
    hymnal = "lyre",            sacred_lyre = "lyre",
    hollow_drum = "aeolian_lute",
  }
  if data.instruments_owned then
    instruments_owned = {}
    for _, id in ipairs(data.instruments_owned) do
      id = INST_MIGRATE[id] or id
      if INSTRUMENTS[id] then instruments_owned[id] = true end
    end
  end
  if data.equipped then
    for cls, id in pairs(data.equipped) do
      id = INST_MIGRATE[id] or id
      if INSTRUMENTS[id] then equipped[cls] = id end
    end
  end
  if data.gold then SHOP.gold = math.max(0, tonumber(data.gold) or 0) end
  if data.quests then
    if data.quests.hens then
      QUESTS.hens.wins = data.quests.hens.wins or 0
      QUESTS.hens.discount = data.quests.hens.discount or false
    end
    if data.quests.brann then
      QUESTS.brann.wins = data.quests.brann.wins or 0
      QUESTS.brann.claimed = data.quests.brann.claimed or false
    end
    if data.quests.tova then
      QUESTS.tova.claimed = data.quests.tova.claimed or false
      QUESTS.tova.spoke = {}
      for k, v in pairs(data.quests.tova.spoke or {}) do QUESTS.tova.spoke[k] = v end
    end
    if data.quests.pith then
      QUESTS.pith.claimed = data.quests.pith.claimed or false
    end
  end
  if data.story_seen then
    STORY.seen = {}
    for k, v in pairs(data.story_seen) do STORY.seen[k] = v end
  end
  if data.jam_root then JAM.root = data.jam_root end
  if data.jam_mode and JAM.scales[data.jam_mode] then JAM.mode = data.jam_mode end
  if data.bestiary then
    CONTENT.bestiary = {}
    for k, v in pairs(data.bestiary) do CONTENT.bestiary[k] = v end
  end
  if data.chests_opened then
    CONTENT.opened = {}
    for k, v in pairs(data.chests_opened) do CONTENT.opened[k] = v end
  end
  if data.recruits_joined then
    if CONTENT.recruits[1] then CONTENT.recruits[1].joined = data.recruits_joined[1] or false end
    if CONTENT.recruits[2] then CONTENT.recruits[2].joined = data.recruits_joined[2] or false end
    if CONTENT.recruits[3] then CONTENT.recruits[3].joined = data.recruits_joined[3] or false end
    if CONTENT.recruits[4] then CONTENT.recruits[4].joined = data.recruits_joined[4] or false end
    -- Ensure each joined recruit has a CHARACTERS record (so they can be
    -- swapped in even if the save predates the per-class persistence layer).
    for _, r in ipairs(CONTENT.recruits) do
      if r.joined and not (CHARACTERS and CHARACTERS[r.class]) then
        CHARACTERS = CHARACTERS or {}
        CHARACTERS[r.class] = build_recruit_record(r)
      end
    end
  end
  if data.achievements then
    CONTENT.achievements = {}
    for k, v in pairs(data.achievements) do CONTENT.achievements[k] = v end
  end
  if data.sergei_intervened ~= nil then CONTENT.sergei_intervened = data.sergei_intervened end
  if data.academy_state then CONTENT.academy_state = data.academy_state end
  if data.prologue_state then CONTENT.prologue_state = data.prologue_state end
  if data.prologue_scene_done ~= nil then
    CONTENT.prologue_scene_done = data.prologue_scene_done
  end
  if data.prologue_intro_done ~= nil then
    CONTENT.prologue_intro_done = data.prologue_intro_done
  end
  -- (No more "assume scene played" migration — saves that predate
  -- prologue_scene_done are treated as never-seen so the choreographed
  -- throne scene gets a chance to play even on continued saves where
  -- the previous version of the prologue was just static dialogue.)
  if data.scene_seen then
    CONTENT.scene_seen = {}
    for k, v in pairs(data.scene_seen) do CONTENT.scene_seen[k] = v end
  end
  if data.silencer_defeated then
    CONTENT.silencer_defeated = data.silencer_defeated
  end
  if data.cave_monster_defeated then
    CONTENT.cave_monster_defeated = data.cave_monster_defeated
  end
  -- Gameplay-gating CONTENT flags (added 2026-05-20). `~= nil` guards so
  -- a `false` saved value still loads; older saves without these keys
  -- keep the module-load defaults.
  if data.courtyard_breached    ~= nil then CONTENT.courtyard_breached    = data.courtyard_breached end
  if data.courtyard_breach_done ~= nil then CONTENT.courtyard_breach_done = data.courtyard_breach_done end
  if data.pell_seen             ~= nil then CONTENT.pell_seen             = data.pell_seen end
  if data.senna_seen            ~= nil then CONTENT.senna_seen            = data.senna_seen end
  if data.endgame_done          ~= nil then CONTENT.endgame_done          = data.endgame_done end
  if data.act3_silence          ~= nil then CONTENT.act3_silence          = data.act3_silence end
  if data.total_wins            ~= nil then CONTENT.total_wins            = data.total_wins end
  if data.tess_defected         ~= nil then CONTENT.tess_defected         = data.tess_defected end
  if data.tilde_paid            ~= nil then CONTENT.tilde_paid            = data.tilde_paid end
  if data.wisp_paid             ~= nil then CONTENT.wisp_paid             = data.wisp_paid end
  if data.return_map            ~= nil then CONTENT.return_map            = data.return_map end
  if data.return_x              ~= nil then CONTENT.return_x              = data.return_x end
  if data.return_y              ~= nil then CONTENT.return_y              = data.return_y end
  if data.outer_return          ~= nil then CONTENT.outer_return          = data.outer_return end
  if data.house_key             ~= nil then CONTENT.house_key             = data.house_key end
  if data.fire_seen             ~= nil then CONTENT.fire_seen             = data.fire_seen end
  if data.cave_entered then
    CONTENT.cave_entered = {}
    for k, v in pairs(data.cave_entered) do CONTENT.cave_entered[k] = v end
  end
  -- Resonances state — restore if present, initialize if missing (older saves).
  if data.resonances then
    for id, r in pairs(data.resonances) do
      if CONTENT.resonances[id] then
        CONTENT.resonances[id].item    = r.item or false
        CONTENT.resonances[id].attuned = r.attuned or false
      end
    end
  end
  -- (CONTENT.resonances was already initialized at module load with all 8
  -- ids set to false, so missing data.resonances on a legacy save just
  -- leaves the defaults in place.)
  -- story flags. Replace, don't merge: save_game dumps the whole table,
  -- so any key absent from the save is genuinely unset — a merge would
  -- let flags from the in-memory session (post-credits TITLE → Continue)
  -- leak into the loaded game. Mutate in place: closures hold `flag`.
  if data.flag then
    for k in pairs(flag) do flag[k] = nil end
    for k, v in pairs(data.flag) do flag[k] = v end
  end
  -- Pending story beat (persisted since wave 9). For saves from before
  -- that, re-derive the one load-bearing case: six shards banked but the
  -- six-shards beat never seen means the beat was queued in a session
  -- that never drained it — without this, the World of Silence and
  -- ECHO's recruitment are silently unreachable for the whole run.
  -- Unconditional (replace, don't merge — same policy as `flag`): a
  -- key absent from the save means no beat is pending.
  CONTENT.queued_scene = data.queued_scene
  if not CONTENT.queued_scene
     and count_shards() >= 6 and not shards.ionian
     and not CONTENT.endgame_done
     and not (CONTENT.scene_seen and CONTENT.scene_seen.six_shards) then
    CONTENT.queued_scene = "six_shards"
  end
  if data.inv then
    SHOP.inv.salve = data.inv.salve or 0
    SHOP.inv.vial  = data.inv.vial or 0
    SHOP.inv.star  = data.inv.star or 0
    SHOP.inv.ether = data.inv.ether or 0
    SHOP.inv.tonic = data.inv.tonic or 0
    SHOP.inv.key   = data.inv.key or 0
  end
  -- Houses (map 38) share one map id: rebuild the interior refs from
  -- the persisted registry key BEFORE the deferred travel_to below runs,
  -- so travel_to(38, ...) points at the right room.
  if ld_map_id == 38 and CONTENT.house_key and CONTENT.HOUSES
     and CONTENT.HOUSES[CONTENT.house_key] then
    local h = CONTENT.HOUSES[CONTENT.house_key]
    CONTENT.house_map = h.map; CONTENT.house_npcs = h.npcs
  end
  -- Deferred map switch (see note above): all story flags / scene_seen /
  -- academy_state are restored by now, so travel_to's map-entry triggers
  -- see the true post-save state and won't replay finished scenes.
  -- Map 38 is exempt from the "same map id" skip: two different houses
  -- share id 38, so equal ids don't imply the same room.
  -- Unknown map ids (hand-edited save) fall through travel_to's else
  -- branch into SUNOS_DOMAIN at arbitrary coords — validate the range
  -- (real maps are 1..38) and fall back to the village.
  if ld_map_id and (ld_map_id < 1 or ld_map_id > 38 or ld_map_id == 25) then
    ld_map_id, ld_x, ld_y = 1, 17, 2   -- 25 is unregistered (cairn scene lives on map 3)
  end
  if ld_map_id and (ld_map_id ~= current_map_id or ld_map_id == 38) then
    travel_to(ld_map_id, ld_x, ld_y)
  end
  player.x = ld_x
  player.y = ld_y
  player.facing = ld_facing
  -- Snap theme + tempo to the loaded map. (Load only happens from
  -- TITLE, never mid-battle; the old unconditional OVERWORLD_BPM write
  -- played themed zones at the wrong tempo when the session's stale
  -- theme matched the loaded zone — no transition ever re-applied it.)
  if resync_zone_tempo then resync_zone_tempo()
  else params:set("clock_tempo", OVERWORLD_BPM) end
  update_camera()
  save_flash_ticks = 24
  save_flash_text = "Game Loaded"
  -- Drain a pending six-shards beat immediately: the queue's normal
  -- consumer is exit_battle, but a just-loaded player can reach the
  -- Cave 7 door without ever exiting another battle. Mirrors the
  -- exit_battle consumer (mark seen, clear, fire; the scene self-warps
  -- to the village fountain).
  if CONTENT.queued_scene == "six_shards" and start_six_shards_scene then
    CONTENT.queued_scene = nil
    CONTENT.scene_seen = CONTENT.scene_seen or {}
    CONTENT.scene_seen.six_shards = true
    start_six_shards_scene()
  end
  return true
end

-- ============================================================ PARTY

-- Stable character store, keyed by class. The party array holds
-- REFERENCES into this table — never copies — so swapping a recruit
-- in/out preserves every character's stats. Save dumps this whole table
-- by class; load rebuilds it. Globals (no `local`) to dodge the
-- 200-main-chunk-locals cap.
CHARACTERS = nil

function build_starter_record(t, queued_default)
  return {
    class=t.class, spd=t.spd, atb=0, queued=queued_default or "ATK",
    note_idx=t.note_idx, note_lo=t.note_lo, note_hi=t.note_hi,
    cutoff=t.cutoff, resonance=t.resonance,
    hp=t.hp_max, hp_max=t.hp_max, mp=t.mp_max, mp_max=t.mp_max,
    atk=t.atk, def=t.def, mag=t.mag,
    level=1, xp=0, xp_total=0,
    alive=true, shield=false, buffed=false, blocking=false,
    last_fire=-99, last_hit=-99,
    stick={lx=0,ly=0,rx=0,ry=0}, xwet=0, dly=0,
  }
end

function build_recruit_record(r)
  local rec = {
    class=r.class, spd=r.spd, atb=0, queued="ATK",
    note_idx=11, note_lo=8, note_hi=20,
    cutoff=2000, resonance=0.30,
    hp=r.hp_max, hp_max=r.hp_max, mp=r.mp_max, mp_max=r.mp_max,
    atk=r.atk, def=r.def, mag=r.mag,
    level=1, xp=0, xp_total=0,
    alive=true, shield=false, buffed=false, blocking=false,
    ever_joined=true,
    last_fire=-99, last_hit=-99,
    stick={lx=0,ly=0,rx=0,ry=0}, xwet=0, dly=0,
  }
  -- Catch-up seeding: recruits used to join at level 1 regardless of
  -- story point (Sergei arrives post-cave-3 with 24 HP against a ~L5
  -- party). Seed to one below the current party average, applying the
  -- same CLASS_GROWTH gains a levelled character would have earned.
  local sum, cnt = 0, 0
  for _, q in ipairs(party or {}) do
    sum = sum + (q.level or 1); cnt = cnt + 1
  end
  local target = math.max(1, (cnt > 0 and math.floor(sum / cnt) or 1) - 1)
  local g = CLASS_GROWTH[rec.class] or {hp=4, mp=2, atk=1, def=1, mag=1, spd_every=6}
  while rec.level < target do
    rec.level = rec.level + 1
    rec.hp_max = rec.hp_max + g.hp
    rec.mp_max = rec.mp_max + g.mp
    rec.atk    = rec.atk    + g.atk
    rec.def    = rec.def    + g.def
    rec.mag    = rec.mag    + g.mag
    if g.spd_every and (rec.level % g.spd_every) == 0 then
      rec.spd = (rec.spd or 1) + 1
    end
  end
  rec.hp = rec.hp_max
  rec.mp = rec.mp_max
  return rec
end

-- ensure_recruit_character(idx) — make sure the recruit in
-- CONTENT.recruits[idx] has a CHARACTERS record the moment they join,
-- so they can be swapped in from the Party menu immediately (before,
-- records were only built lazily by load_game, so a freshly-joined
-- recruit was un-swappable until save+reload). Idempotent: no-op if
-- the class record already exists. Global (like build_recruit_record)
-- so join-scene closures defined earlier in the chunk can call it.
function ensure_recruit_character(idx)
  local r = CONTENT.recruits and CONTENT.recruits[idx]
  if not r then return end
  CHARACTERS = CHARACTERS or {}
  if CHARACTERS[r.class] then return end
  CHARACTERS[r.class] = build_recruit_record(r)
end

local function init_party()
  -- All four starter records still live in CHARACTERS so their stats
  -- track from level 1 even before they join. Active party starts with
  -- Miel ALONE — Alder/Diegues/Strom enter via prologue/story scenes.
  CHARACTERS = {}
  for i, t in ipairs(PARTY_TEMPLATE) do
    CHARACTERS[t.class] = build_starter_record(t, DEFAULT_QUEUED[i])
  end
  CHARACTERS.cleric.ever_joined = true
  party = { CHARACTERS.cleric }   -- Miel only at New Game start
  active = 1
  -- Equip Miel's starter instrument; queue Alder/Diegues/Strom's starter
  -- instruments to the owned pool so they're ready when those characters
  -- join later (no awkward "you have no instrument equipped" moment).
  instruments_owned = {}
  equipped = {}
  for _, t in ipairs(PARTY_TEMPLATE) do
    local id = STARTER_INSTRUMENT[t.class]
    if id then
      instruments_owned[id] = true
      equipped[t.class] = id
    end
  end
end

-- shared XP gain on enemy defeat. Each party member accumulates XP toward
-- their own next-level threshold and levels up via the CLASS_GROWTH table.
-- p.xp is *progress toward next level*; p.xp_total is lifetime XP earned.
-- Global (was local) so prologue helpers (start_prologue_silencer,
-- start_prologue_cave_monster) defined earlier in the file can grant
-- XP. Their `if gain_xp then` guards used to silently no-op because
-- the local wasn't yet in lexical scope at their definition point.
function gain_xp(amount)
  for _, p in ipairs(party) do
    if not p.alive then goto continue end
    p.xp = (p.xp or 0) + amount
    p.xp_total = (p.xp_total or 0) + amount
    while p.level < LEVEL_CAP and p.xp >= xp_for_level(p.level) do
      p.xp = p.xp - xp_for_level(p.level)
      p.level = p.level + 1
      local g = CLASS_GROWTH[p.class] or {hp=4, mp=2, atk=1, def=1, mag=1, spd_every=6}
      p.hp_max = p.hp_max + g.hp
      p.mp_max = p.mp_max + g.mp
      p.atk    = p.atk    + g.atk
      p.def    = p.def    + g.def
      p.mag    = p.mag    + g.mag
      if g.spd_every and (p.level % g.spd_every) == 0 then
        p.spd = (p.spd or 1) + 1
      end
      p.hp = p.hp_max
      p.mp = p.mp_max
      p.last_hit = tick
      levelup_flash_ticks = 32
      levelup_flash_who = CHAR_NAME[p.class] .. " Lv." .. p.level
      -- Triumphant 3-note rising chord: I → V → I' on the bard voice
      local sc = JAM.scales[JAM.mode] or JAM.scales.pentatonic
      for k, idx in ipairs({1, 3, 5}) do
        local pitch = (sc[idx + 12] or sc[idx]) + (JAM.root or 0)
        clock.run(function()
          clock.sleep((k - 1) * 0.06)
          sq_trig("bard", midi_to_freq(pitch), 0.7, 0.003, 0.5, math.min(1, 0.6 * (CONTENT.combat_reverb_mix or 1.0)))
        end)
      end
    end
    if p.level >= LEVEL_CAP then p.xp = 0 end
    ::continue::
  end
end

local function reset_party_for_battle()
  for _, p in ipairs(party) do
    p.atb = 0
    p.shield = false
    p.buffed = false
    p.ring_armed = false   -- Resonance arm-flag is per-battle (matches p.buffed)
    p.long_echo_charges = 0
    p.threefold_until = -99
    p.reso_cooldown_until = 0
    p.reso_denied_t = -99
    p.blocking = false
    p.reflect = false
    p.reflect_ticks = 0
    p.limit_used = false   -- limit-break refreshed each battle
    p.last_fire = -99
    p.last_hit = -99
    if not p.alive then
      p.alive = true
      p.hp = math.max(1, math.floor(p.hp_max * 0.25))
    end
  end
end

-- ============================================================ OVERWORLD MUSIC

-- which region's theme is currently playing — used to detect transitions
local current_theme = "village"

-- The tempo the overworld should currently sound at: the active zone
-- theme's own bpm (zones run 48–130), falling back to the global
-- OVERWORLD_BPM when a theme defines none. Returning from battle uses
-- this so the music resumes at the zone's tempo instead of snapping to
-- the global default — which audibly changed the BPM after every fight.
function overworld_tempo()
  local theme = OW_THEMES[current_theme]
  return (theme and theme.bpm) or OVERWORLD_BPM
end

local function active_theme_id()
  if current_map_id == 2 then return "eastern" end
  if current_map_id == 3 then return "northern" end
  if current_map_id == 4 then return "tower" end
  -- Pass 25: interior themes (inn, shop, each cave, side dungeon).
  if current_map_id == 5 or current_map_id == 17 or current_map_id == 18 then return "inn" end
  if current_map_id == 38 then return "inn" end  -- house interiors: same cozy hearth theme as the inn
  if current_map_id == 6 or current_map_id == 15 or current_map_id == 16 then return "shop" end
  if current_map_id == 19 then return "academy" end  -- academy interior gets its own scholarly theme
  if current_map_id == 20 then return "castle" end -- castle interior: coup-in-progress urgency
  if current_map_id == 27 or current_map_id == 28 or current_map_id == 29
     or current_map_id == 30 or current_map_id == 31
     or current_map_id == 32 or current_map_id == 33
     or current_map_id == 34 then return "castle" end
  if current_map_id == 21 then return "echoes" end -- escape cave: cave-1 echoes theme
  if current_map_id == 22 then return "woods" end  -- western region: hollow-woods theme
  if current_map_id == 23 then return "lirael" end -- Lirael Ruins: mournful Aeolian descent
  if current_map_id == 24 then return "observatory" end -- Velthe Observatory: mathematical Lydian
  if current_map_id == 25 then return "cairn" end  -- Reya's Cairn: single bell tone
  if current_map_id == 26 then return "woods" end  -- Far Hills: woods theme (rolling hills, scattered trees)
  -- Region expansion (2026-05-14) — placeholders, theme strings replaced per phase
  if current_map_id == 35 then return "sunward_coast" end
  if current_map_id == 36 then return "phrygian_city" end
  if current_map_id == 37 then return "phrygian_city" end  -- Ruined Drum-Hall: same Phrygian theme
  -- Note: id 19 (academy), id 23 (lirael), id 24 (observatory) already return their
  -- own placeholder strings; those themes get composed and replaced in later phases.
  if current_map_id == 7 then return "echoes" end
  if current_map_id == 8 then return "grove" end
  if current_map_id == 9 then return "grotto" end
  if current_map_id == 10 then return "dune" end
  if current_map_id == 11 then return "frost" end
  if current_map_id == 12 then return "hollow" end
  if current_map_id == 13 then return "crypt" end
  if current_map_id == 14 then return "chamber" end
  local r = get_region(player.x)
  if r == "village" then return "village"
  elseif r == "woods" then return "woods"
  else return "coast"
  end
end

-- Snap the music state to the current map's theme + tempo. Used by
-- load_game and other out-of-band relocations (the normal transition
-- writer in tick_overworld_music only fires when the theme CHANGES —
-- if a load lands in the same theme the session already had, the zone
-- tempo would otherwise never be re-applied and e.g. Lirael's 48 BPM
-- theme would play at the global 100).
function resync_zone_tempo()
  current_theme = active_theme_id()
  overworld_step = 0
  params:set("clock_tempo", overworld_tempo())
end

local function fire_ow_voice(class, scale_idx, artic_override, scale_override)
  if not scale_idx or scale_idx == 0 then return end
  -- Defensive: a malformed theme could ship a scale idx outside the
  -- 1..#scale range. active_scale()[-1] etc. is nil — guard rather
  -- than crash the clock thread with "arithmetic on a nil value".
  -- scale_override = a mode name ("aeolian", "phrygian", etc.). Lets a
  -- theme lock itself to a fixed scale regardless of the player's
  -- current JAM.mode — used by the castle siege theme so the raid
  -- always plays minor even before any mode shards are collected.
  local sc = scale_override and JAM.scales[scale_override] or active_scale()
  local sc_val = sc[scale_idx]
  if not sc_val then return end
  local note = sc_val + JAM.root
  local freq = midi_to_freq(note)
  -- ACT 3 — World of Silence: while the silence holds, every voice
  -- routed through here keeps its rhythm and register but loses its
  -- tuning — each note bends by a random continuous offset up to ±6
  -- semitones (bible: "the melody is still there, structurally; it
  -- has lost only its tuning"). Both overworld AND battle themes
  -- funnel through fire_ow_voice, so fights during the silence go
  -- atonal too — deliberate (bible: atonal-mode combat, "the fights
  -- feel naked"). Scene sfx and player jam notes stay in tune.
  if CONTENT.act3_silence then
    freq = freq * (2 ^ ((math.random() * 12 - 6) / 12))
  end
  local base = OW_ARTIC[class]
  local ovr = artic_override and artic_override[class]
  local vel    = (ovr and ovr.vel)     or base.vel
  local atk    = (ovr and ovr.attack)  or base.attack
  local rel    = (ovr and ovr.release) or base.release
  local wet    = (ovr and ovr.wet)     or base.wet
  -- Scale the music's per-trig reverb send by the user-configurable mix
  -- param (default 1.0 = unscaled). 0 = bone-dry music, 2 = lush. Combat
  -- SFX (attack_sound) is scaled separately via combat_reverb_mix.
  wet = math.max(0, math.min(1, wet * (CONTENT.music_reverb_mix or 1.0)))
  sq_trig(class, freq, vel, atk, rel, wet)
end

local function tick_overworld_music()
  -- detect region transition → restart theme cleanly at step 1
  local id = active_theme_id()
  if id ~= current_theme then
    current_theme = id
    overworld_step = 0
    -- Theme-specific clock tempo override. Castle pushes the BPM up so
    -- the raid feels urgent; everything else uses the global OW BPM.
    if game_state ~= "BATTLE" then
      local theme = OW_THEMES[current_theme]
      local target = (theme and theme.bpm) or OVERWORLD_BPM
      params:set("clock_tempo", target)
    end
  end
  local theme = OW_THEMES[current_theme] or OW_THEMES.village
  overworld_step = (overworld_step % OW_PATTERN_LEN) + 1
  for class, pat in pairs(theme.pattern) do
    fire_ow_voice(class, pat[overworld_step], theme.artic, theme.scale)
  end
  -- Castle bashing ambient (Pass 62). After the courtyard gate has been
  -- breached and Miel has run back inside, silencers pound on the
  -- now-barred south hallway doors. We fire a low thud + a faint shake
  -- every ~6 seconds while the player is in any castle map and the
  -- prologue still isn't over (escape via tapestry resolves it).
  if CONTENT.courtyard_breached
     and not CONTENT.prologue_scene_done
     and (current_map_id == 20 or current_map_id == 27 or current_map_id == 28
          or current_map_id == 29 or current_map_id == 30 or current_map_id == 31) then
    if (tick % 24) == 0 then
      sq_trig("warrior", midi_to_freq(22), 0.85, 0.001, 0.45, 0.20)
      ANIM.shake(1, 4)
    elseif (tick % 24) == 6 then
      -- a second softer hit on the off-beat for procession
      sq_trig("warrior", midi_to_freq(24), 0.55, 0.001, 0.30, 0.15)
    end
  end
  -- Lirael returning voice (Task 4.7). After the broken cadence fight is
  -- won, flag.lirael_theme_shifted is set and the bard voice "returns" —
  -- a gentle A3/E3 figure that emerges like a presence remembered. Three
  -- sparse notes across the loop, fired directly so they bypass the empty
  -- bard pattern without modifying fire_ow_voice.
  if current_theme == "lirael" and flag.lirael_theme_shifted then
    local sc = active_scale()
    local _crm = CONTENT.music_reverb_mix or 1.0
    if overworld_step == 25 then
      -- bar 2 beat 3: first breath — soft A3
      local f = midi_to_freq((sc[15] or 69) + JAM.root)
      sq_trig("bard", f, 0.38, 1.50, 7.0, math.min(1, 0.96 * _crm))
    elseif overworld_step == 89 then
      -- bar 6 beat 1: E3 response — a fifth below, tentative
      local f = midi_to_freq((sc[12] or 64) + JAM.root)
      sq_trig("bard", f, 0.30, 1.80, 6.5, math.min(1, 0.96 * _crm))
    elseif overworld_step == 113 then
      -- bar 7 beat 3: return to A3 — voice settling back in
      local f = midi_to_freq((sc[15] or 69) + JAM.root)
      sq_trig("bard", f, 0.35, 1.20, 8.0, math.min(1, 0.97 * _crm))
    end
  end
end

local function fire_title_voice(class, scale_idx)
  if not scale_idx or scale_idx == 0 then return end
  local sc_val = active_scale()[scale_idx]
  if not sc_val then return end   -- guard BEFORE arithmetic (nil + would crash the clock)
  local note = sc_val + JAM.root
  local freq = midi_to_freq(note)
  local a = TITLE_ARTIC[class]
  local w = math.max(0, math.min(1, a.wet * (CONTENT.music_reverb_mix or 1.0)))
  sq_trig(class, freq, a.vel, a.attack, a.release, w)
end

local function tick_title_music()
  title_step = (title_step % TITLE_PATTERN_LEN) + 1
  for class, pat in pairs(TITLE_PATTERN) do
