    end
    redraw()
    return
  end
  if t == 77 and current_map_id == 24 then
    -- Observatory crypt_stair → Cave 6 (Locrian Crypt, map 13).
    -- Gated by flag.iolas_letter_received; tile 77 at row 11 col 16 of observatory_map.
    if flag.iolas_letter_received then
      CONTENT.return_map = 24
      CONTENT.return_x = nx; CONTENT.return_y = ny
      travel_to(13, 9, 14)   -- spawn 1 tile above the crypt exit row (row 15 cols 8-9)
      CONTENT.cave_entered = CONTENT.cave_entered or {}
      if not CONTENT.cave_entered[6] then
        CONTENT.cave_entered[6] = true; if STORY.play_id("enter_cave6") then return end
      end
    else
      CONTENT.banner_text  = "* sealed by Velthe's mark *"
      CONTENT.banner_ticks = 48
    end
    redraw()
    return
  end
  if t == 17 then
    -- Interior exit door: pop back to the saved overworld position.
    -- Inn-rest (leaving map 5) is the canonical "campfire moment" that
    -- surfaces an unseen party-banter scene; shop / cave exits should not.
    local was_inn = (current_map_id == 5 or current_map_id == 17 or current_map_id == 18)
    local rm = CONTENT.return_map or 1
    local rx = CONTENT.return_x or 4
    local ry = CONTENT.return_y or 8
    CONTENT.return_map = nil
    CONTENT.return_x = nil; CONTENT.return_y = nil
    -- Leaving any interior (house, cave, shop...): restore the OUTER
    -- warp (e.g. Sunward->mainland signpost) that the interior entry
    -- stashed, so region exits still return the player to their
    -- original overworld position.
    if CONTENT.outer_return then
      CONTENT.return_map = CONTENT.outer_return.m
      CONTENT.return_x   = CONTENT.outer_return.x
      CONTENT.return_y   = CONTENT.outer_return.y
      CONTENT.outer_return = nil
    end
    travel_to(rm, rx, ry)
    if was_inn and STORY.play() then return end
    -- One-shot Strom dream: first inn rest with Strom in the active
    -- party. A black-screen flashback (just SFX + dialogue, no actors)
    -- of his last morning with Reya before the campaign that lost her.
    if was_inn and class_in_party and class_in_party("warrior")
       and not (CONTENT.scene_seen and CONTENT.scene_seen.strom_dream)
       and start_strom_dream_scene then
      CONTENT.scene_seen = CONTENT.scene_seen or {}
      CONTENT.scene_seen.strom_dream = true
      start_strom_dream_scene()
      return
    end
    -- After inn rest with no story scene queued, occasionally fire a
    -- choreographed "dawn departure" beat: party members spawn briefly
    -- around the player and exchange a single-line greeting before the
    -- day starts. Fires ~25% of the time to keep it fresh.
    if was_inn and #party >= 2 and math.random() < 0.25
       and start_inn_dawn_scene then
      start_inn_dawn_scene()
      return
    end
    redraw()
    return
  end
  if is_walkable(nx, ny) and not npc_at(nx, ny) then
    -- Pass 53: footstep dust puff at the previous tile (in screen coords).
    -- Apply the same interior_view_offset the player/NPC renderers use,
    -- otherwise puffs land in the centering margin on small interior maps.
    do
      local view_ox, view_oy = interior_view_offset()
      local sx = (player.x - cam.x) * TILE + 4 + view_ox
      local sy = (player.y - cam.y) * TILE + 7 + view_oy
      ANIM.dust_puff(sx, sy)
    end
    player.x = nx
    player.y = ny
    update_camera()
    -- NPC bark check: any visible NPC within 3 tiles (Manhattan) of the
    -- player rolls for a bark if its cooldown has elapsed. One bark
    -- visible at a time per NPC; barks themselves auto-expire after ~90
    -- ticks via the prune in draw_overworld.
    for _, n in ipairs(npcs) do
      if n.barks and #n.barks > 0 and npc_visible(n) then
        local md = math.abs(n.x - player.x) + math.abs(n.y - player.y)
        if md <= 3 and (tick - (n._bark_t or -9999)) > 240 and math.random() < 0.25 then
          n._bark_t = tick
          local line = n.barks[math.random(#n.barks)]
          CONTENT.barks[#CONTENT.barks + 1] = {name = n.name, line = line, t = tick}
        end
      end
    end
    -- Castle prologue: fires the throne-room confrontation the first
    -- time Miel crosses into the throne hall (row <=5 — she's come up
    -- from the south hallway doors and is now on the throne hall
    -- floor). Only fires after the intro beat played and before the
    -- scene has already played.
    if current_map_id == 20
       and CONTENT.prologue_intro_done
       and not CONTENT.prologue_scene_done
       and player.y <= 5
       and not (SCENE and SCENE.active)
       and start_prologue_throne_scene then
      start_prologue_throne_scene()
      return
    end
    -- Ambient Alder-plays scene: very rare (~0.5%), only when walking
    -- the village clearing with Alder in party AND no other scene/
    -- battle pending. He stops to play one short phrase, then walking
    -- resumes. CONTENT.alder_ambient_t throttles to once per minute or so.
    if current_map_id == 1
       and class_in_party("bard")
       and get_region(player.x) == "village"
       and not (SCENE and SCENE.active)
       and (tick - (CONTENT.alder_ambient_t or -9999)) > 1200
       and math.random() < 0.005
       and start_alder_ambient_scene then
      CONTENT.alder_ambient_t = tick
      start_alder_ambient_scene()
      return
    end
    -- Campfire pickup: heal party 25% HP if standing on a campfire.
    -- First-time visits trigger a small party-memory scene. Each fire's
    -- scene list is ordered by specificity; we run the first scene whose
    -- required classes are ALL currently in active party. This way scenes
    -- featuring Diegues/Strom/Alder don't fire before they've joined.
    local fire_scene_started = false
    for fi, f in ipairs(CONTENT.campfires) do
      if f.map == current_map_id and f.x == nx and f.y == ny then
        for _, q in ipairs(party) do
          if q.alive then q.hp = math.min(q.hp_max, q.hp + math.floor(q.hp_max * 0.25)) end
        end
        CONTENT.flash_text = "+25% HP all"
        CONTENT.flash_ticks = 24
        CONTENT.fire_seen = CONTENT.fire_seen or {}
        if not CONTENT.fire_seen[fi] then
          local lines = pick_campfire_scene(f.map, f.x, f.y)
          if lines then
            CONTENT.fire_seen[fi] = true
            -- Choreographed seating: party gathers around the flame, then
            -- the memory beat plays as dialogue.
            if start_campfire_scene then
              fire_scene_started = start_campfire_scene(f, lines)
            end
            -- Fallback to plain dialogue if the scene helper bailed.
            if not fire_scene_started then
              dlg.lines = pack_dialogue_lines(lines, nil)
              dlg.line = 1
              dlg.npc = nil
              game_state = "DIALOGUE"
              fire_scene_started = true
            end
          end
        end
        break
      end
    end
    if fire_scene_started then redraw(); return end
    -- chest pickup: scan all chests for one at the player's new position
    for _, c in ipairs(CONTENT.chests) do
      if c.map == current_map_id and c.x == nx and c.y == ny and not CONTENT.opened[c.id] then
        if c.locked then
          if SHOP.inv.key and SHOP.inv.key > 0 then
            SHOP.inv.key = SHOP.inv.key - 1
            CONTENT.opened[c.id] = true
            local msg = "Unlocked!"
            if c.loot.g then
              SHOP.gold = SHOP.gold + c.loot.g
              msg = msg .. "  +" .. c.loot.g .. "g"
            end
            if c.loot.item then
              SHOP.inv[c.loot.item] = (SHOP.inv[c.loot.item] or 0) + 1
              msg = msg .. "  +1 " .. c.loot.item
            end
            if c.loot.instrument and INSTRUMENTS[c.loot.instrument] then
              instruments_owned[c.loot.instrument] = true
              msg = msg .. "  + " .. INSTRUMENTS[c.loot.instrument].name
            end
            CONTENT.flash_text = msg
            CONTENT.flash_ticks = 42
          else
            CONTENT.flash_text = "Locked. Need a Key."
            CONTENT.flash_ticks = 30
          end
        else
          CONTENT.opened[c.id] = true
          local msg = "Chest!"
          if c.loot.g then
            SHOP.gold = SHOP.gold + c.loot.g
            msg = "+" .. c.loot.g .. "g"
          end
          if c.loot.item then
            SHOP.inv[c.loot.item] = (SHOP.inv[c.loot.item] or 0) + 1
            msg = msg .. "  +1 " .. c.loot.item
          end
          if c.loot.instrument and INSTRUMENTS[c.loot.instrument] then
            instruments_owned[c.loot.instrument] = true
            msg = msg .. "  + " .. INSTRUMENTS[c.loot.instrument].name
          end
          CONTENT.flash_text = msg
          CONTENT.flash_ticks = 36
        end
        break
      end
    end
    -- Observatory: Velthe's Final Entry — one-shot lore scene (Task 3.9).
    -- Fires when player steps onto the desk tile (col 12, row 8) in map 24,
    -- only after iolas_letter_received is true and before velthes_entry_heard
    -- is set. Takes precedence over ambient scenes (not throttled).
    if current_map_id == 24 and nx == 12 and ny == 8
       and flag.iolas_letter_received and not flag.velthes_entry_heard
       and not (SCENE and SCENE.active) then
      if start_observatory_velthes_entry_scene then
        SCENE.start(start_observatory_velthes_entry_scene())
        redraw()
        return
      end
    end
    -- Lirael: Miel Walks Alone — one-shot cathedral scene (Task 4.5).
    -- Fires when player first steps onto the cathedral_door tile (88) in
    -- map 23 (row 8, cols 19-20 — double-wide entryway) from the south.
    if current_map_id == 23 and map[ny] and map[ny][nx] == 88
       and not flag.miel_walks_alone_done
       and not (SCENE and SCENE.active) then
      if start_lirael_miel_walks_alone_scene then
        SCENE.start(start_lirael_miel_walks_alone_scene())
        redraw()
        return
      end
    end
    -- Lirael: Broken Cadence boss — Task 4.6.
    -- Fires when player steps onto the broken_altar tile (84) at col 18 row 2
    -- in map 23, after Miel Walks Alone is done and before the boss is beaten.
    if current_map_id == 23 and map[ny] and map[ny][nx] == 84
       and nx == 18 and ny == 2
       and flag.miel_walks_alone_done and not flag.broken_cadence_done
       and not (SCENE and SCENE.active) then
      if start_lirael_broken_cadence_scene then
        SCENE.start(start_lirael_broken_cadence_scene())
        redraw()
        return
      end
    end
    -- Sunward Coast tile micro-scenes: fire on specific tiles in map 35.
    -- Throttled to once per ~600 ticks so re-stepping doesn't spam-fire.
    if current_map_id == 35 and not (SCENE and SCENE.active) then
      local last_sw = CONTENT.last_sunward_ambient_t or -9999
      if (tick - last_sw) > 600 then
        local sc = nil
        if nx == 14 and ny == 6 then
          sc = ambient_sunward_bandstand_practice and ambient_sunward_bandstand_practice()
        elseif nx == 9 and ny == 11 then
          sc = ambient_sunward_dock_gull and ambient_sunward_dock_gull()
        elseif nx == 13 and ny == 5 then
          sc = ambient_sunward_market_cry and ambient_sunward_market_cry()
        elseif nx == 31 and ny == 7 then
          sc = ambient_sunward_cliff_reeds and ambient_sunward_cliff_reeds()
        end
        if sc then
          CONTENT.last_sunward_ambient_t = tick
          SCENE.start(sc)
          redraw()
          return
        end
      end
    end
    -- Phrygian Night City tile micro-scenes: fire on specific tiles in map 36.
    -- Throttled to once per ~600 ticks. Lantern scene is night-only.
    if current_map_id == 36 then
      local now = tick or 0
      local last = CONTENT.last_phrygian_ambient_t or 0
      if not (SCENE and SCENE.active) and now - last > 600 then
        if nx == 17 and ny == 7 then
          SCENE.start(ambient_phrygian_vendor())
          CONTENT.last_phrygian_ambient_t = now
        elseif nx == 17 and ny == 3 then
          SCENE.start(ambient_phrygian_prayer())
          CONTENT.last_phrygian_ambient_t = now
        elseif nx == 9 and ny == 5 and sq_is_night and sq_is_night() then
          SCENE.start(ambient_phrygian_lantern())
          CONTENT.last_phrygian_ambient_t = now
        elseif nx == 5 and ny == 9 then
          SCENE.start(ambient_phrygian_tova_hum())
          CONTENT.last_phrygian_ambient_t = now
        end
      end
    end
    -- Sage Hub (Academy id 19, Observatory id 24) ambients
    if current_map_id == 19 then
      local now = tick or 0
      local last = CONTENT.last_sage_hub_ambient_t or 0
      if not (SCENE and SCENE.active) and now - last > 600 then
        if nx == 21 and ny == 10 then
          SCENE.start(ambient_academy_library())
          CONTENT.last_sage_hub_ambient_t = now
        elseif nx == 13 and ny == 7 then
          SCENE.start(ambient_academy_astrolabe())
          CONTENT.last_sage_hub_ambient_t = now
        end
      end
    elseif current_map_id == 24 then
      local now = tick or 0
      local last = CONTENT.last_sage_hub_ambient_t or 0
      if not (SCENE and SCENE.active) and now - last > 600 then
        if nx == 12 and ny == 2 and sq_is_night and sq_is_night() then
          SCENE.start(ambient_observatory_stars())
          CONTENT.last_sage_hub_ambient_t = now
        elseif nx == 12 and ny == 9 and not flag.velthes_entry_heard then
          SCENE.start(ambient_observatory_desk_premature())
          CONTENT.last_sage_hub_ambient_t = now
        end
      end
    end
    -- Lirael Ruins (map 23) tile micro-scenes.
    -- Throttled to once per ~600 ticks via CONTENT.last_lirael_ambient_t.
    if current_map_id == 23 then
      local now = tick or 0
      local last = CONTENT.last_lirael_ambient_t or 0
      if not (SCENE and SCENE.active) and now - last > 600 then
        if nx == 20 and ny == 12 then
          SCENE.start(ambient_lirael_child_toy())
          CONTENT.last_lirael_ambient_t = now
        elseif nx == 2 and ny == 2 then
          SCENE.start(ambient_lirael_window())
          CONTENT.last_lirael_ambient_t = now
        elseif nx == 13 and ny == 4 then
          SCENE.start(ambient_lirael_pillar())
          CONTENT.last_lirael_ambient_t = now
        elseif nx == 33 and ny == 3 then
          SCENE.start(ambient_lirael_hymnal())
          CONTENT.last_lirael_ambient_t = now
        end
      end
    end
    -- random encounter check: only outside the village safe zone
    if try_random_encounter() then return end
  end
  redraw()
end

-- per-tick guards: prevent duplicate input events (gamepad + keyboard remap)
-- from firing the same action twice within one tick
local _dlg_advance_tick = -1
local _dlg_start_tick  = -1

-- Pack raw dialogue lines into "pages" — merge consecutive same-speaker
-- lines until each page fills the box. Uses a char-count heuristic
-- instead of screen.text_extents (which can't safely run outside the
-- redraw cycle and was silently breaking dialogue starts). Compact font
-- fits ~25 chars per line × 5 lines ≈ 125 chars per page.
-- Global to dodge the 200-local main-chunk cap.
function pack_dialogue_lines(raw, npc_name)
  if not raw or #raw == 0 then return raw end
  -- Pre-pass: any single raw line longer than MAX_CHARS gets split into
  -- pages so the renderer (3-wrapped-line cap) doesn't truncate. We
  -- cascade through delimiters of decreasing semantic weight:
  --   1. sentence punctuation .  !  ?
  --   2. clause break          --
  --   3. clause separators     ;
  --   4. comma                 ,
  --   5. word boundary         (last resort)
  -- A chunk is "too big" if it exceeds MAX_CHARS_PRE; we re-split it
  -- using the next-finer delimiter until it fits or there are no more
  -- delimiters (then we hard-split on words).
  local MAX_CHARS_PRE = 66
  local function trim(s) return (s:gsub("^%s+", ""):gsub("%s+$", "")) end
  -- Split s into pieces using a Lua pattern that captures each piece +
  -- whatever trailing delimiter lives on it, so we can reassemble without
  -- losing punctuation.
  local function pieces_by(s, pat)
    local out, i, n = {}, 1, #s
    while i <= n do
      local a, b = s:find(pat, i)
      if not a then
        out[#out + 1] = s:sub(i)
        break
      end
      out[#out + 1] = s:sub(i, b)
      i = b + 1
    end
    return out
  end
  -- Word-boundary split (last-resort) into balanced <=MAX chunks. Picks
  -- the smallest N (>=2) that fits, then targets equal-sized pages so we
  -- don't end up with an awkward 5-char orphan after a 70-char chunk.
  local function hard_word_split(s)
    local words = {}
    for word in s:gmatch("%S+") do words[#words + 1] = word end
    if #words == 0 then return {s} end
    local total = #s
    local n_pages = math.max(2, math.ceil(total / MAX_CHARS_PRE))
    local target = math.ceil(total / n_pages)
    local out, buf = {}, ""
    for _, word in ipairs(words) do
      if #buf == 0 then
        buf = word
      elseif #buf + 1 + #word <= MAX_CHARS_PRE
         and (#buf < target or #buf + 1 + #word <= MAX_CHARS_PRE and #out >= n_pages - 1) then
        buf = buf .. " " .. word
      else
        out[#out + 1] = buf
        buf = word
      end
    end
    if #buf > 0 then out[#out + 1] = buf end
    return out
  end
  -- Split a single oversize chunk by trying delimiter levels in order.
  local function split_oversize(chunk)
    if #chunk <= MAX_CHARS_PRE then return {chunk} end
    local strategies = {
      "[^.!?]+[.!?]?",     -- sentences
      "[^%-]+%-?%-?",       -- "--" clause break (ascii double-hyphen)
      "[^;]+;?",            -- semicolons
      "[^,]+,?",            -- commas
    }
    for _, pat in ipairs(strategies) do
      local subs = pieces_by(chunk, pat)
      -- only useful if the split produced more than one non-trivial piece
      local non_empty = 0
      for _, p in ipairs(subs) do if #trim(p) > 0 then non_empty = non_empty + 1 end end
      if non_empty > 1 then
        -- Recurse: each sub-chunk may itself still be oversize.
        local out = {}
        for _, p in ipairs(subs) do
          local t = trim(p)
          if #t > 0 then
            for _, q in ipairs(split_oversize(t)) do out[#out + 1] = q end
          end
        end
        return out
      end
    end
    return hard_word_split(chunk)
  end
  -- Top-level: split into sentence-ish pieces then greedily merge into
  -- pages of <= MAX_CHARS_PRE. Each piece is itself pre-split if it's
  -- too long on its own.
  local function split_long(s)
    if #s <= MAX_CHARS_PRE then return {s} end
    -- Protect "..." from the sentence pattern below, which would read
    -- it as three sentence ends (orphan "." pages, mangled ellipses).
    -- \1 is unused in dialogue text; three of them keep lengths exact.
    s = s:gsub("%.%.%.", "\1\1\1")
    local out, buf = {}, ""
    local pieces = pieces_by(s, "[^.!?]+[.!?]?")
    -- Re-split any piece that's too big using the finer-grained cascade.
    local refined = {}
    for _, p in ipairs(pieces) do
      local t = trim(p)
      if #t == 0 then goto cont1 end
      if #t > MAX_CHARS_PRE then
        for _, q in ipairs(split_oversize(t)) do refined[#refined + 1] = q end
      else
        refined[#refined + 1] = t
      end
      ::cont1::
    end
    for _, sentence in ipairs(refined) do
      if #buf == 0 then
        buf = sentence
      elseif (#buf + 1 + #sentence) <= MAX_CHARS_PRE then
        buf = buf .. " " .. sentence
      else
        out[#out + 1] = buf
        buf = sentence
      end
    end
    if #buf > 0 then out[#out + 1] = buf end
    for i = 1, #out do
      out[i] = out[i]:gsub("\1\1\1", "...")
      -- The comma-cascade can split inside a stage direction and leave
      -- a page ending in " )" — reattach the paren to its last word.
      out[i] = out[i]:gsub("%s+%)", ")")
    end
    return out
  end
  -- Preserve speaker prefix across splits: if the source line is tagged
  -- `[Name] body...`, every produced chunk keeps the same `[Name] ` prefix
  -- so the main packer (which only merges same-speaker chunks) sees
  -- consistent tags.
  local expanded = {}
  for _, line in ipairs(raw) do
    local sp_pre, body_pre = line:match("^(%[[^%]]+%]%s*)(.*)$")
    if sp_pre and #body_pre > 0 and #line > MAX_CHARS_PRE then
      for _, piece in ipairs(split_long(body_pre)) do
        expanded[#expanded + 1] = sp_pre .. piece
      end
    else
      for _, piece in ipairs(split_long(line)) do
        expanded[#expanded + 1] = piece
      end
    end
  end
  raw = expanded
  -- Scrub characters the Tom Thumb font can't render — em-dash (—) and
  -- en-dash (–) both come out as blank space on the norns. Replace them
  -- with "..." which reads as a pause in dialogue, then collapse any
  -- runs of multiple spaces back down to one. Also strip any redundant
  -- "<NpcName>:" prefix so the dialogue box header doesn't duplicate the
  -- name (the name + sprite already appear in the box's top strip).
  local function escape(s) return (s:gsub("(%W)", "%%%1")) end
  local function clean(s)
    s = s:gsub("\xE2\x80\x94", "--")   -- em-dash UTF-8 → typewriter double-hyphen
    s = s:gsub("\xE2\x80\x93", "-")    -- en-dash UTF-8 → single hyphen
    if npc_name and #npc_name > 0 then
      s = s:gsub("^" .. escape(npc_name) .. ":%s*", "")
    end
    s = s:gsub("  +", " ")
    return s
  end
  local out = {}
  -- Two budgets:
  --   MAX_CHARS — hard cap on a packed body (~3 lines of compact font).
  --   DEFAULT_FONT_CAP — soft cap below which the renderer keeps the
  --     larger default font. Above it, the renderer hops to compact
  --     (small) font, which the player perceives as inconsistent.
  -- We try not to merge ABOVE the soft cap so most pages stay default.
  -- Tagged speech lines may still cross into compact when very long —
  -- that's fine, but narrator lines (no speaker prefix) are kept
  -- below the soft cap so they always render in the same big font.
  local MAX_CHARS = 66
  local DEFAULT_FONT_CAP = 55   -- ~3 lines of default font in 122px wrap
  local i = 1
  while i <= #raw do
    local first = clean(raw[i])
    -- Same tag pattern as draw_dialogue: allows spaces ("[Cave Echo]").
    local sp1, body1 = first:match("^%[([^%]]+)%]%s*(.*)$")
    local prefix = sp1 and ("[" .. sp1 .. "] ") or ""
    local body_acc = body1 or first
    local consumed = 1
    -- Narrator (no speaker) gets the smaller cap so we don't force the
    -- font into compact via over-merge.
    local cap = (sp1 == nil) and DEFAULT_FONT_CAP or MAX_CHARS
    while i + consumed <= #raw do
      local nxt = clean(raw[i + consumed])
      local sp2, body2 = nxt:match("^%[([^%]]+)%]%s*(.*)$")
      if (sp1 or "") ~= (sp2 or "") then break end
      local trial = body_acc .. " " .. (body2 or nxt)
      if #trial > cap then break end
      body_acc = trial
      consumed = consumed + 1
    end
    out[#out + 1] = prefix .. body_acc
    i = i + consumed
  end
  return out
end

start_dialogue = function(npc)
  if _dlg_start_tick == tick then return end
  _dlg_start_tick = tick
  -- An NPC may declare a `scene` (function returning a SCENE script).
  -- Evaluate it BEFORE the quest-flag block below: first-meeting scenes
  -- gate on QUESTS.tova.spoke flags, and setting the flag first made
  -- every sage's choreographed first meeting bail straight to plain
  -- dialogue — the scenes were dead content.
  local scene_script = nil
  if npc.scene and type(npc.scene) == "function" then
    -- Defensive: if a scene function errors, fall through to standard
    -- dialogue rather than freezing the game.
    local ok, script = pcall(npc.scene)
    if ok then
      scene_script = script
    else
      CONTENT.banner_text  = "* scene err: " .. tostring(script):sub(1, 30) .. " *"
      CONTENT.banner_ticks = 60
      print("synth-quest: scene err for " .. tostring(npc.name) .. ": " .. tostring(script))
    end
  end
  -- Tova's sidequest: track when player meets each regional sage.
  -- Keyed on name AND home map: other NPCs share these names (Mira in
  -- Phrygian City, Iolen on the Sunward Coast, Aurin at the academy)
  -- and were silently crediting the quest + suppressing the real
  -- sages' first meetings.
  local SAGE_HOME_MAP = {Veris = 1, Aurin = 1, Mira = 2, Iolen = 3}
  if npc and SAGE_HOME_MAP[npc.name]
     and current_map_id == SAGE_HOME_MAP[npc.name] then
    QUESTS.tova.spoke[npc.name] = true
  end
  if scene_script then
    SCENE.start(scene_script)
    return
  end
  dlg.npc = npc
  dlg.line = 1
  -- Reset typewriter state so the new dialogue starts a fresh reveal.
  dlg.line_start_tick = tick
  dlg.line_start_time = nil   -- real-time typewriter re-inits on next draw
  dlg.complete = false
  dlg.snap_to_complete = false
  -- Defensive: any error from npc.dialogue() (or pack_dialogue_lines)
  -- gets caught and surfaced as a banner instead of silently freezing
  -- the game in DIALOGUE state with no lines to advance through.
  local raw = npc.dialogue
  local raw_lines
  if type(raw) == "function" then
    local ok, result = pcall(raw)
    if ok then
      raw_lines = result
    else
      print("synth-quest: dialogue err for " .. tostring(npc.name) .. ": " .. tostring(result))
      raw_lines = {"(error in dialogue: " .. tostring(result):sub(1, 40) .. ")"}
    end
  else
    raw_lines = raw
  end
  -- pack might also throw (Lua-pattern edge cases). Same defensive guard.
  local ok, packed = pcall(pack_dialogue_lines, raw_lines, npc and npc.name)
  if ok then
    dlg.lines = packed
  else
    print("synth-quest: pack err for " .. tostring(npc.name) .. ": " .. tostring(packed))
    dlg.lines = {"(error packing dialogue)"}
  end
  -- Final guard: if dlg.lines is nil or empty, drop straight back to
  -- overworld instead of getting stuck in DIALOGUE with nothing to render.
  if not dlg.lines or #dlg.lines == 0 then
    dlg.lines = {"(empty dialogue)"}
  end
  game_state = "DIALOGUE"
  redraw()
end

local function advance_dialogue()
  if _dlg_advance_tick == tick then return end
  _dlg_advance_tick = tick
  -- FF-style two-press behavior: if the typewriter hasn't finished
  -- revealing the current line, the first A snaps it to complete; the
  -- second A actually advances. dlg.complete is set in draw_dialogue
  -- once `revealed` reaches the body length.
  if not dlg.complete and not dlg.snap_to_complete then
    dlg.snap_to_complete = true
    redraw()
    return
  end
  dlg.snap_to_complete = false
  dlg.complete = false
  dlg.line_start_tick = tick
  dlg.line_start_time = nil   -- real-time typewriter re-inits on next draw
  dlg.line = dlg.line + 1
  if dlg.line > #(dlg.lines or {}) then
    local npc = dlg.npc
    dlg.npc = nil
    dlg.lines = nil
    -- Story-arc post-dialogue hook: a previous frame can stash a function
    -- in CONTENT.post_dialogue and it runs once at close. Used by the
    -- academy arc to chain entry-cutscene → battle → epilogue → join.
    local hook = CONTENT.post_dialogue
    CONTENT.post_dialogue = nil
    if hook then
      -- Defensive: a buggy post-dialogue hook would otherwise leave the
      -- player stuck in DIALOGUE state with a half-cleared dlg table.
      -- Catch the error, surface a banner, and drop back to overworld.
      local ok, err = pcall(hook)
      if not ok then
        print("synth-quest: post_dialogue err: " .. tostring(err))
        CONTENT.banner_text  = "* hook err: " .. tostring(err):sub(1, 30) .. " *"
        CONTENT.banner_ticks = 60
        game_state = "OVERWORLD"
      end
      redraw()
      return
    end
    -- Hens (mainland shop) and Marek (eastern shop) both open the
    -- SHOP UI when their dialogue ends; other NPCs return to overworld.
    if npc and (npc.name == "Hens" or npc.name == "Marek" or npc.name == "Skari") then
      SHOP.idx = 1
      SHOP.step = 0
      game_state = "SHOP"
    else
      game_state = "OVERWORLD"
    end
  end
  redraw()
end

-- ============================================================ BATTLE

-- Spawn a floating number above the given screen coords. lev: 15=normal,
-- 13=crit (hot), 11=heal (green-tinged on grayscale), 8=blocked.
ANIM.spawn_dmg = function(x, y, amt, lev)
  table.insert(ANIM.popups, {x = x, y = y, amt = amt, lev = lev or 15, t = tick})
end

-- ELEMENTAL AFFINITIES (Pass 58). Each enemy visual maps to a weak
-- and resist mode. When the active JAM.mode matches `weak`, damage is
-- multiplied by 1.5x and a "WEAK!" banner fires; when it matches
-- `resist`, damage is halved and a "RESIST" banner fires. Mode
-- defaults to nil for both = neutral. Bestiary will show these in a
-- future pass; for now they only affect combat numbers.
ELEMENTAL_AFFINITY = {
  slime      = {weak = "phrygian",   resist = "aeolian"},
  bat        = {weak = "lydian",     resist = "locrian"},
  mushroom   = {weak = "phrygian",   resist = "aeolian"},
  wisp       = {weak = "aeolian",    resist = "lydian"},
  wolf       = {weak = "mixolydian", resist = "phrygian"},
  echo       = {weak = "lydian",     resist = "aeolian"},
  sprite     = {weak = "aeolian",    resist = "lydian"},
  treant     = {weak = "phrygian",   resist = "dorian"},
  sentinel   = {weak = "phrygian",   resist = "aeolian"},
  crab       = {weak = "phrygian",   resist = "mixolydian"},
  manta      = {weak = "lydian",     resist = "mixolydian"},
  tide       = {weak = "aeolian",    resist = "mixolydian"},
  scorpion   = {weak = "aeolian",    resist = "phrygian"},
  spectre    = {weak = "ionian",     resist = "locrian"},
  dunerider  = {weak = "aeolian",    resist = "phrygian"},
  yeti       = {weak = "phrygian",   resist = "aeolian"},
  frostwisp  = {weak = "phrygian",   resist = "aeolian"},
  granite    = {weak = "dorian",     resist = "aeolian"},
  crow       = {weak = "lydian",     resist = "locrian"},
  snowgaunt  = {weak = "phrygian",   resist = "aeolian"},
  -- Ice Grotto canon set
  acolyte      = {weak = "phrygian", resist = "aeolian"},
  hollowbell   = {weak = "phrygian", resist = "aeolian"},
  brokenchoir  = {weak = "ionian",   resist = "locrian"},   -- a choir that needs resolving
  drownedsinger= {weak = "lydian",   resist = "aeolian"},   -- bright air against the waterlog
  sunolieut    = {weak = "ionian",   resist = "locrian"},   -- Suno's forces resist the unresolved
  lich       = {weak = "ionian",     resist = "locrian"},
  voidcrawler= {weak = "lydian",     resist = "locrian"},
  echosuno   = {weak = "lydian",     resist = "locrian"},
  mutewarden = {weak = "ionian",     resist = "locrian"},
  locrius    = {weak = "ionian",     resist = "locrian"},
  suno       = {weak = "ionian",     resist = "locrian"},
  -- The Broken Cadence: a song that won't resolve. Ionian is the cadence
  -- home (resolution) so it's the weakness; Locrian (the unresolved
  -- tritone) is what it's already made of, so it resists.
  broken_cadence = {weak = "ionian", resist = "locrian"},
  -- Strom (story battle), the Silencer (pre-modes prologue), the First
  -- Chord (post-game; "all voices", beyond any one mode) and the dummy:
  -- no affinity, neutral damage.
}

local function damage_enemy(amount, is_crit)
  -- Defensive: enemy can be nil if a kill earlier in the same tick
  -- (Strom-arc / prologue-silencer / prologue-cave bypass paths set
  -- `enemy = nil` synchronously). The LIMIT-break damage path used to
  -- crash the clock thread here.
  if not enemy then return end
  -- Damage popup x is moved to 60 (was 96) so the rising number doesn't
  -- pass through the enemy HP bar (x=76..126) or HP X/Y text on its way
  -- up. Lands in the free gap between the action popup (x=1..44) and
  -- the HP bar. The crit particle burst stays at x=96 — it's a distinct
  -- on-enemy effect, not a number.
  if enemy.invincible then
    -- Practice dummy: show damage numbers but never lose HP or die
    ANIM.spawn_dmg(60, 22, amount, is_crit and 13 or 15)
    if is_crit then ANIM.crit_flash = tick; ANIM.burst(96, 32, 6, 15) end
    return
  end
  -- Apply elemental affinity multiplier based on the active JAM.mode
  -- and the enemy's visual key. Banner is one-shot per hit (60 ticks).
  local aff = ELEMENTAL_AFFINITY[enemy.visual or ""]
  if aff and JAM and JAM.mode then
    if aff.weak == JAM.mode then
      amount = math.floor(amount * 1.5)
      CONTENT.banner_text  = "* WEAK! *"
      CONTENT.banner_ticks = 30
    elseif aff.resist == JAM.mode then
      amount = math.max(1, math.floor(amount * 0.5))
      CONTENT.banner_text  = "* RESIST *"
      CONTENT.banner_ticks = 30
    end
  end
  enemy.hp = math.max(0, enemy.hp - amount)
  ANIM.spawn_dmg(60, 22, amount, is_crit and 13 or 15)
  if is_crit then
    -- Crit FX: brief crit_flash (handled by ANIM.draw_action_fx) + a small
    -- particle burst. No screen-wide hit-flash stipple — it was washing
    -- the screen in white dots and being more distracting than punchy.
    ANIM.crit_flash = tick
    ANIM.burst(96, 32, 6, 15)
  else
    -- non-crit hit gets a tiny burst too (smaller, dimmer)
    ANIM.burst(96, 32, 3, 11)
  end
  if enemy.hp == 0 then
    enemy.alive = false
    -- Strom-arc battle (Diegues academy story): bypass the standard
    -- victory window + XP/loot path entirely. The defeat triggers a
    -- bespoke epilogue dialogue that adds Strom to the party.
    -- IMPORTANT: switch game_state out of "BATTLE" BEFORE calling
    -- finish_academy_arc(). The SCENE engine only ticks while in
    -- OVERWORLD/DIALOGUE; if we leave game_state on "BATTLE" the scene
    -- never advances and the on_complete callback never fires, leaving
    -- the player softlocked in a battle with no enemy.
    if enemy.is_strom_arc then
      enemy = nil
      battle_outcome = nil
      game_state = "OVERWORLD"
      params:set("clock_tempo", overworld_tempo())  -- academy runs 110
      -- Bypass exits skip exit_battle, so scrub battle state here or
      -- poison/sleep/tonic/reso arms picked up in this fight resume at
      -- the start of the NEXT battle.
      if scrub_battle_statuses then scrub_battle_statuses() end
      finish_academy_arc()
      return
    end
    -- Prologue silencers / cave monsters: scripted tutorial enemies.
    -- Previously these bypassed BATTLE_END entirely; now they route
    -- through the standard XP-summary screen like every other kill so
    -- the player sees the +XP / level-up panel. The post-fight
    -- bookkeeping (silencer_defeated / cave_monster_defeated flags)
    -- happens in exit_battle below when A dismisses the panel.
    -- Lirael Broken Cadence (Task 4.6): one-shot boss in the nave.
    -- Bypass the standard victory/XP window; finish_broken_cadence
    -- handles XP, flag, and Key of Lirael grant directly.
    if enemy.is_broken_cadence then
      enemy = nil
      battle_outcome = nil
      game_state = "OVERWORLD"
      params:set("clock_tempo", overworld_tempo())  -- Lirael runs 48
      if scrub_battle_statuses then scrub_battle_statuses() end
      finish_broken_cadence()
      return
    end
    -- Snapshot per-class levels BEFORE awarding XP so the victory summary
    -- slide can display "Lv.3 → Lv.4" for any party member that levelled.
    local pre_levels = {}
    for _, p in ipairs(party) do pre_levels[p.class] = p.level end
    local xp_amount = enemy_xp(enemy.name)
    gain_xp(xp_amount)
    -- Build the summary table consumed by draw_battle_end_xp(). xp_cur =
    -- progress toward next level (resets to 0 on level-up); xp_next = the
    -- threshold to advance from p.level. At LEVEL_CAP we surface "MAX".
    CONTENT.xp_summary = {amount = xp_amount, gains = {}}
    for _, p in ipairs(party) do
      if p.alive then
        local pre = pre_levels[p.class] or p.level
        local at_cap = (p.level >= LEVEL_CAP)
        table.insert(CONTENT.xp_summary.gains, {
          class    = p.class,
          pre      = pre,
          post     = p.level,
          leveled  = p.level > pre,
          xp_cur   = p.xp or 0,
          xp_next  = at_cap and 0 or xp_for_level(p.level),
          at_cap   = at_cap,
        })
      end
    end
    SHOP.last_gold = enemy_gold(enemy.name)
    SHOP.gold = SHOP.gold + SHOP.last_gold
    -- bestiary: record this enemy as seen (visual key + name + max stats).
    -- Rares are keyed by NAME so a greater strain never clobbers the base
    -- monster's (or a boss's) visual-keyed entry — their `visual` field
    -- still points at the base art for the sprite/lore lookups.
    CONTENT.bestiary[(enemy.is_rare and enemy.name) or enemy.visual or enemy.name] = {
      name = enemy.name,
      hp_max = enemy.hp_max,
      atk = enemy.atk,
      visual = enemy.visual,
    }
  end
end

-- find the HUD column x for a given party member (index 1..4)
ANIM.party_hud_x = function(p)
  for i, q in ipairs(party) do
    if q == p then return (i - 1) * 32 + 17 end
  end
  return 16
end

-- ── Resonance invocation animations ──────────────────────────────────
-- Each function spawns particles attached to the casting character's
-- combat sprite position. See docs/specs/2026-05-19-resonance-fluid-
-- invocation-design.md for the per-Resonance vocabulary.
-- Sprite position for party member p: (cx+1, 49) where cx = ANIM.party_hud_x(p).
-- Animations target sprite center (cx+5, 53) unless otherwise noted.
-- Functions and dispatcher are intentionally global (no `local`) because
-- the main chunk has hit Lua's 200-local-variable limit.

-- Dispatch a Resonance's combat effect at invoke time. Ring arms a
-- consumed-on-next-ATK buff; others push RESO_FX timed effects, set
-- counters, or mark the enemy. See docs/specs/2026-05-20-resonance-effects-design.md.
function apply_resonance_effect(rid, p)
  if rid == "ring" then
    p.ring_armed = true
  elseif rid == "heavy_hand" then
    reso_fx_add("duck_enemies", 2 * RESO_BAR, {mult = 0.50})
  elseif rid == "long_echo" then
    p.long_echo_charges = 2
  elseif rid == "scatter" then
    if enemy and enemy.attack_pattern then
      enemy.confused_until = (tick or 0) + 4 * RESO_BAR
      local ap = enemy.attack_pattern
      for i = #ap, 2, -1 do
        local j = math.random(i)
        ap[i], ap[j] = ap[j], ap[i]
      end
      enemy.pattern_idx = 1
    end
  elseif rid == "slow_wheel" then
    reso_fx_add("slow_wheel", 4 * RESO_BAR, {spd = 1})
  elseif rid == "masked_voice" then
    reso_fx_add("masked_voice", 1 * RESO_BAR, {mult = 1.25})
  elseif rid == "threefold" then
    p.threefold_until = (tick or 0) + 1 * RESO_BAR
  elseif rid == "spring" then
    -- Spring reverb: arm the heal-echo. The next party heal repeats twice
    -- more at 25% each, one bar apart (consumed in heal_party).
    CONTENT.spring_echo = true
  end
end

function play_ring_anim(p)
  -- Ring modulator: 3 concentric expanding pixel rings from the character's
  -- sprite center. Brightness 15, 13, 11; radii expand 1px/tick. Staggered
  -- start so the rings ripple outward in sequence.
  local cx = ANIM.party_hud_x(p) + 5   -- sprite center x
  local cy = 53                         -- sprite center y
  for i = 0, 2 do
    ANIM.particles[#ANIM.particles + 1] = {
      kind = "ring",
      x = cx, y = cy,
      r0 = 1 + i * 2,        -- starting radius for this ring
      lev = 15 - i * 2,      -- 15, 13, 11
      t = tick + i * 2,      -- staggered start (T0, T+2, T+4)
      dur = 14,
    }
  end
end

function play_long_echo_anim(p)
  -- Tape echo two-head: two ghost-copies of the character spawn at +1px
  -- and +2px to the right of the live sprite. The closer copy fades over
  -- 6 ticks, the further copy over 10. Reads as the singer echoing.
  local cx = ANIM.party_hud_x(p) + 1   -- sprite top-left x (matches draw_battle)
  local sy = 49
  ANIM.ghost_sprite(p.class, cx + 1, sy, 8, 6)
  ANIM.ghost_sprite(p.class, cx + 2, sy, 4, 10)
end

function play_threefold_anim(p)
  -- Vintage chorus: two ghost-copies spawn at -1px and +1px simultaneously,
  -- both held at brightness 7 for 16 ticks. Three sprites visible at once
  -- during the held phase.
  local cx = ANIM.party_hud_x(p) + 1
  local sy = 49
  ANIM.ghost_sprite(p.class, cx - 1, sy, 7, 16)
  ANIM.ghost_sprite(p.class, cx + 1, sy, 7, 16)
end

function play_masked_voice_anim(p)
  -- Vocoder: thin horizontal bar overlays the character's eyes for 4 ticks,
  -- then dissipates upward as 3 small particles drifting straight up.
  local cx = ANIM.party_hud_x(p) + 1
  local sy = 49
  -- The mask bar
  ANIM.particles[#ANIM.particles + 1] = {
    kind = "mask_bar",
    x = cx + 1, y = sy + 2,
    w = 6, h = 1,
    lev = 13,
    t = tick, dur = 4,
  }
  -- 3 upward-drifting sparks (start 4 ticks later)
  for i = 1, 3 do
    ANIM.particles[#ANIM.particles + 1] = {
      kind = "spark",
      x = cx + 1 + (i * 2),
      y = sy + 2,
      vx = 0,
      vy = -0.4,
      t = tick + 4, lev = 11,
    }
  end
end

function play_spring_anim(p)
  -- Spring reverb: 4 horizontal wavy pixel-lines emanate left and right
  -- from the character, sinusoidally oscillating outward. Fades over 14.
  local cx = ANIM.party_hud_x(p) + 5
  local cy = 53
  for i = 1, 4 do
    local dir = (i % 2 == 0) and 1 or -1
    local y_offset = (i <= 2) and -2 or 2
    ANIM.particles[#ANIM.particles + 1] = {
      kind = "spring_line",
      x = cx, y = cy + y_offset,
      vx = dir * 0.8,
      lev = 13,
      t = tick + (i - 1), dur = 14,
    }
  end
end

function play_heavy_hand_anim(p)
  -- Sidechain compressor: 6 particles falling DOWNWARD from the character,
  -- plus 1-tick screen shake (magnitude 2). Uses the existing "spark" kind
  -- with downward-biased velocity. Lifespan 10 ticks.
  local cx = ANIM.party_hud_x(p) + 5
  local cy = 53
  for i = 1, 6 do
    local ang = (math.pi / 6) * (i - 3.5)   -- spread roughly downward
    ANIM.particles[#ANIM.particles + 1] = {
      kind = "spark",
      x = cx, y = cy,
      vx = math.sin(ang) * 0.6,
      vy = math.abs(math.cos(ang)) * 1.4 + 0.4,    -- biased downward
      t = tick, lev = 15, dur = 10,
    }
  end
  ANIM.shake(2, 1)
end

function play_scatter_anim(p)
  -- Granular cloud: 12 tiny particles flying outward in all directions,
  -- with randomized brightness 7-13 each. Lifespan 18 ticks. Fragmentation feel.
  local cx = ANIM.party_hud_x(p) + 5
  local cy = 53
  for i = 1, 12 do
    local ang = math.random() * math.pi * 2
    local speed = 0.6 + math.random() * 1.0
    ANIM.particles[#ANIM.particles + 1] = {
      kind = "spark",
      x = cx, y = cy,
      vx = math.cos(ang) * speed,
      vy = math.sin(ang) * speed,
      t = tick,
      lev = 7 + math.random(0, 6),
      dur = 18,
    }
  end
end

function play_slow_wheel_anim(p)
  -- Analog phaser: a diameter line drawn through the character's sprite
  -- center, rotating ~22.5° every tick (≈45° every 2 ticks). Fades after 16.
  local cx = ANIM.party_hud_x(p) + 5
  local cy = 53
  ANIM.particles[#ANIM.particles + 1] = {
    kind = "rotating_line",
    x = cx, y = cy,
    radius = 6,
    lev = 13,
    t = tick, dur = 16,
  }
end

RESO_ANIMS = {
  ring         = play_ring_anim,
  long_echo    = play_long_echo_anim,
  threefold    = play_threefold_anim,
  masked_voice = play_masked_voice_anim,
  spring       = play_spring_anim,
  heavy_hand   = play_heavy_hand_anim,
  scatter      = play_scatter_anim,
  slow_wheel   = play_slow_wheel_anim,
}

local function damage_party(p, amount)
  -- Party is invincible while in JAM mode (so jamming live during a battle
  -- can't accidentally KO anyone).
  if game_state == "JAM" then return end
  -- Party-size damage scaling. Enemy ATK is balanced for a full 4-member
  -- party that can spread incoming hits and outheal them. Solo Miel
  -- (just out of the chamber) gets one-shot by the same numbers — so
  -- we scale incoming damage down based on how many characters are
  -- alive in the active party. Full party = full damage.
  --   1 alive: 50%   |   2 alive: 65%   |   3 alive: 80%   |   4+: 100%
  do
    local alive = 0
    for _, q in ipairs(party) do if q.alive then alive = alive + 1 end end
    local PARTY_SCALE = {0.50, 0.65, 0.80}
    local scale = PARTY_SCALE[alive] or 1.0
    amount = math.max(1, math.floor(amount * scale))
  end
  -- Heavy Hand (Resonance): enemy output ducked for the effect's duration.
  do
    local hh = reso_fx_active("duck_enemies")
    if hh then amount = math.max(1, math.floor(amount * (hh.mult or 0.5))) end
  end
  -- Strom's BLK: redirect to blocking warrior at 10% damage
  local blocker = nil
  for _, q in ipairs(party) do
    if q.alive and q.blocking and q ~= p then blocker = q; break end
  end
  if blocker then
    amount = math.max(1, math.floor(amount * 0.10))
    blocker.blocking = false
    p = blocker
  end
  -- Miel's REFLECT (cleric B-action). Bounces the full incoming amount
  -- back at the enemy as magical damage and consumes the reflect. Miel
  -- takes NO HP damage and gets NO hit-wobble — the reflect plays only
  -- a silver chime so the read is "she repelled it cleanly" rather than
  -- "she got hit and counter-attacked." No banner: the bounced damage
  -- number on the enemy is the visible feedback.
  if p.reflect then
    p.reflect = false
    p.reflect_ticks = 0
    -- bell-bright reflect chime (uses cleric SynthDef at high pitch)
    local a = ARTIC.REF
    local note = (active_scale()[p.note_idx] or 0) + a.pitch + JAM.root
    local wet = math.max(0, math.min(1, a.wet * (CONTENT.combat_reverb_mix or 1.0)))
    sq_trig("cleric", midi_to_freq(note), a.vel, a.attack, a.release, wet)
    if enemy and enemy.alive then
      damage_enemy(amount, false)
    end
    return
  end
  if p.shield then
    amount = math.floor(amount / 2)
    p.shield = false
  end
  -- HORN's dmg_reduce buff: halve incoming damage while ticks remain
  if (p.dmg_reduce_ticks or 0) > 0 then
    amount = math.max(1, math.floor(amount / 2))
  end
  -- DEF: mild multiplicative reduction — def 10 ≈ -17%, def 25 ≈ -33%.
  -- Multiplicative (not subtractive) so a high-def warrior can't scale
  -- into immunity against fixed enemy ATK. Until wave 10, def was a
  -- fully dead stat: granted by levels, shown on STATUS/EQUIP, and
  -- never read by any damage path.
  do
    local def = (INST and INST.def and INST.def(p)) or 0
    if def > 0 then
      amount = math.max(1, math.floor(amount * 100 / (100 + def * 2)))
    end
  end
  p.hp = math.max(0, p.hp - amount)
  p.last_hit = tick
  if p.hp == 0 then
    p.alive = false
    -- Clear armed Resonance buffs on KO. (p.buffed intentionally
    -- persists per existing behavior, but Ring's spec says the
    -- bell goes silent when the bell-ringer falls.)
    p.ring_armed = false
  end
  ANIM.spawn_dmg(ANIM.party_hud_x(p), 47, amount, 15)
  -- Pass 50: enemy-inflicted status. Each attack has a small chance to
  -- apply a status effect to the hit character. Bosses use higher rates.
  if enemy and p.alive then
    local boss_visuals = {echo=true, sentinel=true, tide=true, dunerider=true,
                          snowgaunt=true, locrius=true, suno=true, broken_cadence=true,
                          firstchord=true}
    local poison_chance = boss_visuals[enemy.visual] and 0.18 or 0.06
    local sleep_chance  = boss_visuals[enemy.visual] and 0.10 or 0.03
    if math.random() < poison_chance then
      p.poison_ticks = math.max(p.poison_ticks or 0, 60)
    end
    if math.random() < sleep_chance then
      p.sleep_ticks = math.max(p.sleep_ticks or 0, 24)
    end
  end
  -- ── SERGEI'S INTERVENTION (one-shot, Cave 3 / Tidewatch boss) ──
  -- If the party is about to wipe during the Tidewatch fight and Sergei
  -- hasn't intervened yet, he steps in: revives all members at 50% HP and
  -- joins the recruits roster permanently.
  if not CONTENT.sergei_intervened
     and game_state == "BATTLE" and current_cave == 3
     and enemy and enemy.visual == "tide" and not enemy.is_rare then
    local any_alive = false
    for _, q in ipairs(party) do if q.alive then any_alive = true; break end end
    if not any_alive then
      CONTENT.sergei_intervened = true
      CONTENT.recruits[1].joined = true   -- Sergei
      if ensure_recruit_character then ensure_recruit_character(1) end
      for _, q in ipairs(party) do
        q.alive = true
        q.hp = math.max(1, math.floor(q.hp_max * 0.50))
        q.atb = 0
        q.last_hit = tick
      end
      -- Autosave AFTER the revive loop: saving first captured a fully
      -- dead party (alive=false, hp=0) — reloading that save booted to
      -- the overworld with everyone KO'd.
      if save_game then save_game() end

      CONTENT.banner_text  = "* SERGEI INTERVENES *"
      CONTENT.banner_ticks = 42
      -- A wrench-against-bell SFX punctuates the moment. Three quick
      -- triggers: the wrench skip, the bell-clang, the chord souring.
      sq_trig("warrior", midi_to_freq(snap_note_to_scale(48)), 0.95, 0.001, 0.20, 0.10)
      clock.run(function()
        clock.sleep(0.10)
        sq_trig("cleric", midi_to_freq(snap_note_to_scale(72)), 0.95, 0.001, 1.20, 0.95)
        clock.sleep(0.30)
        -- deliberately UN-snapped: this is the "chord souring" beat
        sq_trig("bard", midi_to_freq(58), 0.55, 0.005, 2.00, 0.85)
      end)
      ANIM.shake(3, 12)
      ANIM.burst(96, 32, 8, 15)
      -- Pause the battle and play a proper FF4-style intervention scene.
      -- The dialogue closes back into BATTLE so the player can finish
      -- Tidewatch with a freshly-revived party.
      enemy._paused_for_sergei = true
      dlg.lines = pack_dialogue_lines({
        "(A wrench skips across the wet stone of the tidepool. It strikes Tidewatch's chord-bell. The bell sours.)",
        "(Tidewatch staggers, its choir thrown a half-step.)",
        "(A man steps from the rubble of the seawall. Cable spooled across one shoulder, lantern in the other hand.)",
        "(He is older than Strom. He moves like he is younger.)",
        "[Sergei]  (does not look at you) Don't thank me. I owe him a tower.",
        "[Sergei]  (kneels by Miel; lays the wrench down) Up, queen.",
        "[Sergei]  The chord's open for forty seconds. Give or take.",
        "(He passes a hand across the party. The lantern's light is somehow steadier than it should be.)",
        "(They breathe. The water in the tidepool runs back, then forward, on the right beat.)",
        "(Around them: the sound of broken machinery suddenly remembering how to work.)",
        "[Sergei]  Right. Now finish it. I'll watch the door.",
        "[Miel]    (finding her feet) ...thank you anyway.",
        "(Sergei joins your reserve. You can swap him in from the Party menu.)",
      }, nil)
      dlg.line = 1
      dlg.npc = nil
      game_state = "DIALOGUE"
      CONTENT.post_dialogue = function()
        game_state = "BATTLE"
        params:set("clock_tempo",
                   math.floor(BATTLE_BPM * (CONTENT.battle_speed or 1.0)))
        if enemy then enemy._paused_for_sergei = nil end
        -- Bonus: a healing chord rings once as combat resumes — Sergei's
        -- parting "stay alive" gift.
        sq_trig("cleric", midi_to_freq(snap_note_to_scale(67)), 0.65, 0.20, 3.0, 0.95)
        ANIM.burst(96, 32, 6, 11)
        redraw()
      end
    end
  end
end

local function heal_party(hp_frac, mp_frac)
  for _, q in ipairs(party) do
    if q.alive then
      q.hp = math.min(q.hp_max, q.hp + math.floor(q.hp_max * hp_frac))
      if mp_frac and mp_frac > 0 then
        q.mp = math.min(q.mp_max, q.mp + math.floor(q.mp_max * mp_frac))
      end
      q.last_hit = tick   -- reuse the hit-flash to show heal landing
    end
  end
  -- The Spring (bard Resonance): if armed, this heal echoes twice more at
  -- 25% per bar. Cleared up front so the scheduled echoes don't re-arm.
  if CONTENT.spring_echo and hp_frac and hp_frac > 0 then
    CONTENT.spring_echo = false
    local echo = hp_frac * 0.25
    reso_schedule(RESO_BAR,     function() heal_party(echo, 0) end)
    reso_schedule(2 * RESO_BAR, function() heal_party(echo, 0) end)
  end
end

-- When ANY party member plays their instrument, every other living party
-- (Party-jam contagion was removed — caused chain-overwrite of player choices.
-- Each character now only ever fires their own queued action.)
local function trigger_party_jam(except) end

local function apply_player_action(p)
  -- Treat legacy "MAG" save data as the class's instrument.
  if p.queued == "MAG" then p.queued = CLASS_INSTRUMENT[p.class] or "ATK" end
  -- STIR costs 6 MP (the only paid instrument action). If ECHO can't
  -- afford it, fall back to a plain ATK so the turn isn't silently
  -- wasted. Feedback reuses the Resonance-denial idiom: the dim flash
  -- on her HUD glyph slot + the low-MP descending denial chord.
  if p.queued == "STIR" and p.mp < 6 then
    p.reso_denied_t = tick
    sq_trig("cleric", midi_to_freq(36), 0.4,  0.005, 0.15, 0)
    sq_trig("cleric", midi_to_freq(33), 0.35, 0.005, 0.15, 0)
    sq_trig("cleric", midi_to_freq(28), 0.3,  0.005, 0.15, 0)
    p.queued = "ATK"
  end
  -- LIMIT BREAK: when a character is at <=25% HP and hasn't used theirs
  -- yet this battle, the next ATK fires as a class-specific limit
  -- instead. Single-use per battle. Cleric variant heals and revives
  -- the whole party (no damage); others deal massive damage with a
  -- broken-chord SFX flourish.
  if p.queued == "ATK" and p.alive and not p.limit_used
     and p.hp > 0 and p.hp <= p.hp_max * 0.25 and enemy and enemy.alive then
    p.limit_used = true
    if unlock_achievement then unlock_achievement("first_limit", "Broken Chord") end
    local cls = p.class
    if cls == "cleric" then
      -- Full party revive + heal-to-full. No damage.
      for _, q in ipairs(party) do
        if not q.alive then q.atb = 0 end  -- revived members restart their turn (matches Star/HEAL/SMPL)
        q.alive = true
        q.hp = q.hp_max
        q.mp = q.mp_max
        q.poison_ticks = 0
        q.sleep_ticks = 0
        q.regen_hp_ticks = math.max(q.regen_hp_ticks or 0, 256)
        q.last_hit = tick
      end
      CONTENT.banner_text  = "* MIEL: WHOLE-NOTE REST *"
      CONTENT.banner_ticks = 60
      sq_trig("cleric", midi_to_freq(snap_note_to_scale(72)), 0.85, 0.001, 6.0,
              math.min(1, 1.0 * (CONTENT.combat_reverb_mix or 1.0)))
    elseif cls == "wraith" then
      -- ECHO: DISPERSE. Splits into 5 ghost-copies for one beat. Scales
      -- off MAG (her ATK is negligible). Guaranteed-crit single hit +
      -- 5 staggered ghost-bursts across the enemy column.
      local dmg = math.floor(INST.mag(p) * 4)
      local mv_lim_mag = reso_fx_active("masked_voice")
      if mv_lim_mag then dmg = math.floor(dmg * (mv_lim_mag.mult or 1.25)) end
      damage_enemy(dmg, true)
      CONTENT.banner_text  = "* ECHO: DISPERSE *"
      CONTENT.banner_ticks = 60
      ANIM.shake(2, 12)
      for k = 1, 5 do
        clock.run(function()
          clock.sleep((k - 1) * 0.04)
          ANIM.burst(90 + k * 3, 28 + (k % 2) * 6, 4, 13)
          sq_trig("wraith", midi_to_freq(67 + k), 0.55, 0.005, 0.6,
                  math.min(1, 0.7 * (CONTENT.combat_reverb_mix or 1.0)))
        end)
      end
    else
      -- Damage variant: 4-5x base atk, guaranteed crit, splash burst.
      local mult = (cls == "warrior") and 5 or (cls == "bard") and 4 or 4
      local dmg = math.floor(INST.atk(p) * mult)
      local mv_lim_atk = reso_fx_active("masked_voice")
      if mv_lim_atk then dmg = math.floor(dmg * (mv_lim_atk.mult or 1.25)) end
      damage_enemy(dmg, true)
      ANIM.burst(96, 32, 14, 15)
      ANIM.shake(3, 18)
      local label = (cls == "warrior") and "STROM: ANTHEM"
                 or (cls == "bard")    and "ALDER: BREAKING CHORD"
                 or (cls == "mage")    and "DIEGUES: LOOP CRASH"
                 or (cls == "engineer") and "SERGEI: FULL PATCH"
                 or (cls == "mathwiz")  and "PAJ: PROOF BY VOLUME"
                 or (cls == "drummer")  and "NIKO: DOWNBEAT"
                 or (cls .. ": LIMIT")
      CONTENT.banner_text  = "* " .. label:upper() .. " *"
      CONTENT.banner_ticks = 60
      -- Broken-chord SFX: ring class voice + a fifth above. Recruits
      -- must alias to their engine voice family (engineer→mage,
      -- mathwiz→bard, drummer→warrior) — engine.trig_engineer doesn't
      -- exist, and an unaliased call here killed the main game clock.
      local voice = (cls == "engineer" and "mage")
                 or (cls == "mathwiz"  and "bard")
                 or (cls == "drummer"  and "warrior")
                 or cls
      local note = (active_scale()[p.note_idx] or 12) + JAM.root
      sq_trig(voice, midi_to_freq(note),     0.85, 0.001, 2.0, 1.0)
      sq_trig(voice, midi_to_freq(snap_note_to_scale(note + 7)), 0.65, 0.005, 2.5, 1.0)
    end
    p.last_fire = tick
    p.last_action = "ATK"
    p.note_idx = p.note_idx + 1
    if p.note_idx > p.note_hi then p.note_idx = p.note_lo end
    return
  end
  if p.queued == "ATK" then
    -- Guard with `enemy and` — a previous party member's hit may have
    -- already killed the enemy this tick (e.g. Strom-arc clears the
    -- global `enemy` synchronously on kill).
    if enemy and enemy.alive then
      local dmg = INST.atk(p)
      -- Rhythm-crit: guaranteed crit if charged via on-beat A press.
      local rhythm_was_set = p.rhythm_charged
      local crit = p.rhythm_charged or (math.random() < ANIM.crit)
      p.rhythm_charged = false   -- consumed regardless of outcome
      if rhythm_was_set and unlock_achievement then
        unlock_achievement("first_rhythm_crit", "On the Beat")
      end
      if crit then dmg = dmg * 2 end
      if p.buffed then dmg = math.floor(dmg * 1.5); p.buffed = false end
      -- The Ring (Miel's Resonance): empowered next-attack. 1.30x damage
      -- plus a clangor sound + larger burst + screen shake. Stacks
      -- multiplicatively with crit/buffed (the bell amplifies what the
      -- attack already is). Consumed regardless of whether the hit lands.
      local ring_fx = false
      if p.ring_armed then
        dmg = math.floor(dmg * 1.30)
        p.ring_armed = false
        ring_fx = true
      end
      local mv_atk = reso_fx_active("masked_voice")
      if mv_atk then dmg = math.floor(dmg * (mv_atk.mult or 1.25)) end
      damage_enemy(dmg, crit)
      -- Long Echo (Resonance): the next 2 attacks echo at 50%, one beat late.
      if (p.long_echo_charges or 0) > 0 then
        p.long_echo_charges = p.long_echo_charges - 1
        local echo_dmg = math.max(1, math.floor(dmg * 0.50))
        reso_schedule(6, function()
          if enemy and enemy.alive then
            damage_enemy(echo_dmg, false)
            ANIM.burst(96, 32, 4, 11)
          end
        end)
      end
      if ring_fx then
        -- Clangor: root bell + a fifth above (same cleric voice as
        -- the signature sound; the fifth is the "harmonics no one
        -- could place" beat from the bible).
        local sig = RESONANCE_SITES.ring and RESONANCE_SITES.ring.shrine
                    and RESONANCE_SITES.ring.shrine.signature
        if sig and sig.sound then
          local s = sig.sound
          sq_trig(s.class, midi_to_freq(snap_note_to_scale(s.note)),
                  s.vel or 0.7, s.attack or 0.05, s.release or 4.0,
                  math.min(1, (s.wet or 1.0) * (CONTENT.combat_reverb_mix or 1.0)))
          sq_trig(s.class, midi_to_freq(snap_note_to_scale(s.note + 7)),
                  0.55, 0.005, 2.0,
                  math.min(1, (s.wet or 1.0) * (CONTENT.combat_reverb_mix or 1.0)))
        end
        ANIM.burst(96, 32, 10, 15)
        ANIM.shake(2, 10)
      end
    end
  elseif p.queued == "HEAL" then
    -- Miel's lyre: revive + heal + apply LONG HP/MP regen.
    -- Regen now lasts 256 ticks ≈ 16 ATB turns at base speed (atb fills
    -- in 16 ticks). HP pulses +1 every 8 ticks → ~32 HP healed across
    -- the duration. MP pulses +1 every 12 ticks → ~21 MP. Sustained
    -- party support that lasts most of a fight.
    for _, q in ipairs(party) do
      if not q.alive then
        q.alive = true
        q.hp = math.max(1, math.floor(q.hp_max * 0.30))
        q.atb = 0
        q.last_hit = tick
        break
      end
    end
    heal_party(0.25, 0)
    for _, q in ipairs(party) do
      if q.alive then
        q.regen_hp_ticks = math.max(q.regen_hp_ticks or 0, 256)
        q.regen_mp_ticks = math.max(q.regen_mp_ticks or 0, 256)
        -- Pass 50: Miel's lyre also dispels poison + sleep on the party.
        q.poison_ticks = 0
        q.sleep_ticks = 0
      end
    end
  elseif p.queued == "LUTE" then
    -- Alder's lute: heal all 10% HP + buff next attack of all alive.
    -- The heal routes through heal_party so an armed Spring echoes the
    -- bard's own lute — without this, Spring only echoed Miel's HEAL
    -- and was dead weight in cleric-less parties.
    heal_party(0.10, 0)
    for _, q in ipairs(party) do
      if q.alive then
        q.buffed = true
      end
    end
    -- Mira's gift: the flat-second grace note rides every strum once
    -- learned (Phrygian City, drone-singer Mira).
    if flag.mira_flat_second then
      sq_trig("bard", midi_to_freq(61), 0.30, 0.005, 0.5,
              math.min(1, 0.6 * (CONTENT.combat_reverb_mix or 1.0)))
    end
  elseif p.queued == "MIX" then
    -- Sergei's MIX: remix the enemy's pattern (deal MAG damage, scramble its
    -- attack pattern order, debuff atk).
    -- IMPORTANT: damage_enemy can clear the global `enemy` (e.g. Strom-arc
    -- branch on a kill) so re-check before touching it again.
    if enemy and enemy.alive then
      local dmg = math.floor(INST.mag(p) * 1.4)
      local crit = math.random() < ANIM.crit
      if crit then dmg = dmg * 2 end
      local mv_mix = reso_fx_active("masked_voice")
      if mv_mix then dmg = math.floor(dmg * (mv_mix.mult or 1.25)) end
      damage_enemy(dmg, crit)
      if enemy then
        enemy.atk_debuff_ticks = math.max(enemy.atk_debuff_ticks or 0, 24)
        -- shuffle the enemy's attack_pattern in-place (Fisher-Yates)
        local ap = enemy.attack_pattern
        if ap and #ap > 1 then
          for i = #ap, 2, -1 do
            local j = math.random(i)
            ap[i], ap[j] = ap[j], ap[i]
          end
          enemy.pattern_idx = 1
        end
      end
    end
  elseif p.queued == "DRUM" then
    -- Niko's DRUM: hit ON the one. ATK-scaled damage, and the impact
    -- knocks the enemy off its own count — its attack-gap timer
    -- restarts (last_attack rebased) plus a short ATK debuff. (This
    -- branch was missing entirely: Niko's special was a sound with no
    -- combat effect.)
    if enemy and enemy.alive then
      local dmg = math.floor(INST.atk(p) * 1.3)
      local crit = math.random() < ANIM.crit
      if crit then dmg = dmg * 2 end
      local mv_drum = reso_fx_active("masked_voice")
      if mv_drum then dmg = math.floor(dmg * (mv_drum.mult or 1.25)) end
      damage_enemy(dmg, crit)
      if enemy then
        enemy.last_attack = tick   -- stolen beat: full gap before its next hit
        enemy.atk_debuff_ticks = math.max(enemy.atk_debuff_ticks or 0, 16)
      end
    end
  elseif p.queued == "CODE" then
    -- Paj's CODE: damage proportional to enemy's CURRENT HP percent (the bigger
    -- the foe, the bigger the bite); also self-heals a small chunk.
    if enemy and enemy.alive then
      local pct = enemy.hp / math.max(1, enemy.hp_max)
      local dmg = math.floor(INST.mag(p) * (1.0 + pct * 1.5))
      local crit = math.random() < ANIM.crit
      if crit then dmg = dmg * 2 end
      local mv_code = reso_fx_active("masked_voice")
      if mv_code then dmg = math.floor(dmg * (mv_code.mult or 1.25)) end
      damage_enemy(dmg, crit)
    end
    p.hp = math.min(p.hp_max, p.hp + math.floor(p.hp_max * 0.15))
    p.last_hit = tick
  elseif p.queued == "TUNE" then
    -- Strom's war horn: party gains attack buff + damage reduction; enemy ATK halved.
    for _, q in ipairs(party) do
      if q.alive then
        q.buffed = true
        q.dmg_reduce_ticks = math.max(q.dmg_reduce_ticks or 0, 28)
      end
    end
    if enemy and enemy.alive then
      enemy.atk_debuff_ticks = math.max(enemy.atk_debuff_ticks or 0, 28)
    end
    trigger_party_jam(p)
  elseif p.queued == "SMPL" then
    -- Diegues' samplers: deal big damage to enemy, debuff its ATK, inspire
    -- party — and now heal everyone slightly (revives KO'd at low HP).
    -- IMPORTANT: damage_enemy may clear `enemy` (Strom-arc kill); re-check.
    if enemy and enemy.alive then
      local dmg = math.floor(INST.mag(p) * 2.0)
      local crit = math.random() < ANIM.crit
      if crit then dmg = dmg * 2 end
      local mv_smpl = reso_fx_active("masked_voice")
      if mv_smpl then dmg = math.floor(dmg * (mv_smpl.mult or 1.25)) end
      damage_enemy(dmg, crit)
      if enemy then
        enemy.atk_debuff_ticks = math.max(enemy.atk_debuff_ticks or 0, 20)
      end
    end
    for _, q in ipairs(party) do
      if not q.alive then
        -- Revive KO'd at 15% HP
        q.alive = true
        q.hp = math.max(1, math.floor(q.hp_max * 0.15))
        q.atb = 0
        q.last_hit = tick
      else
        q.hp = math.min(q.hp_max, q.hp + math.floor(q.hp_max * 0.08))
        q.buffed = true
      end
    end
    trigger_party_jam(p)
  elseif p.queued == "STIR" then
    -- ECHO's STIR: a fragmented 3-grain chord across the active mode on
    -- the wraith voice. MAG-scaled single-target damage. Costs 6 MP --
    -- unlike the other instrument actions (which are free), STIR draws
    -- on ECHO's large MP pool. Revisit in playtest if the asymmetry
    -- feels off.
    if p.mp >= 6 then  -- always true here: MP-starved STIR was rewritten to ATK at the top of this function
      p.mp = p.mp - 6
      local sc = (JAM and JAM.scales and JAM.scales[JAM.mode]) or {0, 2, 4, 5, 7, 9, 11}
      local root = (JAM and JAM.root) or 0
      for k, deg in ipairs({1, 4, 6}) do
        local note = (sc[deg] or sc[1]) + root + 60
        clock.run(function()
          clock.sleep((k - 1) * 0.06)
          sq_trig("wraith", midi_to_freq(note), 0.65, 0.005, 1.2,
                  math.min(1, 0.85 * (CONTENT.combat_reverb_mix or 1.0)))
        end)
      end
      if enemy and enemy.alive then
        local dmg = math.floor(INST.mag(p) * 1.6)
        local mv_stir = reso_fx_active("masked_voice")
        if mv_stir then dmg = math.floor(dmg * (mv_stir.mult or 1.25)) end
        damage_enemy(dmg, false)
        ANIM.burst(96, 32, 6, 11)
      end
    end
  elseif p.queued == "PLAY" then
    -- Alder's bard play: heal all 10% HP + buff next attack of all alive. Now also jams.
    for _, q in ipairs(party) do
      if q.alive then
        q.hp = math.min(q.hp_max, q.hp + math.floor(q.hp_max * 0.10))
        q.buffed = true
        q.last_hit = tick
      end
    end
    trigger_party_jam(p)
  elseif p.queued == "BLK" then
    -- Strom's block-for-party: next enemy hit on someone else redirects to him at 10%. Free.
    p.blocking = true
    p.mp = math.min(p.mp_max, p.mp + 1)
  elseif p.queued == "ITM" then
    -- Item resolution. If the player picked a specific item via repeated
    -- Y presses (p.item_pick ~= "auto"), use that one when in stock and
    -- fall through to auto-priority otherwise. Auto = revive star →
    -- heal-all salve → MP vial/ether → ATK-buff tonic → tiny self-heal.
    local pick = p.item_pick or "auto"
    if pick ~= "auto" and (SHOP.inv[pick] or 0) > 0 then
      SHOP.inv[pick] = SHOP.inv[pick] - 1
      if pick == "salve" then
        for _, q in ipairs(party) do
          if q.alive then q.hp = math.min(q.hp_max, q.hp + 35) end
        end
        SHOP.last_item = "Salve"
      elseif pick == "vial" then
        for _, q in ipairs(party) do
          if q.alive then q.mp = math.min(q.mp_max, q.mp + 10) end
        end
        SHOP.last_item = "Vial"
      elseif pick == "ether" then
        for _, q in ipairs(party) do
          if q.alive then q.mp = math.min(q.mp_max, q.mp + 25) end
        end
        SHOP.last_item = "Ether"
      elseif pick == "tonic" then
        for _, q in ipairs(party) do
          if q.alive then q.tonic_ticks = 999 end
        end
        SHOP.last_item = "Tonic"
      elseif pick == "star" then
        local revive_target
        for _, q in ipairs(party) do
          if not q.alive then revive_target = q; break end
        end
        if revive_target then
          revive_target.alive = true
          revive_target.hp = revive_target.hp_max
          revive_target.atb = 0
          revive_target.last_hit = tick
          SHOP.last_item = "Star"
        else
          -- nobody KO'd — full party heal as fallback
          for _, q in ipairs(party) do
            if q.alive then q.hp = q.hp_max end
          end
          SHOP.last_item = "Star (heal-all)"
        end
      end
      goto item_done
    end
    -- Auto-priority fallback (original logic).
    local revive_target = nil
    for _, q in ipairs(party) do
      if not q.alive then revive_target = q; break end
    end
    if revive_target and SHOP.inv.star > 0 then
      SHOP.inv.star = SHOP.inv.star - 1
      revive_target.alive = true
      revive_target.hp = revive_target.hp_max
      revive_target.atb = 0
      revive_target.last_hit = tick
      SHOP.last_item = "Star"
    elseif SHOP.inv.salve > 0 then
      SHOP.inv.salve = SHOP.inv.salve - 1
      for _, q in ipairs(party) do
        if q.alive then q.hp = math.min(q.hp_max, q.hp + 35) end
      end
      SHOP.last_item = "Salve"
    elseif SHOP.inv.vial > 0 then
      SHOP.inv.vial = SHOP.inv.vial - 1
      for _, q in ipairs(party) do
        if q.alive then q.mp = math.min(q.mp_max, q.mp + 10) end
      end
      SHOP.last_item = "Vial"
    elseif SHOP.inv.ether > 0 then
      SHOP.inv.ether = SHOP.inv.ether - 1
      for _, q in ipairs(party) do
        if q.alive then q.mp = math.min(q.mp_max, q.mp + 25) end
      end
      SHOP.last_item = "Ether"
    elseif SHOP.inv.tonic > 0 then
      -- Tonic: stamps a one-battle ATK boost on every alive party member
      SHOP.inv.tonic = SHOP.inv.tonic - 1
      for _, q in ipairs(party) do
        if q.alive then q.tonic_ticks = 999 end   -- cleared on exit_battle
      end
      SHOP.last_item = "Tonic"
    else
      -- empty pockets: a meager self-care motion
      p.hp = math.min(p.hp_max, p.hp + 4)
      p.mp = math.min(p.mp_max, p.mp + 2)
      SHOP.last_item = "(empty)"
    end
    ::item_done::
  elseif p.queued == "DEF" then
    p.shield = true
    p.mp = math.min(p.mp_max, p.mp + 1)
  elseif p.queued == "REF" then
    -- Miel's REFLECT: any incoming hit while reflect is up bounces the full
    -- damage back at the enemy and is consumed. damage_party() reads
    -- p.reflect; reflect_ticks lets us flash a brief HUD marker that fades
    -- on the next enemy attack regardless of whether it hit Miel or not.
    p.reflect = true
    p.reflect_ticks = 24
    p.mp = math.min(p.mp_max, p.mp + 1)
  elseif p.queued == "RESO" then
    -- Fluid invocation: SFX + animation + arm buff. Does NOT consume the
    -- firing slot (no p.last_fire set). Sets a 6-tick per-character
    -- Resonance cooldown to prevent re-invoke spam.
    -- See docs/specs/2026-05-19-resonance-fluid-invocation-design.md.
    local rid = p.queued_resonance
    local r   = rid and RESONANCES[rid]
    -- MP is charged HERE (the single fire point), not at queue time.
    -- The R2 path pre-checks affordability; the dpad/encoder cycles
    -- don't — either way, can't-afford at fire = denial chord, and the
    -- NEXT auto-turn attacks normally (this turn itself deals no
    -- damage — unlike STIR's top-of-function rewrite).
    if r and p.mp < (r.mp_cost or 0) then
      p.reso_denied_t = tick
      sq_trig("cleric", midi_to_freq(36), 0.4,  0.005, 0.15, 0)
      sq_trig("cleric", midi_to_freq(33), 0.35, 0.005, 0.15, 0)
      sq_trig("cleric", midi_to_freq(28), 0.3,  0.005, 0.15, 0)
      r = nil
      p.queued_resonance = nil
      p._was_reso = true
      p.queued = "ATK"
    end
    if r then
      p.mp = p.mp - (r.mp_cost or 0)
      -- Signature SFX
      local sig = RESONANCE_SITES[rid] and RESONANCE_SITES[rid].shrine and RESONANCE_SITES[rid].shrine.signature
      if sig and sig.sound then
        sq_trig(sig.sound.class, midi_to_freq(snap_note_to_scale(sig.sound.note)),
                sig.sound.vel or 0.7,
                sig.sound.attack or 0.05,
                sig.sound.release or 4.0,
                math.min(1, (sig.sound.wet or 1.0) * (CONTENT.combat_reverb_mix or 1.0)))
      end
      -- Per-Resonance animation
      if RESO_ANIMS and RESO_ANIMS[rid] then
        RESO_ANIMS[rid](p)
      end
      -- Arm the per-Resonance buff / dispatch the effect.
      apply_resonance_effect(rid, p)
      -- Per-character 6-tick cooldown — separate from firing slot.
      p.reso_cooldown_until = tick + 6
      p.queued_resonance = nil
      -- (Historical note says "do NOT set p.last_fire" but fire() has
      -- always set it unconditionally after this returns — RESO is
      -- fluid in UI terms, not in the firing-slot sense.)
      p.last_action = "RESO"
      -- Fall back to ATK: leaving queued="RESO" with the id consumed
      -- made every subsequent auto-turn a silent no-op. Mark the call
      -- so fire() doesn't read the fallback as a REAL attack and
      -- register a chord-combo entry for a resonance invoke.
      p._was_reso = true
      p.queued = "ATK"
    end
  end
  -- Threefold (Resonance): while active, every party action feeds the caster.
  for _, c in ipairs(party) do
    if c.alive and c.threefold_until and (tick or 0) < c.threefold_until then
      local heal = math.floor((c.hp_max or 0) * 0.05)
      if heal > 0 then
        c.hp = math.min(c.hp_max, c.hp + heal)
      end
    end
  end
end

-- COMBO / CHORD attacks. When 2+ characters fire ATK within COMBO_WINDOW
-- ticks of each other, their notes are read as a chord and award bonus
-- damage scaled by chord size and consonance. Window matches roughly
-- one beat at BATTLE_BPM (16th = ~1.5 ticks @ 85 BPM, beat = ~6 ticks).
local COMBO_WINDOW = 6
-- Each entry: {t = tick fired, p = party member ref, note = midi pitch}
-- Mutated by fire() and trigger_combo_check(); cleared in enter_battle/exit_battle.
combo_window = {}

-- ── Resonance FX runtime ──────────────────────────────────────────────
-- Per-battle. RESO_BAR ≈ 4 beats at 85 BPM (COMBO_WINDOW=6 ticks ≈ 1 beat).
RESO_BAR = 24
RESO_FX = {}      -- active timed effects: {kind, expires, ...params}
RESO_QUEUE = {}   -- scheduled events: {at, fn}

function reso_fx_add(kind, ticks, params)
  local e = {kind = kind, expires = (tick or 0) + ticks}
  if params then for k, v in pairs(params) do e[k] = v end end
  RESO_FX[#RESO_FX + 1] = e
  return e
end

function reso_fx_active(kind)
  for _, e in ipairs(RESO_FX) do
    if e.kind == kind and (tick or 0) < e.expires then return e end
  end
  return nil
end

function reso_schedule(delay, fn)
  RESO_QUEUE[#RESO_QUEUE + 1] = {at = (tick or 0) + delay, fn = fn}
end

function reso_fx_tick()
  for i = #RESO_FX, 1, -1 do
    if (tick or 0) >= RESO_FX[i].expires then table.remove(RESO_FX, i) end
  end
  for i = #RESO_QUEUE, 1, -1 do
    if (tick or 0) >= RESO_QUEUE[i].at then
      local fn = RESO_QUEUE[i].fn
      table.remove(RESO_QUEUE, i)
      if fn then fn() end
    end
  end
end

function reso_clear_all()
  RESO_FX = {}
  RESO_QUEUE = {}
  CONTENT.spring_echo = false
end

-- Per-battle state scrub shared by exit_battle and the bypass-victory
-- exits (Strom arc / Broken Cadence), which skip exit_battle entirely.
-- Global to dodge the 200-local main-chunk cap.
function scrub_battle_statuses()
  reso_clear_all()
  for _, p in ipairs(party) do
    p.tonic_ticks = 0
    p.poison_ticks = 0
    p.sleep_ticks = 0
    p.reflect = false
    p.reflect_ticks = 0
    p.reso_cooldown_until = 0
    p.reso_denied_t = -99
    p.ring_armed = false
    p.long_echo_charges = 0
    p.threefold_until = -99
    p.regen_hp_ticks = 0
    p.regen_mp_ticks = 0
    p.dmg_reduce_ticks = 0
    p.rhythm_charged = false
    p.buffed = false
  end
end

-- Score a single interval (semitones, mod 12) for consonance:
--   3 = perfect (unison/4th/5th/octave)
--   2 = consonant (3rds/6ths)
--   1 = mild dissonance (2nds/7ths)
--   0 = harsh (semitone/tritone/maj7)
-- Global to dodge the 200-local main-chunk cap.
function interval_consonance(semis)
  local s = semis % 12
  if s == 0 or s == 5 or s == 7 then return 3
  elseif s == 3 or s == 4 or s == 8 or s == 9 then return 2
  elseif s == 2 or s == 10 then return 1
  else return 0   -- 1, 6, 11
  end
end

-- Compute average pairwise consonance for the current combo window.
function combo_consonance(entries)
  if #entries < 2 then return 0 end
  local total, n = 0, 0
  for i = 1, #entries - 1 do
    for j = i + 1, #entries do
      total = total + interval_consonance(math.abs(entries[i].note - entries[j].note))
      n = n + 1
    end
  end
  return total / n
end

-- Trigger the combo bonus if 2+ unique party members fired ATK in window.
-- Bonus damage = floor(N * avg_atk * 0.5 * (1 + consonance / 3)).
-- Plus a re-ring of the chord (all notes simultaneously, longer release).
function trigger_combo_check()
  -- prune stale entries
  for i = #combo_window, 1, -1 do
    if tick - combo_window[i].t > COMBO_WINDOW then
      table.remove(combo_window, i)
    end
  end
  -- de-dup by party member (a single char can't combo with itself)
  local seen, uniq = {}, {}
  for _, e in ipairs(combo_window) do
    if not seen[e.p] then
      seen[e.p] = true
      uniq[#uniq + 1] = e
    end
  end
  if #uniq < 2 then return end
  if not (enemy and enemy.alive) then return end
  local cons = combo_consonance(uniq)
  -- average atk across the chord members
  local sum_atk = 0
  for _, e in ipairs(uniq) do sum_atk = sum_atk + INST.atk(e.p) end
  local avg_atk = sum_atk / #uniq
  local bonus = math.floor(#uniq * avg_atk * 0.5 * (1 + cons / 3))
  if bonus < 1 then bonus = 1 end
  damage_enemy(bonus, cons >= 2.5)   -- treat very-consonant combos as crit
  -- Banner + audio: ring all chord notes simultaneously with sustain.
  local label = "* CHORD x" .. #uniq .. ": +" .. bonus .. " *"
  CONTENT.banner_text  = label
  CONTENT.banner_ticks = 30
  for _, e in ipairs(uniq) do
    local cls = ((e.p.class == "engineer" and "mage")
              or (e.p.class == "mathwiz"  and "bard")
              or (e.p.class == "drummer"  and "warrior")
              or e.p.class)
    sq_trig(cls, midi_to_freq(e.note), 0.5, 0.005, 1.6,
            math.min(1, 0.7 * (CONTENT.combat_reverb_mix or 1.0)))
  end
  -- Achievement: first 2+ chord combo.
  if unlock_achievement then unlock_achievement("first_chord", "First Harmony") end
  -- Clear so the next fire doesn't double-count this chord.
  combo_window = {}
end

local function fire(p)
  apply_player_action(p)
  -- p.queued is already articulation-correct here: apply_player_action
  -- remaps legacy "MAG" to the class instrument and rewrites an
  -- MP-starved STIR to plain ATK, so no insufficient-MP fixup is needed.
  -- (Replaced a vestigial `action == "MAG" and p.mp < 0` check that
  -- could never fire.)
  local action = p.queued
  -- RESO turns (success or denial) rewrite queued to "ATK" mid-call as
  -- the NEXT turn's fallback; the invoke already made its own sound
  -- (signature SFX or denial chord). Don't also play an attack-
  -- articulated note for an attack that didn't happen.
  if p._was_reso then
    p._was_reso = nil
    p.last_fire = tick
    p.last_action = "RESO"
    return
  end
  local a = ARTIC[action] or ARTIC.ATK
  local note = (active_scale()[p.note_idx] or 0) + a.pitch + JAM.root
  local freq = midi_to_freq(note)
  -- apply equipped instrument's tone overrides
  local inst = INST.of(p)
  local atk_t = a.attack  * (inst and inst.atk_mul or 1)
  local rel_t = a.release * (inst and inst.rel_mul or 1)
  local wet_t = math.max(0, math.min(1, (a.wet + (inst and inst.wet_add or 0)) * (CONTENT.combat_reverb_mix or 1.0)))
  sq_trig((((p.class == "engineer" and "mage") or (p.class == "mathwiz" and "bard") or (p.class == "drummer" and "warrior") or p.class)), freq, a.vel, atk_t, rel_t, wet_t)
  p.last_fire = tick
  p.last_action = action  -- so the HUD can render an action-specific animation
  p.note_idx = p.note_idx + 1
  if p.note_idx > p.note_hi then p.note_idx = p.note_lo end
  -- Combo registration: only ATK fires count toward the chord. Other
  -- actions (HEAL/LUTE/MIX/CODE) have their own narrative weight.
  -- (RESO turns can't reach here — the _was_reso early-return above
  -- exits before the note/combo stage.)
  if action == "ATK" then
    combo_window[#combo_window + 1] = {t = tick, p = p, note = note}
    trigger_combo_check()
  end
end

local function enemy_tick()
  if not enemy then return end          -- defensive nil guard
  if not enemy.alive then return end
  if enemy.invincible then return end  -- practice dummy never attacks
  -- Pass 51: boss phase 2. When a boss drops below 30% HP, it ENRAGES:
  -- attack gaps cut in half + atk +25%. One-shot banner on the trigger.
  local boss_visuals = {echo=true, sentinel=true, tide=true, dunerider=true,
                        snowgaunt=true, locrius=true, suno=true, broken_cadence=true,
                        firstchord=true}
  if boss_visuals[enemy.visual] and not enemy.phase2
     and enemy.hp_max > 0 and enemy.hp <= enemy.hp_max * 0.30 then
    enemy.phase2 = true
    enemy.atk = math.ceil(enemy.atk * 1.25)
    -- halve every gap in the attack pattern (faster cadence)
    for i = 1, #enemy.attack_pattern do
      enemy.attack_pattern[i] = math.max(2, math.floor(enemy.attack_pattern[i] / 2))
    end
    -- Boss-specific enrage banners replace the generic "X ENRAGES!" line
    -- so each phase-2 transition has its own character + atmosphere.
    local ENRAGE_BANNERS = {
      echo      = "* the chamber inhales *",
      sentinel  = "* the moss falls away *",
      tide      = "* the water rises wrong *",
      dunerider = "* the courtesy ends *",
      snowgaunt = "* his three-count compresses *",
      locrius   = "* he steps out of time *",
      suno      = "* SUNO TURNS TO YOU *",
      broken_cadence = "* the last phrase rises *",
      firstchord = "* it remembers being whole *",
    }
    CONTENT.banner_text  = ENRAGE_BANNERS[enemy.visual] or ("* " .. enemy.name .. " ENRAGES! *")
    CONTENT.banner_ticks = 42
    ANIM.shake(2, 5); ANIM.burst(96, 32, 8, 15)
  end
  if enemy.confused_until and (tick or 0) < enemy.confused_until then
    local ap = enemy.attack_pattern
    if ap and #ap > 1 then
      for i = #ap, 2, -1 do
        local j = math.random(i)
        ap[i], ap[j] = ap[j], ap[i]
      end
    end
  end
  local next_gap = enemy.attack_pattern[enemy.pattern_idx] or 8
  if (tick - enemy.last_attack) < next_gap then return end
  enemy.last_attack = tick
  enemy.pattern_idx = (enemy.pattern_idx % #enemy.attack_pattern) + 1
  -- attack-sound voice (each enemy has a unique sonic signature)
  if enemy.attack_sound then
    local s = enemy.attack_sound
    local mix = CONTENT.combat_reverb_mix or 1.0
    local sw = math.max(0, math.min(1, s.wet * mix))
    sq_trig(s.class, midi_to_freq(snap_note_to_scale(s.note)), s.vel, s.attack, s.release, sw)
  end
  local alive_idx = alive_party()
  if #alive_idx == 0 then return end
  local target_i = alive_idx[math.random(#alive_idx)]
  local target = party[target_i]
  -- spawn a projectile from the enemy sprite center to the target HUD sprite
  ANIM.proj = {
    sx = 96, sy = 32,
    tx = (target_i - 1) * 32 + 5, ty = 53,
    t = tick,
  }
  -- enemy ATK debuff (HORN/SMPL): halved while ticks remain
  local atk = enemy.atk
  if (enemy.atk_debuff_ticks or 0) > 0 then
    atk = math.max(1, math.floor(atk / 2))
  end
  damage_party(target, atk)
end

local exit_battle  -- forward decl

-- Pass 52: lightweight achievement system. unlock_achievement(id, name)
-- one-shots a flash banner the first time a milestone is hit; stores the
-- flag in CONTENT.achievements (saved/loaded with the rest of CONTENT
-- via the existing snapshot logic).
--
-- ACHIEVEMENT_DEFS lists the visible achievements rendered in the
-- menu's Achievements page. Hidden ones (id not listed here) still
-- unlock via banner but won't appear in the index — used for spoilery
-- story moments. Order = display order.
ACHIEVEMENT_DEFS = {
  {id = "first_jam",          name = "First Jam",         hint = "Open the Jam Pad."},
  {id = "first_chord",        name = "First Harmony",     hint = "Land a 2+ char combo in battle."},
  {id = "first_limit",        name = "Broken Chord",      hint = "Use a Limit Break."},
  {id = "first_rhythm_crit",  name = "On the Beat",       hint = "Crit by pressing A on the beat."},
  {id = "all_shards",         name = "Whole Chord",       hint = "Collect all 7 shards."},
  {id = "ng_plus",            name = "Encore",            hint = "Begin New Game +."},
  {id = "hundred_wins",       name = "Centurion",         hint = "Win 100 random battles."},
  {id = "first_rare",         name = "Rare Hunter",       hint = "Fell one of the six greater strains."},
  {id = "all_caves",          name = "All Seven Sealed",  hint = "Clear all 7 caves."},
  {id = "first_chord_silenced", name = "First Chord Silenced", hint = "Defeat the post-endgame superboss."},
  {id = "first_shard",        name = "First Shard",       hint = "Clear your first cave."},
  {id = "diegues_study",      name = "Diegues' Study",    hint = "Witness Diegues' research scene."},
  {id = "choir_hour",         name = "Choir Hour",        hint = "Witness the Hollow choir."},
  {id = "strom_dream",        name = "Strom Dreams",      hint = "Witness Strom's flashback."},
  {id = "velthe_sightings",   name = "Velthe's Sightings",hint = "Find the observatory log."},
  {id = "reya_cairn",         name = "The Cairn Remembers", hint = "Visit Reya's cairn."},
}

function unlock_achievement(id, name)
  CONTENT.achievements = CONTENT.achievements or {}
  if CONTENT.achievements[id] then return end
  CONTENT.achievements[id] = true
  CONTENT.flash_text = "* " .. name .. " *"
  CONTENT.flash_ticks = 60
end

local function check_battle_end()
  -- Defensive: enemy can be nil if a SCENE or some other state mutation
  -- cleared it between battle ticks (e.g. start_finale_scene completing
  -- mid-tick, or exit_battle racing against a clock.run callback). Bail
  -- out cleanly rather than crashing the clock thread.
  if not enemy then return end
  if not enemy.alive then
    battle_outcome = "VICTORY"
    game_state = "BATTLE_END"
    -- Phase 1 = main reward window (shard / instrument / quip).
    -- Phase 2 = XP gain summary slide (advanced via A press).
    CONTENT.battle_end_phase = 1
    engine.drone_amp(0)         -- silent — victory fanfare plays instead
    victory_step = 0            -- start fanfare from step 1 next tick
    params:set("clock_tempo", OVERWORLD_BPM)  -- victory theme at journey rate
    -- track progression toward boss in the current cave
    last_boss_drop = nil
    local function award_drop(cave_id)
      local id = BOSS_INSTRUMENT_DROP[cave_id]
      if id and not instruments_owned[id] then
        instruments_owned[id] = true
        last_boss_drop = id
      end
    end
    local function clear_boss(cave_id, shard)
      cave_state[cave_id].cleared = true
      cave_state[cave_id].victories = 0
      obtain_shard(shard)
      award_drop(cave_id)
      -- Pass 52 achievement triggers
      unlock_achievement("first_shard", "First Shard")
      local total_cleared = 0
      for i = 1, 7 do if cave_state[i].cleared then total_cleared = total_cleared + 1 end end
      if total_cleared >= 7 then unlock_achievement("all_caves", "All Seven Sealed") end
      -- Boss-specific victory quip. Stashed here, applied by exit_battle
      -- (which otherwise overwrites CONTENT.victory_quip with a random
      -- class-pool one-liner). Small character moments tied to the
      -- specific boss just felled.
      local BOSS_QUIPS = {
        echo      = {speaker="Diegues", body="The chamber is quiet now. Only ours.", class="mage"},
        sentinel  = {speaker="Strom",   body="It sleeps now. As it always should have.", class="warrior"},
        tide      = {speaker="Miel",    body="Tidewatch's chord ends. The shore can rest.", class="cleric"},
        dunerider = {speaker="Alder",   body="Six beats out, two back. Iska was right.", class="bard"},
        snowgaunt = {speaker="Strom",   body="His three-count broke before ours did.", class="warrior"},
        locrius   = {speaker="Diegues", body="Half a step. He was wrong by exactly half a step.", class="mage"},
        suno      = {speaker="Miel",    body="...the seventh note. The chord is whole.", class="cleric"},
      }
      if enemy and BOSS_QUIPS[enemy.visual] then
        CONTENT.boss_quip_pending = BOSS_QUIPS[enemy.visual]
      end
      -- Stash a boss-aftermath scene to fire on exit_battle. Skip cave 7
      -- (Suno) — that goes straight to ENDING via ending_pending.
      -- CRITICAL: obtain_shard (called above) may have queued a BIGGER
      -- beat ("six_shards" → the World of Silence, or "endgame") —
      -- never clobber it. This overwrite is why the six-shards scene
      -- (and with it ECHO's entire recruitment) never fired: the 6th
      -- shard always comes from a cave 1-6 boss.
      if cave_id < 7 and not CONTENT.queued_scene then
        CONTENT.queued_scene = "boss_aftermath_" .. cave_id
      end
      -- Auto-save the story milestone LAST, so the save contains the
      -- shard, the boss instrument drop, the achievements, and the
      -- queued beat together (six_shards included — queued inside
      -- obtain_shard above, so it's on disk too).
      if save_game then save_game() end
    end
    -- (battle-end no longer calls flash_hit — same wash-out concern)
    -- Rare encounters share visuals with cave bosses (Sage Sentinel →
    -- "sentinel", Tideturner → "tide"), so mask the visual for rares:
    -- a rare kill must NEVER trigger clear_boss / shard progression.
    -- Rares fall through to the random_battle branch below instead.
    local boss_visual = (not enemy.is_rare) and enemy.visual or nil
    if boss_visual == "echo"      then clear_boss(1, "lydian")
    elseif boss_visual == "sentinel"  then clear_boss(2, "dorian")
    elseif boss_visual == "tide"      then clear_boss(3, "mixolydian")
    elseif boss_visual == "dunerider" then clear_boss(4, "phrygian")
    elseif boss_visual == "snowgaunt" then clear_boss(5, "aeolian")
    elseif boss_visual == "locrius"   then clear_boss(6, "locrian")
    elseif boss_visual == "suno"      then
      clear_boss(7, "ionian")
      -- final victory triggers the ENDING sequence in exit_battle
      ending_pending = true
    elseif boss_visual == "firstchord" then
      -- Post-endgame superboss. No shard, no instrument; only the
      -- achievement and a one-shot banner. Mark cave 8 cleared so the
      -- player can re-fight via VoidEcho (the NPC stays visible) or
      -- track it in the journal.
      cave_state[8].cleared = true
      unlock_achievement("first_chord_silenced", "First Chord Silenced")
      if save_game then save_game() end   -- milestone: superboss down
      CONTENT.banner_text  = "* THE FIRST CHORD FALLS *"
      CONTENT.banner_ticks = 90
    elseif enemy.is_prologue_silencer or enemy.is_prologue_cave then
      -- Prologue tutorial kills: no cave-progress increment, no item
      -- drop, no boss-progress, no quest counters. The XP-summary
      -- builder above already credited Miel; exit_battle will set the
      -- silencer_defeated / cave_monster_defeated flags.
      SHOP.last_item_drop = nil
    elseif random_battle then
      -- random encounters give XP/loot but don't count toward boss progress
      -- — they DO count toward Hens & Brann sidequests though.
      QUESTS.hens.wins  = QUESTS.hens.wins + 1
      QUESTS.brann.wins = QUESTS.brann.wins + 1
      -- Lifetime random-battle wins (separate from per-quest counters
      -- that get reset on quest claim or NG+).
      CONTENT.total_wins = (CONTENT.total_wins or 0) + 1
      if CONTENT.total_wins >= 100 then
        unlock_achievement("hundred_wins", "Centurion")
      end
      -- Pass 32: random-battle item drops. ~35% chance per win to drop a
      -- consumable. Weighted: salve > vial > ether > tonic > star > key.
      if math.random() < 0.35 then
        local table_drops = {
          {id = "salve", w = 30},
          {id = "vial",  w = 22},
          {id = "ether", w = 14},
          {id = "tonic", w = 8},
          {id = "star",  w = 4},
          {id = "key",   w = 2},
        }
        local total = 0; for _, d in ipairs(table_drops) do total = total + d.w end
        local roll = math.random() * total
        local acc = 0
        for _, d in ipairs(table_drops) do
          acc = acc + d.w
          if roll <= acc then
            SHOP.inv[d.id] = (SHOP.inv[d.id] or 0) + 1
            SHOP.last_item_drop = d.id
            break
          end
        end
      else
        SHOP.last_item_drop = nil
      end
      -- Pass 45: rare encounters override the random-drop with a guaranteed
      -- high-tier item from the rare's own table.
      if enemy.is_rare and enemy.rare_drop then
        SHOP.inv[enemy.rare_drop] = (SHOP.inv[enemy.rare_drop] or 0) + 1
        SHOP.last_item_drop = enemy.rare_drop
        unlock_achievement("first_rare", "Rare Hunter")
      end
    else
      cave_state[current_cave].victories = cave_state[current_cave].victories + 1
    end
  elseif #alive_party() == 0 then
    battle_outcome = "DEFEAT"
    game_state = "BATTLE_END"
    engine.drone_amp(DRONE_AMP_BATTLE_END)   -- somber drone for defeat
    -- Story-arc retry hooks: if the defeated battle was a one-shot
    -- scripted encounter (Strom academy fight, prologue silencers,
    -- prologue cave wisps), roll the relevant story flag back so the
    -- player can re-enter the area and try again. Without this the
    -- player is soft-locked out of the join scene on a single loss.
    if enemy and enemy.is_strom_arc then
      CONTENT.academy_state = "untriggered"
      -- Don't undo Diegues' join — he's already a party member, so the
      -- replay will skip his join logic (class_in_party guard) and go
      -- straight to dialogue + battle. Player keeps progress.
    elseif enemy and enemy.is_prologue_silencer then
      -- Player retreats to the throne room — they re-engage the same
      -- silencer next time they walk up to it (state stays "coup").
      -- Nothing to roll back.
    elseif enemy and enemy.is_prologue_cave then
      -- Same idea — wisp stays alive on the map, retry by walking up.
    elseif enemy and enemy.is_broken_cadence then
      -- Broken Cadence defeat: roll back so stepping onto the altar
      -- re-triggers the scene on next visit (flag stays false).
      flag.broken_cadence_done = false
    end
  end
end

-- ──────────────────────────────────────────────────────────────────────────
-- Pass 34: battle music. Plays underneath combat: warrior bass ostinato,
-- cleric pad, mage melodic line, bard accent stabs. Boss flag picks the
-- heavier "boss" theme; otherwise "encounter" for random+regular fights.
-- Intentionally global to stay under the 200-local main-chunk cap.
function tick_battle_music()
  if not enemy then return end
  -- Practice dummy uses no battle music — let the player jam unobstructed.
  if enemy.invincible then return end
  -- choose theme:
  -- - boss enemies (cave bosses by visual) → BATTLE_THEMES.boss (heavy doom)
  -- - rare encounters → BATTLE_THEMES.boss too, since they're mini-bosses
  --   and the encounter theme felt too casual for the moment. Tempo bump
  --   in enter_battle separates them sonically from real bosses.
  -- - everything else → BATTLE_THEMES.encounter (the standard random fight).
  local boss_visuals = {echo=true, sentinel=true, tide=true, dunerider=true,
                        snowgaunt=true, locrius=true, suno=true, broken_cadence=true,
                        firstchord=true}
  local theme
  if boss_visuals[enemy.visual] then
    theme = BATTLE_THEMES.boss
  elseif enemy.is_rare then
    theme = BATTLE_THEMES.boss
  else
    theme = BATTLE_THEMES.encounter
  end
  -- Each theme can declare its own pattern length (e.g. encounter is 16
  -- bars / 256 steps). Falls back to OW_PATTERN_LEN.
  local plen = theme.pattern_len or OW_PATTERN_LEN
  TITLE.battle_step = (TITLE.battle_step % plen) + 1
  for class, pat in pairs(theme.pattern) do
    fire_ow_voice(class, pat[TITLE.battle_step], theme.artic)
  end
end

local function tick_battle()
  -- Defensive: enemy may be nil if exit_battle fired but the BATTLE
  -- game_state hasn't yet flipped (clock-thread vs main-thread race).
  -- Bail out cleanly so the clock callback doesn't crash the whole loop.
  if not enemy then return end
  -- music underlay (Pass 34)
  tick_battle_music()
  -- per-beat status effect ticking
  for _, p in ipairs(party) do
    if p.alive then
      if (p.regen_hp_ticks or 0) > 0 then
        p.regen_hp_ticks = p.regen_hp_ticks - 1
        if (tick % 8) == 0 then
          p.hp = math.min(p.hp_max, p.hp + 1)
        end
      end
      if (p.regen_mp_ticks or 0) > 0 then
        p.regen_mp_ticks = p.regen_mp_ticks - 1
        if (tick % 12) == 0 then
          p.mp = math.min(p.mp_max, p.mp + 1)
        end
      end
      -- Pass 50: POISON — slow HP drip every 6 ticks while poisoned.
      if (p.poison_ticks or 0) > 0 then
        p.poison_ticks = p.poison_ticks - 1
        if (tick % 6) == 0 then
          p.hp = math.max(1, p.hp - 1)
          ANIM.spawn_dmg(ANIM.party_hud_x(p), 47, 1, 9)
        end
      end
      -- Pass 50: SLEEP — countdown only; ATB freeze handled below.
      if (p.sleep_ticks or 0) > 0 then p.sleep_ticks = p.sleep_ticks - 1 end
      if (p.dmg_reduce_ticks or 0) > 0 then p.dmg_reduce_ticks = p.dmg_reduce_ticks - 1 end
    end
  end
  if enemy and (enemy.atk_debuff_ticks or 0) > 0 then
    enemy.atk_debuff_ticks = enemy.atk_debuff_ticks - 1
  end
  -- (banner_ticks countdown moved to the universal tick section of the
  -- main clock — banners fire from overworld gates/pickups/scenes too,
  -- and decrementing only in battle froze them there.)
  local sw = reso_fx_active("slow_wheel")
  for _, p in ipairs(party) do
    if p.alive then
      -- Sleep freezes the ATB. Poison still ticks (it's a damage-over-time).
      if (p.sleep_ticks or 0) == 0 then
        local eff_spd = INST.spd(p) + (sw and sw.spd or 0)
        p.atb = p.atb + eff_spd
        if p.atb >= 16 then
          p.atb = p.atb - 16
          fire(p)
        end
      end
    end
  end
  enemy_tick()
  reso_fx_tick()
  check_battle_end()
end

travel_to = function(map_id, x, y)
  current_map_id = map_id
  _G.current_map_id = map_id   -- keep the STORY-closure mirror in sync
  if map_id == 1 then
    map = MAINLAND; npcs = MAINLAND_NPCS
  elseif map_id == 2 then
    map = EASTERN_REACHES; npcs = EASTERN_NPCS
  elseif map_id == 3 then
    map = NORTHERN_WILDS; npcs = NORTHERN_NPCS
  elseif map_id == 5 then
    map = CONTENT.inn_map; npcs = CONTENT.inn_npcs
  elseif map_id == 6 then
    map = CONTENT.shop_map; npcs = CONTENT.shop_npcs
  elseif map_id == 15 then
    map = CONTENT.eastern_shop_map; npcs = CONTENT.eastern_shop_npcs
  elseif map_id == 16 then
    map = CONTENT.northern_shop_map; npcs = CONTENT.northern_shop_npcs
  elseif map_id == 17 then
    map = CONTENT.eastern_inn_map; npcs = CONTENT.eastern_inn_npcs
  elseif map_id == 18 then
    map = CONTENT.northern_inn_map; npcs = CONTENT.northern_inn_npcs
  elseif map_id == 19 then
    map = CONTENT.academy_map; npcs = CONTENT.academy_npcs
  elseif map_id == 20 then
    map = CONTENT.castle_map; npcs = CONTENT.castle_npcs
  elseif map_id == 21 then
    map = CONTENT.escape_cave_map; npcs = CONTENT.escape_cave_npcs
  elseif map_id == 22 then
    map = CONTENT.western_region_map; npcs = CONTENT.western_region_npcs
  elseif map_id == 23 then
    map = CONTENT.lirael_ruins_map; npcs = CONTENT.lirael_ruins_npcs
  elseif map_id == 24 then
    map = CONTENT.observatory_map; npcs = CONTENT.observatory_npcs
  elseif map_id == 26 then
    map = CONTENT.far_hills_map; npcs = CONTENT.far_hills_npcs
  elseif map_id == 27 then
    map = CONTENT.castle_hallway_map; npcs = CONTENT.castle_hallway_npcs
  elseif map_id == 28 then
    map = CONTENT.quarters_map; npcs = CONTENT.quarters_npcs
  elseif map_id == 29 then
    map = CONTENT.study_map; npcs = CONTENT.study_npcs
  elseif map_id == 30 then
    map = CONTENT.library_map; npcs = CONTENT.library_npcs
  elseif map_id == 31 then
    map = CONTENT.overlook_map; npcs = CONTENT.overlook_npcs
  elseif map_id == 32 then
    map = CONTENT.courtyard_map; npcs = CONTENT.courtyard_npcs
  elseif map_id == 33 then
    map = CONTENT.barracks_map; npcs = CONTENT.barracks_npcs
  elseif map_id == 34 then
    map = CONTENT.infirmary_map; npcs = CONTENT.infirmary_npcs
  elseif map_id == 7 then
    map = CONTENT.cave1_map; npcs = CONTENT.cave1_npcs
  elseif map_id == 8 then
    map = CONTENT.cave2_map; npcs = CONTENT.cave2_npcs
  elseif map_id == 9 then
    map = CONTENT.cave3_map; npcs = CONTENT.cave3_npcs
  elseif map_id == 10 then
    map = CONTENT.cave4_map; npcs = CONTENT.cave4_npcs
  elseif map_id == 11 then
    map = CONTENT.cave5_map; npcs = CONTENT.cave5_npcs
  elseif map_id == 12 then
    map = CONTENT.hollow_map; npcs = CONTENT.hollow_npcs
  elseif map_id == 13 then
    map = CONTENT.cave6_map; npcs = CONTENT.cave6_npcs
  elseif map_id == 14 then
    map = CONTENT.cave7_map; npcs = CONTENT.cave7_npcs
  elseif map_id == 35 then
    map = SUNWARD_COAST_MAP; npcs = CONTENT.sunward_coast_npcs or {}
  elseif map_id == 36 then
    map = PHRYGIAN_CITY_MAP; npcs = CONTENT.phrygian_city_npcs or {}
  elseif map_id == 37 then
    map = DRUMHALL_MAP; npcs = DRUMHALL_NPCS
  elseif map_id == 38 then
    -- Shared house-interior id (see CONTENT.HOUSES). try_move's tile-5
    -- handler / load_game point house_map + house_npcs at the right
    -- registry entry before warping; the fallbacks only matter if a
    -- corrupt save lands here without a key.
    map = CONTENT.house_map or CONTENT.inn_map
    npcs = CONTENT.house_npcs or {}
  else
    map = SUNOS_DOMAIN; npcs = SUNOS_NPCS
  end
  MAP_W = #map[1]
  MAP_H = #map
  player.x = x
  player.y = y
  last_region = nil   -- force banner refresh
  update_camera()
  -- Academy story trigger: first time the player enters map 19 with
  -- academy_state still "untriggered", launch the entry cutscene which
  -- chains into the Strom battle when its dialogue closes.
  -- IMPORTANT: every scene-launcher below is gated on `not SCENE.active`
  -- so that a scripted scene calling `travel_to(...)` in a `set` step
  -- can't trigger a NESTED scene that would clobber its own state
  -- (SCENE.start wipes script/step/actors). E.g. the courtyard breach
  -- ends with travel_to(27, ...) and must not re-fire page_warning.
  local _scene_busy = (SCENE and SCENE.active) and true or false
  if not _scene_busy and map_id == 19 and CONTENT and CONTENT.academy_state == "untriggered" then
    if start_academy_intro then start_academy_intro() end
  end
  -- ECHO recruitment: Act 3 "World of Silence" beat at the Academy
  -- courtyard. Fires once when the player enters map 19 with the silence
  -- flag set (the six-shards scene sets it; see start_six_shards_scene).
  -- CONTENT.debug_force_echo_recruit still bypasses the check for testing.
  -- Re-check SCENE.active FRESH here (not just the _scene_busy snapshot):
  -- on a first-ever Academy entry during the silence, the academy-intro
  -- gate above has already SCENE.start-ed — firing ECHO's scene in the
  -- same travel_to would wipe the intro script and its on_complete
  -- (Diegues join + Strom battle), losing both recruits for the run.
  -- ECHO simply waits for the next visit.
  if not _scene_busy and not (SCENE and SCENE.active) and map_id == 19 and CONTENT
     and (CONTENT.act3_silence or CONTENT.debug_force_echo_recruit)
     and not (CONTENT.scene_seen and CONTENT.scene_seen.echo_recruit) then
    if start_echo_recruit_scene then start_echo_recruit_scene() end
  end
  -- Castle prologue: on first map entry, play a brief INTRO beat
  -- (raid sounds + opening line) then hand control to Miel in her
  -- private chamber. Suno's confrontation scene now fires when Miel
  -- walks INTO the throne hall (handled in the per-tile try_move
  -- check via CONTENT.prologue_throne_room_pending).
  if not _scene_busy and map_id == 28 and CONTENT and not CONTENT.prologue_intro_done then
    if start_prologue_castle_intro then start_prologue_castle_intro() end
  end
  -- First time stepping into the hallway from Quarters during prologue:
  -- the royal Page sprints up to Miel with the warning. Once-only.
  if not _scene_busy and map_id == 27 and CONTENT and CONTENT.prologue_intro_done
     and not CONTENT.prologue_scene_done
     and not (CONTENT.scene_seen and CONTENT.scene_seen.page_warning) then
    CONTENT.scene_seen = CONTENT.scene_seen or {}
    CONTENT.scene_seen.page_warning = true
    if start_page_warning_scene then start_page_warning_scene() end
  end
  -- Post-clear academy revisit: a one-time quiet beat when player walks
  -- back into the cleared library.
  if not _scene_busy and map_id == 19 and CONTENT and CONTENT.academy_state == "complete" then
    queue_first_arrival("academy_revisit", {
      "(The Hall of Resonance is quiet. Plaster dust still drifts. Diegues stops at the lectern.)",
      "[Diegues] (touches the wood; his hand comes away white) ...still warm. Where the silencer's hammer fell.",
      "[Strom]   (looks at his own hands) ...I'm sorry.",
      "[Diegues] (does not look up) Don't be sorry. Be different.",
      "[Strom]   (a single nod) Yes.",
      "(They stand in the dust a moment. Then they walk back out together.)",
    })
    -- Choir Hour: choreographed scene that fires the FIRST revisit after
    -- the player has at least 3 shards (so the academy has had time to
    -- recover its choir). Diegues conducts a small four-voice choir of
    -- restored students; one held chord at the end.
    local n = 0; for _, v in pairs(shards) do if v then n = n + 1 end end
    if n >= 3 and not (CONTENT.scene_seen and CONTENT.scene_seen.academy_choir)
       and start_academy_choir_scene then
      CONTENT.scene_seen = CONTENT.scene_seen or {}
      CONTENT.scene_seen.academy_choir = true
      start_academy_choir_scene()
    end
    -- Diegues' Study revisit: separate one-shot. Fires the first time
    -- Miel revisits the academy with Diegues in active party AND at
    -- least 5 shards. A quiet character beat: he reads his own old
    -- notes and admits something he wouldn't say at the lectern.
    if n >= 5 and class_in_party and class_in_party("mage")
       and not (CONTENT.scene_seen and CONTENT.scene_seen.diegues_study)
       and start_diegues_study_scene then
      CONTENT.scene_seen = CONTENT.scene_seen or {}
      CONTENT.scene_seen.diegues_study = true
      start_diegues_study_scene()
    end
  end
  -- Cinematic first-arrivals for the three remote regions. Each is a
  -- choreographed SCENE with camera pan, atmospheric SFX, and a brief
  -- party-reaction beat — replaces the older text-only banner.
  if not _scene_busy and map_id == 2 and start_eastern_arrival_scene
     and not (CONTENT.scene_seen and CONTENT.scene_seen.eastern_arrival) then
    CONTENT.scene_seen = CONTENT.scene_seen or {}
    CONTENT.scene_seen.eastern_arrival = true
    start_eastern_arrival_scene()
  elseif not _scene_busy and map_id == 3 and start_northern_arrival_scene
     and not (CONTENT.scene_seen and CONTENT.scene_seen.northern_arrival) then
    CONTENT.scene_seen = CONTENT.scene_seen or {}
    CONTENT.scene_seen.northern_arrival = true
    start_northern_arrival_scene()
  elseif not _scene_busy and map_id == 4 and start_sunos_arrival_scene
     and not (CONTENT.scene_seen and CONTENT.scene_seen.sunos_arrival) then
    CONTENT.scene_seen = CONTENT.scene_seen or {}
    CONTENT.scene_seen.sunos_arrival = true
    start_sunos_arrival_scene()
  elseif not _scene_busy and map_id == 35 and start_sunward_arrival_scene
     and not (CONTENT.scene_seen and CONTENT.scene_seen.sunward_arrival) then
    CONTENT.scene_seen = CONTENT.scene_seen or {}
    CONTENT.scene_seen.sunward_arrival = true
    start_sunward_arrival_scene()
  elseif not _scene_busy and map_id == 36 and start_phrygian_arrival_scene
     and not (CONTENT.scene_seen and CONTENT.scene_seen.phrygian_arrival) then
    CONTENT.scene_seen = CONTENT.scene_seen or {}
    CONTENT.scene_seen.phrygian_arrival = true
    start_phrygian_arrival_scene()
  elseif not _scene_busy and map_id == 19 and not flag.diegues_returned then
    local lead = party[active] and party[active].class
    if lead == "mage" and start_academy_diegues_returns_scene then
      SCENE.start(start_academy_diegues_returns_scene())
    end
  end
  -- First-arrival story beats. Each fires exactly once per save.
  if not _scene_busy and map_id == 21 then
    -- First step into the escape cave — choreographed if we have the
    -- helper, otherwise fall back to plain text.
    if not (CONTENT.scene_seen and CONTENT.scene_seen.escape_cave_first)
       and start_escape_cave_scene then
      CONTENT.scene_seen = CONTENT.scene_seen or {}
      CONTENT.scene_seen.escape_cave_first = true
      start_escape_cave_scene()
    else
      queue_first_arrival("escape_cave_first", {
        "(The tapestry falls back into place behind her.)",
        "(The cave smells of wet stone and a cold older than the keep.)",
        "[Miel]   (her voice is very small) ...grandmother walked this once.",
        "[Miel]   She came back. She was dressed as a baker. No one knew where she had been.",
        "(The dark stretches forward. There is something in it that is not dark.)",
        "(She hums her grandmother's song, so the dark stays small. She walks east.)",
      })
    end
  elseif not _scene_busy and map_id == 22 then
    -- First step into the Western Region overworld.
    queue_first_arrival("western_region_first", {
      "(The land west of the village is older than maps. Trees grew here when the Crystal still sang as one.)",
      "(Through the trees, a building. Tall windows. A spiral on the door, faintly carved.)",
      "(This was the Academy. Once. It is being attacked now. You can hear the breaking.)",
    })
  elseif not _scene_busy and map_id == 23 then
    -- First step into the Lirael Ruins. A memory scene that only fires
    -- once per save. Choreographed: the camera rests on the ruined
    -- throne in the hall from the prologue raid; Miel walks up the
    -- carpet remnant to the foot of the dais; the ghost-bell rings.
    if not (CONTENT.scene_seen and CONTENT.scene_seen.lirael_first)
       and start_lirael_first_visit then
      CONTENT.scene_seen = CONTENT.scene_seen or {}
      CONTENT.scene_seen.lirael_first = true
      start_lirael_first_visit()
    end
  elseif not _scene_busy and map_id == 24 then
    -- First step into Velthe's Observatory. Iola greets Miel; awards the
    -- Sightings Lens instrument.
    if not (CONTENT.scene_seen and CONTENT.scene_seen.observatory_first)
       and start_observatory_first_visit then
      CONTENT.scene_seen = CONTENT.scene_seen or {}
      CONTENT.scene_seen.observatory_first = true
      start_observatory_first_visit()
    elseif not (CONTENT.scene_seen and CONTENT.scene_seen.observatory_tour)
       and start_observatory_caretaker_tour_scene then
      CONTENT.scene_seen = CONTENT.scene_seen or {}
      CONTENT.scene_seen.observatory_tour = true
      start_observatory_caretaker_tour_scene()
    end
  elseif not _scene_busy and map_id == 26 then
    -- First step into the Far Hills. A small text panel and a held
    -- bard tone — the chord ran here once.
    queue_first_arrival("far_hills_first", {
      "(The hills roll out beyond the cave-mouth. Older than the village. Quieter.)",
      "(A creek runs west. A small ruin at the center. A man with sheep.)",
      "[Miel]    ...grandmother walked these.",
    })
  end
end
-- Mirror travel_to into _ENV so closures created BEFORE the forward
-- decl at line ~11630 (e.g. start_courtyard_breach_script, defined at
-- line ~5443) can resolve it via global lookup at call time. Without
-- this, those closures call nil and the error is silently swallowed
-- by their pcall wrappers, leaving the player on the old map.
_G.travel_to = travel_to

-- Pass 45: rare encounters. Each cave-pool has a uniquely-named, boosted
-- variant of one of its enemies that drops a guaranteed high-tier item.
-- 4% chance per random encounter to roll rare instead of standard.
-- Global to dodge the 200-local main-chunk cap.
