  screen.level(5); screen.move(px + 1, py + 6); screen.line(px + 4, py + 2); screen.line(px + 7, py + 6); screen.stroke()
  -- dark interior
  screen.level(0); screen.rect(px + 2, py + 4, 4, 3); screen.fill()
