  screen.level(5); screen.rect(px + 1, py + 1, 6, 1); screen.fill()
  -- door (warm brown)
  screen.level(7); screen.rect(px + 3, py + 4, 2, 3); screen.fill()
  -- door handle pixel
  screen.level(11); screen.pixel(px + 4, py + 5); screen.fill()
  -- lantern over the door (yellow blink)
