    screen.level(15); screen.pixel(px + 4, py + 2); screen.fill()
  else
    screen.level(11); screen.pixel(px + 4, py + 2); screen.fill()
  end
  -- dome top (a single dim arc pixel)
  screen.level(7); screen.pixel(px + 3, py); screen.pixel(px + 4, py); screen.fill()
end

