  screen.pixel(sx + 7, sy + 2); screen.pixel(sx + 7, sy + 4); screen.pixel(sx + 7, sy + 6); screen.fill()
end

-- QuenchBarrel (Brann's forge): water sheen + a steam wisp that rises
-- even with nothing cooling in it.
NPC_SPRITES.QuenchBarrel = function(sx, sy)
  screen.level(8); screen.rect(sx + 2, sy + 2, 4, 2); screen.fill()    -- water surface
  screen.level(11); screen.pixel(sx + 3, sy + 2); screen.fill()        -- sheen
  local w = (tick // 8) % 3
  screen.level(4); screen.pixel(sx + 3 + w, sy + 1 - (w % 2)); screen.fill()  -- wandering steam
end

-- SparePlate (Brann's forge): iron plate on the rack — gone once taken
-- (same vanish-on-flag trick as RemedyShelf).
NPC_SPRITES.SparePlate = function(sx, sy)
  if flag and flag.brann_plate_taken then return end
  screen.level(7);  screen.rect(sx + 2, sy + 3, 4, 3); screen.fill()   -- the plate
  screen.level(11); screen.rect(sx + 2, sy + 3, 4, 1); screen.fill()   -- top edge catches the forge light
  screen.level(3);  screen.pixel(sx + 4, sy + 4); screen.fill()        -- Brann's stamp
end

-- NetLoft (fisher cottage): net mesh hung from the loft beam.
NPC_SPRITES.NetLoft = function(sx, sy)
  screen.level(5)
  screen.move(sx + 1, sy + 1); screen.line(sx + 6, sy + 6); screen.stroke()
  screen.move(sx + 6, sy + 1); screen.line(sx + 1, sy + 6); screen.stroke()
  screen.move(sx + 1, sy + 3); screen.line(sx + 6, sy + 3); screen.stroke()
  screen.level(9); screen.pixel(sx + 7, sy + 6); screen.fill()          -- cork float
end

-- HarborLedger (widow's house): the ledger open on the table.
NPC_SPRITES.HarborLedger = function(sx, sy)
  screen.level(13); screen.rect(sx + 1, sy + 3, 6, 3); screen.fill()   -- open pages
  screen.level(3);  screen.move(sx + 4, sy + 3); screen.line(sx + 4, sy + 5); screen.stroke()  -- spine
  screen.level(5);  screen.move(sx + 2, sy + 4); screen.line(sx + 3, sy + 4); screen.stroke()  -- entries
  screen.level(2);  screen.pixel(sx + 5, sy + 4); screen.fill()        -- the last, unfinished line
end

-- TwoCups (widow's house): one cup washed and rim-down, one facing the
-- sea, untouched for years.
NPC_SPRITES.TwoCups = function(sx, sy)
  screen.level(11); screen.rect(sx + 1, sy + 4, 2, 2); screen.fill()   -- washed cup, rim-down
  screen.level(6);  screen.rect(sx + 5, sy + 3, 2, 3); screen.fill()   -- his cup, upright
  screen.level(2);  screen.pixel(sx + 5, sy + 2); screen.fill()        -- dust on the rim
end

-- CoiledLines (Beck's cottage): rope coils on the shelf pegs.
NPC_SPRITES.CoiledLines = function(sx, sy)
  screen.level(9); screen.rect(sx + 1, sy + 2, 3, 3); screen.fill()
  screen.level(2); screen.pixel(sx + 2, sy + 3); screen.fill()          -- coil hole
  screen.level(7); screen.rect(sx + 5, sy + 3, 2, 2); screen.fill()     -- smaller coil
end

-- PracticeRoom (Academy west box): chalk tally marks climbing the wall.
NPC_SPRITES.PracticeRoom = function(sx, sy)
  screen.level(11)
  screen.move(sx + 1, sy + 2); screen.line(sx + 1, sy + 5); screen.stroke()
  screen.move(sx + 3, sy + 2); screen.line(sx + 3, sy + 5); screen.stroke()
  screen.move(sx + 5, sy + 2); screen.line(sx + 5, sy + 5); screen.stroke()
  screen.move(sx, sy + 4); screen.line(sx + 6, sy + 3); screen.stroke() -- the cross-stroke of five
  screen.level(5); screen.pixel(sx + 7, sy + 6); screen.fill()          -- chalk stub on the floor
end

-- ListeningRoom (Academy east box): felt panel + the carved name.
NPC_SPRITES.ListeningRoom = function(sx, sy)
  screen.level(3); screen.rect(sx + 1, sy + 1, 6, 5); screen.fill()    -- felt panel
  screen.level(1); screen.rect(sx + 2, sy + 2, 4, 3); screen.fill()    -- deeper hush
  screen.level(7); screen.move(sx + 2, sy + 6); screen.line(sx + 5, sy + 6); screen.stroke()  -- the carving
end

-- Bothy (Far Hills ruin): bedroll + wind-chime of flat keys.
NPC_SPRITES.Bothy = function(sx, sy)
  screen.level(6);  screen.rect(sx + 1, sy + 5, 5, 2); screen.fill()   -- bedroll
  screen.level(9);  screen.rect(sx + 1, sy + 5, 2, 2); screen.fill()   -- rolled end
  screen.level(7)                                                       -- hanging chime keys
  screen.move(sx + 6, sy + 1); screen.line(sx + 6, sy + 3); screen.stroke()
  screen.move(sx + 7, sy + 1); screen.line(sx + 7, sy + 4); screen.stroke()
  if (tick % 40) < 6 then screen.level(13); screen.pixel(sx + 7, sy + 4); screen.fill() end  -- a key catches the wind
end

-- Salt (Beck's cat): shares the cat sprite with Mews/Pim.
NPC_SPRITES.Salt = NPC_SPRITES.Mews

-- ============================================================ DRAWING — STATES

-- Pixel offsets that center an interior map within the 128x64 viewport.
-- Returns (0,0) for maps that meet or exceed viewport dimensions
-- (overworld, throne hall, etc.). When non-zero, the surrounding margin
-- is painted with a static musical-staff backdrop and the room is
-- inset by (ox, oy).
-- Global (not local) to dodge the 200-locals-per-main-chunk Lua cap.
function interior_view_offset()
  local ox = math.max(0, math.floor((VIEW_W - MAP_W) / 2) * TILE)
  local oy = math.max(0, math.floor((VIEW_H - MAP_H) / 2) * TILE)
  return ox, oy
end

-- Static musical-staff wallpaper for the margin around a centered
-- interior map. Five horizontal lines plus a small treble-clef glyph
-- anchored in the left margin. Drawn before tiles so opaque room walls
-- cover it where they overlap; only the off-room strips show.
function draw_staff_backdrop(ox, oy)
  -- Plain black backdrop. Previously this drew a 5-line music staff +
  -- treble-clef glyph in the side margins of small interior maps; the
  -- staff + clef were removed in favor of a clean black surround so the
  -- room reads more clearly against the OLED.
  screen.level(0); screen.rect(0, 0, 128, 64); screen.fill()
end

local function draw_overworld()
  local view_ox, view_oy = interior_view_offset()
  local centered = (view_ox > 0) or (view_oy > 0)
  if centered then draw_staff_backdrop(view_ox, view_oy) end
  for vy = 0, VIEW_H - 1 do
    for vx = 0, VIEW_W - 1 do
      local tx = cam.x + vx
      local ty = cam.y + vy
      if centered and (tx < 1 or tx > MAP_W or ty < 1 or ty > MAP_H) then
        goto next_tile
      end
      local t = tile_at(tx, ty)
      local sx = vx * TILE + view_ox
      local sy = vy * TILE + view_oy
      -- Inside-an-interior overrides:
      --   inn/shop (5/6) → wood planks for floor + themed walls
      --   cave1-5 (7-11) → cave floor for floor
      if (current_map_id == 5 or current_map_id == 6 or current_map_id == 15 or current_map_id == 16
          or current_map_id == 17 or current_map_id == 18 or current_map_id == 19
          or current_map_id == 20 or current_map_id == 21
          or current_map_id == 27 or current_map_id == 28
          or current_map_id == 29 or current_map_id == 30
          or current_map_id == 31 or current_map_id == 33
          or current_map_id == 34
          or current_map_id == 38) and t == 0 then   -- 38 = house interiors
        TILE_DRAW.floor(sx, sy)
      elseif current_map_id == 23 and t == 0 then
        -- Lirael Ruins: ash-covered scorched stone. Drawn as dim stone
        -- with sparse light flecks (per-tile-stable so it doesn't shimmer).
        screen.level(2); screen.rect(sx, sy, 8, 8); screen.fill()
        local seed = (tx * 17 + ty * 31) % 32
        if seed < 6 then
          screen.level(4); screen.pixel(sx + (seed % 7), sy + ((seed * 3) % 7))
          screen.fill()
        end
        if seed > 24 then
          screen.level(3); screen.pixel(sx + 7 - (seed % 7), sy + 7 - ((seed * 5) % 7))
          screen.fill()
        end
      elseif current_map_id == 23 and t == 4 then
        -- Ruined wall block — broken stone with chipped edge.
        screen.level(5); screen.rect(sx, sy, 8, 8); screen.fill()
        screen.level(3); screen.rect(sx, sy + 4, 8, 1); screen.fill()
        screen.level(2); screen.pixel(sx + 1, sy + 1); screen.pixel(sx + 6, sy + 6); screen.fill()
        local seed = (tx * 13 + ty * 7) % 8
        if seed < 3 then
          screen.level(0); screen.rect(sx + (seed * 2), sy + 7, 2, 1); screen.fill()
        end
      elseif current_map_id == 24 and t == 0 then
        -- Observatory floor — deep blue-black polished stone. Faint
        -- starfield: a few stable bright pixels that don't shimmer.
        screen.level(1); screen.rect(sx, sy, 8, 8); screen.fill()
        local seed = (tx * 19 + ty * 11) % 64
        if seed < 4 then
          screen.level(11); screen.pixel(sx + (seed % 7), sy + ((seed * 5) % 7))
          screen.fill()
        elseif seed < 8 then
          screen.level(7); screen.pixel(sx + ((seed + 3) % 7), sy + ((seed * 3) % 7))
          screen.fill()
        end
      elseif current_map_id == 24 and t == 4 then
        -- Observatory wall — dark with brass-fitting glints.
        screen.level(3); screen.rect(sx, sy, 8, 8); screen.fill()
        screen.level(5); screen.rect(sx, sy, 8, 1); screen.fill()
        screen.level(5); screen.rect(sx, sy + 7, 8, 1); screen.fill()
        local seed = (tx * 7 + ty * 13) % 16
        if seed < 3 then
          screen.level(11); screen.pixel(sx + 4, sy + 4); screen.fill()
        end
      elseif (current_map_id == 5 or current_map_id == 17 or current_map_id == 18 or current_map_id == 19 or current_map_id == 20
              or current_map_id == 27 or current_map_id == 28
              or current_map_id == 29 or current_map_id == 30
              or current_map_id == 31 or current_map_id == 32
              or current_map_id == 33 or current_map_id == 34) and t == 4 then
        TILE_DRAW.inn_wall(sx, sy, tx + ty * MAP_W)
      elseif (current_map_id == 6 or current_map_id == 15 or current_map_id == 16) and t == 4 then
        TILE_DRAW.shop_wall(sx, sy, tx + ty * MAP_W)
      elseif (current_map_id == 7 or current_map_id == 8 or current_map_id == 9
              or current_map_id == 10 or current_map_id == 11
              or current_map_id == 12 or current_map_id == 13
              or current_map_id == 14) and t == 0 then
        TILE_DRAW.cavefloor(sx, sy, tx + ty * MAP_W)
      else
        local fn = TILE_DRAW[t] or TILE_DRAW[0]
        if t == 3 or t == 6 or t == 7 or t == 9 or t == 11 or t == 14 or t == 16 or t == 18 or t == 19 or t == 20 or t == 24 or t == 27 or t == 30 or t == 32 or t == 36 or t == 38 or t == 39 or t == 41 or t == 43 or t == 52 or t == 53 or t == 54 or t == 55 or t == 56 or t == 57 or t == 58 or t == 62 or t == 67 or t == 70 or t == 73 or t == 84 or t == 94 or t == 95 or t == 96 or t == 108 then fn(sx, sy, tick)
        elseif t == 0 or t == 8 then fn(sx, sy, tx + ty * MAP_W)
        else fn(sx, sy)
        end
      end
      ::next_tile::
    end
  end

  -- NPCs face the camera (down) regardless of where the player is facing,
  -- since some NPC sprites (engineer, mathwiz) use the player.facing
  -- dispatcher when rendered.
  local saved_facing_npc = player.facing
  player.facing = "down"
  -- During an active SCENE, hide any static NPC whose name is being
  -- puppeted by a scene actor (e.g. the breach script spawns "Capt.Ren"
  -- + "GuardA..D"). Without this filter, the static NPC keeps rendering
  -- at its original tile while the scene actor moves — leaving a
  -- "ghost" sprite at the start position.
  local _scene_puppets = nil
  if SCENE and SCENE.active and SCENE.actors and #SCENE.actors > 0 then
    _scene_puppets = {}
    for _, a in ipairs(SCENE.actors) do
      if a.name then _scene_puppets[a.name] = true end
    end
  end
  for _, n in ipairs(npcs) do
    if n.x >= cam.x and n.x < cam.x + VIEW_W
       and n.y >= cam.y and n.y < cam.y + VIEW_H
       and npc_visible(n)
       and not (_scene_puppets and _scene_puppets[n.name]) then
      local fn = NPC_SPRITES[n.name] or draw_npc_at
      -- subtle idle bob: each NPC breathes 1px out of phase with the others
      local bob = (((tick + n.x * 7 + n.y * 3) % 32) < 16) and 0 or 1
      fn((n.x - cam.x) * TILE + view_ox, (n.y - cam.y) * TILE - bob + view_oy)
    end
  end
  player.facing = saved_facing_npc

  -- NPC barks: small text bubble above the NPC sprite, fades out over
  -- 90 ticks. Match each bark to its source NPC by name; skip any
  -- whose NPC is offscreen or no longer visible. Prune expired entries.
  if CONTENT.barks and #CONTENT.barks > 0 then
    screen.font_face(25); screen.font_size(6)
    for i = #CONTENT.barks, 1, -1 do
      local b = CONTENT.barks[i]
      local age = tick - b.t
      if age > 90 then
        table.remove(CONTENT.barks, i)
      else
        -- find NPC by name to get current position
        local src
        for _, n in ipairs(npcs) do
          if n.name == b.name then src = n; break end
        end
        if src and src.x >= cam.x and src.x < cam.x + VIEW_W
           and src.y >= cam.y and src.y < cam.y + VIEW_H
           and npc_visible(src) then
          local sx = (src.x - cam.x) * TILE + 4 + view_ox
          local sy = (src.y - cam.y) * TILE - 4 + view_oy
          local w = math.min(110, #b.line * 4 + 4)
          -- truncate to the bubble's char capacity (~4px/char at this
          -- font size) so a long bark can't spill past the border
          local line = b.line
          local cap = math.floor((w - 4) / 4)
          if #line > cap then line = line:sub(1, cap) end
          -- clamp the bubble center so the rect stays inside [0,128];
          -- the tail below still points at the NPC's true position
          local bx = math.max(w / 2, math.min(128 - w / 2, sx))
          -- bubble background (dark)
          screen.level(0); screen.rect(bx - w / 2, sy - 6, w, 7); screen.fill()
          -- bubble border + tail (fades with age)
          local lev = math.max(2, 11 - math.floor(age / 12))
          screen.level(lev); screen.rect(bx - w / 2, sy - 6, w, 7); screen.stroke()
          screen.pixel(sx, sy + 1); screen.pixel(sx, sy + 2); screen.fill()
          -- text
          screen.level(math.max(2, 15 - math.floor(age / 8)))
          screen.move(bx, sy - 1); screen.text_center(line)
        end
      end
    end
    screen.font_face(1); screen.font_size(8)
  end

  -- campfires (always visible — they don't get used up)
  for _, f in ipairs(CONTENT.campfires) do
    if f.map == current_map_id
       and f.x >= cam.x and f.x < cam.x + VIEW_W
       and f.y >= cam.y and f.y < cam.y + VIEW_H then
      local sx, sy = (f.x - cam.x) * TILE + view_ox, (f.y - cam.y) * TILE + view_oy
      -- log base
      screen.level(5)
      screen.rect(sx + 1, sy + 6, 6, 1); screen.fill()
      screen.level(7)
      screen.rect(sx + 2, sy + 5, 4, 1); screen.fill()
      -- flame (animated)
      local f1 = (tick % 4 < 2) and 0 or 1
      screen.level(15)
      screen.move(sx + 4, sy + 1 + f1)
      screen.line(sx + 2, sy + 5)
      screen.line(sx + 6, sy + 5)
      screen.close(); screen.fill()
      screen.level(11)
      screen.pixel(sx + 4, sy + 3 + f1); screen.fill()
    end
  end
  -- treasure chests on the current map (only render unopened ones)
  for _, c in ipairs(CONTENT.chests) do
    if c.map == current_map_id and not CONTENT.opened[c.id]
       and c.x >= cam.x and c.x < cam.x + VIEW_W
       and c.y >= cam.y and c.y < cam.y + VIEW_H then
      local sx, sy = (c.x - cam.x) * TILE + view_ox, (c.y - cam.y) * TILE + view_oy
      -- gold chest, lid + body, with a tiny shimmer
      screen.level(11); screen.rect(sx + 1, sy + 3, 6, 4); screen.fill()
      screen.level(15); screen.rect(sx + 1, sy + 2, 6, 1); screen.fill()  -- lid
      screen.level(0);  screen.pixel(sx + 4, sy + 4); screen.fill()       -- keyhole
      if (tick % 8) < 4 then
        screen.level(15); screen.pixel(sx + 5, sy + 1); screen.fill()
      else
        screen.level(13); screen.pixel(sx + 2, sy + 1); screen.fill()
      end
    end
  end

  -- Scripted scene actors render between map sprites and the player.
  if SCENE and SCENE.active and SCENE.draw then SCENE.draw() end

  if not (SCENE and SCENE.active and SCENE.hide_player) then
    draw_player_at((player.x - cam.x) * TILE + view_ox, (player.y - cam.y) * TILE + view_oy)
  end

  -- prompt: talk OR enter cave OR enter inn. Suppressed entirely
  -- during scripted scenes — the player can't interact mid-scene, and
  -- a flashing "A: talk" over choreography reads as a glitch.
  local _in_scene = SCENE and SCENE.active
  local fnpc = (not _in_scene) and find_facing_npc() or nil
  local fdx, fdy = facing_offset()
  local ftile = _in_scene and -1 or tile_at(player.x + fdx, player.y + fdy)
  if fnpc and (tick % 8) < 5 then
    screen.level(15)
    screen.move(64, 60)
    -- Prompt verb varies by NPC kind:
    --   kind = "object" → "check"  (stones, plaques, orrery, graves)
    --   kind = "pet"    → "pet"    (cats, falcons, birds)
    --   default         → "talk"
    local verb = "talk"
    if fnpc.kind == "object" then verb = "check"
    elseif fnpc.kind == "pet" then verb = "pet" end
    screen.text_center("A/K3: " .. verb)
  elseif (ftile == 5 or ftile == 113) and (tick % 8) < 5 then
    screen.level(15)
    screen.move(64, 60)
    screen.text_center("walk in")   -- tile-5 doors are homes now, not the inn
  elseif ftile == 6 and (tick % 8) < 5 then
    screen.level(15)
    screen.move(64, 60)
    local s = cave_state[1]
    if s.cleared then screen.text_center("the cave hums softly")
    elseif s.victories >= BOSS_THRESHOLD then screen.text_center("the air thickens...")
    else screen.text_center("walk in to fight (" .. s.victories .. "/" .. BOSS_THRESHOLD .. ")") end
  elseif ftile == 7 and (tick % 8) < 5 then
    screen.level(15)
    screen.move(64, 60)
    local s = cave_state[2]
    if s.cleared then screen.text_center("the woods are still")
    elseif s.victories >= BOSS_THRESHOLD then screen.text_center("the trees stop swaying...")
    else screen.text_center("enter the deep wood (" .. s.victories .. "/" .. BOSS_THRESHOLD .. ")") end
  elseif ftile == 9 and (tick % 8) < 5 then
    screen.level(15)
    screen.move(64, 60)
    local s = cave_state[3]
    if s.cleared then screen.text_center("the tide breathes calm")
    elseif s.victories >= BOSS_THRESHOLD then screen.text_center("the water rises...")
    else screen.text_center("descend the cavern (" .. s.victories .. "/" .. BOSS_THRESHOLD .. ")") end
  elseif ftile == 11 and (tick % 8) < 5 then
    screen.level(15)
    screen.move(64, 60)
    local s = cave_state[4]
    if s.cleared then screen.text_center("the dunes whisper")
    elseif s.victories >= BOSS_THRESHOLD then screen.text_center("sand stirs...")
    else screen.text_center("enter the glass cave (" .. s.victories .. "/" .. BOSS_THRESHOLD .. ")") end
  elseif ftile == 16 and (tick % 8) < 5 then
    screen.level(15)
    screen.move(64, 60)
    local s = cave_state[5]
    if s.cleared then screen.text_center("the wind quiets")
    elseif s.victories >= BOSS_THRESHOLD then screen.text_center("the cold deepens...")
    else screen.text_center("enter the ice grotto (" .. s.victories .. "/" .. BOSS_THRESHOLD .. ")") end
  elseif ftile == 15 and (tick % 8) < 5 then
    screen.level(15)
    screen.move(64, 60)
    screen.text_center("cross the pass")
  elseif ftile == 10 and (tick % 8) < 5 then
    screen.level(15)
    screen.move(64, 60)
    screen.text_center("set sail")
  end

  -- region environmental overlay (atmospheric particles per region)
  local region = get_region(player.x)
  if region == "woods" then
    -- falling leaves drifting downward
    for i = 1, 4 do
      local lx = (i * 41 + tick * 2) % 128
      local ly = (i * 17 + tick) % 64
      screen.level(7)
      screen.pixel(lx, ly)
      screen.fill()
    end
    -- dim mist stipple
    screen.level(2)
    for i = 0, 9 do
      screen.pixel((i * 13 + tick) % 128, (i * 7 + 3) % 64)
    end
    screen.fill()
  elseif region == "coast" then
    -- sun rays from upper-right corner
    screen.level(13)
    for i = 1, 5 do
      local x = 124 - i * 4
      screen.pixel(x, i * 2)
      screen.pixel(x - 1, i * 2 + 1)
    end
    screen.fill()
    -- shimmer sparkles
    for i = 1, 3 do
      local sx = (i * 53 + tick * 3) % 128
      local sy = (i * 11 + tick) % 28
      if (tick + i * 7) % 8 < 3 then
        screen.level(15)
        screen.pixel(sx, sy)
        screen.fill()
      end
    end
  end

  -- active voice indicator (top-right) — which character the right stick filters
  if party[active] then
    screen.level(11)
    screen.move(126, 8)
    screen.text_right("> " .. CHAR_NAME[party[active].class])
  end

  -- World of Silence cue: tiny tilde squiggle + "detuned" tag in the
  -- top-left corner (the voice indicator owns top-right; interaction
  -- prompts and banners are all centered lower). Subtle, level 6.
  if CONTENT.act3_silence then
    screen.font_face(25); screen.font_size(6)
    screen.level(6)
    screen.pixel(2, 4); screen.pixel(3, 3); screen.pixel(4, 4); screen.fill()
    screen.move(7, 6); screen.text("detuned")
    screen.font_face(1); screen.font_size(8)
  end

  -- place label banner (shows briefly on entering a new place / crossing a region)
  if region_label_ticks > 0 then
    -- last_region is "<map_id>:<sub>" — sub is the mainland get_region() value
    -- or empty for non-mainland maps. Map a friendly name per place.
    local PLACE_NAMES = {
      ["1:village"] = "Village Clearing",
      ["1:woods"]   = "Hollow Woods",
      ["1:coast"]   = "East Shore",
      ["35:"]       = "Sunward Coast",
      ["2:"]        = "Eastern Reaches",
      ["3:"]        = "Northern Wilds",
      ["4:"]        = "Suno's Domain",
      ["5:"]        = "The Inn",
      ["6:"]        = "Item Shop",
      ["7:"]        = "Cave 1 - The Echoes",
      ["8:"]        = "Cave 2 - Sentinel Grove",
      ["9:"]        = "Cave 3 - Tidewater Grotto",
      ["10:"]       = "Cave 4 - Dune Hall",
      ["11:"]       = "Cave 5 - Frost Vault",
      ["12:"]       = "The Hollow",
      ["13:"]       = "Cave 6 - Locrian Crypt",
      ["14:"]       = "Cave 7 - Suno's Chamber",
      ["17:"]       = "The Saltway Inn",
      ["18:"]       = "Pinehearth Lodge",
      ["19:"]       = "Hall of Resonance",
      ["20:"]       = "Lirael Throne Room",
      ["21:"]       = "The Escape Cave",
      ["22:"]       = "Western Region",
      ["23:"]       = "Lirael Ruins",
      ["24:"]       = "Velthe's Observatory",
      ["25:"]       = "Reya's Cairn",
      ["26:"]       = "The Far Hills",
    }
    local name = PLACE_NAMES[last_region or ""] or ""
    -- Houses share map id 38; the banner shows the specific home's
    -- label from the CONTENT.HOUSES registry.
    if current_map_id == 38 then
      local h = CONTENT.HOUSES and CONTENT.house_key and CONTENT.HOUSES[CONTENT.house_key]
      name = (h and h.label) or "a quiet house"
    end
    if name ~= "" then
      screen.level(0)
      screen.rect(4, 22, 120, 14); screen.fill()
      screen.level(15)
      screen.rect(4, 22, 120, 14); screen.stroke()
      screen.font_face(25); screen.font_size(6)
      screen.move(64, 31); screen.text_center(name)
      screen.font_face(1); screen.font_size(8)
    end
  end

  -- DEBUG overlay (toggle in menu)
  if debug_visible then
    if l2_held then
      screen.level(15)
      screen.move(2, 8)
      screen.text("[L2]")
    end
    if (tick - last_input_at) < 60 then
      screen.level(8)
      screen.move(2, 64)
      screen.text(last_input)
    end
  end

  -- inn rest banner — animated zzz, full heal feedback
  if inn_rest_ticks > 0 then
    screen.level(0)
    screen.rect(4, 20, 120, 24)
    screen.fill()
    screen.level(15)
    screen.rect(4, 20, 120, 24)
    screen.stroke()
    screen.font_face(25); screen.font_size(6)
    screen.move(64, 30)
    screen.text_center("Rested at the inn")
    -- zzz drift
    local zoff = (tick // 3) % 8
    screen.level(11)
    screen.move(96, 32 - zoff)
    screen.text("z")
    screen.move(100, 28 - zoff)
    screen.text("z")
    screen.move(104, 24 - zoff)
    screen.text("z")
    screen.level(8)
    screen.move(64, 39)
    screen.text_center("HP & MP fully restored")
    screen.font_face(1); screen.font_size(8)
  end

  -- tower-locked banner (shows briefly when player tries to enter without 5 shards)
  if tower_locked_ticks > 0 then
    screen.level(0)
    screen.rect(4, 22, 120, 20)
    screen.fill()
    screen.level(15)
    screen.rect(4, 22, 120, 20)
    screen.stroke()
    screen.font_face(25); screen.font_size(6)
    screen.move(64, 30)
    screen.text_center("The Tower bars your way.")
    screen.level(8)
    screen.move(64, 38)
    screen.text_center("Gather 5 shards to enter.")
    screen.font_face(1); screen.font_size(8)
  end

  -- generic event flash banner (chest, campfire heal, equip toast, etc.)
  if CONTENT.flash_ticks > 0 then
    screen.level(0); screen.rect(4, 28, 120, 12); screen.fill()
    screen.level(15); screen.rect(4, 28, 120, 12); screen.stroke()
    screen.font_face(25); screen.font_size(6)
    screen.move(64, 36); screen.text_center(scrub_text(CONTENT.flash_text or ""))
    screen.font_face(1); screen.font_size(8)
  end

  -- DAY/NIGHT overlay (Pass 58). Nighttime stipples a sparse dim-pixel
  -- mask across the OVERWORLD only (interiors, ruins, observatory and
  -- caves don't dim). The stipple is deterministic per tile so it
  -- doesn't shimmer. Skipped during scripted scenes (their letterbox
  -- + fade already handle framing). A small "night" indicator in the
  -- top-right corner cues the player.
  if sq_is_night and sq_is_night()
     and (current_map_id == 1 or current_map_id == 2 or current_map_id == 3
          or current_map_id == 22 or current_map_id == 26
          or current_map_id == 35)  -- Sunward hosts the night-gated bandstand
     and not (SCENE and SCENE.active) then
    -- Soft "it is night" cue, no screen-wide stipple — the dense
    -- pattern was reading as visual noise and made sprites hard to
    -- track. Now: thin dim line at the top edge, a handful of fixed-
    -- position stars, and the moon glyph. (The old second line at
    -- y=47 — mid-playfield — read as a rendering glitch, a stray grey
    -- bar across the screen, and was removed.)
    screen.level(3)
    screen.rect(0, 0, 128, 1); screen.fill()
    screen.level(7)
    screen.pixel(14, 3); screen.pixel(38, 5); screen.pixel(62, 2)
    screen.pixel(86, 6); screen.pixel(102, 4); screen.fill()
    -- moon glyph top-right
    screen.level(11); screen.pixel(120, 4); screen.pixel(121, 3)
    screen.pixel(122, 3); screen.pixel(122, 4); screen.pixel(122, 5); screen.fill()
  end

  -- Weather particle pool (region-ambient snow/leaves/ash). Drawn here
  -- (world layer) so it sits UNDER dialogue boxes, scene panels, and
  -- the redraw-tail scene fade — it used to draw at the very end of
  -- redraw(), landing on top of dialogue text and full-black fades.
  if PARTICLES and PARTICLES.draw then PARTICLES.draw() end

  -- Full-screen scene panel (attunement signature visuals). Drawn OVER
  -- the world/HUD but UNDER the dialogue box (draw_dialogue calls
  -- draw_overworld first) and UNDER the global fade overlay (drawn in
  -- the redraw tail). Set/cleared by the show_panel/hide_panel scene
  -- steps; only ever visible while a scene is active.
  if SCENE and SCENE.active and SCENE.panel then
    local fn = SCENE_DRAW and SCENE_DRAW[SCENE.panel]
    if fn then fn() end
  end
end

-- DAY / NIGHT cycle. ~11 minutes per half-phase at 85 BPM with the
-- 1/4-beat tick rate (3000-tick window). Returns true while the world
-- is in night phase. Used by draw_overworld for the dimming overlay
-- and by night-only NPC visibility closures.
function sq_is_night()
  return ((tick or 0) // 3000) % 2 == 1
end

-- pixel-accurate word wrap using norns screen metrics
local function wrap_text(str, max_px)
  local lines = {}
  local current = ""
  for word in str:gmatch("%S+") do
    local candidate = (#current == 0) and word or (current .. " " .. word)
    if screen.text_extents(candidate) <= max_px then
      current = candidate
    else
      if #current > 0 then table.insert(lines, current) end
      current = word
    end
  end
  if #current > 0 then table.insert(lines, current) end
  return lines
end

-- Maps a party-scene "[Speaker]" tag to a class for sprite lookup.
-- Now includes the recruits so post-join scenes render their portraits too.
local DLG_NAME_TO_CLASS = {
  Alder="bard", Miel="cleric", Strom="warrior", Diegues="mage",
  Sergei="engineer", Paj="mathwiz", Niko="drummer", ECHO="wraith",
}

local function draw_dialogue()
  -- Backdrop: normally the overworld, but mid-battle dialogue (Sergei's
  -- intervention pauses the Tidewatch fight) should show the paused
  -- battle, not the map the fight is standing on. `_paused_for_sergei`
  -- is self-cleaning (nil'd when combat resumes). draw_battle is a
  -- later local, reached via its _G mirror.
  if enemy and enemy._paused_for_sergei and _G.draw_battle then
    _G.draw_battle()
  else
    draw_overworld()
  end
  -- Single dialogue box for ALL dialogue (NPC + scene). Same size
  -- everywhere so the player isn't seeing two different UIs.
  -- Box: y=26..63 = 38px tall.
  --   Header strip y=27..37 (sprite + name + underline)
  --   Body strip   y=39..62 (up to 3 wrapped lines)
  -- Scenes that need actors visible during dialogue must put them at
  -- map rows above where the box covers (cam.y=1 → rows 1-3 visible).
  screen.level(0)
  screen.rect(0, 26, 128, 38)
  screen.fill()
  screen.level(15)
  screen.rect(0, 26, 128, 38)
  screen.stroke()

  -- Parse the current line. If it starts with "[Name]", extract the speaker
  -- (so party-scene lines show the actual character + their sprite, not
  -- "_party_scene").
  local cur = (dlg.lines or {})[dlg.line] or ""
  -- Tag pattern allows spaces inside the brackets ("[Cave Echo]") —
  -- %S+ silently failed on multi-word names and dumped the raw tag
  -- into the dialogue body.
  local sp, rest = cur:match("^%[([^%]]+)%]%s*(.*)$")
  -- dlg.npc may be nil for narrator-style sequences (campfire memories,
  -- in-line story banter). Fall back to no speaker label in that case.
  local speaker = sp or (dlg.npc and dlg.npc.name) or ""
  if speaker == "_party_scene" then speaker = "" end
  -- Narration is never spoken by a character: in a SCRIPTED SCENE, an
  -- untagged line that is entirely parenthetical "(like this.)" is
  -- scene description, so it renders with no speaker header even inside
  -- an npc-attributed dialogue step. Explicitly tagged action beats
  -- ("[Miel] (touches the basin's lip)") keep their header — the [Name]
  -- tag is the author saying whose beat it is. Scoped to SCENE.active:
  -- outside scenes, examine-objects (Fountain, gravestones, shelves)
  -- speak entirely in parentheticals and NEED their name label, and an
  -- NPC's own stage direction under their label is the game's idiom.
  if not sp and SCENE and SCENE.active
     and cur:match("^%(") and cur:match("%)%s*$") then
    speaker = ""
  end
  local body = rest or cur
  -- Final safety: if the body still leads with "<speaker>:" (e.g. someone
  -- wrote "[Strom] Strom: ..." or pack didn't catch a stray prefix),
  -- strip it so the name doesn't appear twice (header + body).
  if speaker ~= "" then
    local pat = "^" .. (speaker:gsub("(%W)", "%%%1")) .. ":%s*"
    body = body:gsub(pat, "")
  end

  -- ── HEADER STRIP (y=27..37) — sprite + speaker name + underline ──
  do
    local sprite_fn = nil
    local cls = DLG_NAME_TO_CLASS[speaker]
    if cls and SPRITE_BY_CLASS[cls] then
      sprite_fn = SPRITE_BY_CLASS[cls]
    elseif NPC_SPRITES and NPC_SPRITES[speaker] then
      sprite_fn = NPC_SPRITES[speaker]
    end
    local name_x = 4
    if sprite_fn then
      local saved = player.facing
      player.facing = "down"
      local bob = ((tick % 6) < 3) and 0 or 1
      sprite_fn(2, 28 - bob)
      if (tick % 4) < 2 then
        screen.level(15); screen.pixel(11, 32 - bob); screen.fill()
      end
      player.facing = saved
      name_x = 13
    end
    screen.level(15)
    screen.move(name_x, 34)
    screen.text(speaker)
    screen.level(4)
    screen.move(2, 37); screen.line(126, 37); screen.stroke()
  end

  -- ── BODY STRIP (y=39..62) ──
  -- Always the compact 6px font. The old scheme rendered short pages in
  -- the default 8px font and flipped to compact only when a page
  -- wrapped past 3 large lines — so consecutive pages changed text size
  -- constantly, which playtested as "some text small, then the next
  -- paragraph large." One font, one size, always (user report,
  -- 2026-07-16).
  --
  -- FF-style typewriter. Characters reveal at TYPEWRITER_CPT chars/tick.
  -- 3.0 cpt @ 20fps = 60 chars/sec — fast enough that the reveal feels
  -- snappy ("characters speak quickly") without being instant. A single
  -- A-press still snaps to fully-revealed; a second A advances.
  -- (Previous value of 0.85 cpt = 17 chars/sec was glacial — most lines
  --  took 4+ seconds, which read as "cut off and moving really slow".)
  -- Typewriter runs on REAL time (util.time), not game ticks: ticks
  -- follow the musical tempo, so tick-based reveal crawled in slow-BPM
  -- zones (Lirael, 48 BPM). The scene clock redraws dialogue at 10 fps
  -- so the reveal actually animates between music ticks.
  if not dlg.line_start_time then dlg.line_start_time = util.time() end
  local TYPEWRITER_CPS = 55   -- chars/sec, real-time
  local age_s = util.time() - dlg.line_start_time
  local total_chars = #body
  local revealed = math.min(total_chars, math.floor(age_s * TYPEWRITER_CPS))
  if dlg.snap_to_complete then revealed = total_chars end
  dlg.complete = (revealed >= total_chars)
  screen.level(13)
  local body_x = 2
  -- Set the font BEFORE wrapping: wrap_text measures with the current
  -- font via screen.text_extents.
  screen.font_face(25); screen.font_size(6)
  -- Wrap the FULL body once, then reveal characters across the fixed
  -- line layout — wrapping the partially-revealed text made growing
  -- words hop from the end of one line to the start of the next
  -- mid-reveal, which read as text jitter.
  local lines = wrap_text(body, 124 - body_x)
  local budget = revealed
  -- 4 compact lines fit the 39..62 strip (6px pitch), which also gives
  -- the 66-char page cap comfortable headroom.
  for i = 1, math.min(4, #lines) do
    if budget <= 0 then break end
    local ln = lines[i]
    screen.move(body_x, 39 + i * 6)   -- baselines 45/51/57/63: last row inside the box
    screen.text(ln:sub(1, budget))
    budget = budget - #ln - 1   -- the +1 eats the joining space
  end
  screen.font_face(1); screen.font_size(8)
  -- advance prompt — only flickers once the full line is revealed.
  if dlg.complete and (tick % 6) < 4 then
    screen.level(15)
    screen.move(122, 62)
    screen.text("v")
  end
end

-- ============================================================ DRAWING — BATTLE

local DRAW_ENEMY = {}

-- Practice dummy: a stout straw figure with concentric target rings.
-- Drawn calmly (tiny sway only) so it reads as "harmless" rather than alive.
function DRAW_ENEMY.dummy(cx, cy)
  local sway = math.sin(tick / 6) * 0.5
  -- post / pole
  screen.level(4)
  screen.move(cx + sway, cy + 8)
  screen.line(cx + sway, cy + 14)
  screen.stroke()
  -- straw body (rounded rectangle-ish)
  screen.level(8)
  screen.rect(cx - 6 + sway, cy - 6, 12, 14)
  screen.fill()
  -- target rings on the body
  screen.level(0)
  screen.circle(cx + sway, cy, 5)
  screen.stroke()
  screen.level(15)
  screen.circle(cx + sway, cy, 3)
  screen.fill()
  screen.level(0)
  screen.circle(cx + sway, cy, 1)
  screen.fill()
  -- arms (straw tufts)
  screen.level(6)
  screen.move(cx - 6 + sway, cy - 2); screen.line(cx - 9 + sway, cy + 1); screen.stroke()
  screen.move(cx + 6 + sway, cy - 2); screen.line(cx + 9 + sway, cy + 1); screen.stroke()
  -- friendly head: simple circle with two dots
  screen.level(10)
  screen.circle(cx + sway, cy - 9, 3)
  screen.fill()
  screen.level(0)
  screen.pixel(math.floor(cx - 1 + sway), math.floor(cy - 10)); screen.fill()
  screen.pixel(math.floor(cx + 1 + sway), math.floor(cy - 10)); screen.fill()
end

function DRAW_ENEMY.silencer(cx, cy)
  -- Suno's faceless enforcer: a tall dark uniform (lit left, shadowed
  -- right), shoulder guards, a blank faceplate with a single slit (no
  -- eyes), a tuning-fork antenna, and the resonator coil humming on its
  -- chest -- the wire it shares with Sergei's machine.
  local hum = (tick % 20 < 10) and 0 or 1
  -- torso
  screen.level(5);  screen.rect(cx - 6, cy - 4, 12, 16); screen.fill()
  screen.level(8);  screen.rect(cx - 6, cy - 4, 2, 16); screen.fill()   -- lit left edge
  screen.level(3);  screen.rect(cx + 4, cy - 4, 2, 16); screen.fill()   -- shadow right edge
  -- shoulder guards
  screen.level(7);  screen.rect(cx - 9, cy - 5, 4, 3); screen.rect(cx + 5, cy - 5, 4, 3); screen.fill()
  -- legs
  screen.level(3);  screen.rect(cx - 5, cy + 12, 3, 4); screen.rect(cx + 2, cy + 12, 3, 4); screen.fill()
  -- head: smooth blank faceplate w/ helm highlight
  screen.level(9);  screen.rect(cx - 4, cy - 12, 8, 8); screen.fill()
  screen.level(11); screen.rect(cx - 4, cy - 12, 8, 1); screen.fill()
  screen.level(0);  screen.rect(cx - 3, cy - 8, 6, 1); screen.fill()    -- the silencing slit
  -- tuning-fork antenna
  screen.level(10)
  screen.move(cx - 1, cy - 12); screen.line(cx - 1, cy - 15); screen.stroke()
  screen.move(cx + 1, cy - 12); screen.line(cx + 1, cy - 15); screen.stroke()
  -- resonator coil on the chest (faint hum pulse) + trailing wire
  screen.level(10 + hum * 3)
  screen.circle(cx, cy + 3, 3); screen.stroke()
  screen.level(13); screen.pixel(cx, cy + 3); screen.fill()
  screen.level(6);  screen.move(cx, cy + 6); screen.line(cx, cy + 11); screen.stroke()
end

function DRAW_ENEMY.slime(cx, cy)
  local pulse = (tick % 4) / 4
  local r = 6 + math.floor(math.sin(pulse * math.pi * 2) * 1.5)
  -- gel body
  screen.level(8); screen.circle(cx, cy, r); screen.fill()
  -- domed top sheen + a bright glint (gives it a wet, gel look)
  screen.level(11); screen.circle(cx, cy - 1, r - 2); screen.stroke()
  screen.level(13); screen.pixel(cx - 2, cy - r + 2); screen.fill()
  -- two eyes + a little mouth
  screen.level(0)
  screen.rect(cx - 3, cy - 1, 1, 2); screen.rect(cx + 2, cy - 1, 1, 2); screen.fill()
  screen.level(15); screen.pixel(cx - 3, cy - 1); screen.pixel(cx + 2, cy - 1); screen.fill()  -- eye glints
  screen.level(0); screen.move(cx - 1, cy + 2); screen.line(cx + 1, cy + 2); screen.stroke()    -- mouth
  -- flat base meniscus
  screen.level(5); screen.move(cx - r + 1, cy + r - 1); screen.line(cx + r - 1, cy + r - 1); screen.stroke()
end

function DRAW_ENEMY.bat(cx, cy)
  local wing = math.sin((tick % 2) / 2 * math.pi * 2) * 3
  -- fuzzy body
  screen.level(10); screen.circle(cx, cy, 2); screen.fill()
  screen.level(6);  screen.circle(cx, cy + 1, 2); screen.stroke()   -- belly fuzz
  -- pointed ears
  screen.level(10); screen.pixel(cx - 2, cy - 3); screen.pixel(cx + 2, cy - 3); screen.fill()
  -- glowing eyes
  screen.level(15); screen.pixel(cx - 1, cy - 1); screen.pixel(cx + 1, cy - 1); screen.fill()
  -- membrane wings with a finger-strut, flapping
  screen.level(8)
  screen.move(cx - 9, cy - wing); screen.line(cx - 4, cy - 1)
  screen.line(cx - 2, cy + 1);    screen.line(cx + 2, cy + 1)
  screen.line(cx + 4, cy - 1);    screen.line(cx + 9, cy - wing); screen.stroke()
  screen.level(5)  -- wing struts
  screen.move(cx - 4, cy - 1); screen.line(cx - 6, cy - wing + 1); screen.stroke()
  screen.move(cx + 4, cy - 1); screen.line(cx + 6, cy - wing + 1); screen.stroke()
end

function DRAW_ENEMY.mushroom(cx, cy)
  -- toadstool creature: domed cap with a shaded underside-gill rim,
  -- white spots, a pale stem with two beady eyes. Gentle sway.
  local sway = (tick % 32 < 16) and 0 or 1
  -- cap dome
  screen.level(11); screen.circle(cx + sway, cy - 2, 5); screen.fill()
  screen.level(13); screen.circle(cx + sway, cy - 3, 3); screen.stroke()   -- cap top highlight
  -- gill rim (underside, darker)
  screen.level(5);  screen.rect(cx - 4 + sway, cy + 1, 9, 1); screen.fill()
  -- white spots
  screen.level(15)
  screen.pixel(cx - 2 + sway, cy - 3); screen.pixel(cx + 2 + sway, cy - 2)
  screen.pixel(cx + sway, cy - 4); screen.fill()
  -- stem
  screen.level(13); screen.rect(cx - 2, cy + 2, 4, 4); screen.fill()
  screen.level(8);  screen.rect(cx + 1, cy + 2, 1, 4); screen.fill()       -- stem shade
  -- beady eyes on the stem
  screen.level(0); screen.pixel(cx - 1, cy + 3); screen.pixel(cx + 1, cy + 3); screen.fill()
end

function DRAW_ENEMY.wisp(cx, cy)
  local pulse = (tick % 6) / 6
  -- outer halo flickers brightness
  screen.level(math.floor(3 + 3 * math.sin(pulse * math.pi * 2)))
  screen.circle(cx, cy, 5)
  screen.fill()
  -- core
  screen.level(15)
  screen.circle(cx, cy, 2)
  screen.fill()
  -- spark pixels orbit
  if (tick % 4) < 2 then
    screen.level(10)
    screen.pixel(cx - 4, cy - 3)
    screen.pixel(cx + 3, cy + 2)
  else
    screen.level(10)
    screen.pixel(cx + 4, cy - 2)
    screen.pixel(cx - 3, cy + 3)
  end
  screen.fill()
end

function DRAW_ENEMY.wolf(cx, cy)
  -- feral wolf in profile: shaded body (lit back / dark underbelly),
  -- muzzle with a bared fang, glowing eye, bristled tail, four legs
  -- with a subtle breathing crouch.
  local breath = (tick % 24 < 12) and 0 or 1
  -- body
  screen.level(8);  screen.rect(cx - 6, cy - 1 + breath, 12, 4); screen.fill()
  screen.level(10); screen.rect(cx - 6, cy - 1 + breath, 12, 1); screen.fill()   -- lit back
  screen.level(5);  screen.rect(cx - 6, cy + 2 + breath, 12, 1); screen.fill()   -- dark underbelly
  -- head + muzzle
  screen.level(8);  screen.rect(cx + 4, cy - 3 + breath, 4, 3); screen.fill()
  screen.level(8);  screen.rect(cx + 7, cy - 1 + breath, 2, 1); screen.fill()    -- muzzle
  screen.level(15); screen.pixel(cx + 8, cy - 1 + breath); screen.fill()         -- bared fang
  -- ears (pricked)
  screen.level(8); screen.pixel(cx + 5, cy - 4 + breath); screen.pixel(cx + 7, cy - 4 + breath); screen.fill()
  -- glowing eye
  screen.level(15); screen.pixel(cx + 6, cy - 2 + breath); screen.fill()
  -- bristled tail
  screen.level(8); screen.move(cx - 6, cy + breath); screen.line(cx - 9, cy - 2 + breath); screen.stroke()
  screen.level(5); screen.pixel(cx - 9, cy - 1 + breath); screen.fill()
  -- four legs
  screen.level(6)
  screen.rect(cx - 5, cy + 3 + breath, 1, 2); screen.rect(cx - 2, cy + 3 + breath, 1, 2)
  screen.rect(cx + 2, cy + 3 + breath, 1, 2); screen.rect(cx + 5, cy + 3 + breath, 1, 2)
  screen.fill()
end

function DRAW_ENEMY.echo(cx, cy)
  -- big amorphous body that breathes
  local pulse = math.sin((tick % 8) / 8 * math.pi * 2)
  local r = 9 + math.floor(pulse * 1.5)
  screen.level(6)
  screen.circle(cx, cy, r)
  screen.fill()
  screen.level(2)
  screen.circle(cx, cy, math.max(1, r - 2))
  screen.fill()
  -- multiple eyes pulsing in 3-phase cycle
  local eye_phase = math.floor(tick / 4) % 3
  screen.level(15)
  if eye_phase == 0 then
    screen.rect(cx - 3, cy - 2, 2, 1)
    screen.fill()
    screen.pixel(cx + 2, cy + 1)
  elseif eye_phase == 1 then
    screen.rect(cx + 1, cy - 3, 2, 1)
    screen.fill()
    screen.pixel(cx - 4, cy + 2)
  else
    screen.pixel(cx, cy + 2)
    screen.pixel(cx + 4, cy - 1)
    screen.pixel(cx - 1, cy + 3)
  end
  screen.fill()
end

function DRAW_ENEMY.sprite(cx, cy)
  -- tiny darting magical creature: bright core + 4 trailing pixels
  local pulse = (tick % 6) / 6
  local r = 2 + math.floor(math.sin(pulse * math.pi * 2) * 1)
  screen.level(15)
  screen.circle(cx, cy, r)
  screen.fill()
  screen.level(8)
  screen.pixel(cx - 4, cy - 2)
  screen.pixel(cx + 4, cy + 1)
  screen.pixel(cx - 2, cy + 3)
  screen.pixel(cx + 3, cy - 3)
  screen.fill()
end

function DRAW_ENEMY.treant(cx, cy)
  -- A walking tree: wide gnarled trunk + two branch-arms + leafy crown +
  -- glowing eyes peering out of a face carved into the bark. Subtle sway.
  local sway = math.floor(math.sin(tick / 8) * 1)
  -- root base (splayed roots)
  screen.level(3)
  screen.move(cx - 7, cy + 11); screen.line(cx, cy + 7); screen.line(cx + 7, cy + 11)
  screen.close(); screen.fill()
  -- gnarled trunk (wider middle than top)
  screen.level(5)
  screen.rect(cx - 4 + sway, cy - 2, 8, 9); screen.fill()
  screen.level(3)
  screen.move(cx - 4 + sway, cy + 7); screen.line(cx + 4 + sway, cy + 7); screen.stroke()
  -- bark grooves (vertical lines on trunk)
  screen.level(3)
  screen.move(cx - 2 + sway, cy - 1); screen.line(cx - 2 + sway, cy + 6); screen.stroke()
  screen.move(cx + 2 + sway, cy - 1); screen.line(cx + 2 + sway, cy + 6); screen.stroke()
  -- branch-arms (one bent up, one down — like an Ent stride)
  screen.level(5)
  screen.move(cx - 4 + sway, cy);     screen.line(cx - 8 + sway, cy - 3); screen.stroke()
  screen.move(cx - 8 + sway, cy - 3); screen.line(cx - 9 + sway, cy);     screen.stroke()
  screen.move(cx + 4 + sway, cy + 1); screen.line(cx + 8 + sway, cy + 4); screen.stroke()
  screen.move(cx + 8 + sway, cy + 4); screen.line(cx + 9 + sway, cy + 1); screen.stroke()
  -- finger twigs at each hand
  screen.level(3)
  screen.pixel(cx - 9 + sway, cy - 1); screen.pixel(cx - 10 + sway, cy + 1); screen.fill()
  screen.pixel(cx + 9 + sway, cy + 5); screen.pixel(cx + 10 + sway, cy + 3); screen.fill()
  -- leafy crown (rounded blob with little leaf clusters)
  screen.level(7)
  screen.circle(cx + sway, cy - 6, 5); screen.fill()
  screen.level(11)
  screen.pixel(cx - 3 + sway, cy - 8); screen.pixel(cx + 4 + sway, cy - 7)
  screen.pixel(cx - 1 + sway, cy - 10); screen.pixel(cx + 2 + sway, cy - 9); screen.fill()
  screen.level(3)  -- shadow underside of crown
  screen.move(cx - 4 + sway, cy - 3); screen.line(cx + 4 + sway, cy - 3); screen.stroke()
  -- carved face: hollow eyes (glow) + mouth slit
  local lit = (tick % 30) < 22
  screen.level(lit and 13 or 8)
  screen.pixel(cx - 2 + sway, cy + 1); screen.pixel(cx + 2 + sway, cy + 1); screen.fill()
  screen.level(0)
  screen.move(cx - 2 + sway, cy + 4); screen.line(cx + 2 + sway, cy + 4); screen.stroke()
end

function DRAW_ENEMY.sentinel(cx, cy)
  -- tall antlered guardian: shaded body with a lit leading edge + a
  -- shadowed flank, a banded chest plate, a narrower head with glowing
  -- eyes, a four-tine antler crown, and two stout legs. Slow sway.
  local sway = math.floor(math.sin((tick % 32) / 32 * math.pi * 2) * 1.5)
  local x = cx + sway
  -- body w/ lit edge + shadow flank
  screen.level(8);  screen.rect(x - 4, cy - 4, 8, 12); screen.fill()
  screen.level(11); screen.rect(x - 4, cy - 4, 1, 12); screen.fill()
  screen.level(5);  screen.rect(x + 3, cy - 4, 1, 12); screen.fill()
  -- banded chest plate
  screen.level(12); screen.rect(x - 3, cy + 1, 6, 1); screen.fill()
  screen.level(6);  screen.rect(x - 3, cy + 3, 6, 1); screen.fill()
  -- narrower head
  screen.level(10); screen.rect(x - 2, cy - 6, 4, 3); screen.fill()
  -- antler crown (four tines)
  screen.level(11)
  screen.move(x - 2, cy - 6); screen.line(x - 5, cy - 10); screen.stroke()
  screen.move(x - 4, cy - 8); screen.line(x - 6, cy - 8); screen.stroke()
  screen.move(x + 2, cy - 6); screen.line(x + 5, cy - 10); screen.stroke()
  screen.move(x + 4, cy - 8); screen.line(x + 6, cy - 8); screen.stroke()
  -- glowing eyes (2-phase)
  local lit = (tick % 16) < 12
  screen.level(lit and 15 or 4)
  screen.pixel(x - 1, cy - 5); screen.pixel(x + 1, cy - 5); screen.fill()
  -- two stout legs
  screen.level(6)
  screen.rect(x - 3, cy + 8, 2, 2); screen.rect(x + 1, cy + 8, 2, 2); screen.fill()
end

function DRAW_ENEMY.crab(cx, cy)
  -- shelled body w/ rim shading, eye-stalks, pincer claws, little legs.
  local skitter = (tick % 4) < 2 and -1 or 1
  local sx0 = cx + skitter
  screen.level(10); screen.rect(sx0 - 4, cy, 8, 4); screen.fill()              -- shell
  screen.level(13); screen.rect(sx0 - 4, cy, 8, 1); screen.fill()             -- shell top highlight
  screen.level(6);  screen.rect(sx0 - 4, cy + 3, 8, 1); screen.fill()         -- underside shade
  -- claws (pincer triangles) + darker pincer gap
  screen.level(10)
  screen.move(sx0 - 6, cy + 2); screen.line(sx0 - 8, cy); screen.line(sx0 - 4, cy); screen.close(); screen.fill()
  screen.move(sx0 + 6, cy + 2); screen.line(sx0 + 8, cy); screen.line(sx0 + 4, cy); screen.close(); screen.fill()
  screen.level(6); screen.pixel(sx0 - 7, cy + 1); screen.pixel(sx0 + 7, cy + 1); screen.fill()
  -- legs poking under the shell
  screen.level(8); screen.pixel(sx0 - 3, cy + 4); screen.pixel(sx0 + 3, cy + 4); screen.fill()
  -- eye-stalks with bright eyes
  screen.level(8);  screen.pixel(sx0 - 1, cy - 1); screen.pixel(sx0 + 2, cy - 1); screen.fill()
  screen.level(15); screen.pixel(sx0 - 1, cy - 2); screen.pixel(sx0 + 2, cy - 2); screen.fill()
end

function DRAW_ENEMY.manta(cx, cy)
  -- gliding ray: shaded wings w/ bright leading edges, cephalic fins,
  -- a whip tail tipped with a barb. Slow swoop.
  local sw = math.floor(math.sin((tick % 12) / 12 * math.pi * 2) * 2)
  screen.level(8)
  screen.move(cx, cy - 4); screen.line(cx - 7, cy + sw); screen.line(cx, cy + 4); screen.line(cx + 7, cy + sw); screen.close(); screen.fill()
  -- bright leading edges (top of each wing)
  screen.level(11)
  screen.move(cx, cy - 4); screen.line(cx - 7, cy + sw); screen.stroke()
  screen.move(cx, cy - 4); screen.line(cx + 7, cy + sw); screen.stroke()
  screen.level(5); screen.pixel(cx, cy + 2); screen.fill()                    -- underbelly shade
  -- cephalic fins (the little head "horns")
  screen.level(8); screen.pixel(cx - 1, cy - 5); screen.pixel(cx + 1, cy - 5); screen.fill()
  -- whip tail with a barb
  screen.level(8); screen.move(cx, cy + 4); screen.line(cx, cy + 7); screen.stroke()
  screen.level(13); screen.pixel(cx, cy + 7); screen.fill()
  -- eyespots
  screen.level(0); screen.pixel(cx - 2, cy); screen.pixel(cx + 2, cy); screen.fill()
end

function DRAW_ENEMY.tide(cx, cy)
  -- broad wave-creature with multiple peaks, slow churning
  local phase = (tick % 16) / 16 * math.pi * 2
  screen.level(5)
  -- low wide body
  screen.rect(cx - 10, cy + 1, 20, 6)
  screen.fill()
  -- wave peaks
  screen.level(8)
  for i = -2, 2 do
    local px = cx + i * 4
    local h = 4 + math.floor(math.sin(phase + i * 0.7) * 2)
    screen.move(px - 2, cy + 1)
    screen.line(px, cy + 1 - h)
    screen.line(px + 2, cy + 1)
    screen.close()
    screen.fill()
  end
  -- shimmering eyes
  if (tick % 8) < 6 then
    screen.level(15)
    screen.pixel(cx - 3, cy + 4)
    screen.pixel(cx + 3, cy + 4)
    screen.fill()
  end
end

function DRAW_ENEMY.scorpion(cx, cy)
  -- armored desert scorpion: carapace highlight + belly shade, legs,
  -- pincer claws, segmented raised tail, glinting stinger w/ venom flash.
  screen.level(10); screen.rect(cx - 4, cy + 1, 8, 3); screen.fill()        -- body
  screen.level(13); screen.rect(cx - 4, cy + 1, 8, 1); screen.fill()        -- carapace highlight
  screen.level(6);  screen.rect(cx - 4, cy + 3, 8, 1); screen.fill()        -- belly shade
  -- legs
  screen.level(7); screen.pixel(cx - 3, cy + 4); screen.pixel(cx - 1, cy + 4)
  screen.pixel(cx + 1, cy + 4); screen.pixel(cx + 3, cy + 4); screen.fill()
  -- claws (forward) w/ darker joints
  screen.level(10)
  screen.move(cx - 6, cy + 1); screen.line(cx - 8, cy - 1); screen.line(cx - 4, cy + 1); screen.close(); screen.fill()
  screen.move(cx + 6, cy + 1); screen.line(cx + 8, cy - 1); screen.line(cx + 4, cy + 1); screen.close(); screen.fill()
  screen.level(6); screen.pixel(cx - 7, cy); screen.pixel(cx + 7, cy); screen.fill()
  -- segmented tail curling over the back
  screen.level(13)
  screen.pixel(cx + 1, cy); screen.pixel(cx + 2, cy - 1); screen.pixel(cx + 1, cy - 2)
  screen.pixel(cx, cy - 3); screen.pixel(cx - 1, cy - 2); screen.fill()
  -- stinger glint + venom-drip flash
  screen.level(15); screen.pixel(cx - 2, cy - 3); screen.fill()
  if (tick % 10) < 5 then screen.level(15); screen.pixel(cx - 2, cy - 4); screen.fill() end
  -- beady eyes
  screen.level(0); screen.pixel(cx - 1, cy + 2); screen.pixel(cx + 1, cy + 2); screen.fill()
end

function DRAW_ENEMY.spectre(cx, cy)
  -- ghostly figure: dim outer shroud, brighter translucent inner core,
  -- a darker hooded crown, a gaping mouth, trailing wisps. Wavy drift.
  local sw = math.floor(math.sin((tick % 16) / 16 * math.pi * 2) * 1)
  -- outer shroud (dim)
  screen.level(5)
  screen.move(cx - 4 + sw, cy - 6); screen.line(cx + 4 + sw, cy - 6)
  screen.line(cx + 5 + sw, cy + 5); screen.line(cx + 2 + sw, cy + 6)
  screen.line(cx + sw, cy + 5);     screen.line(cx - 2 + sw, cy + 6)
  screen.line(cx - 5 + sw, cy + 5); screen.close(); screen.fill()
  -- translucent inner core (brighter)
  screen.level(9); screen.rect(cx - 2 + sw, cy - 4, 4, 6); screen.fill()
  -- hooded crown (dark fade at the top)
  screen.level(3); screen.rect(cx - 3 + sw, cy - 6, 7, 1); screen.fill()
  -- gaping mouth
  screen.level(0); screen.rect(cx - 1 + sw, cy, 2, 2); screen.fill()
  -- glowing eyes
  if (tick % 12) < 8 then
    screen.level(15)
    screen.pixel(cx - 2 + sw, cy - 3); screen.pixel(cx + 2 + sw, cy - 3); screen.fill()
  end
  -- trailing wisps
  screen.level(3); screen.pixel(cx - 3 + sw, cy + 7); screen.pixel(cx + 1 + sw, cy + 7); screen.fill()
end

function DRAW_ENEMY.dunerider(cx, cy)
  -- desert raider on a low sand-mount: sun-lit back + shadowed belly on
  -- the mount, a cloaked rider with a wrapped head and a thrusting spear
  -- that bobs with the gait.
  local phase = (tick % 16) / 16 * math.pi * 2
  -- mount body (low broad) w/ top-light + belly shadow
  screen.level(11); screen.rect(cx - 9, cy + 2, 18, 5); screen.fill()
  screen.level(13); screen.rect(cx - 9, cy + 2, 18, 1); screen.fill()
  screen.level(8);  screen.rect(cx - 9, cy + 6, 18, 1); screen.fill()
  -- mount head + dark eye
  screen.level(11)
  screen.move(cx + 9, cy + 2); screen.line(cx + 12, cy + 4); screen.line(cx + 9, cy + 6)
  screen.close(); screen.fill()
  if (tick % 8) < 6 then screen.level(0); screen.pixel(cx + 10, cy + 4); screen.fill() end
  -- legs (shadowed, two pairs)
  screen.level(8)
  screen.rect(cx - 6, cy + 7, 1, 2); screen.rect(cx - 2, cy + 7, 1, 2)
  screen.rect(cx + 4, cy + 7, 1, 2); screen.rect(cx + 7, cy + 7, 1, 2); screen.fill()
  -- cloaked rider w/ lit edge
  screen.level(5); screen.rect(cx - 1, cy - 4, 4, 6); screen.fill()
  screen.level(8); screen.rect(cx - 1, cy - 4, 1, 6); screen.fill()
  -- rider head + wrap
  screen.level(13); screen.rect(cx, cy - 6, 2, 2); screen.fill()
  screen.level(9);  screen.rect(cx, cy - 6, 2, 1); screen.fill()
  -- thrusting spear (bobs with gait)
  screen.level(15)
  screen.move(cx + 3, cy - 4); screen.line(cx + 7 + math.floor(math.sin(phase) * 1), cy - 8)
  screen.stroke()
end

-- Cave 5 enemies (Northern Wilds)
function DRAW_ENEMY.yeti(cx, cy)
  -- hulking furred brute: lit shaggy crown, shadowed underbelly + right
  -- flank, recessed brow over deep-socket eyes, snarling tusked maw,
  -- heavy shaded arms ending in dark claws. Slow breathing bob.
  local breath = (tick % 28 < 14) and 0 or 1
  local top = cy - 16 + breath
  -- off-white fur body
  screen.level(13); screen.rect(cx - 14, top, 28, 28); screen.fill()
  -- lit crown (top catches the light)
  screen.level(15); screen.rect(cx - 14, top, 28, 4); screen.fill()
  -- shadowed underbelly + right flank give it volume
  screen.level(8);  screen.rect(cx - 14, top + 22, 28, 6); screen.fill()
  screen.level(10); screen.rect(cx + 10, top + 4, 4, 18); screen.fill()
  -- shaggy fur notches along the lower edge
  screen.level(9)
  for i = -12, 12, 4 do screen.rect(cx + i, top + 26, 2, 2); screen.fill() end
  -- arms with inner shadow
  screen.level(12); screen.rect(cx - 18, top + 8, 4, 14); screen.fill()
  screen.level(12); screen.rect(cx + 14, top + 8, 4, 14); screen.fill()
  screen.level(8);  screen.rect(cx - 18, top + 8, 1, 14); screen.fill()
  screen.level(8);  screen.rect(cx + 17, top + 8, 1, 14); screen.fill()
  -- dark claws
  screen.level(3)
  screen.pixel(cx - 18, top + 22); screen.pixel(cx - 16, top + 22)
  screen.pixel(cx + 15, top + 22); screen.pixel(cx + 17, top + 22); screen.fill()
  -- recessed face hollow + heavy brow ridge
  screen.level(2); screen.rect(cx - 6, top + 6, 12, 8); screen.fill()
  screen.level(5); screen.rect(cx - 6, top + 6, 12, 2); screen.fill()
  -- glowing deep-socket eyes (slow flicker)
  local eye = (tick % 40 < 34) and 15 or 6
  screen.level(eye)
  screen.rect(cx - 4, top + 9, 2, 2); screen.rect(cx + 2, top + 9, 2, 2); screen.fill()
  -- snarling maw with a few teeth
  screen.level(0); screen.rect(cx - 4, top + 12, 8, 2); screen.fill()
  screen.level(13)
  screen.pixel(cx - 3, top + 12); screen.pixel(cx, top + 13); screen.pixel(cx + 3, top + 12); screen.fill()
  -- upward tusks from the maw corners
  screen.level(14)
  screen.move(cx - 4, top + 13); screen.line(cx - 6, top + 10); screen.stroke()
  screen.move(cx + 4, top + 13); screen.line(cx + 6, top + 10); screen.stroke()
end

function DRAW_ENEMY.frostwisp(cx, cy)
  -- shimmering ice diamond + drift
  local d = (tick // 4) % 8
  screen.level(15)
  screen.move(cx,     cy - 12 + d)
  screen.line(cx + 8, cy)
  screen.line(cx,     cy + 12 + d)
  screen.line(cx - 8, cy)
  screen.close()
  screen.fill()
  -- inner shadow
  screen.level(7)
  screen.move(cx,     cy - 6 + d)
  screen.line(cx + 4, cy)
  screen.line(cx,     cy + 6 + d)
  screen.line(cx - 4, cy)
  screen.close()
  screen.fill()
  -- crystalline facet lines (catch the light)
  screen.level(11)
  screen.move(cx, cy - 6 + d); screen.line(cx + 4, cy); screen.stroke()
  screen.move(cx, cy + 6 + d); screen.line(cx - 4, cy); screen.stroke()
  -- core
  screen.level(15)
  screen.pixel(cx, cy)
  screen.fill()
  -- drifting snowflakes around
  screen.level(13)
  screen.pixel(cx - 12, cy - 4 + d)
  screen.pixel(cx + 13, cy + 6 - d)
  screen.pixel(cx - 9, cy + 8 - d)
  screen.fill()
end

-- The First Chord — post-endgame superboss. A shifting cluster of
-- void-pixels that rearrange themselves every few ticks (no fixed
-- form), with a bright central "kernel" that pulses like a heartbeat.
-- The whole thing reads as a thing too dissonant to settle.
function DRAW_ENEMY.firstchord(cx, cy)
  -- outer void halo (dark)
  screen.level(2); screen.rect(cx - 18, cy - 14, 36, 28); screen.fill()
  -- shifting field of bright pixels (8 rotating positions)
  local seed = math.floor(tick / 3) % 8
  for i = 0, 11 do
    local a = (i / 12) * math.pi * 2 + (seed * 0.3)
    local r = 10 + (i % 3) * 3
    local px = math.floor(cx + math.cos(a) * r)
    local py = math.floor(cy + math.sin(a) * (r * 0.6))
    screen.level((i + seed) % 4 == 0 and 15 or 8)
    screen.pixel(px, py); screen.fill()
  end
  -- middle cluster (bright)
  local pulse = ((tick % 16) < 8) and 13 or 15
  screen.level(pulse); screen.rect(cx - 4, cy - 4, 9, 9); screen.fill()
  -- inner kernel (heartbeat)
  screen.level(0); screen.rect(cx - 1, cy - 1, 3, 3); screen.fill()
  screen.level(15); screen.pixel(cx, cy); screen.fill()
  -- vertical "rip" through center (a glitch line)
  if (tick % 32) < 4 then
    screen.level(15)
    screen.rect(cx, cy - 14, 1, 28); screen.fill()
  end
end

-- Strom, the academy boss — heavy warrior with a slab hammer. Stands
-- ~28 tall x ~24 wide; raises the hammer 1 px on alternate ticks so
-- the silhouette reads as menacing rather than static.
function DRAW_ENEMY.strom(cx, cy)
  local hammer_lift = ((tick % 16) < 8) and 0 or 1
  -- legs (dark armored boots)
  screen.level(3)
  screen.rect(cx - 6, cy + 8, 4, 5); screen.fill()
  screen.rect(cx + 2, cy + 8, 4, 5); screen.fill()
  -- chestplate (mid-tone iron)
  screen.level(6)
  screen.rect(cx - 8, cy - 6, 16, 14); screen.fill()
  -- chestplate highlight strip (top edge)
  screen.level(11); screen.rect(cx - 8, cy - 6, 16, 1); screen.fill()
  -- belt + buckle
  screen.level(2); screen.rect(cx - 8, cy + 4, 16, 2); screen.fill()
  screen.level(13); screen.pixel(cx - 1, cy + 5); screen.pixel(cx, cy + 5); screen.fill()
  -- pauldrons (shoulder armor flares)
  screen.level(7); screen.rect(cx - 11, cy - 5, 4, 6); screen.fill()
  screen.level(7); screen.rect(cx + 7,  cy - 5, 4, 6); screen.fill()
  -- arms holding the hammer (right arm raised across body)
  screen.level(5); screen.rect(cx - 10, cy - 1, 3, 7); screen.fill()
  screen.level(5); screen.rect(cx + 2,  cy - 6 - hammer_lift, 3, 9); screen.fill()
  -- helmet base
  screen.level(5); screen.rect(cx - 6, cy - 14, 12, 8); screen.fill()
  -- helmet top crest (a single ridge)
  screen.level(11); screen.rect(cx - 1, cy - 16, 2, 2); screen.fill()
  -- helmet visor slit
  screen.level(0); screen.rect(cx - 5, cy - 10, 10, 2); screen.fill()
  -- glowing visor eyes
  screen.level(15)
  screen.pixel(cx - 3, cy - 9); screen.pixel(cx + 2, cy - 9); screen.fill()
  -- HAMMER on his right shoulder (handle going up-right; head at top)
  -- handle
  screen.level(4)
  screen.rect(cx + 3, cy - 14 - hammer_lift, 2, 8); screen.fill()
  -- head (slab block)
  screen.level(7)
  screen.rect(cx,     cy - 20 - hammer_lift, 8, 6); screen.fill()
  screen.level(11); screen.rect(cx, cy - 20 - hammer_lift, 8, 1); screen.fill()
  screen.level(2);  screen.rect(cx, cy - 15 - hammer_lift, 8, 1); screen.fill()
  -- rivet marks on the hammer head
  screen.level(13)
  screen.pixel(cx + 1, cy - 18 - hammer_lift)
  screen.pixel(cx + 6, cy - 18 - hammer_lift); screen.fill()
end

function DRAW_ENEMY.granite(cx, cy)
  -- craggy stone golem: top-lit face, dark base + crevices, faint ore
  -- vein, glowing ore eyes, boulder arms w/ a lit top edge.
  screen.level(7);  screen.rect(cx - 16, cy - 14, 32, 28); screen.fill()    -- mass
  screen.level(10); screen.rect(cx - 16, cy - 14, 32, 4); screen.fill()     -- top-lit face
  screen.level(4);  screen.rect(cx - 16, cy + 8, 32, 6); screen.fill()      -- base shadow
  -- carved planes / crevices
  screen.level(2)
  screen.move(cx - 16, cy - 10); screen.line(cx + 16, cy - 2); screen.stroke()
  screen.move(cx - 16, cy + 6);  screen.line(cx + 16, cy + 12); screen.stroke()
  screen.move(cx, cy - 14);      screen.line(cx - 8, cy + 14); screen.stroke()
  -- faint ore vein
  screen.level(9); screen.move(cx + 2, cy - 8); screen.line(cx + 8, cy + 2); screen.stroke()
  -- glowing ore eyes
  screen.level(15); screen.rect(cx - 7, cy - 7, 2, 2); screen.rect(cx + 5, cy - 5, 2, 2); screen.fill()
  -- boulder arms w/ top-light
  screen.level(8);  screen.rect(cx - 20, cy - 4, 4, 12); screen.rect(cx + 16, cy - 2, 4, 12); screen.fill()
  screen.level(11); screen.rect(cx - 20, cy - 4, 4, 1); screen.rect(cx + 16, cy - 2, 4, 1); screen.fill()
end

function DRAW_ENEMY.crow(cx, cy)
  -- silhouetted bird wraith
  screen.level(0)
  screen.rect(cx - 14, cy - 8, 28, 16)
  screen.fill()
  -- body
  screen.level(2)
  screen.rect(cx - 6, cy - 4, 12, 10)
  screen.fill()
  -- wings (flap with tick)
  local f = (tick // 4) % 2
  screen.level(0)
  if f == 0 then
    screen.move(cx - 6, cy);  screen.line(cx - 18, cy - 6); screen.line(cx - 6, cy + 4); screen.close(); screen.fill()
    screen.move(cx + 6, cy);  screen.line(cx + 18, cy - 6); screen.line(cx + 6, cy + 4); screen.close(); screen.fill()
  else
    screen.move(cx - 6, cy);  screen.line(cx - 16, cy + 6); screen.line(cx - 6, cy + 4); screen.close(); screen.fill()
    screen.move(cx + 6, cy);  screen.line(cx + 16, cy + 6); screen.line(cx + 6, cy + 4); screen.close(); screen.fill()
  end
  -- head + glowing eyes
  screen.level(0)
  screen.rect(cx - 3, cy - 9, 6, 5)
  screen.fill()
  screen.level(15)
  screen.pixel(cx - 2, cy - 7)
  screen.pixel(cx + 1, cy - 7)
  screen.fill()
  -- beak
  screen.level(11)
  screen.move(cx - 1, cy - 4); screen.line(cx + 2, cy - 2); screen.line(cx - 1, cy - 2); screen.close(); screen.fill()
end

function DRAW_ENEMY.snowgaunt(cx, cy)
  -- towering frost lich figure
  -- robe shape
  screen.level(11)
  screen.move(cx,      cy - 22)
  screen.line(cx - 18, cy + 18)
  screen.line(cx + 18, cy + 18)
  screen.close()
  screen.fill()
  -- robe shading: shadowed right half, lit left edge, drape folds
  screen.level(8)
  screen.move(cx, cy - 22); screen.line(cx + 18, cy + 18); screen.line(cx + 4, cy + 18)
  screen.close(); screen.fill()
  screen.level(13)
  screen.move(cx, cy - 22); screen.line(cx - 18, cy + 18); screen.stroke()
  screen.level(8)
  screen.move(cx - 6, cy - 2); screen.line(cx - 8, cy + 18); screen.stroke()
  screen.move(cx - 1, cy - 6); screen.line(cx - 1, cy + 18); screen.stroke()
  -- hood frost trim
  screen.level(15)
  screen.move(cx - 10, cy - 12); screen.line(cx + 10, cy - 12); screen.stroke()
  -- skull face inside hood
  screen.level(2)
  screen.rect(cx - 5, cy - 18, 10, 8); screen.fill()
  screen.level(15)
  -- two glowing icy eyes
  screen.pixel(cx - 2, cy - 14); screen.pixel(cx - 3, cy - 14)
  screen.pixel(cx + 2, cy - 14); screen.pixel(cx + 3, cy - 14)
  screen.fill()
  -- jaw line
  screen.level(0)
  screen.move(cx - 4, cy - 11); screen.line(cx + 4, cy - 11); screen.stroke()
  -- icicle staff
  screen.level(13)
  screen.rect(cx + 16, cy - 16, 1, 30); screen.fill()
  screen.level(15)
  screen.pixel(cx + 16, cy - 17)
  screen.fill()
  -- snow swirl around base (animates)
  local s = (tick // 3) % 6
  screen.level(15)
  screen.pixel(cx - 12 + s, cy + 18)
  screen.pixel(cx + 12 - s, cy + 16)
  screen.fill()
end

-- ── Ice Grotto canon set (Cave 5 / story bible) ──────────────────────────
function DRAW_ENEMY.acolyte(cx, cy)
  -- a worshipper frozen mid-prayer: short hooded robe (lit left, shadowed
  -- right), bowed hood, hands pressed at the chest, a faint frost halo.
  screen.level(6)
  screen.move(cx, cy - 6); screen.line(cx - 7, cy + 10); screen.line(cx + 7, cy + 10); screen.close(); screen.fill()
  screen.level(3)
  screen.move(cx, cy - 6); screen.line(cx + 7, cy + 10); screen.line(cx + 2, cy + 10); screen.close(); screen.fill()
  screen.level(9)
  screen.move(cx, cy - 6); screen.line(cx - 7, cy + 10); screen.stroke()
  -- bowed hood + face shadow
  screen.level(4); screen.rect(cx - 3, cy - 9, 6, 4); screen.fill()
  screen.level(2); screen.rect(cx - 2, cy - 6, 4, 1); screen.fill()
  -- pressed hands at the chest
  screen.level(11); screen.rect(cx - 1, cy - 1, 2, 4); screen.fill()
  -- faint frost halo (slow shimmer)
  local h = (tick % 24 < 12) and 7 or 4
  screen.level(h)
  screen.pixel(cx - 5, cy - 8); screen.pixel(cx + 5, cy - 8); screen.pixel(cx, cy - 11); screen.fill()
end

function DRAW_ENEMY.hollowbell(cx, cy)
  -- a cracked cathedral bell tolling under the ice: trapezoid body (lit
  -- crown, shadow lip), a jagged crack, a frost rim, a swaying clapper.
  local sway = math.floor(math.sin(tick / 7) * 1)
  -- yoke / mount
  screen.level(4); screen.rect(cx - 8, cy - 12, 16, 2); screen.fill()
  screen.level(6); screen.move(cx, cy - 10); screen.line(cx, cy - 12); screen.stroke()
  -- bell body (trapezoid)
  screen.level(9)
  screen.move(cx - 4, cy - 9); screen.line(cx + 4, cy - 9); screen.line(cx + 9, cy + 8); screen.line(cx - 9, cy + 8); screen.close(); screen.fill()
  screen.level(13); screen.move(cx - 4, cy - 9); screen.line(cx + 4, cy - 9); screen.stroke()
  screen.level(5);  screen.rect(cx - 9, cy + 6, 18, 2); screen.fill()
  -- jagged crack
  screen.level(2)
  screen.move(cx + 2, cy - 8); screen.line(cx - 1, cy - 3); screen.line(cx + 2, cy + 1); screen.line(cx - 1, cy + 7); screen.stroke()
  -- frost rim
  screen.level(15); screen.pixel(cx - 9, cy + 8); screen.pixel(cx + 9, cy + 8); screen.pixel(cx, cy + 8); screen.fill()
  -- clapper (sways)
  screen.level(3); screen.rect(cx - 1 + sway, cy + 2, 2, 5); screen.fill()
end

function DRAW_ENEMY.brokenchoir(cx, cy)
  -- five cracked voices, no center: a huddle of pale heads with open
  -- singing mouths, each pulsing on its own phase (no shared downbeat).
  local heads = {{-7, 2}, {-3, -2}, {1, 1}, {5, -3}, {7, 3}}
  for i, hd in ipairs(heads) do
    local hx, hy = cx + hd[1], cy + hd[2]
    local on = ((tick // 4) + i) % 3
    screen.level(on == 0 and 11 or 6)
    screen.circle(hx, hy, 2); screen.fill()
    screen.level(0); screen.pixel(hx, hy + 1); screen.fill()       -- open mouth
    screen.level(2); screen.pixel(hx - 1, hy - 1); screen.fill()   -- crack
  end
  -- thin robed mass below
  screen.level(4); screen.rect(cx - 8, cy + 5, 16, 5); screen.fill()
  screen.level(2); screen.rect(cx - 8, cy + 9, 16, 1); screen.fill()
end

function DRAW_ENEMY.drownedsinger(cx, cy)
  -- sang as the cold took the grotto: a pale waterlogged figure, head
  -- tilted back mid-note, water beading and dripping from the hem.
  screen.level(6); screen.rect(cx - 5, cy - 4, 10, 14); screen.fill()
  screen.level(9); screen.rect(cx - 5, cy - 4, 2, 14); screen.fill()   -- wet sheen
  screen.level(3); screen.rect(cx + 3, cy - 4, 2, 14); screen.fill()   -- shadow
  -- head tilted back, mouth open
  screen.level(10); screen.rect(cx - 3, cy - 10, 6, 6); screen.fill()
  screen.level(0);  screen.rect(cx - 1, cy - 6, 2, 2); screen.fill()
  screen.level(13); screen.pixel(cx - 2, cy - 9); screen.pixel(cx + 1, cy - 9); screen.fill()
  -- dripping water (animated)
  local d = (tick // 4) % 6
  screen.level(12)
  screen.pixel(cx - 4, cy + 10 + (d % 4)); screen.pixel(cx + 4, cy + 10 + ((d + 2) % 4)); screen.fill()
end

function DRAW_ENEMY.sunolieut(cx, cy)
  -- Suno's officer: square-shouldered uniform (lit left, shadow right),
  -- heavy epaulettes, a blank slit faceplate like the rank-and-file
  -- silencer, and a rank sigil pulsing on the chest.
  screen.level(6);  screen.rect(cx - 7, cy - 4, 14, 16); screen.fill()
  screen.level(9);  screen.rect(cx - 7, cy - 4, 2, 16); screen.fill()
  screen.level(3);  screen.rect(cx + 5, cy - 4, 2, 16); screen.fill()
  -- epaulettes
  screen.level(8);  screen.rect(cx - 10, cy - 5, 4, 4); screen.rect(cx + 6, cy - 5, 4, 4); screen.fill()
  -- legs
  screen.level(3);  screen.rect(cx - 6, cy + 12, 4, 4); screen.rect(cx + 2, cy + 12, 4, 4); screen.fill()
  -- head: blank faceplate w/ slit
  screen.level(10); screen.rect(cx - 4, cy - 11, 8, 7); screen.fill()
  screen.level(0);  screen.rect(cx - 3, cy - 8, 6, 1); screen.fill()
  -- rank sigil (inverted triangle, faint pulse)
  local p = (tick % 30 < 22) and 13 or 8
  screen.level(p)
  screen.move(cx - 2, cy + 1); screen.line(cx + 2, cy + 1); screen.line(cx, cy + 4); screen.close(); screen.fill()
end

-- Cave 6 + 7 enemies (Suno's Domain)
function DRAW_ENEMY.lich(cx, cy)
  -- skeletal robed figure: shaded robe (lit left, shadowed right) with a
  -- faint ribcage showing through, a bright skull, and a bone staff.
  screen.level(3)
  screen.move(cx, cy - 18); screen.line(cx - 14, cy + 14); screen.line(cx + 14, cy + 14); screen.close(); screen.fill()
  screen.level(1)   -- shadowed right half
  screen.move(cx, cy - 18); screen.line(cx + 14, cy + 14); screen.line(cx + 3, cy + 14); screen.close(); screen.fill()
  screen.level(6)   -- lit left edge
  screen.move(cx, cy - 18); screen.line(cx - 14, cy + 14); screen.stroke()
  -- faint ribcage
  screen.level(6)
  screen.move(cx - 4, cy - 4); screen.line(cx + 4, cy - 4); screen.stroke()
  screen.move(cx - 3, cy - 1); screen.line(cx + 3, cy - 1); screen.stroke()
  -- skull w/ jaw shadow
  screen.level(15); screen.rect(cx - 5, cy - 14, 10, 8); screen.fill()
  screen.level(8);  screen.rect(cx - 5, cy - 7, 10, 1); screen.fill()
  screen.level(0)
  screen.pixel(cx - 2, cy - 11); screen.pixel(cx + 2, cy - 11); screen.fill()   -- eye sockets
  screen.move(cx - 3, cy - 8); screen.line(cx + 3, cy - 8); screen.stroke()
  -- bone staff
  screen.level(11); screen.rect(cx + 12, cy - 16, 1, 30); screen.fill()
  screen.level(15); screen.pixel(cx + 12, cy - 17); screen.fill()
end

function DRAW_ENEMY.voidcrawler(cx, cy)
  -- many-legged void: near-black body w/ faint inner mass + rim sheen,
  -- twitching legs, mandibles, and a sweeping row of eyes where the
  -- active one flares bright + large (the rest are dim).
  screen.level(0); screen.rect(cx - 14, cy - 6, 28, 14); screen.fill()      -- void body
  screen.level(2); screen.rect(cx - 10, cy - 4, 20, 10); screen.fill()      -- faint inner mass
  screen.level(1); screen.rect(cx - 12, cy - 5, 24, 1); screen.fill()       -- top rim sheen
  -- twitching legs (per-leg phase)
  screen.level(8)
  for i = 0, 5 do
    local t = ((tick // 3) + i) % 2
    screen.move(cx - 12 + i * 5, cy + 6); screen.line(cx - 12 + i * 5 - 1 + t, cy + 12); screen.stroke()
  end
  -- mandibles
  screen.level(6); screen.pixel(cx - 13, cy + 5); screen.pixel(cx + 13, cy + 5); screen.fill()
  -- sweeping eye-row (active eye flares; fixes the old no-op loop)
  local s = (tick // 4) % 4
  for i = 0, 3 do
    if i == s then
      screen.level(15); screen.rect(cx - 6 + i * 4, cy - 2, 2, 2); screen.fill()
    else
      screen.level(9); screen.pixel(cx - 6 + i * 4, cy - 1); screen.fill()
    end
  end
end

function DRAW_ENEMY.echosuno(cx, cy)
  -- mocking shadow figure resembling suno (smaller, paler): lightly shaded
  -- robe (lit left, shadowed right), dark hood, glinting eyes, mocking grin.
  screen.level(7)
  screen.move(cx, cy - 16); screen.line(cx - 12, cy + 12); screen.line(cx + 12, cy + 12); screen.close(); screen.fill()
  screen.level(4)   -- shadowed right half
  screen.move(cx, cy - 16); screen.line(cx + 12, cy + 12); screen.line(cx + 3, cy + 12); screen.close(); screen.fill()
  screen.level(10)  -- lit left edge
  screen.move(cx, cy - 16); screen.line(cx - 12, cy + 12); screen.stroke()
  -- hood
  screen.level(2)
  screen.rect(cx - 4, cy - 14, 8, 6); screen.fill()
  -- eyes (mocking smile)
  screen.level(15)
  screen.pixel(cx - 2, cy - 11); screen.pixel(cx + 2, cy - 11)
  screen.move(cx - 3, cy - 8); screen.line(cx - 1, cy - 6); screen.line(cx + 1, cy - 6); screen.line(cx + 3, cy - 8); screen.stroke()
end

function DRAW_ENEMY.mutewarden(cx, cy)
  -- silent armored sentry, no face: plated body with a lit pauldron line,
  -- shadowed greaves, beveled sides, a waist seam, a closed visor with a
  -- vision slit, a chestplate cross, and corner rivets.
  screen.level(7);  screen.rect(cx - 12, cy - 14, 24, 26); screen.fill()
  screen.level(10); screen.rect(cx - 12, cy - 14, 24, 2); screen.fill()   -- lit pauldrons
  screen.level(4);  screen.rect(cx - 12, cy + 8, 24, 4); screen.fill()    -- shadowed greaves
  screen.level(9);  screen.rect(cx - 12, cy - 12, 2, 24); screen.fill()   -- left bevel
  screen.level(4);  screen.rect(cx + 10, cy - 12, 2, 24); screen.fill()   -- right bevel (shadow)
  screen.level(4);  screen.rect(cx - 12, cy, 24, 1); screen.fill()        -- waist seam
  -- helm visor (closed) w/ vision slit
  screen.level(0);  screen.rect(cx - 6, cy - 10, 12, 4); screen.fill()
  screen.level(5);  screen.rect(cx - 5, cy - 9, 10, 1); screen.fill()
  -- chestplate cross
  screen.level(11)
  screen.move(cx, cy - 4); screen.line(cx, cy + 8); screen.stroke()
  screen.move(cx - 6, cy + 2); screen.line(cx + 6, cy + 2); screen.stroke()
  -- corner rivets
  screen.level(13)
  screen.pixel(cx - 10, cy - 12); screen.pixel(cx + 10, cy - 12)
  screen.pixel(cx - 10, cy + 10); screen.pixel(cx + 10, cy + 10); screen.fill()
end

function DRAW_ENEMY.locrius(cx, cy)
  -- conductor of void: tall shaded robe (lit left, shadowed right),
  -- sweeping bone-hand arms with a forearm taper, a black hood, the
  -- triple-eye locrian mark (slow flare), and a whirling shadow at the hem.
  screen.level(3)
  screen.move(cx, cy - 22); screen.line(cx - 18, cy + 18); screen.line(cx + 18, cy + 18); screen.close(); screen.fill()
  screen.level(1)   -- shadowed right half
  screen.move(cx, cy - 22); screen.line(cx + 18, cy + 18); screen.line(cx + 4, cy + 18); screen.close(); screen.fill()
  screen.level(6)   -- lit left edge
  screen.move(cx, cy - 22); screen.line(cx - 18, cy + 18); screen.stroke()
  screen.level(1)   -- fold
  screen.move(cx - 6, cy - 2); screen.line(cx - 9, cy + 18); screen.stroke()
  -- sweeping bone-hand arms (upper arm dim, bone hand bright)
  screen.level(11)
  screen.move(cx - 10, cy - 6); screen.line(cx - 16, cy - 4); screen.stroke()
  screen.move(cx + 10, cy - 6); screen.line(cx + 16, cy - 4); screen.stroke()
  screen.level(15)
  screen.move(cx - 16, cy - 4); screen.line(cx - 22, cy + 4); screen.stroke()
  screen.move(cx + 16, cy - 4); screen.line(cx + 22, cy + 4); screen.stroke()
  -- hood
  screen.level(0)
  screen.rect(cx - 5, cy - 18, 10, 7); screen.fill()
  -- triple-eye mark (locrian/diabolus), slow flare
  local f = (tick % 30 < 22) and 15 or 7
  screen.level(f)
  screen.pixel(cx - 3, cy - 14); screen.pixel(cx, cy - 14); screen.pixel(cx + 3, cy - 14); screen.fill()
  -- whirling shadow at the hem
  local s = (tick // 3) % 6
  screen.level(11)
  screen.pixel(cx - 14 + s, cy + 18); screen.pixel(cx + 14 - s, cy + 16); screen.fill()
end

function DRAW_ENEMY.suno(cx, cy)
  -- towering crowned tyrant with broken-crystal aura
  -- huge robed silhouette
  screen.level(0)
  screen.rect(cx - 22, cy - 22, 44, 44); screen.fill()
  -- robe interior
  screen.level(2)
  screen.move(cx, cy - 22); screen.line(cx - 22, cy + 18); screen.line(cx + 22, cy + 18); screen.close(); screen.fill()
  -- crown spikes
  screen.level(15)
  screen.move(cx - 8, cy - 20); screen.line(cx - 5, cy - 26); screen.line(cx - 2, cy - 20); screen.stroke()
  screen.move(cx - 2, cy - 20); screen.line(cx, cy - 28); screen.line(cx + 2, cy - 20); screen.stroke()
  screen.move(cx + 2, cy - 20); screen.line(cx + 5, cy - 26); screen.line(cx + 8, cy - 20); screen.stroke()
  -- masked face
  screen.level(7)
  screen.rect(cx - 6, cy - 18, 12, 8); screen.fill()
  -- glowing eyes (red-ish on norns = max bright)
  if (tick // 4) % 2 == 0 then
    screen.level(15)
  else
    screen.level(11)
  end
  screen.rect(cx - 4, cy - 15, 3, 2); screen.fill()
  screen.rect(cx + 1, cy - 15, 3, 2); screen.fill()
  -- chest crystal (broken)
  screen.level(13)
  screen.move(cx, cy - 4); screen.line(cx - 4, cy + 2); screen.line(cx, cy + 8); screen.line(cx + 4, cy + 2); screen.close(); screen.fill()
  screen.level(0)
  screen.move(cx, cy - 4); screen.line(cx, cy + 8); screen.stroke()
  -- floating shard fragments (animate around)
  local s = (tick // 2) % 8
  screen.level(15)
  screen.pixel(cx - 18 + s, cy - 8)
  screen.pixel(cx + 18 - s, cy + 4)
  screen.pixel(cx - 14, cy + 12 - s)
  screen.fill()
  -- arms outstretched
  screen.level(7)
  screen.move(cx - 18, cy + 4); screen.line(cx - 22, cy + 14); screen.stroke()
  screen.move(cx + 18, cy + 4); screen.line(cx + 22, cy + 14); screen.stroke()
end

function DRAW_ENEMY.broken_cadence(cx, cy)
  -- A chorister in decaying vestments; one arm raised, one falling.
  -- Flickers on odd phrase-beats to mirror the "ending one note short" motif.
  local breathe = math.floor(math.sin((tick % 40) / 40 * math.pi * 2) * 1)
  -- robed body
  screen.level(6)
  screen.move(cx, cy - 18); screen.line(cx - 12, cy + 14); screen.line(cx + 12, cy + 14); screen.close(); screen.fill()
  -- hooded head
  screen.level(9)
  screen.circle(cx, cy - 20, 7); screen.fill()
  -- raised arm (left — the unfinished gesture)
  screen.level(11)
  screen.move(cx - 10, cy - 8 + breathe)
  screen.line(cx - 18, cy - 16 + breathe)
  screen.stroke()
  -- falling arm (right — half-lowered)
  screen.level(7)
  screen.move(cx + 10, cy - 6)
  screen.line(cx + 16, cy + 2)
  screen.stroke()
  -- hollow eye sockets: flicker to imply the missing note
  local show = (tick // 6) % 3 ~= 0
  if show then
    screen.level(15)
    screen.pixel(cx - 3, cy - 20)
    screen.pixel(cx + 3, cy - 20)
    screen.fill()
  end
  -- broken staff fragment floating to the side
  local drift = (tick // 4) % 6
  screen.level(8)
  screen.move(cx + 14 + drift, cy - 12)
  screen.line(cx + 20 + drift, cy - 4)
  screen.stroke()
end

-- Per-action firing animation. Called from the HUD on the active sprite cell.
-- (sx, sy) = top-left of 8x8 sprite. Animation lasts ~6 ticks (~0.7s @100bpm).
ANIM.draw_action_fx = function(p, sx, sy)
  local t = tick - p.last_fire
  if t < 0 or t > 5 then return end
  local action = p.last_action
  if not action then return end
  local cxc, cyc = sx + 4, sy + 4              -- sprite center
  local ex, ey = 96, 24                         -- enemy center
  if action == "ATK" then
    -- Slash: trail of 3 bright pixels traveling from sprite to enemy
    for k = 0, 2 do
      local prog = (t + 1) / 7 - k * 0.10
      if prog > 0 and prog < 1 then
        local px = math.floor(cxc + (ex - cxc) * prog)
        local py = math.floor(cyc + (ey - cyc) * prog)
        screen.level(15 - k * 4)
        screen.pixel(px, py); screen.pixel(px + 1, py); screen.fill()
      end
    end
    -- short slash mark on the sprite side at the start
    if t < 2 then
      screen.level(15)
      screen.move(sx + 7, sy); screen.line(sx + 9, sy + 5); screen.stroke()
    end
  elseif action == "MAG" then
    -- Spell sparkles: bright stars near the enemy + a vertical bolt arriving
    if t >= 2 then
      screen.level(15)
      screen.rect(ex, ey - 16 + (t - 2) * 4, 1, 4); screen.fill()  -- bolt descends
    end
    local seed = p.last_fire * 17 + t
    for k = 0, 4 do
      local sxk = ex - 8 + ((seed * 13 + k * 7) % 16)
      local syk = ey - 6 + ((seed * 5  + k * 3) % 12)
      screen.level(15 - t * 2)
      screen.pixel(sxk, syk); screen.pixel(sxk + 1, syk); screen.pixel(sxk, syk + 1); screen.fill()
    end
  elseif action == "PLAY" or action == "HEAL" or action == "TUNE" or action == "SMPL" then
    -- Musical notes drifting up. Different glyph counts/colors per instrument
    -- so each character's "play" feels visually distinct.
    local count, color = 3, 15
    if action == "HEAL" then count, color = 4, 13          -- gentle gold
    elseif action == "TUNE" then count, color = 2, 11      -- bold low notes
    elseif action == "SMPL" then count, color = 5, 15      -- many bright sparks
    end
    for k = 0, count - 1 do
      local nx = sx + 1 + k * 2
      local ny = sy - 2 - k * 3 - t
      if ny > 30 then
        screen.level(color - k * 2)
        screen.rect(nx, ny, 2, 2); screen.fill()
        screen.move(nx + 2, ny - 3); screen.line(nx + 2, ny + 1); screen.stroke()
      end
    end
  elseif action == "BLK" then
    -- Shield bash: thick double outline pulses on the sprite, then fades
    local lev = (t < 3) and 15 or 8
    screen.level(lev)
    screen.rect(sx - 1, sy - 1, 10, 10); screen.stroke()
    if t < 3 then
      screen.rect(sx - 2, sy - 2, 12, 12); screen.stroke()
    end
    -- impact mark center
    if t < 2 then
      screen.level(15)
      screen.rect(cxc - 1, cyc - 1, 3, 3); screen.fill()
    end
  elseif action == "DEF" then
    -- Expanding bright diamond (shield-up) around the sprite
    local r = 3 + t
    screen.level(15 - t * 2)
    screen.move(cxc - r, cyc); screen.line(cxc, cyc - r); screen.stroke()
    screen.move(cxc, cyc - r); screen.line(cxc + r, cyc); screen.stroke()
    screen.move(cxc + r, cyc); screen.line(cxc, cyc + r); screen.stroke()
    screen.move(cxc, cyc + r); screen.line(cxc - r, cyc); screen.stroke()
  elseif action == "REF" then
    -- Mirror-shimmer: two concentric diamonds (the 'mirror' field) +
    -- four orbiting sparkles. Brighter than DEF, hangs longer.
    local r1 = 3 + t
    local r2 = 5 + t
    screen.level(15 - t)
    screen.move(cxc - r1, cyc); screen.line(cxc, cyc - r1); screen.stroke()
    screen.move(cxc, cyc - r1); screen.line(cxc + r1, cyc); screen.stroke()
    screen.move(cxc + r1, cyc); screen.line(cxc, cyc + r1); screen.stroke()
    screen.move(cxc, cyc + r1); screen.line(cxc - r1, cyc); screen.stroke()
    screen.level(math.max(2, 12 - t * 2))
    screen.move(cxc - r2, cyc); screen.line(cxc, cyc - r2); screen.stroke()
    screen.move(cxc, cyc - r2); screen.line(cxc + r2, cyc); screen.stroke()
    screen.move(cxc + r2, cyc); screen.line(cxc, cyc + r2); screen.stroke()
    screen.move(cxc, cyc + r2); screen.line(cxc - r2, cyc); screen.stroke()
    -- four orbiting sparkles, rotating with t
    local ang0 = t * 0.8
    for i = 0, 3 do
      local a = ang0 + i * (math.pi / 2)
      local sxp = cxc + math.floor(math.cos(a) * (r2 + 2))
      local syp = cyc + math.floor(math.sin(a) * (r2 + 2))
      screen.level(15)
      screen.pixel(sxp, syp); screen.fill()
    end
  elseif action == "ITM" then
    -- Bright + cross on the sprite + 4 corner sparkles flying outward
    screen.level(15 - t)
    screen.move(cxc - 2, cyc); screen.line(cxc + 2, cyc); screen.stroke()
    screen.move(cxc, cyc - 2); screen.line(cxc, cyc + 2); screen.stroke()
    local off = 4 + t
    screen.pixel(cxc - off, cyc - off)
    screen.pixel(cxc + off, cyc - off)
    screen.pixel(cxc - off, cyc + off)
    screen.pixel(cxc + off, cyc + off)
    screen.fill()
  end
end

local function draw_battle()
  -- Critical-HP vignette: any alive party member below 25% HP triggers a
  -- subtle pulsing border tint. Reads as urgency without obscuring the
  -- battle UI. Drawn FIRST so it sits behind everything.
  do
    local crit = false
    for _, p in ipairs(party) do
      if p.alive and p.hp_max > 0 and (p.hp / p.hp_max) <= 0.25 then crit = true; break end
    end
    if crit then
      local pulse = ((tick % 16) < 8) and 11 or 7
      screen.level(pulse)
      -- Two-pixel-thick border at top + bottom (corners only).
      screen.rect(0, 0, 12, 1); screen.fill()
      screen.rect(0, 1, 4, 1); screen.fill()
      screen.rect(116, 0, 12, 1); screen.fill()
      screen.rect(124, 1, 4, 1); screen.fill()
      screen.rect(0, 63, 12, 1); screen.fill()
      screen.rect(0, 62, 4, 1); screen.fill()
      screen.rect(116, 63, 12, 1); screen.fill()
      screen.rect(124, 62, 4, 1); screen.fill()
    end
  end
  -- ── TOP BAR (rows 0-7): cave name (left) with tiny BPM/key inline ──
  screen.font_face(25); screen.font_size(6)
  screen.level(15)
  screen.move(2, 6)
  screen.text((ANIM.cave_names[current_cave] or "CAVE"))
  -- BPM + key anchored RIGHT NEXT TO the cave name, smaller / dimmer
  local cave_w = screen.text_extents((ANIM.cave_names[current_cave] or "CAVE"))
  screen.level(4)
  screen.move(2 + cave_w + 3, 6)
  screen.text(BATTLE_BPM .. " " .. JAM.note_names[((JAM.root or 0) % 12) + 1])
  -- World of Silence cue: tiny tilde squiggle + "detuned" tag, right-
  -- aligned at the screen edge (the stick pads that used to sit at
  -- x=108+ are gone). Subtle (level 6), no pulse.
  if CONTENT.act3_silence then
    screen.level(6)
    local dw = screen.text_extents("detuned")
    screen.move(126, 6); screen.text_right("detuned")
    screen.pixel(126 - dw - 7, 4); screen.pixel(126 - dw - 6, 3)
    screen.pixel(126 - dw - 5, 4); screen.fill()
  end
  screen.font_face(1); screen.font_size(8)

  -- ── SCENE (rows 9-44): action popup on left, party sprites bottom-left, enemy right ──
  screen.level(3)
  screen.move(0, 9); screen.line(128, 9); screen.stroke()
  -- Climax dimming: as enemy HP drops below 30%, paint a faint dark veil over
  -- the scene area to add visual tension to the final blows.
  if enemy and enemy.hp_max and enemy.hp_max > 0 then
    local hp_pct = enemy.hp / enemy.hp_max
    if hp_pct < 0.30 then
      local dim = math.floor((0.30 - hp_pct) / 0.30 * 3)  -- 0..3
      if dim > 0 then
        screen.level(dim)
        screen.rect(0, 10, 128, 36); screen.fill()
      end
    end
  end
  -- Region-specific battle background: a sparse moving texture layered behind
  -- the enemy + popup. Stays subtle (level 1-3) so foreground reads cleanly.
  do
    local cc = current_cave
    if cc == 1 then
      -- Cave: faint dripping dots
      for i = 1, 6 do
        local dx = (i * 23) % 128
        local dy = 11 + ((tick // 2 + i * 7) % 30)
        screen.level(2); screen.pixel(dx, dy); screen.fill()
      end
    elseif cc == 2 then
      -- Hollow Woods: drifting leaves
      for i = 1, 5 do
        local lx = (i * 31 + tick * 2) % 128
        local ly = 12 + ((i * 11 + tick) % 30)
        screen.level(3); screen.pixel(lx, ly); screen.fill()
      end
    elseif cc == 3 then
      -- Tide cavern: horizontal water shimmer
      for r = 0, 2 do
        local off = (tick * (r + 1)) % 16
        screen.level(2)
        for x = -off, 128, 16 do
          screen.move(x, 14 + r * 10); screen.line(x + 6, 14 + r * 10); screen.stroke()
        end
      end
    elseif cc == 4 then
      -- Glass cavern: sand grains rising
      for i = 1, 7 do
        local sx = (i * 17) % 128
        local sy = 42 - ((tick // 2 + i * 5) % 30)
        screen.level(3); screen.pixel(sx, sy); screen.fill()
      end
    elseif cc == 5 then
      -- Ice grotto: snowflakes drifting down
      for i = 1, 6 do
        local sx = (i * 19 + (tick // 3)) % 128
        local sy = 12 + ((tick + i * 9) % 30)
        screen.level(3); screen.pixel(sx, sy); screen.fill()
        screen.level(2); screen.pixel(sx + 1, sy); screen.fill()
      end
    elseif cc == 6 then
      -- Locrian crypt: pulsing void shadow streaks
      for i = 1, 4 do
        local x = (i * 31) % 128
        local lev = ((tick // 4 + i) % 3) + 1
        screen.level(lev); screen.rect(x, 12, 14, 1); screen.fill()
      end
    elseif cc == 7 then
      -- Suno's chamber: glyph flicker around the boss
      for i = 1, 5 do
        local gx = 60 + ((i * 13 + tick // 4) % 30)
        local gy = 12 + ((i * 7) % 30)
        local lev = ((tick + i * 5) % 8 < 4) and 4 or 2
        screen.level(lev); screen.pixel(gx, gy); screen.pixel(gx + 1, gy + 1); screen.fill()
      end
    end
  end

  -- ENEMY sprite shifted DOWN so its head clears the new compact HP bar above.
  -- Center moved from (96, 24) → (96, 32). Suno (44 tall) still extends a bit
  -- past the HUD divider but clipping is cosmetic.
  if enemy and enemy.alive then
    local fn = DRAW_ENEMY[enemy.visual] or DRAW_ENEMY.slime
    pcall(fn, 96, 32)  -- a drawer bug must not kill the main clock
  end
  -- Compact enemy info pinned to the top of the scene (rows 11-15), placed in the
  -- gap between the action popup (x=1-44) and the enemy sprite area on the right.
  if enemy then
    screen.font_face(25); screen.font_size(6)
    screen.level(11)
    screen.move(46, 14)
    -- Elide long names so they can't collide with the right-aligned HP text
    -- (worst-case HP "1300/1300" starts ~x=88; 12 compact chars at ~4.2px/char
    -- from x=46 end ~x=96 -- close, but real 4-digit-HP bosses have short names).
    local nm = enemy.name
    if #nm > 12 then nm = nm:sub(1, 11) .. "." end
    screen.text(nm)
    if enemy.invincible then
      -- Practice dummy: replace HP/bar with a calm "JAM PAD" hint and exit prompt
      screen.level(6)
      screen.move(126, 14)
      screen.text_right("JAM PAD")
      screen.level(3)
      screen.move(76, 16); screen.line(126, 16); screen.stroke()
      screen.level(5)
      screen.move(126, 22)
      screen.text_right("START/K2 exit")
    else
      -- HP "X/Y" right-aligned, tiny font
      screen.level(7)
      screen.move(126, 14)
      screen.text_right(math.max(0, enemy.hp) .. "/" .. enemy.hp_max)
      -- HP bar: 1 px tall, narrower (28 wide), positioned just below the text
      local hp_w = 50
      local hp_x = 76
      screen.level(2); screen.rect(hp_x, 16, hp_w, 1); screen.fill()
      if enemy.hp_max > 0 then
        local fill = math.floor(hp_w * math.max(0, enemy.hp) / enemy.hp_max)
        if fill > 0 then
          screen.level(13)
          screen.rect(hp_x, 16, fill, 1); screen.fill()
        end
      end
    end
    screen.font_face(1); screen.font_size(8)
  end

  -- ACTION POPUP on the left (lists the active character's 4 class actions)
  local ap = party[active]
  if ap then
    local px, py, pw, ph = 1, 11, 44, 28
    screen.level(0); screen.rect(px, py, pw, ph); screen.fill()
    screen.level(11); screen.rect(px, py, pw, ph); screen.stroke()
    screen.level(15)
    screen.move(px + pw / 2 - 4, py + 6)
    screen.text_center(CHAR_NAME[ap.class])
    -- Equipped instrument icon (8x8) in the top-right corner
    local eq_id = equipped[ap.class]
    if eq_id and INST.sprites[eq_id] then
      INST.sprites[eq_id](px + pw - 9, py + 1)
    end
    screen.level(4)
    screen.move(px + 1, py + 8); screen.line(px + pw - 1, py + 8); screen.stroke()
    -- 4 actions in fixed A/B/X/Y order
    local ca = CLASS_ACTIONS[ap.class]
    local actions = {ca.A, ca.B, ca.X, ca.Y}
    -- LIMIT BREAK indicator: when this character is at <=25% HP and
    -- their limit is unused, the ATK row gets a flashing "!" prefix
    -- so the player knows pressing A will fire their special.
    local limit_ready = (ap.alive and not ap.limit_used
                         and ap.hp > 0 and ap.hp <= ap.hp_max * 0.25)
    for i, act in ipairs(actions) do
      local y = py + 13 + (i - 1) * 5
      local sel = (act == ap.queued)
      screen.level(sel and 15 or 6)
      screen.move(px + 3, y)
      screen.font_face(25); screen.font_size(6)
      -- For ITM: append the picked item name when one is pinned, so the
      -- player can see what their next ITM action will use.
      local label = act
      if act == "ITM" and sel and ap.item_pick and ap.item_pick ~= "auto" then
        label = "ITM:" .. ap.item_pick
      end
      if act == "ATK" and limit_ready then
        local blink = (tick % 8) < 4
        screen.level(blink and 15 or 11)
        label = "LIMIT!"
      end
      screen.text((sel and ">" or " ") .. label)
      screen.font_face(1); screen.font_size(8)
    end
  end

  -- ── HUD (bottom 16 px, rows 48-63): 4 compact character columns ──
  -- Sprite (with fire/hit/active animations) + tiny HP number + thin HP/ATB bars
  -- + queued-action label. The HUD sprite IS the battle sprite.
  screen.level(3)
  screen.move(0, 47); screen.line(128, 47); screen.stroke()
  -- face all sprites right toward the enemy in the HUD
  local saved_facing = player.facing
  player.facing = "right"
  for i, p in ipairs(party) do
    local cx = (i - 1) * 32
    local active_col = (i == active)
    -- column highlight bg for active char
    if active_col then
      screen.level(2)
      screen.rect(cx, 48, 32, 16); screen.fill()
    end
    -- low-HP warning: when alive p ≤ 25% HP, pulse a bright frame
    if p.alive and p.hp_max > 0 and p.hp <= p.hp_max / 4 then
      screen.level((tick % 6 < 3) and 15 or 8)
      screen.rect(cx, 48, 32, 16); screen.stroke()
    end
    -- Rhythm-charged indicator: bright ♪ at top-right of column when
    -- the player armed a rhythm-crit by pressing A on the beat. Fades
    -- after a few ticks so it reads as confirmation, not clutter.
    if p.rhythm_charged then
      local age = tick - (p.rhythm_charged_t or tick)
      local lev = math.max(8, 15 - math.floor(age * 0.5))
      screen.level(lev)
      -- glyph slot hoisted above the divider (rows 42-46 are free between
      -- the action popup, bottom y=39, and the divider at y=47) so it no
      -- longer overlaps the HP "X/Y" text at baseline 52.
      screen.pixel(cx + 27, 42); screen.pixel(cx + 27, 43)
      screen.pixel(cx + 28, 42); screen.pixel(cx + 28, 44)
      screen.pixel(cx + 29, 43); screen.fill()
    end
    -- Denial feedback: brief dim flash on the bell glyph slot whenever
    -- a Resonance invocation was rejected (any cause). Renders even when
    -- no buff is armed, so the player gets a clear visual cue.
    if p.reso_denied_t and (tick - p.reso_denied_t) < 4 and p.alive then
      local bx, by = cx + 25, 42   -- glyph slot above the divider (see rhythm note)
      screen.level(3)   -- norns is grayscale — level 3 reads as dim/wrong in context
      screen.pixel(bx + 1, by);     screen.pixel(bx + 2, by);     screen.pixel(bx + 3, by)
      for c = 0, 4 do
        screen.pixel(bx + c, by + 1); screen.pixel(bx + c, by + 2)
      end
      screen.pixel(bx + 1, by + 3); screen.pixel(bx + 2, by + 3); screen.pixel(bx + 3, by + 3)
      screen.pixel(bx + 2, by + 4)
      screen.fill()
    end
    -- The Ring armed indicator (Miel-specific). Bell silhouette in
    -- the top-right of the HUD column, slower pulse than the rhythm
    -- glyph so the two read as distinct when both are armed at once.
    if p.ring_armed and p.alive then
      local bx, by = cx + 25, 42   -- glyph slot above the divider (see rhythm note)
      local lev = ((tick % 24) < 12) and 13 or 15
      screen.level(lev)
      -- row 0 (bell crown): 3 wide, centered
      screen.pixel(bx + 1, by);     screen.pixel(bx + 2, by);     screen.pixel(bx + 3, by)
      -- row 1-2 (body): full 5 wide
      for c = 0, 4 do
        screen.pixel(bx + c, by + 1); screen.pixel(bx + c, by + 2)
      end
      -- row 3 (mouth narrows): 3 wide centered
      screen.pixel(bx + 1, by + 3); screen.pixel(bx + 2, by + 3); screen.pixel(bx + 3, by + 3)
      -- row 4 (clapper): single center pixel
      screen.pixel(bx + 2, by + 4)
      screen.fill()
    end
    -- Long Echo armed indicator (ECHO-specific). One tiny chevron arrow
    -- per remaining echo charge, in the same glyph slot the bell uses
    -- (classes are mutually exclusive per column) with the same slow
    -- pulse convention.
    if (p.long_echo_charges or 0) > 0 and p.alive then
      local bx, by = cx + 25, 42   -- glyph slot above the divider (see rhythm note)
      local lev = ((tick % 24) < 12) and 13 or 15
      screen.level(lev)
      for k = 1, math.min(2, p.long_echo_charges) do
        local ax = bx + (k - 1) * 3
        screen.pixel(ax, by); screen.pixel(ax + 1, by + 1); screen.pixel(ax, by + 2)
      end
      screen.fill()
    end
    -- Threefold active indicator (Paj-specific). Tiny triangle in the
    -- bell's glyph slot while the heal-on-action window holds; same
    -- pulse convention as the bell.
    if p.alive and p.threefold_until and (tick or 0) < p.threefold_until then
      local bx, by = cx + 25, 42   -- glyph slot above the divider (see rhythm note)
      local lev = ((tick % 24) < 12) and 13 or 15
      screen.level(lev)
      screen.pixel(bx + 2, by)
      screen.pixel(bx + 1, by + 1); screen.pixel(bx + 3, by + 1)
      for c = 0, 4 do screen.pixel(bx + c, by + 2) end
      screen.fill()
    end
    -- character sprite (left of column at row 49) — battle animations land here.
    -- FF-style shock-jump: when recently hit (last 6 ticks), the sprite
    -- bumps 1-2 px back and to the side, easing back to neutral. Reads
    -- as a recoil from the projectile.
    local sx, sy = cx + 1, 49
    if p.alive then
      local hit_age = tick - p.last_hit
      if hit_age >= 0 and hit_age < 6 then
        -- 0..2: peak displacement; 3..5: ease back.
        local mag = (hit_age < 3) and (3 - hit_age) or (6 - hit_age)
        sy = sy + mag             -- pushed down (recoil)
      end
      local fn = SPRITE_BY_CLASS[p.class]
      if fn then fn(sx, sy) end
      -- per-action firing animation (slash / spell / notes / shield / barrier / heal sparkle)
      ANIM.draw_action_fx(p, sx, sy)
      -- recently hit = bright outline + 4 corner sparks (sprite stays visible)
      if hit_age < 3 then
        screen.level(15)
        screen.rect(sx - 1, sy - 1, 10, 10); screen.stroke()
        screen.pixel(sx - 2, sy - 2); screen.pixel(sx + 9, sy - 2)
        screen.pixel(sx - 2, sy + 9); screen.pixel(sx + 9, sy + 9); screen.fill()
      end
    else
      -- KO marker: faint X
      screen.level(2)
      screen.rect(sx, sy, 8, 8); screen.fill()
      screen.level(8)
      screen.move(sx, sy); screen.line(sx + 7, sy + 7); screen.stroke()
      screen.move(sx + 7, sy); screen.line(sx, sy + 7); screen.stroke()
    end
    -- right side: tiny HP "X/Y" at native size 6 (crisp) + thin bars
    screen.font_face(25); screen.font_size(6)
    screen.level(p.alive and (p.hp <= p.hp_max / 4 and 15 or 10) or 4)
    screen.move(cx + 30, 52)
    screen.text_right(p.hp .. "/" .. p.hp_max)
    -- HP bar — 1 px tall, slimmer
    local bx, bw = cx + 11, 16
    screen.level(2); screen.rect(bx, 54, bw, 1); screen.fill()
    if p.alive then
      local fill = math.floor(bw * p.hp / p.hp_max)
      if fill > 0 then
        screen.level(p.hp <= p.hp_max / 4 and 15 or 11)
        screen.rect(bx, 54, fill, 1); screen.fill()
      end
    end
    -- ATB bar — 1 px tall
    screen.level(2); screen.rect(bx, 56, bw, 1); screen.fill()
    if p.alive then
      local fill = math.floor(bw * (p.atb / 16))
      if fill > 0 then
        screen.level(active_col and 14 or 8)
        screen.rect(bx, 56, fill, 1); screen.fill()
      end
    end
    -- queued action label (back at native size 6 — readable)
    screen.font_size(6)
    screen.level(p.alive and (active_col and 15 or 11) or 4)
    screen.move(cx + 11, 62)
    screen.text(p.queued or "")
    -- status markers (right edge): up to 2 stacked symbols showing all
    -- active buffs/debuffs at a glance.
    if p.alive then
      local marks = {}
      if p.blocking then marks[#marks+1] = "B" end
      if p.buffed then marks[#marks+1] = "+" end
      if p.shield then marks[#marks+1] = "*" end
      if p.reflect then marks[#marks+1] = "M" end   -- Mirror (Miel's reflect)
      if (p.regen_hp_ticks or 0) > 0 then marks[#marks+1] = "R" end
      if (p.dmg_reduce_ticks or 0) > 0 then marks[#marks+1] = "D" end
      if (p.poison_ticks or 0) > 0 then marks[#marks+1] = "P" end
      if (p.sleep_ticks or 0) > 0 then marks[#marks+1] = "Z" end
      for k, m in ipairs(marks) do
        if k > 2 then break end
        screen.level(15)
        screen.move(cx + 30, 56 + k * 4); screen.text_right(m)
      end
    end
    screen.font_face(1); screen.font_size(8)
  end
  player.facing = saved_facing

  -- crit-flash pulse on the enemy (3 ticks of bright outline ring)
  if ANIM.crit_flash and (tick - ANIM.crit_flash) < 4 then
    screen.level(15)
    screen.circle(96, 24, 18 - (tick - ANIM.crit_flash) * 2)
    screen.stroke()
  end
  -- in-flight enemy projectile (small bright dot traveling from enemy to target)
  if ANIM.proj then
    local age = tick - ANIM.proj.t
    if age >= 0 and age <= 5 then
      local prog = (age + 1) / 6
      local px = math.floor(ANIM.proj.sx + (ANIM.proj.tx - ANIM.proj.sx) * prog)
      local py = math.floor(ANIM.proj.sy + (ANIM.proj.ty - ANIM.proj.sy) * prog)
      screen.level(15)
      screen.rect(px, py, 2, 2); screen.fill()
      screen.level(11)
      screen.pixel(px - 1, py); screen.pixel(px, py - 1)
      screen.pixel(px + 2, py + 1); screen.pixel(px + 1, py + 2); screen.fill()
    elseif age > 6 then
      ANIM.proj = nil
    end
  end

  -- floating damage numbers (rise + fade); prune expired entries
  for i = #ANIM.popups, 1, -1 do
    local d = ANIM.popups[i]
    local age = tick - d.t
    if age > 12 then
      table.remove(ANIM.popups, i)
    else
      screen.font_face(25); screen.font_size(6)
      local lev = math.max(2, d.lev - math.floor(age * 1.0))
      screen.level(lev)
      screen.move(d.x, d.y - age)
      screen.text_center(tostring(d.amt))
      screen.font_face(1); screen.font_size(8)
    end
  end

  -- (level-up flash moved to the redraw() tail — level-ups happen
  -- outside battle, where this site never rendered them.)
  -- generic story-event banner (Sergei intervention, ambient events,
  -- chord milestones etc.). Box is full-width-ish (4-124) and uses the
  -- compact 6px font so 30-40 char strings fit on one line. Without
  -- the font swap the default 8px font caps usable text at ~12 chars
  -- and longer banners (e.g. "* a lute, far off, plays one phrase *")
  -- overflow the previous 96px box.
  -- (banner draw moved to the redraw() tail so it renders in EVERY
  -- gameplay state — it only ever drew here in draw_battle, leaving
  -- overworld gate refusals, pickups, and scene flashes invisible.)
end
-- Mirror to _ENV: draw_dialogue is defined ABOVE this local and needs
-- it as a backdrop for mid-battle dialogue (Sergei's intervention) —
-- same load-order pattern as _G.enter_battle/_G.travel_to.
_G.draw_battle = draw_battle

-- ── Victory phase 2: XP gain + level-up summary ─────────────────────────
-- Full-screen slide that follows the rewards window. Up to four rows
-- (one per alive party member) with sprite + name + Lv.X→Y if leveled.
-- Globals (no `local`) to dodge the 200-main-chunk-locals cap; the
-- name lookup is rebuilt inside the function for the same reason.
function draw_battle_end_xp()
  local NAMES = {
    mage="Diegues", cleric="Miel", warrior="Strom", bard="Alder",
    engineer="Sergei", mathwiz="Paj", drummer="Niko", wraith="ECHO",
  }
  draw_battle()
  screen.level(0); screen.rect(0, 0, 128, 64); screen.fill()
  screen.level(15); screen.rect(0, 0, 128, 64); screen.stroke()

  -- Header: "+N XP" centered.
  screen.font_face(1); screen.font_size(8)
  local sum = CONTENT.xp_summary or {amount = 0, gains = {}}
  screen.level(15); screen.move(64, 9)
  screen.text_center("+" .. (sum.amount or 0) .. " XP")
  screen.level(4); screen.move(2, 12); screen.line(126, 12); screen.stroke()

  -- Up to 4 rows of party gains. Row pitch 11 px keeps the bottom of row
  -- 4 (sprite ends at y=54, text baseline at 54) clear of the y=58 footer.
  screen.font_face(25); screen.font_size(6)
  local saved_facing = player.facing
  player.facing = "down"
  for i, g in ipairs(sum.gains) do
    if i > 4 then break end
    local row_y = 14 + (i - 1) * 11
    local fn = SPRITE_BY_CLASS[g.class]
    if fn then fn(2, row_y) end
    -- name (left)
    screen.level(15); screen.move(14, row_y + 4)
    screen.text(NAMES[g.class] or g.class)
    -- level info (middle column)
    if g.leveled then
      screen.level(15); screen.move(48, row_y + 4)
      screen.text("Lv." .. g.pre .. ">" .. g.post)
    else
      screen.level(11); screen.move(48, row_y + 4)
      screen.text("Lv." .. g.post)
    end
    -- xp progress (right column or LVL UP badge if just leveled)
    if g.leveled then
      if (tick % 8) < 5 then
        screen.level(15); screen.move(126, row_y + 4); screen.text_right("LVL UP!")
      end
    elseif g.at_cap then
      screen.level(8); screen.move(126, row_y + 4); screen.text_right("MAX")
    else
      screen.level(13); screen.move(126, row_y + 4)
      screen.text_right(g.xp_cur .. "/" .. g.xp_next .. " XP")
    end
  end
  player.facing = saved_facing
  screen.font_face(1); screen.font_size(8)

  -- Footer
  screen.level(4); screen.move(2, 58); screen.line(126, 58); screen.stroke()
  if (tick % 6) < 4 then
    screen.font_face(25); screen.font_size(6)
    screen.level(12); screen.move(64, 63); screen.text_center("A/K3 to leave")
    screen.font_face(1); screen.font_size(8)
  end
end

local function draw_battle_end()
  -- Phase 2 = XP summary slide (only on victory after A press).
  if battle_outcome == "VICTORY" and (CONTENT.battle_end_phase or 1) == 2 then
    draw_battle_end_xp()
    return
  end
  -- Full-screen end-of-battle panel. Bands top→bottom:
  --   y= 1.. 9  header     — VICTORY/DEFEAT + gold pickup (right)
  --   y=12        divider
  --   y=14..36  rewards    — shard/heal, instrument or consumable, class hint
  --   y=38        divider
  --   y=39..54  quip strip — speaker sprite + name + body line (one line)
  --   y=60        press-A   — blinking footer
  -- Each text line uses a fixed baseline; bands never overlap.
  draw_battle()
  -- black backdrop + thin border
  screen.level(0); screen.rect(0, 0, 128, 64); screen.fill()
  screen.level(15); screen.rect(0, 0, 128, 64); screen.stroke()

  -- ── HEADER ──
  screen.font_face(1); screen.font_size(8)
  screen.level(15); screen.move(64, 8); screen.text_center(battle_outcome)
  if battle_outcome == "VICTORY" and SHOP.last_gold and SHOP.last_gold > 0 then
    screen.level(11); screen.move(124, 8); screen.text_right("+" .. SHOP.last_gold .. "g")
  end
  screen.level(4); screen.move(2, 12); screen.line(126, 12); screen.stroke()

  if battle_outcome == "VICTORY" then
    -- ── REWARDS BAND ──
    -- Row 1: shard line (boss) OR heal line (random)
    if last_obtained_shard then
      screen.level(15); screen.move(64, 21)
      screen.text_center("+ " .. SHARD_DISPLAY[last_obtained_shard] .. " Shard")
    else
      screen.level(13); screen.move(64, 21); screen.text_center("party heals 25%")
    end
    -- Row 2: instrument drop (boss) OR consumable drop (random); they're
    -- mutually exclusive in practice — boss fights don't drop salves and
    -- random fights don't drop instruments.
    if last_boss_drop and INSTRUMENTS[last_boss_drop] then
      local inst = INSTRUMENTS[last_boss_drop]
      screen.level(11); screen.move(64, 29); screen.text_center("+ " .. inst.name)
      -- Row 3: class hint in 6px font, comfortably below row 2.
      screen.font_face(25); screen.font_size(6)
      screen.level(6); screen.move(64, 36)
      screen.text_center("(" .. inst.class .. " - equip in menu)")
      screen.font_face(1); screen.font_size(8)
    elseif SHOP.last_item_drop and SHOP.items[SHOP.last_item_drop] then
      screen.level(13); screen.move(64, 29)
      screen.text_center("+ 1 " .. SHOP.items[SHOP.last_item_drop].name)
    end
  else
    screen.level(8); screen.move(64, 24); screen.text_center("retreat to overworld")
  end

  -- ── VICTORY POSES + QUIP STRIP ──
  -- Top half (y=38..49): row of celebratory sprites for every alive
  -- party member, each bobbing on its own phase. Speaker (if any) gets
  -- a brighter sparkle. Bottom half (y=48..58): speaker name + quip (2 lines).
  if battle_outcome == "VICTORY" then
    screen.level(4); screen.move(2, 38); screen.line(126, 38); screen.stroke()
    local NAME_TO_CLASS = {Alder="bard", Miel="cleric", Strom="warrior", Diegues="mage",
                            Sergei="engineer", Paj="mathwiz", Niko="drummer"}
    local q = CONTENT.victory_quip
    local speaker_cls = q and (NAME_TO_CLASS[q.speaker] or q.class) or nil
    -- Collect alive party members for the pose row.
    local alive = {}
    for _, p in ipairs(party) do if p.alive then alive[#alive + 1] = p end end
    local n = #alive
    if n > 0 then
      local saved = player.facing
      player.facing = "down"
      local span = 110                    -- usable width
      local left = 64 - span / 2
      local step = (n > 1) and (span / (n - 1)) or 0
      for i, p in ipairs(alive) do
        local cx = math.floor(left + (i - 1) * step + (n == 1 and span / 2 or 0))
        local fn = SPRITE_BY_CLASS[p.class]
        if fn then
          -- Per-character bob phase so the row reads as four people, not a wave.
          local bob = (((tick + i * 3) % 8) < 4) and 0 or 1
          fn(cx - 4, 41 - bob)
        end
        -- Celebratory symbol above each head — class-themed glyph that
        -- pops every few ticks. Speaker gets a brighter twinkle.
        local is_speaker = (speaker_cls == p.class)
        local twinkle = (((tick + i * 5) % 12) < 6)
        if twinkle then
          local lev = is_speaker and 15 or 11
          screen.level(lev)
          if p.class == "bard" then
            -- musical eighth note (♪)
            screen.pixel(cx + 1, 36); screen.pixel(cx + 2, 35)
            screen.pixel(cx + 3, 34); screen.pixel(cx + 3, 36)
            screen.fill()
          elseif p.class == "cleric" then
            -- soft halo dot pair
            screen.pixel(cx,     35); screen.pixel(cx + 4, 35); screen.fill()
            screen.pixel(cx + 2, 34); screen.fill()
          elseif p.class == "warrior" then
            -- raised-blade glint (vertical 2px + sparkle)
            screen.rect(cx + 2, 34, 1, 3); screen.fill()
            screen.pixel(cx + 4, 35); screen.fill()
          elseif p.class == "mage" then
            -- arcane sparkle (4-pointed)
            screen.pixel(cx + 2, 34); screen.fill()
            screen.pixel(cx + 1, 35); screen.pixel(cx + 3, 35); screen.fill()
            screen.pixel(cx + 2, 36); screen.fill()
          else
            -- generic plus-spark for engineer/mathwiz/drummer
            screen.pixel(cx + 2, 34); screen.fill()
            screen.pixel(cx + 1, 35); screen.pixel(cx + 3, 35); screen.fill()
          end
        end
      end
      player.facing = saved
    end
    -- Speaker quip (6px) below the pose row. Quips run 40-49 chars and a
    -- single centered 6px line caps out around 28, so wrap to two lines,
    -- splitting at the space nearest the midpoint (baselines 52 + 58; the
    -- footer below moved to the compact font at 63 to clear line 2).
    if q then
      screen.font_face(25); screen.font_size(6)
      local full = q.speaker .. ": " .. q.body
      local l1, l2 = full, nil
      if #full > 26 then
        local best, init = nil, 1
        local mid = math.floor(#full / 2)
        while true do
          local s = full:find(" ", init, true)
          if not s then break end
          if not best or math.abs(s - mid) < math.abs(best - mid) then best = s end
          init = s + 1
        end
        if best then
          l1 = full:sub(1, best - 1)
          l2 = full:sub(best + 1)
        end
      end
      screen.level(15)
      if l2 then
        screen.move(64, 52); screen.text_center(l1)
        screen.move(64, 58); screen.text_center(l2)
      else
        screen.move(64, 53); screen.text_center(l1)
      end
      screen.font_face(1); screen.font_size(8)
    end
  end

  -- ── FOOTER ── (compact font so it clears the quip's second line)
  if (tick % 6) < 4 then
    screen.font_face(25); screen.font_size(6)
    screen.level(12); screen.move(64, 63); screen.text_center("A/K3 to leave")
    screen.font_face(1); screen.font_size(8)
  end
end

-- GAME OVER screen. Black field, slow fade-in of "GAME OVER", a thin rule
-- of static beneath, blinking "press A — return to title" prompt. Globally
-- assigned so the dispatcher (which references it by name above) can find
-- it regardless of declaration order.
function draw_game_over()
  screen.level(0); screen.rect(0, 0, 128, 64); screen.fill()
  local age = tick - (GAME_OVER_TICK or 0)
  -- 60-tick fade-in on the title text (eased), capped at level 15.
  local lev = math.min(15, math.floor(age * 0.30))
  screen.font_face(1); screen.font_size(8)
  screen.level(lev)
  screen.move(64, 24); screen.text_center("GAME OVER")
  -- decorative rule + sparse static below the text
  screen.level(math.max(2, lev - 7))
  screen.move(28, 30); screen.line(100, 30); screen.stroke()
  if age > 24 then
    for i = 1, 14 do
      local sx = 28 + (i * 5 + (tick // 4)) % 72
      local sy = 33 + ((i * 7 + tick) % 4)
      if ((tick + i) % 5) < 2 then
        screen.level(math.max(2, lev - 4))
        screen.pixel(sx, sy); screen.fill()
      end
    end
  end
  -- subtitle (only after fade-in mostly resolves)
  if age > 40 then
    screen.font_face(25); screen.font_size(6)
    screen.level(math.max(4, lev - 4))
    screen.move(64, 44); screen.text_center("the chord falls silent.")
    screen.font_face(1); screen.font_size(8)
  end
  -- blinking prompt
  if age > 80 and (tick % 12) < 8 then
    screen.font_face(25); screen.font_size(6)
    screen.level(11)
    screen.move(64, 58); screen.text_center("A/K3  return to title")
    screen.font_face(1); screen.font_size(8)
  end
end

local function draw_menu()
  draw_overworld()
  -- FF7-style menu: party panels (left half) + menu list (right half).
  -- Solid black background so the overworld is fully obscured.
  screen.level(0); screen.rect(0, 0, 128, 64); screen.fill()

  -- ── LEFT: party panels (62 wide × 64 tall, 4 stacked panels of 16) ──
  -- The active leader's panel gets a brighter frame so the "current"
  -- party member is visually distinguishable from the roster.
  screen.font_face(25); screen.font_size(6)
  local saved_facing = player.facing
  player.facing = "down"
  for i, p in ipairs(party) do
    local py0 = (i - 1) * 16
    local is_lead = (i == active)
    screen.level(is_lead and 15 or 4); screen.rect(0, py0, 62, 15); screen.stroke()
    local fn = SPRITE_BY_CLASS[p.class]
    if fn then fn(2, py0 + 4) end
    screen.level(15); screen.move(13, py0 + 5)
    screen.text(CHAR_NAME[p.class] or p.class)
    screen.level(11); screen.move(45, py0 + 5)
    screen.text("LV " .. (p.level or 1))
    screen.level(p.alive and 15 or 5)
    screen.move(13, py0 + 11)
    screen.text("HP " .. (p.hp or 0) .. "/" .. (p.hp_max or 0))
    if not p.alive then
      screen.level(8); screen.move(13, py0 + 13); screen.text("KO")
    end
  end

  -- ── RIGHT: menu list (64 wide × 64 tall) ──
  -- The leader-indicator slot was removed — the highlighted (level 15)
  -- frame on the active leader's left-side party panel is enough of a
  -- "you are here" cue without crowding the menu header.
  local mx = 64
  screen.level(11); screen.rect(mx, 0, 64, 64); screen.stroke()
  player.facing = saved_facing
  screen.level(15); screen.move(mx + 32, 6); screen.text_center("MENU")
  screen.level(6); screen.move(mx + 3, 8); screen.line(mx + 61, 8); screen.stroke()
  -- Two-column option grid: 11 options overflowed the old single
  -- 5-px-pitch column (row 11 landed at y=64, off-screen and colliding
  -- with the gold footer). Options 1-6 fill column A, 7-11 column B;
  -- menu_idx stays absolute and the cursor tick renders in whichever
  -- column holds it (column B = idx > 6). Long labels are display-
  -- shortened to fit the ~26-px column width — dispatch still keys off
  -- the full MENU_OPTIONS strings. First row at y=16 so 6px-font glyphs
  -- (y=11..16) clear the divider at y=8.
  local SHORT_LBL = {["Save Game"] = "Save", ["Party Status"] = "Status",
                     ["Equipment"] = "Equip", ["Bestiary"] = "Beasts",
                     ["Achievements"] = "Awards", ["Jam Pad"] = "JamPad",
                     ["Jam Mode"] = "Jam"}
  for i, opt in ipairs(MENU_OPTIONS) do
    local col_b = (i > 6)
    local x = col_b and (mx + 33) or (mx + 3)
    local y = 16 + (col_b and (i - 7) or (i - 1)) * 7
    local label = SHORT_LBL[opt] or opt
    if i == menu_idx then
      screen.level(15)
      screen.rect(x, y - 4, 2, 4); screen.fill()   -- cursor tick
      screen.move(x + 4, y); screen.text(label)
    else
      screen.level(7)
      screen.move(x + 4, y); screen.text(label)
    end
  end
  -- Footer: gold counter (left). Options end at y=16+5*7=51 (column A's
  -- 6th row), so the y=62 footer band stays clear.
  screen.level(11); screen.move(mx + 3, 62); screen.text(SHOP.gold .. "g")
  screen.font_face(1); screen.font_size(8)
  -- save flash (kept on default font)
  if save_flash_ticks > 0 then
    screen.level(0)
    screen.rect(20, 56, 88, 8)
    screen.fill()
    screen.level(15)
    screen.move(64, 62)
    screen.text_center(scrub_text(save_flash_text or ""))
  end
end

-- ============================================================ PORTRAITS
