do
local function draw_scene_cosmic()
  -- two-layer drifting starfield with a distant ringed planet + brighter stars
  screen.level(2)
  for i = 1, 18 do
    local sx = (i * 13 + tick) % 128
    local sy = (i * 7 + i * 3) % 64
