    local sx = (i * 23 + tick * 2) % 128
    local sy = (i * 11 + 4) % 60
    screen.pixel(sx, sy)
  end
  screen.fill()
  -- a bright pulsar that twinkles
  if (tick % 14) < 7 then
    screen.level(15); screen.pixel(40, 18); screen.pixel(40, 17); screen.pixel(40, 19)
    screen.pixel(39, 18); screen.pixel(41, 18); screen.fill()
