function draw_scene_lirael_bell_alcove()
  -- Animate on scene time (15 Hz), not the tempo-dependent music tick.
  local tick = (SCENE and SCENE.panel_t) or tick
  -- Tapestry alcove with a slow-swinging bell silhouette growing larger
  -- as the attunement reaches its peak. Background is the alcove
  -- (dark tapestry), foreground is the bell.
  screen.level(1); screen.rect(0, 0, 128, 64); screen.fill()
  -- alcove walls (frame the tapestry)
  screen.level(3); screen.rect(40, 4, 48, 56); screen.fill()
  -- tapestry pattern (vertical stripes, dim)
  screen.level(5)
  for x = 44, 84, 4 do screen.move(x, 8); screen.line(x, 56); screen.stroke() end
  -- floor stripes leading to the alcove
  screen.level(2)
  for y = 56, 62, 2 do screen.move(0, y); screen.line(128, y); screen.stroke() end
  -- the bell silhouette: grows over a 60-tick cycle, then resets
  local phase = (tick % 60) / 60
  local r = 6 + math.floor(phase * 14)
  local sw = math.floor(math.sin(tick * 0.18) * 4)
  -- bell body
  screen.level(11)
  screen.circle(64 + sw, 28, r); screen.fill()
  -- bell mouth (cut-out)
  screen.level(0)
  screen.circle(64 + sw, 28 + r, 2); screen.fill()
  -- clapper at the bottom
  screen.level(13); screen.pixel(64 + sw, 28 + r); screen.fill()
  -- soft halo around the bell at peak
  if phase > 0.6 then
    screen.level(7); screen.circle(64 + sw, 28, r + 4); screen.stroke()
  end
end

function draw_scene_academy_astrolabe_resonant()
  -- Animate on scene time (15 Hz), not the tempo-dependent music tick.
  local tick = (SCENE and SCENE.panel_t) or tick
  -- Academy courtyard with the astrolabe at center. Concentric rings
  -- expand outward from it; ECHO's silhouette stands beside it at solid
  -- (no-trail) brightness, confirming she's anchored.
  screen.level(1); screen.rect(0, 0, 128, 64); screen.fill()
  -- courtyard floor (paving stripes)
  screen.level(3)
  for y = 36, 60, 4 do screen.move(0, y); screen.line(128, y); screen.stroke() end
  -- astrolabe: pillar + rotating ring
  screen.level(7); screen.rect(60, 28, 8, 24); screen.fill()
  screen.level(11); screen.circle(64, 24, 8); screen.stroke()
  local a = (tick * 0.05) % (math.pi * 2)
  screen.level(13)
  screen.pixel(64 + math.floor(math.cos(a) * 8), 24 + math.floor(math.sin(a) * 8))
  screen.fill()
  -- expanding rings emanating from the astrolabe
  for k = 0, 2 do
    local r = ((tick + k * 8) % 24) + 4
    if r < 22 then
      screen.level(math.max(3, 11 - k * 2)); screen.circle(64, 24, r); screen.stroke()
    end
  end
  -- ECHO silhouette to the left (solid brightness, anchored)
  screen.level(11); screen.rect(50, 26, 4, 4); screen.fill()  -- head
  screen.level(11); screen.rect(49, 30, 6, 8); screen.fill()  -- body
end


