function draw_scene_observatory_masked_voice()
  -- Animate on scene time (15 Hz), not the tempo-dependent music tick.
  local tick = (SCENE and SCENE.panel_t) or tick
  -- Velthe's study: tall arched star-window, the desk, and a mask
  -- floating over it. Beneath the mask, the voice-line redraws itself
  -- in a different shape every half-cycle — the same phrase, sung as
  -- someone else.
  screen.level(1); screen.rect(0, 0, 128, 64); screen.fill()
  -- arched window (right side) with stars
  screen.level(3); screen.rect(88, 6, 30, 44); screen.fill()
  screen.level(0); screen.rect(90, 8, 26, 40); screen.fill()
  screen.level(9)
  screen.pixel(96, 14); screen.pixel(108, 20); screen.pixel(101, 30)
  screen.pixel(112, 38); screen.pixel(94, 42); screen.fill()
  -- desk (low, left-center) + a small open book
  screen.level(4); screen.rect(20, 44, 44, 3); screen.fill()
  screen.level(2); screen.rect(24, 47, 3, 12); screen.rect(56, 47, 3, 12); screen.fill()
  screen.level(8); screen.rect(38, 42, 10, 2); screen.fill()
  -- the mask: floating rounded face with two eye slits, breathing
  local bob = math.floor(math.sin(tick * 0.10) * 2)
  screen.level(12); screen.rect(36, 16 + bob, 14, 12); screen.fill()
  screen.level(0);  screen.rect(39, 20 + bob, 3, 1); screen.rect(44, 20 + bob, 3, 1); screen.fill()
  -- the voice-line: alternates between two waveforms every 30 ticks —
  -- a smooth wave and a squared one (same melody, different voice)
  local squared = ((tick % 60) >= 30)
  screen.level(10)
  for x = 10, 76, 2 do
    local ph = (x + tick) * 0.25
    local y
    if squared then
      y = 34 + (((math.floor(ph / math.pi) % 2) == 0) and -3 or 3)
    else
      y = 34 + math.floor(math.sin(ph) * 3 + 0.5)
    end
    screen.pixel(x, y + bob)
  end
  screen.fill()
  -- Diegues silhouette at the desk, solid
  screen.level(11); screen.rect(28, 34, 4, 4); screen.fill()  -- head
  screen.level(11); screen.rect(27, 38, 6, 8); screen.fill()  -- body
end

function draw_scene_sunward_bandstand_resonant()
  -- Animate on scene time (15 Hz), not the tempo-dependent music tick.
  local tick = (SCENE and SCENE.panel_t) or tick
  -- The Sunward bandstand at golden hour: posts + canopy, sea horizon
  -- behind. The Spring wells up through the boards — bright droplets
  -- rise, and every ring the fountain-water makes is answered by a
  -- dimmer echo of itself a beat later.
  screen.level(1); screen.rect(0, 0, 128, 64); screen.fill()
  -- horizon + low sun
  screen.level(3); screen.move(0, 22); screen.line(128, 22); screen.stroke()
  screen.level(6); screen.circle(106, 20, 5); screen.fill()
  screen.level(1); screen.rect(98, 21, 20, 6); screen.fill()
  -- bandstand: deck, two posts, canopy arc
  screen.level(4); screen.rect(28, 46, 72, 3); screen.fill()
  screen.level(5); screen.rect(34, 22, 3, 24); screen.rect(92, 22, 3, 24); screen.fill()
  screen.level(7); screen.rect(30, 18, 68, 3); screen.fill()
  screen.level(5); screen.rect(26, 21, 76, 1); screen.fill()
  -- the Spring: droplets rising from the boards on staggered cycles
  -- (fill per droplet — each has its own fade level)
  for k = 0, 4 do
    local ph = ((tick + k * 9) % 36) / 36
    local dy = math.floor(ph * 22)
    local lev = math.max(2, 12 - math.floor(ph * 10))
    screen.level(lev)
    screen.pixel(48 + k * 8, 44 - dy)
    screen.fill()
  end
  -- water ring + its echo: same center, echo trails 8 ticks dimmer
  local r1 = (tick % 28) + 3
  if r1 < 26 then screen.level(9); screen.circle(64, 45, r1); screen.stroke() end
  local r2 = ((tick - 8) % 28) + 3
  if r2 < 26 then screen.level(4); screen.circle(64, 45, r2); screen.stroke() end
  -- Alder silhouette on the deck, solid, lute at his side
  screen.level(11); screen.rect(60, 32, 4, 4); screen.fill()   -- head
  screen.level(11); screen.rect(59, 36, 6, 8); screen.fill()   -- body
  screen.level(8);  screen.rect(66, 38, 2, 5); screen.fill()   -- lute neck
end

function draw_scene_phrygian_scatter()
  -- Animate on scene time (15 Hz), not the tempo-dependent music tick.
  local tick = (SCENE and SCENE.panel_t) or tick
  -- The Phrygian bazaar at night: awning lines and stall shapes in the
  -- sand-stone palette. Sergei's rig sits center; the Scatter throws a
  -- handful of bright points into NEW positions on every beat — order
  -- becoming delightful confusion.
  screen.level(1); screen.rect(0, 0, 128, 64); screen.fill()
  -- sand-stone floor stripes (drumhall palette)
  screen.level(3)
  for y = 44, 60, 4 do screen.move(0, y); screen.line(128, y); screen.stroke() end
  -- stall awnings: two slanted canopies
  screen.level(4); screen.move(6, 16); screen.line(40, 12); screen.stroke()
  screen.move(6, 16); screen.line(10, 30); screen.stroke()
  screen.move(122, 18); screen.line(90, 13); screen.stroke()
  screen.move(122, 18); screen.line(118, 32); screen.stroke()
  -- Sergei's rig: a squat box with a dial and one blinking lamp
  screen.level(6); screen.rect(56, 34, 16, 10); screen.fill()
  screen.level(2); screen.circle(64, 39, 2); screen.stroke()
  if (tick % 16) < 8 then screen.level(13); screen.pixel(70, 36); screen.fill() end
  -- the Scatter: 7 points that JUMP to new deterministic positions
  -- every 12 ticks (hash on the beat index — no math.random in draws)
  local beat = math.floor(tick / 12)
  screen.level(12)
  for k = 1, 7 do
    local h = (beat * 73 + k * 137) % 97
    local x = 24 + ((h * 83 + k * 29) % 80)
    local y = 8 + ((h * 47 + k * 61) % 26)
    screen.pixel(x, y)
  end
  screen.fill()
  -- Sergei silhouette beside the rig, solid
  screen.level(11); screen.rect(46, 32, 4, 4); screen.fill()  -- head
  screen.level(11); screen.rect(45, 36, 6, 8); screen.fill()  -- body
end

function draw_scene_sunward_slow_wheel()
  -- Animate on scene time (15 Hz), not the tempo-dependent music tick.
  local tick = (SCENE and SCENE.panel_t) or tick
  -- The harbor capstan: a great wheel that turns on its own — slow,
  -- even, unhurried — over the water. Strom stands with a hand on it.
  screen.level(1); screen.rect(0, 0, 128, 64); screen.fill()
  -- sea horizon + water stripes
  screen.level(3); screen.move(0, 20); screen.line(128, 20); screen.stroke()
  screen.level(2)
  for y = 24, 32, 4 do screen.move(0, y); screen.line(128, y); screen.stroke() end
  -- dock boards
  screen.level(4)
  for y = 48, 62, 4 do screen.move(0, y); screen.line(128, y); screen.stroke() end
  -- the capstan wheel: hub + rim + four spokes rotating SLOWLY
  local cx, cy, R = 64, 36, 14
  screen.level(9); screen.circle(cx, cy, R); screen.stroke()
  screen.level(5); screen.circle(cx, cy, R - 3); screen.stroke()
  local a0 = tick * 0.02   -- slow, even, on its own
  screen.level(11)
  for k = 0, 3 do
    local a = a0 + k * (math.pi / 2)
    screen.move(cx, cy)
    screen.line(cx + math.floor(math.cos(a) * R), cy + math.floor(math.sin(a) * R))
    screen.stroke()
  end
  screen.level(13); screen.circle(cx, cy, 2); screen.fill()
  -- Strom silhouette at the wheel's edge, hand on the rim, solid
  screen.level(11); screen.rect(42, 32, 4, 4); screen.fill()  -- head
  screen.level(11); screen.rect(41, 36, 6, 8); screen.fill()  -- body
  screen.level(9);  screen.rect(47, 37, 4, 1); screen.fill()  -- arm to the rim
end

function draw_scene_academy_threefold()
  -- Animate on scene time (15 Hz), not the tempo-dependent music tick.
  local tick = (SCENE and SCENE.panel_t) or tick
  -- The Academy: three tuning forks stand on the lectern table, struck
  -- as one — three ring-sets bloom from three mouths and meet in the
  -- middle as a single chord. Paj beside the table.
  screen.level(1); screen.rect(0, 0, 128, 64); screen.fill()
  -- hall floor stripes
  screen.level(3)
  for y = 46, 60, 4 do screen.move(0, y); screen.line(128, y); screen.stroke() end
  -- lectern table
  screen.level(4); screen.rect(38, 40, 52, 3); screen.fill()
  screen.level(2); screen.rect(42, 43, 3, 12); screen.rect(82, 43, 3, 12); screen.fill()
  -- three tuning forks (U shapes) standing on the table
  screen.level(10)
  for k = 0, 2 do
    local fx = 48 + k * 16
    screen.rect(fx,     28, 1, 8); screen.fill()   -- left tine
    screen.rect(fx + 4, 28, 1, 8); screen.fill()   -- right tine
    screen.rect(fx + 1, 36, 3, 1); screen.fill()   -- base
    screen.rect(fx + 2, 37, 1, 3); screen.fill()   -- stem to table
  end
  -- three ring-sets, one per fork, same phase — one chord, threefold
  local r = (tick % 26) + 2
  if r < 24 then
    for k = 0, 2 do
      screen.level(math.max(2, 11 - math.floor(r / 3)))
      screen.circle(50 + k * 16, 30, r); screen.stroke()
    end
  end
  -- a bright meeting-point where the rings overlap (pulses on cycle)
  if r > 8 and r < 16 then
    screen.level(14); screen.pixel(58, 30); screen.pixel(74, 30); screen.fill()
  end
  -- Paj silhouette beside the table, solid
  screen.level(11); screen.rect(30, 34, 4, 4); screen.fill()  -- head
  screen.level(11); screen.rect(29, 38, 6, 8); screen.fill()  -- body
end

SCENE_DRAW = {
  cosmic  = draw_scene_cosmic,
  dark    = draw_scene_dark,
  village = draw_scene_village,
  threat  = draw_scene_threat,
  throne  = draw_scene_throne,
  coup    = draw_scene_coup,
  passage = draw_scene_passage,
  -- intro overhaul (2026-05-14): per-panel scenes for the rewritten opening cutscene
  cosmic_stars        = draw_scene_cosmic_stars,
  cosmic_chord        = draw_scene_cosmic_chord,
  cosmic_modes        = draw_scene_cosmic_modes,
  cosmic_world        = draw_scene_cosmic_world,
  cosmic_shatter      = draw_scene_cosmic_shatter,
  cosmic_drift        = draw_scene_cosmic_drift,
  dark_suno           = draw_scene_dark_suno,
  dark_march          = draw_scene_dark_march,
  dark_village        = draw_scene_dark_village,
  lirael_coast        = draw_scene_lirael_coast,
  lirael_belltower    = draw_scene_lirael_belltower,
  lirael_hall         = draw_scene_lirael_hall,
  lirael_southwall    = draw_scene_lirael_southwall,
  lirael_chamber      = draw_scene_lirael_chamber,
  lirael_road         = draw_scene_lirael_road,
  lirael_sentry       = draw_scene_lirael_sentry,
  lirael_captain_run  = draw_scene_lirael_captain_run,
  lirael_courtyard    = draw_scene_lirael_courtyard,
  lirael_gate         = draw_scene_lirael_gate,
  lirael_bell_alcove  = draw_scene_lirael_bell_alcove,
  academy_astrolabe_resonant = draw_scene_academy_astrolabe_resonant,
  phrygian_drumhall_resonant = draw_scene_phrygian_drumhall_resonant,
  -- Resonance signature panels (2026-07-02) — completes all 8; shown
  -- by the attunement scaffold via the show_panel scene step.
  observatory_masked_voice   = draw_scene_observatory_masked_voice,
  sunward_bandstand_resonant = draw_scene_sunward_bandstand_resonant,
  phrygian_scatter           = draw_scene_phrygian_scatter,
  sunward_slow_wheel         = draw_scene_sunward_slow_wheel,
  academy_threefold          = draw_scene_academy_threefold,
}
-- Mirror to _G for draw_overworld's panel hook: that function is
-- defined lexically BEFORE the `local SCENE_DRAW` declaration, so its
-- reference compiles as a global read (the documented local-scoping
-- trap). Same pattern as the _G.travel_to / _G.save_game mirrors.
_G.SCENE_DRAW = SCENE_DRAW
end  -- scene draws

-- Scrub characters the Tom Thumb / default fonts can't render, mirroring
-- what pack_dialogue_lines does for NPC dialogue. Used by the cutscene
-- + ending panels + banners so all in-game text renders consistently.
-- Global to dodge the 200-local main-chunk cap.
function scrub_text(s)
  if not s then return "" end
  s = s:gsub("\xE2\x80\x94", "--")   -- em-dash UTF-8
  s = s:gsub("\xE2\x80\x93", "-")    -- en-dash UTF-8
  s = s:gsub("\xE2\x80\xA6", "...")  -- ellipsis UTF-8 (just in case)
  s = s:gsub("  +", " ")
  return s
end

local function draw_cutscene()
  local panel = CUTSCENE_LINES[cutscene_idx]
  if type(panel) ~= "table" then panel = {text = tostring(panel or ""), scene = "cosmic"} end
  panel = {text = scrub_text(panel.text), scene = panel.scene}

  -- background scene
  local fn = SCENE_DRAW[panel.scene] or SCENE_DRAW.cosmic
  fn()

  -- (Letterbox bars removed — they were clipping content on the 64px
  -- tall OLED. Cinematic feel is preserved by the existing per-panel
  -- flash + fade + scene_draw backgrounds.)

  -- Panel-change transition: fade text and overlay a brief flash for the
  -- first ~12 ticks after a panel change. cutscene_panel_start is set on
  -- new-game-start AND on every advance.
  local t_in = tick - (CONTENT.cutscene_panel_start or 0)
  local flash_phase = math.max(0, math.min(1, t_in / 4))
  local fade_phase  = math.max(0, math.min(1, (t_in - 2) / 10))

  -- White flash on panel change (4-tick falloff)
  if flash_phase < 1 then
    screen.level(math.floor(15 * (1 - flash_phase)))
    screen.rect(0, 0, 128, 64); screen.fill()
  end

  -- text panel: subtle dark band behind text for readability
  local lines = wrap_text(panel.text, 116)
  local panel_h = 6 + (#lines * 8)
  local panel_y = 28 - math.floor(#lines * 4)
  screen.level(0)
  screen.rect(2, panel_y - 4, 124, panel_h + 2)
  screen.fill()
  screen.level(math.floor(2 + 4 * fade_phase))
  screen.rect(2, panel_y - 4, 124, panel_h + 2)
  screen.stroke()
  for i, line in ipairs(lines) do
    screen.level(math.floor(2 + 11 * fade_phase))
    screen.move(64, panel_y + i * 8)
    screen.text_center(line)
  end

  -- progress dots — current dot pulses gently
  for i = 1, #CUTSCENE_LINES do
    local x = 64 + (i - (#CUTSCENE_LINES + 1) / 2) * 5
    if i == cutscene_idx then
      local pulse = ((tick % 12) < 6) and 15 or 11
      screen.level(pulse)
    else
      screen.level(i < cutscene_idx and 7 or 3)
    end
    screen.rect(x - 1, 58, 2, 2)
    screen.fill()
  end

  -- Advance prompt only appears after the fade-in completes
  if fade_phase >= 1 and (tick % 8) < 5 then
    screen.level(10)
    screen.move(124, 62)
    screen.text_right("A/K3 >")
  end
end

local function draw_ending()
  -- mirrors draw_cutscene structure but reads from ENDING_LINES
  local panel = ENDING_LINES[ending_idx]
  if type(panel) ~= "table" then panel = {text = tostring(panel or ""), scene = "cosmic"} end
  panel = {text = scrub_text(panel.text), scene = panel.scene}
  local fn = SCENE_DRAW[panel.scene] or SCENE_DRAW.cosmic
  fn()
  -- (Top letterbox removed — was clipping the cosmic background. Ending
  -- already feels cinematic via the SCENE_DRAW background + slow text.)
  local lines = wrap_text(panel.text, 116)
  local panel_h = 6 + (#lines * 8)
  local panel_y = 28 - math.floor(#lines * 4)
  screen.level(0)
  screen.rect(2, panel_y - 4, 124, panel_h + 2)
  screen.fill()
  screen.level(2)
  screen.rect(2, panel_y - 4, 124, panel_h + 2)
  screen.stroke()
  for i, line in ipairs(lines) do
    screen.level(15)
    screen.move(64, panel_y + i * 8)
    screen.text_center(line)
  end
  for i = 1, #ENDING_LINES do
    local x = 64 + (i - (#ENDING_LINES + 1) / 2) * 5
    screen.level(i == ending_idx and 15 or 3)
    screen.rect(x - 1, 58, 2, 2)
    screen.fill()
  end
  if (tick % 8) < 5 then
    screen.level(10)
    screen.move(124, 62)
    screen.text_right("A/K3 >")
  end
end

local function draw_voyage()
  -- ocean horizon + scrolling waves; boat sails across center
  -- background: dark sea, faint horizon line
  screen.level(1)
  screen.rect(0, 0, 128, 28)
  screen.fill()
  screen.level(3)
  screen.rect(0, 28, 128, 36)
  screen.fill()
  -- horizon line
  screen.level(5)
  screen.move(0, 28)
  screen.line(128, 28)
  screen.stroke()
  -- distant clouds (drifting slowly)
  local cloud_off = (tick // 4) % 128
  for i = 0, 2 do
    local cx = (i * 50 + cloud_off) % 140 - 12
    screen.level(6)
    screen.rect(cx, 8 + i * 3, 14, 2)
    screen.fill()
  end
  -- wave lines (scroll right→left)
  for row = 0, 6 do
    local wy = 30 + row * 4
    local off = (tick * (row + 1) // 2) % 16
    screen.level(row % 2 == 0 and 7 or 5)
    for x = -off, 128, 16 do
      screen.move(x, wy)
      screen.line(x + 6, wy)
      screen.stroke()
      screen.move(x + 8, wy + 1)
      screen.line(x + 12, wy + 1)
      screen.stroke()
    end
  end
  -- boat: sails left→right or right→left across screen based on which dir
  local progress = 1 - (voyage_ticks / VOYAGE_DURATION)
  local bx
  if voyage_target_map == 2 then
    bx = math.floor(8 + progress * 110)
  else
    bx = math.floor(118 - progress * 110)
  end
  local by = 30 + ((tick // 4) % 2)  -- gentle bob
  -- hull
  screen.level(13)
  screen.move(bx, by + 4)
  screen.line(bx + 14, by + 4)
  screen.line(bx + 12, by + 7)
  screen.line(bx + 2, by + 7)
  screen.close()
  screen.fill()
  -- mast
  screen.level(11)
  screen.rect(bx + 7, by - 4, 1, 8)
  screen.fill()
  -- sail (triangle)
  screen.level(15)
  screen.move(bx + 7, by - 4)
  screen.line(bx + 13, by + 3)
  screen.line(bx + 7, by + 3)
  screen.close()
  screen.fill()
  -- pennant
  screen.level(8)
  screen.pixel(bx + 8, by - 4)
  screen.pixel(bx + 9, by - 4)
  screen.fill()
  -- text banner
  local dest = voyage_target_map == 2 and "EASTERN REACHES" or "SUNWARD COAST"
  screen.level(0)
  screen.rect(0, 54, 128, 10)
  screen.fill()
  screen.level(2)
  screen.move(0, 54)
  screen.line(128, 54)
  screen.stroke()
  screen.level(13)
  screen.move(64, 62)
  screen.text_center("Sailing to " .. dest)
end

local function draw_title()
  -- Scenic backdrop: layered parallax sky + village + Crystal Synth animation
  -- Sky band (top half, dark)
  screen.level(1)
  screen.rect(0, 0, 128, 36); screen.fill()
  -- Far star layer (slow drift)
  for i = 1, 22 do
    local sx = ((i * 19) + (tick // 4)) % 128
    local sy = (i * 5) % 30
    screen.level((i % 7 == 0) and 13 or 6)
    screen.pixel(sx, sy); screen.fill()
  end
  -- Near star layer (faster drift, dimmer — depth cue)
  for i = 1, 14 do
    local sx = ((i * 31) + (tick // 2)) % 128
    local sy = (i * 7 + 2) % 28
    screen.level((i % 5 == 0) and 11 or 4)
    screen.pixel(sx, sy); screen.fill()
  end
  -- Occasional shooting star — fires once per long cycle, traces a 6-px diagonal
  local cycle = tick % 280
  if cycle < 12 then
    local t = cycle
    local sx = 8 + t * 6
    local sy = 4 + t
    screen.level(15); screen.pixel(sx, sy); screen.fill()
    screen.level(11); screen.pixel(sx - 1, sy); screen.pixel(sx, sy - 1)
    screen.pixel(sx - 2, sy); screen.pixel(sx, sy - 2); screen.fill()
  end
  -- Distant moon (top right) with phase crater
  screen.level(11); screen.circle(110, 10, 5); screen.fill()
  screen.level(2); screen.circle(108, 8, 3); screen.fill()
  screen.level(8); screen.pixel(112, 11); screen.pixel(110, 13); screen.fill()
  -- Drifting cloud silhouette (very slow)
  local cdx = (tick // 8) % 160 - 32
  screen.level(2)
  screen.rect(cdx, 14, 18, 2); screen.fill()
  screen.rect(cdx + 4, 12, 10, 2); screen.fill()
  -- Distant mountain silhouette (back)
  screen.level(2)
  screen.move(0, 36)
  screen.line(20, 24); screen.line(36, 32); screen.line(56, 18)
  screen.line(72, 30); screen.line(92, 22); screen.line(112, 34); screen.line(128, 28)
  screen.line(128, 36); screen.line(0, 36); screen.close(); screen.fill()
  -- Mid-mountain ridge (slightly lighter, smaller silhouette)
  screen.level(3)
  screen.move(0, 40)
  screen.line(14, 34); screen.line(30, 38); screen.line(48, 32); screen.line(68, 38)
  screen.line(86, 34); screen.line(108, 38); screen.line(128, 36); screen.line(128, 40); screen.close(); screen.fill()
  -- Foreground hill (lighter)
  screen.level(4)
  screen.move(0, 52); screen.line(28, 44); screen.line(60, 50)
  screen.line(96, 42); screen.line(128, 50); screen.line(128, 64); screen.line(0, 64); screen.close(); screen.fill()
  -- Distant village lights on the foreground hill (window flickers)
  for i = 0, 4 do
    local vx = 20 + i * 22
    local vy = 47 + (i % 2)
    local on = ((tick // 6) + i * 3) % 5 < 4
    screen.level(on and 15 or 9)
    screen.pixel(vx, vy); screen.fill()
  end
  -- Tiny party silhouettes standing on the hill (4 dots — Diegues, Miel, Strom, Alder)
  local hill_y = 51
  screen.level(0)
  screen.rect(46, hill_y, 1, 3); screen.fill()
  screen.rect(50, hill_y - 1, 1, 4); screen.fill()
  screen.rect(54, hill_y, 1, 3); screen.fill()
  screen.rect(58, hill_y - 1, 1, 4); screen.fill()
  screen.level(11); screen.pixel(46, hill_y - 1); screen.pixel(50, hill_y - 2)
  screen.pixel(54, hill_y - 1); screen.pixel(58, hill_y - 2); screen.fill()

  -- ── CRYSTAL SYNTH (centered, animated) ──
  -- Floating crystal: large diamond outline made of 7 facet shards (one per mode)
  local cx, cy = 64, 22
  -- pulsing aura ring
  local pulse = (tick // 3) % 8
  screen.level(13 - pulse)
  screen.circle(cx, cy, 14 + (pulse % 3)); screen.stroke()
  -- inner crystal — large diamond
  screen.level(15)
  screen.move(cx, cy - 12)
  screen.line(cx + 10, cy)
  screen.line(cx, cy + 12)
  screen.line(cx - 10, cy)
  screen.close()
  screen.fill()
  -- inner facet lines (creating 7 wedges)
  screen.level(2)
  screen.move(cx, cy - 12); screen.line(cx, cy + 12); screen.stroke()
  screen.move(cx - 10, cy); screen.line(cx + 10, cy); screen.stroke()
  screen.move(cx - 5, cy - 6); screen.line(cx + 5, cy + 6); screen.stroke()
  screen.move(cx + 5, cy - 6); screen.line(cx - 5, cy + 6); screen.stroke()
  -- bright core
  screen.level(15)
  screen.rect(cx - 1, cy - 1, 3, 3); screen.fill()
  -- floating particles around crystal
  for i = 0, 5 do
    local ang = (tick * 3 + i * 60) % 360
    local rad = ang * 0.01745
    local px = math.floor(cx + math.cos(rad) * 18 + 0.5)
    local py = math.floor(cy + math.sin(rad) * 9 + 0.5)
    screen.level((i % 3 == 0) and 15 or 11)
    screen.pixel(px, py); screen.fill()
  end

  -- ── TITLE TEXT ──
  screen.level(0); screen.move(65, 45); screen.text_center("SYNTH QUEST")
  screen.level(15); screen.move(64, 44); screen.text_center("SYNTH QUEST")

  screen.font_face(25); screen.font_size(6)
  screen.level(8); screen.move(64, 50); screen.text_center("the chord must sing")
  -- New Game / Continue selector
  for i = 0, 1 do
    local label = (i == 0) and "New Game" or "Continue"
    local sel = (TITLE.idx == i)
    local x = 36 + i * 56
    screen.level(sel and 15 or 7)
    screen.move(x, 58)
    screen.text_center((sel and "> " or "  ") .. label)
    if sel then
      screen.level(15)
      screen.move(x, 60)
      screen.line(x + 22, 60); screen.stroke()
    end
  end
  -- Flash (e.g. "no save found")
  if TITLE.flash_ticks > 0 then
    -- (countdown happens on the main clock tick; draw only reads it)
    screen.level(0); screen.rect(28, 53, 72, 9); screen.fill()
    screen.level(15); screen.move(64, 60); screen.text_center(scrub_text(TITLE.flash_text or ""))
  end
  -- Pass 55: flashing "USB Controller Required" only when no controller
  -- is plugged in. Detection priority:
  --   1. `gamepad.is_connected()` if the norns gamepad lib exposes it
  --   2. Any HID gamepad-class device present in `hid.devices`
  --   3. `controller_seen` (set true by any gamepad handler) — fallback
  -- so the banner clears once you press something even on older API.
  local connected = controller_seen
  if not connected and gamepad and type(gamepad.is_connected) == "function" then
    local ok, v = pcall(gamepad.is_connected); if ok and v then connected = true end
  end
  if not connected and hid and hid.devices then
    for _, d in pairs(hid.devices) do
      if d and (d.types and (d.types.gamepad or d.types.joystick)) then connected = true; break end
    end
  end
  if not connected and (tick % 16) < 10 then
    screen.level(0); screen.rect(8, 0, 112, 7); screen.fill()
    screen.level(15); screen.move(64, 6); screen.text_center("keys OK - gamepad optional")
  end
  screen.font_face(1); screen.font_size(8)
end

local function draw_equip()
  if equip_idx > #party then equip_idx = 1 end
  local p = party[equip_idx]
  local list = INST.owned_for(p.class)
  if #list > 0 then
    if equip_choice > #list then equip_choice = #list end
    if equip_choice < 1 then equip_choice = 1 end
  end
  local cur_id = equipped[p.class]
  local cur = INSTRUMENTS[cur_id]
  -- header (left-anchored title + dedicated party-selector slot top-right)
  screen.font_face(25); screen.font_size(6)
  screen.level(15); screen.move(2, 7)
  screen.text("EQUIP - " .. (CHAR_NAME[p.class] or p.class))
  for i = 1, #party do
    local dx = 100 + (i - 1) * 7
    screen.level(i == equip_idx and 15 or 4)
    screen.rect(dx, 4, 3, 3); screen.fill()
  end
  screen.level(3); screen.move(0, 9); screen.line(128, 9); screen.stroke()
  screen.font_face(1); screen.font_size(8)
  -- "portrait" — use the in-game sprite (3x scale + frame) to match the status screen
  local fx, fy, fw, fh = 2, 12, 28, 40
  screen.level(2); screen.rect(fx, fy, fw, fh); screen.fill()
  screen.level(11); screen.rect(fx, fy, fw, fh); screen.stroke()
  local bob = ((tick // 6) % 2)
  local sx = fx + math.floor((fw - 24) / 2)
  local sy = fy + 4 - bob
  SPRITE_BY_CLASS.scaled(p.class, sx, sy, 3)
  -- ── Right column (6px font for tight rows; sprites + text fully separated)
  screen.font_face(25); screen.font_size(6)
  local rx = 36

  -- "Equipped:" header row (no sprite on this row — sprite gets its own line below)
  screen.level(11); screen.move(rx, 14); screen.text("Equipped:")
  -- Sprite + name on a dedicated row so they no longer collide vertically.
  if cur_id and INST.sprites[cur_id] then INST.sprites[cur_id](rx, 16) end
  screen.level(15); screen.move(rx + 11, 22)
  screen.text(cur and cur.name or "-")

  -- "OWNED" header pushed below the equipped block.
  screen.level(6); screen.move(rx, 30); screen.text("OWNED")

  -- 4 rows max, 7px pitch so sprite (8x8) + text on each row never crosses
  -- into the next row's sprite or the delta-preview band.
  for i = 1, math.min(#list, 4) do
    local id = list[i]
    local inst = INSTRUMENTS[id]
    local row_top = 32 + i * 6   -- rows at y=38, 44, 50, 56 (sprite top)
    local sel = (i == equip_choice)
    local eq  = (id == cur_id)
    if INST.sprites[id] then INST.sprites[id](rx, row_top) end
    screen.level(sel and 15 or (eq and 11 or 5))
    screen.move(rx + 11, row_top + 6)
    screen.text((sel and ">" or " ") .. (eq and "*" or " ") .. inst.name)
  end
  if #list == 0 then
    screen.level(5); screen.move(rx, 42); screen.text("(none)")
  end

  -- Stat-delta preview tucked under the portrait (left column, below frame
  -- bottom at y=52). Was at y=56 right side, colliding with the 4th OWNED
  -- row's sprite + text.
  local sel_id = list[equip_choice]
  local sel_inst = sel_id and INSTRUMENTS[sel_id]
  if sel_inst and cur then
    local function fmt(label, v)
      if v == 0 then return label .. ":-" end
      return label .. ":" .. (v > 0 and ("+" .. v) or tostring(v))
    end
    screen.level(9); screen.move(2, 58)
    screen.text(fmt("A", sel_inst.atk - cur.atk) .. " " ..
                fmt("D", sel_inst.def - cur.def) .. " " ..
                fmt("M", sel_inst.mag - cur.mag) .. " " ..
                fmt("S", sel_inst.spd - cur.spd))
  end

  -- Footer hint (page dots are gone — moved to header top-right).
  screen.level(6); screen.move(2, 63); screen.text("E3 char  A/K3 equip  B/K2 back")
  screen.font_face(1); screen.font_size(8)
end

