-- Shop visible items: hide already-owned one-shot instruments. Eastern
-- and northern caravans don't carry instruments — those are luthier
-- crafts only sold in the village shop (map 6). GLOBAL so it can be
-- called from earlier-defined input handlers (Lua local scope rules).
function shop_visible_order()
  local out = {}
  for _, id in ipairs(SHOP.order) do
    local it = SHOP.items[id]
    if it then
      if it.is_instrument then
        if current_map_id == 6 and not instruments_owned[id] then
          out[#out + 1] = id
        end
      else
        out[#out + 1] = id
      end
    end
  end
  return out
end

local function draw_shop()
  -- header bar — title reflects the current shop interior so each region
  -- keeps its identity (Hens / Marek / Skari).
  local titles = {[6] = "HENS' SHOP", [15] = "MAREK'S CARAVAN", [16] = "SKARI'S OUTPOST"}
  screen.level(15)
  screen.move(64, 7)
  screen.text_center(titles[current_map_id] or "ITEM SHOP")
  screen.level(3)
  screen.move(0, 9)
  screen.line(128, 9)
  screen.stroke()
  -- gold balance (right)
  screen.level(11)
  screen.move(126, 7)
  screen.text_right(SHOP.gold .. "g")
  -- items: one row per item, 7px spacing — name | price | own | desc.
  -- Use the filtered visible list so the UI doesn't show consumables we
  -- don't carry or already-bought one-shots.
  screen.font_face(25)
  screen.font_size(6)
  local vis = shop_visible_order()
  if SHOP.idx > #vis then SHOP.idx = math.max(1, #vis) end
  -- Scroll window: 6 rows visible at a time so 10+ items don't overflow.
  local window = 6
  local first = math.max(1, math.min(#vis - window + 1, SHOP.idx - math.floor(window / 2)))
  if first < 1 then first = 1 end
  local last = math.min(#vis, first + window - 1)
  -- Row layout (8px tall to give sprites breathing room):
  --   x=0..7  : 8×8 item sprite
  --   x=10    : caret
  --   x=14    : name (left-aligned)
  --   x=88    : price (right-aligned)
  --   x=126   : owned count / "(new)" tag (right-aligned)
  -- Description for the SELECTED row appears in the footer strip
  -- (replaces the help line), so longer instrument names no longer
  -- collide with desc text.
  local row_h = 7
  for slot = 0, last - first do
    local i = first + slot
    local id = vis[i]
    local it = SHOP.items[id]
    local y_top = 12 + slot * row_h        -- top of sprite cell
    local y_txt = y_top + 6                 -- text baseline
    local sel = (i == SHOP.idx)
    local price = QUESTS.hens.discount and math.floor(it.cost * 0.75) or it.cost
    -- 8×8 item sprite at far left
    if SHOP.sprites[id] then
      SHOP.sprites[id](0, y_top - 1)
    end
    -- selection caret
    screen.level(sel and 15 or 0)
    screen.move(10, y_txt); screen.text(sel and ">" or " ")
    -- name (highlighted when selected)
    screen.level(sel and 15 or 8)
    screen.move(14, y_txt); screen.text(it.name)
    -- price (right-aligned)
    screen.level(sel and 13 or 6)
    screen.move(102, y_txt); screen.text_right(price .. "g")
    -- owned count (right edge)
    screen.level(sel and 11 or 5)
    screen.move(126, y_txt)
    if it.is_instrument then screen.text_right("(new)")
    else screen.text_right("x" .. (SHOP.inv[id] or 0)) end
  end
  -- scroll indicators
  if first > 1 then
    screen.level(8); screen.move(124, 14); screen.text_right("^")
  end
  if last < #vis then
    screen.level(8); screen.move(124, 53); screen.text_right("v")
  end
  screen.font_face(1)
  screen.font_size(8)
  -- flash banner (purchase / not enough gold) — sits just above the help line
  if SHOP.flash_ticks > 0 then
    screen.level(0)
    screen.rect(16, 54, 96, 8)
    screen.fill()
    screen.font_face(25); screen.font_size(6)
    screen.level(15)
    screen.move(64, 60)
    screen.text_center(scrub_text(SHOP.flash_text or ""))
    screen.font_face(1); screen.font_size(8)
  else
    screen.font_face(25); screen.font_size(6)
    -- Selected item description (replaces the row-level desc column).
    local sel_id = vis[SHOP.idx]
    local sel_it = sel_id and SHOP.items[sel_id]
    if sel_it and sel_it.desc then
      screen.level(11); screen.move(64, 56); screen.text_center(sel_it.desc)
    end
    screen.level(6)
    screen.move(2, 62); screen.text("E2/dpad pick  A/K3 buy  B/K2 leave")
    screen.font_face(1); screen.font_size(8)
  end
end

-- ── JAM MODE ──────────────────────────────────────────────────────────────
-- Single-screen synth-jam dashboard. Shows all 4 voices' effect parameters
-- (cutoff / resonance / wet / delay) as bars; sticks edit the active voice;
-- L1/R1 cycle voice; SELECT or B exits back to the prior state.
-- pretty 14×14 stick visualizer with crosshair, range ring, and a glowing dot
ANIM.draw_stick_big = function(box_x, box_y, nx, ny, label)
  -- subtle range ring (octagon outline)
  screen.level(2)
  screen.rect(box_x, box_y, 14, 14); screen.stroke()
  -- crosshair lines
  screen.level(4)
  screen.move(box_x, box_y + 7); screen.line(box_x + 14, box_y + 7); screen.stroke()
  screen.move(box_x + 7, box_y); screen.line(box_x + 7, box_y + 14); screen.stroke()
  -- center dot (rest position)
  screen.level(3)
  screen.pixel(box_x + 7, box_y + 7); screen.fill()
  -- stick dot with halo
  local dx = math.floor(box_x + 7 + (nx or 0) * 6 + 0.5)
  local dy = math.floor(box_y + 7 + (ny or 0) * 6 + 0.5)
  screen.level(8)
  screen.pixel(dx - 1, dy); screen.pixel(dx + 1, dy)
  screen.pixel(dx, dy - 1); screen.pixel(dx, dy + 1); screen.fill()
  screen.level(15)
  screen.rect(dx, dy, 2, 2); screen.fill()
  -- label below
  if label then
    screen.font_face(25); screen.font_size(6)
    screen.level(7)
    screen.move(box_x + 7, box_y + 21); screen.text_center(label)
    screen.font_face(1); screen.font_size(8)
  end
end

-- Map JAM.root semitone offset to a note-name label (A is the home key).
local function jam_root_label()
  local n = ((JAM.root or 0) % 12 + 12) % 12
  local octv = math.floor((JAM.root or 0) / 12)
  return JAM.note_names[n + 1] .. (octv ~= 0 and (octv > 0 and ("+" .. octv) or tostring(octv)) or "")
end

local function draw_jam()
  -- header
  screen.font_face(25); screen.font_size(6)
  screen.level(15); screen.move(2, 6); screen.text("JAM MODE")
  -- L2 indicator (BPM-edit mode armed)
  if l2_held then
    screen.level(0); screen.rect(50, 0, 22, 9); screen.fill()
    screen.level(15); screen.move(52, 6); screen.text("L2:BPM")
  end
  local ap = party[active]
  if ap then
    screen.level(11)
    screen.move(126, 6); screen.text_right(CHAR_NAME[ap.class])
  end
  screen.level(3)
  screen.move(0, 9); screen.line(128, 9); screen.stroke()
  -- 4 voice columns, 32px wide each — top section (rows 11-44).
  -- Each column tops with the character's animated 8x8 sprite "jamming" its
  -- instrument: a 1-px talk-bob + a flickering note-dot above the sprite.
  local saved_facing = player.facing
  player.facing = "down"
  for i, p in ipairs(party) do
    local cx = (i - 1) * 32
    local act = (i == active)
    if act then
      screen.level(2)
      screen.rect(cx, 11, 32, 33); screen.fill()
    end
    -- jamming sprite (centered horizontally in the column, top of the panel)
    local fn = SPRITE_BY_CLASS[p.class]
    if fn then
      local bob = ((tick + i * 3) % 6 < 3) and 0 or 1
      fn(cx + 12, 11 - bob)
      -- note flicker above the sprite (suggests they're playing)
      if ((tick + i * 5) % 8) < 4 then
        screen.level(15); screen.pixel(cx + 22, 12 - bob); screen.fill()
      else
        screen.level(11); screen.pixel(cx + 9,  13 - bob); screen.fill()
      end
    end
    -- 4 horizontal bars: cutoff / resonance / wet / delay
    local labels = {"CUT", "RES", "WET", "DLY"}
    local r = CUTOFF_RANGE[p.class]
    local norm = {
      math.log(p.cutoff / r.min) / math.log(r.max / r.min),
      ((p.resonance or 0.05) - 0.05) / 0.45,
      p.xwet or 0,
      p.dly or 0,
    }
    for j = 1, 4 do
      local y = 24 + (j - 1) * 5
      local v = math.max(0, math.min(1, norm[j] or 0))
      screen.level(act and 11 or 7)
      screen.move(cx + 2, y); screen.text(labels[j])
      screen.level(2); screen.rect(cx + 16, y - 3, 14, 1); screen.fill()
      screen.level(act and 15 or 8)
      screen.rect(cx + 16, y - 3, math.floor(14 * v + 0.5), 1); screen.fill()
    end
  end
  player.facing = saved_facing
  -- divider
  screen.level(3)
  screen.move(0, 45); screen.line(128, 45); screen.stroke()
  -- bottom section (rows 46-63): global params + bigger stick visualizers
  -- Global params (left)
  screen.level(11); screen.move(2, 51); screen.text("BPM")
  screen.level(15); screen.move(22, 51); screen.text(tostring(BATTLE_BPM))
  screen.level(11); screen.move(2, 58); screen.text("ROOT")
  screen.level(15); screen.move(26, 58); screen.text(jam_root_label())
  -- Mode (current scale) at footer-left, A to cycle through unlocked modes
  screen.level(11); screen.move(2, 63); screen.text("MODE")
  screen.level(15); screen.move(26, 63); screen.text(JAM.mode:upper())
  -- Stick visualizers (only shown in debug mode — kept the jam UI cluttered).
  if debug_visible then
    local lx, ly, rx, ry = 0, 0, 0, 0
    if ap and ap.stick then
      lx, ly, rx, ry = ap.stick.lx, ap.stick.ly, ap.stick.rx, ap.stick.ry
    end
    ANIM.draw_stick_big(60, 47, lx, ly, "L")
    ANIM.draw_stick_big(80, 47, rx, ry, "R")
  end
  -- footer hints (size 5 for tighter footprint than the rest of the UI)
  screen.font_size(5)
  screen.level(6)
  if l2_held then
    screen.move(126, 51); screen.text_right("L2 dpadLR=BPM")
  else
    screen.move(126, 51); screen.text_right("UD/E2 scale LR/E3 root")
  end
  -- ("A latch" dropped from the hint — it collided with the ROOT value;
  -- A-latch stays documented in the README.)
  screen.move(126, 57); screen.text_right("L1/R1 voice X mode")
  -- Scale-locked zones (castle raid etc.) ignore the mode on exit —
  -- say so, or mode-cycling there reads as broken. Shares the y=63
  -- footer row with the exit hint (same anchor — draw one string, not
  -- two overlapping ones).
  local zone_locked = OW_THEMES and current_theme and OW_THEMES[current_theme]
    and OW_THEMES[current_theme].scale
  -- Both variants kept to <=13 chars so they clear the MODE value
  -- (MIXOLYDIAN ends ~x=75; 13 chars at size 5 start at ~x=73).
  screen.move(126, 63)
  screen.text_right(zone_locked and "LOCKED - B/K2" or "B/K2 exit")
  screen.font_face(1); screen.font_size(8)
end

-- UI is intentionally global (saves a `local` slot — we're at the 200-cap).
UI = {}
-- Quest journal: 2-page paginated. L1/R1 flips pages.
--   Page 1: MAIN — shard count, recruits, prologue.
--   Page 2: SIDES — Hens, Brann, Tova.
-- Page state lives on UI.quests_page (defaults to 1).
UI.draw_quests = function()
  UI.quests_page = UI.quests_page or 1
  screen.font_face(25); screen.font_size(6)
  screen.level(15); screen.move(64, 7); screen.text_center("QUEST JOURNAL")
  screen.level(3); screen.move(0, 9); screen.line(128, 9); screen.stroke()
  -- pagination indicator (top-right): 1/2 or 2/2
  screen.level(8); screen.move(126, 7); screen.text_right(UI.quests_page .. "/2")

  if UI.quests_page == 1 then
    -- ── MAIN QUESTS ──
    -- Crystal Synth (shards)
    local n = 0; for _, v in pairs(shards or {}) do if v then n = n + 1 end end
    screen.level(11); screen.move(2, 17); screen.text("Crystal Synth")
    local lev = (n >= 7) and 11 or 15
    screen.level(lev); screen.move(2, 23); screen.text(n .. "/7 shards recovered")

    -- Companions — anyone who has ever joined stays lit, benched or not
    -- (reserve members live in CHARACTERS); joined recruits are appended.
    screen.level(11); screen.move(2, 31); screen.text("Companions")
    local roster = {"cleric", "bard", "warrior", "mage"}
    for _, r in ipairs((CONTENT and CONTENT.recruits) or {}) do
      if r.joined then roster[#roster + 1] = r.class end
    end
    local wide = #roster > 5
    local got = 0
    local x = 2
    for _, cls in ipairs(roster) do
      local joined = (class_in_party and class_in_party(cls))
        or (CHARACTERS and CHARACTERS[cls] and CHARACTERS[cls].ever_joined)
      if joined then got = got + 1 end
      screen.level(joined and 11 or 4)
      screen.move(x, 37)
      screen.text((CHAR_NAME[cls] or cls):sub(1, wide and 3 or 4))
      x = x + (wide and 13 or 22)
    end
    screen.level(8); screen.move(126, 37); screen.text_right(got .. "/" .. #roster)

    -- Caves cleared
    local cleared = 0
    for i = 1, 7 do if cave_state[i] and cave_state[i].cleared then cleared = cleared + 1 end end
    screen.level(11); screen.move(2, 45); screen.text("Caves cleared")
    screen.level(cleared >= 7 and 11 or 15)
    screen.move(2, 51); screen.text(cleared .. "/7 sealed")

    -- Prologue / endgame state hint
    if CONTENT.endgame_done then
      screen.level(11); screen.move(2, 57); screen.text("* the song is whole *")
    elseif n >= 7 then
      screen.level(15); screen.move(2, 57); screen.text("the synth is calling.")
    elseif (CONTENT.prologue_state or "") == "complete" then
      screen.level(8); screen.move(2, 57); screen.text("escaped the castle.")
    end
  else
    -- ── SIDE QUESTS ──
    -- Four quests at an 11-px entry pitch (label + status 6 px apart);
    -- last status baseline y=54 clears the y=62 footer glyphs.
    -- Hens
    do
      local q = QUESTS.hens
      local status, lev
      if q.discount then status, lev = "DONE  shop -25%", 11
      else status, lev = q.wins .. "/" .. q.target .. " road wins", 15 end
      screen.level(11); screen.move(2, 15); screen.text("Hens (Shopkeep)")
      screen.level(lev); screen.move(2, 21); screen.text(status)
    end
    -- Brann
    do
      local q = QUESTS.brann
      local status, lev
      if q.claimed then status, lev = "DONE  +200g, +1 Star", 11
      else status, lev = q.wins .. "/" .. q.target .. " road wins", 15 end
      screen.level(11); screen.move(2, 26); screen.text("Brann (Smith)")
      screen.level(lev); screen.move(2, 32); screen.text(status)
    end
    -- Tova
    do
      local s = QUESTS.tova.spoke
      local visited = (s.Veris and 1 or 0) + (s.Aurin and 1 or 0)
                    + (s.Mira and 1 or 0) + (s.Iolen and 1 or 0)
      local status, lev
      if QUESTS.tova.claimed then status, lev = "DONE  +80g + lore", 11
      else status, lev = visited .. "/4 sages met", 15 end
      screen.level(11); screen.move(2, 37); screen.text("Tova (Sage)")
      screen.level(lev); screen.move(2, 43); screen.text(status)
    end
    -- Pith (cartographer — report back with 3+ caves cleared)
    do
      local q = QUESTS.pith
      -- Mirror Pith's own dialogue logic, which counts caves 1-5.
      local cleared = 0
      for i = 1, 5 do
        if cave_state[i] and cave_state[i].cleared then cleared = cleared + 1 end
      end
      local status, lev
      if q.claimed then status, lev = "DONE  +100g, +1 Tonic", 11
      else status, lev = cleared .. "/" .. q.target .. " caves logged", 15 end
      screen.level(11); screen.move(2, 48); screen.text("Pith's report")
      screen.level(lev); screen.move(2, 54); screen.text(status)
    end
  end

  screen.level(6); screen.move(2, 62);   screen.text("L1/R1/K3 page")
  screen.level(6); screen.move(126, 62); screen.text_right("B/K2 back")
  screen.font_face(1); screen.font_size(8)
end

-- Overworld map: renders the current map at low resolution with the
-- player position highlighted. Useful for orientation in the wider
-- regions (Mainland is 64×16 — easy to lose your bearings).
UI.draw_map = function()
  screen.font_face(25); screen.font_size(6)
  -- header
  local region_name = ({[1]="Modalia",  [2]="Eastern Reaches", [3]="Northern Wilds",
                        [22]="Western Region", [23]="Lirael Ruins",
                        [24]="Velthe's Observatory", [26]="Far Hills"})[current_map_id]
                      or ("Map " .. tostring(current_map_id))
  screen.level(15); screen.move(64, 7); screen.text_center(region_name)
  screen.level(3); screen.move(0, 9); screen.line(128, 9); screen.stroke()

  -- Compute scale so the whole map fits in the (124×42) drawing area.
  local area_x, area_y, area_w, area_h = 2, 12, 124, 42
  local scale = math.min(area_w / MAP_W, area_h / MAP_H)
  scale = math.max(1, math.floor(scale))   -- integer scale, min 1
  local draw_w = MAP_W * scale
  local draw_h = MAP_H * scale
  local ox = area_x + math.floor((area_w - draw_w) / 2)
  local oy = area_y + math.floor((area_h - draw_h) / 2)

  -- Render every tile.
  for ty = 1, MAP_H do
    for tx = 1, MAP_W do
      local t = tile_at(tx, ty)
      local lev
      if t == 0 or t == 23 then lev = 6                     -- grass / floor
      elseif t == 1 or t == 4 then lev = 2                  -- tree / wall
      elseif t == 2 or t == 45 then lev = 11                -- path / pier
      elseif t == 3 then lev = 5                            -- water
      elseif t == 5 or t == 47 or t == 48 or t == 49        -- doors / arches
          or t == 50 or t == 51 or t == 52 or t == 56
          or t == 113 then lev = 13                         -- cottages read as doors
      elseif t == 8 then lev = 9                            -- sand
      elseif t >= 6 and t <= 14 then lev = 7                -- cave / floor variants
      else lev = 4
      end
      screen.level(lev)
      screen.rect(ox + (tx - 1) * scale, oy + (ty - 1) * scale, scale, scale)
      screen.fill()
    end
  end

  -- Player position marker — blinking 2×2 bright dot (or +scale-square at small scales).
  local px = ox + (player.x - 1) * scale
  local py = oy + (player.y - 1) * scale
  local sz = math.max(2, scale)
  if (tick % 12) < 8 then
    screen.level(15)
    screen.rect(px, py, sz, sz); screen.fill()
    -- crosshair extending 1 pixel each side so it's findable on dense maps
    screen.pixel(px - 1, py); screen.pixel(px + sz, py); screen.fill()
    screen.pixel(px, py - 1); screen.pixel(px, py + sz); screen.fill()
  end

  -- Footer: position + region hint
  screen.level(8); screen.move(2, 62); screen.text("(" .. player.x .. "," .. player.y .. ")")
  screen.level(6); screen.move(126, 62); screen.text_right("B/K2 back")
  screen.font_face(1); screen.font_size(8)
end

-- Achievements: a paginated list of milestones. Locked entries show
-- a dim "? name"; unlocked show "* name" in bright. Counter at the top.
UI.draw_achievements = function()
  screen.font_face(25); screen.font_size(6)
  screen.level(15); screen.move(64, 7); screen.text_center("ACHIEVEMENTS")
  screen.level(3); screen.move(0, 9); screen.line(128, 9); screen.stroke()
  CONTENT.achievements = CONTENT.achievements or {}
  local unlocked = 0
  for _, def in ipairs(ACHIEVEMENT_DEFS) do
    if CONTENT.achievements[def.id] then unlocked = unlocked + 1 end
  end
  screen.level(11); screen.move(126, 7)
  screen.text_right(unlocked .. "/" .. #ACHIEVEMENT_DEFS)

  -- Each entry: bright if unlocked, dim hint/"?" if locked. Two balanced
  -- columns of ceil(n/2) rows so every entry renders (the old fixed 7/6
  -- split silently dropped entries past 13). Row pitch shrinks to 6 px
  -- once a column exceeds 7 rows so the last row clears the y=62 footer.
  local n_defs = #ACHIEVEMENT_DEFS
  local rows = math.ceil(n_defs / 2)
  local pitch = (rows > 7) and 6 or 7
  -- Both columns render the achievement NAME (never the hint -- hints are
  -- long and clipped at the ~62px column width): unlocked = bright "* name",
  -- locked = dim "? name". Names elide to 12 chars (B1 policy) to fit.
  for i = 1, rows do
    local def = ACHIEVEMENT_DEFS[i]
    local y = 14 + (i - 1) * pitch
    local got = CONTENT.achievements[def.id]
    local nm = def.name
    if #nm > 12 then nm = nm:sub(1, 11) .. "." end
    screen.level(got and 15 or 4)
    screen.move(2, y); screen.text((got and "* " or "? ") .. nm)
  end
  -- second column
  for i = rows + 1, n_defs do
    local def = ACHIEVEMENT_DEFS[i]
    local y = 14 + (i - rows - 1) * pitch
    local got = CONTENT.achievements[def.id]
    local nm = def.name
    if #nm > 12 then nm = nm:sub(1, 11) .. "." end
    screen.level(got and 15 or 4)
    screen.move(70, y); screen.text((got and "* " or "? ") .. nm)
  end
  screen.level(6); screen.move(126, 62); screen.text_right("B/K2 back")
  screen.font_face(1); screen.font_size(8)
end

-- Endgame credits roll. Triggered after start_endgame_scene completes.
-- Slow vertical scroll of the credits text. Press A to advance to the
-- "PRESS A FOR NEW GAME +" prompt; press A again from the prompt to
-- enter NG+ (resets shards/cave clears, retains levels/instruments/gold).
UI.draw_credits = function()
  screen.level(0); screen.rect(0, 0, 128, 64); screen.fill()
  local age = tick - (CONTENT.credits_t or tick)
  -- The roll spans ~600 ticks before the NG+ prompt becomes available.
  local PROMPT_AT = 600
  local lines = {
    "* THE CHORD IS WHOLE *",
    "",
    "a synth quest",
    "",
    "for the white norns",
    "",
    "music & code: lil om",
    "engine: synth quest",
    "framework: norns",
    "",
    "with thanks to",
    "monome  /  tehn",
    "the dust community",
    "",
    "and to whoever",
    "kept the chord",
    "alive in the dark.",
    "",
    "*",
  }
  -- Scroll: y starts at 64 (just below screen) and rises.
  local y0 = 64 - math.floor(age * 0.18)
  screen.font_face(25); screen.font_size(6)
  for i, line in ipairs(lines) do
    local y = y0 + (i - 1) * 9
    if y > -8 and y < 64 then
      screen.level((i == 1 or i == 19) and 15 or 11)
      screen.move(64, y); screen.text_center(line)
    end
  end
  screen.font_face(1); screen.font_size(8)
  -- NG+ prompt — fades in after PROMPT_AT ticks.
  if age > PROMPT_AT then
    local lev = math.min(15, math.floor((age - PROMPT_AT) * 0.20))
    screen.level(0); screen.rect(0, 50, 128, 14); screen.fill()
    screen.font_face(25); screen.font_size(6)
    screen.level(lev); screen.move(64, 60)
    screen.text_center("A/K3: NG+   B/K2: title")
    screen.font_face(1); screen.font_size(8)
  end
end

UI.draw_shards = function()
  -- Visual constellation of the 7 shards arranged around a central circle.
  -- Lit when collected, dim with diamond outline when not.
  screen.font_face(25); screen.font_size(6)
  screen.level(15); screen.move(64, 7); screen.text_center("CRYSTAL SYNTH")
  screen.level(3); screen.move(0, 9); screen.line(128, 9); screen.stroke()
  -- centre
  local cx, cy = 64, 36
  local r = 18
  local order = {"lydian", "dorian", "mixolydian", "phrygian", "aeolian", "locrian", "ionian"}
  local n = 0
  -- Draw a subtle outer ring connecting collected shards
  screen.level(2); screen.circle(cx, cy, r); screen.stroke()
  -- Each shard at an angle around the circle
  for i, name in ipairs(order) do
    local ang = -math.pi / 2 + (i - 1) * (2 * math.pi / 7)  -- start at top
    local sx = cx + math.cos(ang) * r
    local sy = cy + math.sin(ang) * r
    local got = shards[name]
    if got then n = n + 1 end
    -- shard glyph: small diamond
    screen.level(got and 15 or 4)
    screen.move(sx, sy - 3); screen.line(sx + 3, sy)
    screen.line(sx, sy + 3); screen.line(sx - 3, sy); screen.close()
    if got then screen.fill() else screen.stroke() end
    -- short label
    screen.level(got and 11 or 3)
    local lx = cx + math.cos(ang) * (r + 8)
    local ly = cy + math.sin(ang) * (r + 8) + 2
    screen.move(math.floor(lx), math.floor(ly))
    screen.text_center(name:sub(1, 3):upper())
  end
  -- Highlight the currently-tuned JAM mode: a pulsing ring around its
  -- shard so the player can see which mode they're playing in (it drives
  -- battle weak/resist). Only when that mode is actually collected.
  for i, name in ipairs(order) do
    if name == JAM.mode and shards[name] then
      local ang = -math.pi / 2 + (i - 1) * (2 * math.pi / 7)
      local sx = cx + math.cos(ang) * r
      local sy = cy + math.sin(ang) * r
      screen.level((tick % 16) < 8 and 15 or 9)
      screen.circle(math.floor(sx), math.floor(sy), 5); screen.stroke()
    end
  end
  -- centre core (brightens with progress)
  screen.level(math.min(15, 2 + n * 2))
  screen.rect(cx - 1, cy - 1, 3, 3); screen.fill()
  -- count + currently-tuned mode
  screen.level(11)
  screen.move(64, 54); screen.text_center(n .. " / 7 shards collected")
  do
    local MODE_LBL = {pentatonic="Pentatonic", lydian="Lydian", dorian="Dorian",
                      mixolydian="Mixolydian", phrygian="Phrygian", aeolian="Aeolian",
                      locrian="Locrian", ionian="Ionian"}
    screen.level(7); screen.move(64, 61)
    screen.text_center("tuned: " .. (MODE_LBL[JAM.mode] or JAM.mode or "?"))
  end
  screen.level(6); screen.move(126, 62); screen.text_right("B/K2 back")
  screen.font_face(1); screen.font_size(8)
end

