UI.draw_bestiary = function()
  screen.font_face(25); screen.font_size(6)
  screen.level(15); screen.move(64, 7); screen.text_center("BESTIARY")
  screen.level(3); screen.move(0, 9); screen.line(128, 9); screen.stroke()
  -- collect entries into a stable order (keep the table key on each
  -- entry: rares are name-keyed, so key ~= visual identifies them)
  local list = {}
  for k, e in pairs(CONTENT.bestiary) do e.key = k; list[#list+1] = e end
  -- name tiebreaker so equal-HP entries don't swap order between redraws
  table.sort(list, function(a, b)
    local ah, bh = (a.hp_max or 0), (b.hp_max or 0)
    if ah ~= bh then return ah < bh end
    return (a.name or "") < (b.name or "")
  end)
  if #list == 0 then
    screen.level(7); screen.move(64, 36); screen.text_center("(no defeated foes yet)")
    screen.level(6); screen.move(126, 62); screen.text_right("B/K2 back")
    screen.font_face(1); screen.font_size(8)
    return
  end
  local total = #list
  CONTENT.bestiary_idx = math.max(1, math.min(total, CONTENT.bestiary_idx or 1))
  local sel = CONTENT.bestiary_idx
  local cur = list[sel]
  local lore = BESTIARY_LORE[cur.visual or cur.name] or {"(no lore yet.)", ""}
  -- Rare (name-keyed) entries reuse the base monster's lore — flag them
  -- as the greater strain: marker becomes line 1, base line 1 follows,
  -- and the voice/sound-design note (lore[3]) is kept for the detail row.
  if cur.key and cur.visual and cur.key ~= cur.visual then
    lore = {"(a rare, greater strain.)", lore[1], lore[3]}
  end

  if CONTENT.bestiary_detail then
    -- ── DETAIL VIEW: name strip + sprite center + stats + lore ──
    -- name strip
    screen.level(15); screen.move(64, 15); screen.text_center(cur.name)
    -- enemy sprite drawn via DRAW_ENEMY (these funcs draw around a center
    -- point with class-typical dimensions; most fit comfortably here).
    local fn = DRAW_ENEMY[cur.visual or "slime"] or DRAW_ENEMY.slime
    pcall(fn, 64, 30)
    -- compact stats row below the sprite
    screen.level(3); screen.move(0, 44); screen.line(128, 44); screen.stroke()
    screen.level(11); screen.move(2, 50);  screen.text("HP " .. (cur.hp_max or 0))
    screen.level(11); screen.move(36, 50); screen.text("AT " .. (cur.atk or 0))
    -- elemental weak/resist mode (right side) — tactical reference for
    -- which JAM mode to play against this foe. 3-letter mode abbrevs.
    do
      local ABBR = {lydian="Lyd", dorian="Dor", mixolydian="Mix", phrygian="Phr",
                    aeolian="Aeo", locrian="Loc", ionian="Ion"}
      local aff = ELEMENTAL_AFFINITY[cur.visual or ""]
      if aff then
        screen.level(13); screen.move(126, 50)
        screen.text_right("WK:" .. (ABBR[aff.weak] or "?") .. " RS:" .. (ABBR[aff.resist] or "?"))
      else
        -- No affinity entry (firstchord/silencer): show the sound-design
        -- note instead, clipped to ~16 chars so it clears the AT column.
        local note = lore[3] or ""
        if #note > 16 then note = note:sub(1, 16) end
        screen.level(7); screen.move(126, 50); screen.text_right(note)
      end
    end
    -- lore (2 compact lines, clipped to the ~28-char row width)
    local function clip28(s)
      s = s or ""
      if #s > 28 then s = s:sub(1, 28) .. ".." end
      return s
    end
    screen.level(13); screen.move(2, 56); screen.text(clip28(lore[1]))
    screen.level(13); screen.move(2, 62); screen.text(clip28(lore[2]))
    screen.level(6); screen.move(126, 62); screen.text_right("B/K2 back")
    screen.font_face(1); screen.font_size(8)
    return
  end

  -- ── LIST VIEW: 4 entries + selected lore at bottom ──
  screen.level(7); screen.move(126, 16); screen.text_right(sel .. "/" .. total)
  local view_start = math.max(1, sel - 1)
  if view_start + 3 > total then view_start = math.max(1, total - 3) end
  for i = 0, math.min(3, total - 1) do
    local idx = view_start + i
    local e = list[idx]
    local y = 18 + i * 7
    local is_sel = (idx == sel)
    screen.level(is_sel and 15 or 0)
    screen.move(2, y + 5); screen.text(is_sel and ">" or " ")
    local nm = e.name or "?"
    if #nm > 12 then nm = nm:sub(1, 11) .. "." end  -- clear the HP col at x=74
    screen.level(is_sel and 15 or 8); screen.move(8, y + 5); screen.text(nm)
    screen.level(is_sel and 13 or 6); screen.move(74, y + 5); screen.text("HP " .. (e.hp_max or 0))
    screen.level(is_sel and 13 or 6); screen.move(102, y + 5); screen.text("AT " .. (e.atk or 0))
  end
  -- Single lore line in list view (line 2 lives in the detail view) so
  -- the y=62 footer is free for hints without text collisions.
  screen.level(3); screen.move(0, 50); screen.line(128, 50); screen.stroke()
  do
    local l1 = lore[1] or ""
    if #l1 > 28 then l1 = l1:sub(1, 28) .. ".." end
    screen.level(11); screen.move(2, 57); screen.text(l1)
  end
  screen.level(6); screen.move(2, 63); screen.text("A/K3 view")
  screen.level(6); screen.move(126, 63); screen.text_right("B/K2 back")
  screen.font_face(1); screen.font_size(8)
end

-- Items menu: selectable list. dpad Y / E2 scrolls; A uses the selected
-- item out-of-battle (heals/MP/revive/buff/etc); B/START returns. Globals
-- kept in CONTENT to dodge the 200-locals cap.
ITEMS_ORDER = {"salve", "vial", "ether", "star", "tonic", "key"}
ITEMS_INFO = {
  salve = {name="Salve", desc="+35 HP party"},
  vial  = {name="Vial",  desc="+10 MP party"},
  ether = {name="Ether", desc="+25 MP party"},
  star  = {name="Star",  desc="Revive KO'd"},
  tonic = {name="Tonic", desc="+ATK 1 fight"},
  key   = {name="Key",   desc="Open lock"},
}

-- Trophy / key-item ledger. These all live in `instruments_owned` (or a
-- bespoke flag) and are NOT class-equippable, so they don't surface in
-- the EQUIP screen. Listed here so the KEY tab on the items menu can
-- show them with sprite + flavor desc. Order is canonical (acquisition
-- order through the story).
TROPHY_ORDER = {
  "tisa_bell",
  "arams_token",
  "velthes_letter",
  "sightings_lens",
  "lirael_captains_insignia",
  "key_of_lirael",
  "iolas_letter",
}
TROPHY_INFO = {
  tisa_bell        = { name="Tisa's Bell",            desc="Cave 1 echo-chamber resonance" },
  arams_token      = { name="Aram's Token",           desc="iron disc; Strom's keep" },
  velthes_letter   = { name="Velthe's Letter",        desc="opened letter, Velthe's hand" },
  sightings_lens   = { name="Sightings Lens",         desc="Velthe's brass scope" },
  lirael_captains_insignia = { name="Captain's Insignia", desc="iron pin in Lirael blue" },
  key_of_lirael    = { name="Key of Lirael",          desc="opens the Ice Grotto" },
  iolas_letter     = { name="Iola's Letter",          desc="Iola's farewell, in her hand" },
}
-- Resolve whether the player currently has a given trophy id. Most live
-- on `instruments_owned`; a few are pure flags.
function has_trophy(id)
  if id == "tisa_bell"    then return CONTENT.resonances and CONTENT.resonances.ring and CONTENT.resonances.ring.item or false end
  if id == "iolas_letter" then return flag and flag.iolas_letter_received or false end
  return instruments_owned and instruments_owned[id] or false
end

-- Items-menu tab labels. Index drives CONTENT.items_tab.
ITEM_TABS = { "USE", "GEAR", "KEY", "SHARDS" }

-- Tiny SFX layer for menu item use. Each item gets its own short chime
-- trig'd on the bard or cleric voice; honors the live combat_reverb_mix.
-- Global (no `local`) to dodge the 200-main-chunk-locals cap.
function items_play_sfx(id)
  local crm = CONTENT.combat_reverb_mix or 1.0
  local function chime(voice, midi, vel, atk, rel, wet)
    local f = midi_to_freq(snap_note_to_scale(midi))
    local w = math.min(1, (wet or 0.4) * crm)
    if engine["trig_" .. voice] then
      engine["trig_" .. voice](f, vel, atk, rel, w)
    end
  end
  if id == "salve" then
    chime("cleric", 76, 0.55, 0.04, 1.20, 0.55)   -- warm rising heal pad
    chime("bard",   83, 0.45, 0.005, 0.50, 0.65)
  elseif id == "vial" then
    chime("bard",   79, 0.50, 0.003, 0.35, 0.55)  -- bright single chime
  elseif id == "ether" then
    chime("bard",   79, 0.55, 0.003, 0.45, 0.60)  -- richer ether chime
    chime("cleric", 67, 0.40, 0.06,  1.50, 0.65)
  elseif id == "star" then
    -- Triumphant 3-note revive arpeggio (like a level-up but smaller)
    local notes = {72, 76, 79}
    for k, m in ipairs(notes) do
      clock.run(function()
        clock.sleep((k - 1) * 0.07)
        chime("bard", m, 0.65, 0.003, 0.55, 0.60)
      end)
    end
  elseif id == "tonic" then
    chime("warrior", 48, 0.70, 0.005, 0.45, 0.20)  -- low confident thrum
  elseif id == "key" then
    chime("warrior", 36, 0.45, 0.005, 0.18, 0.10)  -- dim refusal click
  end
end

function items_use_selected()
  local id = ITEMS_ORDER[CONTENT.items_idx or 1]
  if not id then return end
  local inv = SHOP.inv
  if (inv[id] or 0) <= 0 then
    CONTENT.items_flash = "(none left)"
    CONTENT.items_flash_ticks = 30
    -- Soft refusal blip — via sq_trig so octave shift + MIDI-out apply
    if engine.trig_warrior then
      sq_trig("warrior", midi_to_freq(snap_note_to_scale(36)), 0.30, 0.005, 0.10, 0.05)
    end
    return
  end
  local msg
  if id == "salve" then
    inv.salve = inv.salve - 1
    for _, q in ipairs(party) do
      if q.alive then q.hp = math.min(q.hp_max, q.hp + 35) end
    end
    msg = "+35 HP party"
  elseif id == "vial" then
    inv.vial = inv.vial - 1
    for _, q in ipairs(party) do
      if q.alive then q.mp = math.min(q.mp_max, q.mp + 10) end
    end
    msg = "+10 MP party"
  elseif id == "ether" then
    inv.ether = inv.ether - 1
    for _, q in ipairs(party) do
      if q.alive then q.mp = math.min(q.mp_max, q.mp + 25) end
    end
    msg = "+25 MP party"
  elseif id == "star" then
    local target
    for _, q in ipairs(party) do
      if not q.alive then target = q; break end
    end
    if not target then
      CONTENT.items_flash = "no one needs reviving"
      CONTENT.items_flash_ticks = 30
      return
    end
    inv.star = inv.star - 1
    target.alive = true
    target.hp = target.hp_max
    msg = "Revived " .. (CHAR_NAME[target.class] or target.class)
  elseif id == "tonic" then
    inv.tonic = inv.tonic - 1
    for _, q in ipairs(party) do
      if q.alive then q.tonic_ticks = 999 end
    end
    msg = "ATK up next fight"
  elseif id == "key" then
    CONTENT.items_flash = "Keys open locked chests"
    CONTENT.items_flash_ticks = 36
    items_play_sfx("key")
    return
  end
  items_play_sfx(id)
  CONTENT.items_flash = msg or ""
  CONTENT.items_flash_ticks = 30
end

-- A-button dispatcher for the items menu. USE tab consumes; GEAR tab
-- equips the highlighted instrument onto its class; KEY/SHARDS are
-- review-only. Global so the early-defined input handlers can reach it.
function items_action_selected()
  local tab = CONTENT.items_tab or 1
  if tab == 1 then
    items_use_selected()
  elseif tab == 2 then
    local rows = items_rows_for_tab(2)
    local r = rows[CONTENT.items_idx or 1]
    if not r then return end
    local inst = INSTRUMENTS[r.id]
    if not inst then return end
    if equipped[inst.class] == r.id then
      CONTENT.items_flash = "already equipped"
      CONTENT.items_flash_ticks = 24
    else
      equipped[inst.class] = r.id
      CONTENT.items_flash = "equipped " .. (inst.name or "")
      CONTENT.items_flash_ticks = 30
      if items_play_sfx then items_play_sfx("tonic") end
    end
  end
  -- KEY / SHARDS: A is a no-op (review only).
end

-- Build the row list for the currently active tab. Returns an array of
-- {id, name, sprite, count_str, desc, dim} so the draw loop is uniform
-- across categories. `dim` is true for entries not yet acquired.
function items_rows_for_tab(tab_idx)
  local rows = {}
  if tab_idx == 1 then
    for _, id in ipairs(ITEMS_ORDER) do
      local info = ITEMS_INFO[id]
      local count = SHOP.inv[id] or 0
      rows[#rows + 1] = {
        id = id, name = info.name, desc = info.desc,
        count_str = "x" .. count,
        sprite = (SHOP.sprites and SHOP.sprites[id]) or nil,
        dim = (count <= 0),
      }
    end
  elseif tab_idx == 2 then
    local CLASS_ABBR  = {bard="BRD", cleric="CLR", warrior="WAR", mage="MAG",
                         engineer="ENG", mathwiz="MTH", drummer="DRM", wraith="ECH"}
    local CLASS_ORDER = {"bard", "cleric", "warrior", "mage",
                         "engineer", "mathwiz", "drummer", "wraith"}
    -- Stable listing: pairs() hash order shuffled rows between sessions.
    local ids = {}
    for id in pairs(INSTRUMENTS) do ids[#ids + 1] = id end
    table.sort(ids)
    for _, cls in ipairs(CLASS_ORDER) do
      for _, id in ipairs(ids) do
        local inst = INSTRUMENTS[id]
        if inst.class == cls and instruments_owned[id] then
          local equipped_mark = (equipped[cls] == id) and "*" or " "
          rows[#rows + 1] = {
            id = id, name = inst.name,
            desc = string.format("A%d D%d M%d S%d", inst.atk, inst.def, inst.mag, inst.spd),
            count_str = equipped_mark .. (CLASS_ABBR[cls] or "?"),
            sprite = INST.sprites and INST.sprites[id] or nil,
            dim = false,
          }
        end
      end
    end
  elseif tab_idx == 3 then
    for _, id in ipairs(TROPHY_ORDER) do
      local info = TROPHY_INFO[id]
      local owned = has_trophy(id)
      rows[#rows + 1] = {
        id = id, name = info.name, desc = info.desc,
        count_str = owned and " *" or " -",
        sprite = (KEY_SPRITES and KEY_SPRITES[id]) or (INST.sprites and INST.sprites[id]) or nil,
        dim = not owned,
      }
    end
  else
    for _, name in ipairs(SHARD_ORDER) do
      local owned = shards[name] or false
      rows[#rows + 1] = {
        id = name, name = SHARD_DISPLAY[name] or name,
        desc = owned and "obtained" or "(not yet)",
        count_str = owned and " *" or " -",
        sprite = nil, dim = not owned,
      }
    end
  end
  return rows
end

UI.draw_items = function()
  screen.font_face(25); screen.font_size(6)
  -- Tabs row (y=0..9). Each tab is 32 px wide so 4 fit in 128 px.
  CONTENT.items_tab = math.max(1, math.min(#ITEM_TABS, CONTENT.items_tab or 1))
  local tab = CONTENT.items_tab
  for i, label in ipairs(ITEM_TABS) do
    local tx = (i - 1) * 32
    local sel = (i == tab)
    if sel then
      screen.level(15); screen.rect(tx, 0, 32, 9); screen.stroke()
      screen.level(15)
    else
      screen.level(6)
    end
    screen.move(tx + 16, 6); screen.text_center(label)
  end
  screen.level(3); screen.move(0, 10); screen.line(128, 10); screen.stroke()

  local rows = items_rows_for_tab(tab)
  CONTENT.items_idx = math.max(1, math.min(math.max(1, #rows), CONTENT.items_idx or 1))

  -- Scroll window: 5 rows visible (8 px each), then a full-width detail
  -- line for the selected row's description, then the footer. Names and
  -- trophy descriptions are too long to share a row, so the row shows
  -- only name + a right-aligned status marker; the desc lives on its
  -- own line where it has the full 128 px.
  local PAGE = 5
  local cur = CONTENT.items_idx
  local top = math.max(1, math.min(math.max(1, #rows - PAGE + 1), cur - math.floor(PAGE / 2)))
  for vis = 0, PAGE - 1 do
    local i = top + vis
    local r = rows[i]
    if not r then break end
    local y = 14 + vis * 8
    local is_sel = (i == cur)
    local lev_name = is_sel and 15 or (r.dim and 4 or 11)
    local lev_meta = is_sel and 13 or (r.dim and 4 or 6)
    screen.level(is_sel and 15 or 0)
    screen.move(2, y); screen.text(is_sel and ">" or " ")
    if r.sprite then r.sprite(8, y - 6) end
    screen.level(lev_name); screen.move(18, y); screen.text(r.name or "")
    -- status marker (count for USE, equip/owned mark elsewhere), right-aligned
    screen.level(lev_meta); screen.move(126, y); screen.text_right(r.count_str or "")
  end
  if #rows == 0 then
    screen.level(6); screen.move(64, 36); screen.text_center("(nothing yet)")
  end

  -- Detail line: full description of the selected row, full width at y=56.
  -- Truncated defensively so an over-long string can't run off-screen.
  do
    local sel = rows[cur]
    if sel and sel.desc and #sel.desc > 0 then
      local d = sel.desc
      if #d > 24 then d = d:sub(1, 24) .. ".." end
      screen.level(9); screen.move(2, 56); screen.text(d)
    end
  end

  -- Footer.
  screen.level(3); screen.move(0, 58); screen.line(128, 58); screen.stroke()
  screen.level(11); screen.move(2, 64); screen.text("Gold:")
  screen.level(15); screen.move(28, 64); screen.text(SHOP.gold .. "g")
  -- Pager lives on the desc row (y=56): the footer row can't fit gold +
  -- pager + a hint that names real keys (verified overlap at 128 px).
  if #rows > PAGE then
    screen.level(6); screen.move(126, 56)
    screen.text_right(cur .. "/" .. #rows)
  end
  screen.level(6); screen.move(126, 64)
  if tab == 1 then
    screen.text_right("K3 use  K2 back")
  elseif tab == 2 then
    screen.text_right("K3 equip  E3 tab")
  else
    screen.text_right("E3 tab  K2 back")
  end

  if (CONTENT.items_flash_ticks or 0) > 0 then
    local bw, bh = 110, 16
    local bx, by = (128 - bw) / 2, (64 - bh) / 2
    screen.level(0); screen.rect(bx, by, bw, bh); screen.fill()
    screen.level(15); screen.rect(bx, by, bw, bh); screen.stroke()
    screen.level(15); screen.move(64, by + 11)
    screen.text_center(CONTENT.items_flash or "")
  end
  screen.font_face(1); screen.font_size(8)
end

-- Build the dynamic STANDBY cell list shown in PARTYSEL's bottom half.
-- Cells are: every character in CHARACTERS not currently in `party`
-- (reserve, swappable), then any locked recruits (joined=false). Stable
-- order keeps the same character in the same cell across redraws.
function partysel_cells()
  local CLASS_ORDER = {mage=1, cleric=2, warrior=3, bard=4,
                       engineer=5, mathwiz=6, drummer=7}
  local cells = {}
  local in_party = {}
  for _, p in ipairs(party) do
    in_party[p.class] = true
    -- being in the party is proof of joining — self-heals saves that
    -- predate the ever_joined flag, so benching never hides a member
    p.ever_joined = true
  end
  local reserve = {}
  for cls, ch in pairs(CHARACTERS or {}) do
    if not in_party[cls] and ch.ever_joined then
      reserve[#reserve + 1] = cls
    end
  end
  table.sort(reserve, function(a, b)
    return (CLASS_ORDER[a] or 99) < (CLASS_ORDER[b] or 99)
  end)
  for _, cls in ipairs(reserve) do
    cells[#cells + 1] = {kind = "reserve", char = CHARACTERS[cls]}
  end
  for _, r in ipairs(CONTENT.recruits) do
    if not r.joined then
      cells[#cells + 1] = {kind = "locked", recruit = r}
    end
  end
  return cells
end

UI.draw_partysel = function()
  screen.font_face(25); screen.font_size(6)
  screen.level(15); screen.move(64, 7); screen.text_center("PARTY")
  screen.level(3); screen.move(0, 9); screen.line(128, 9); screen.stroke()

  -- ── ACTIVE PARTY (top half, y=11..37) — 4 cells, 32 wide each ──
  local saved_facing = player.facing
  player.facing = "down"
  for i, p in ipairs(party) do
    local cx = (i - 1) * 32
    local act = (i == active)
    if act then
      screen.level(2); screen.rect(cx, 11, 32, 26); screen.fill()
      screen.level(15); screen.rect(cx, 11, 32, 26); screen.stroke()
    end
    local fn = SPRITE_BY_CLASS[p.class]
    if fn then fn(cx + 12, 13) end
    screen.level(act and 15 or 11)
    screen.move(cx + 16, 28); screen.text_center(CHAR_NAME[p.class] or p.class)
    screen.level(p.alive and 11 or 4)
    screen.move(cx + 16, 35); screen.text_center("LV " .. (p.level or 1))
  end

  -- ── STANDBY (bottom half, y=39..57) — up to 3 dynamic cells ──
  -- Anyone NOT in the active party (recruits OR displaced starters) appears
  -- here automatically; locked recruits dim out at the end.
  screen.level(3); screen.move(0, 38); screen.line(128, 38); screen.stroke()
  screen.level(11); screen.move(2, 43); screen.text("STANDBY")

  local cells = partysel_cells()
  -- Clamp focus to the cell range (0 = no focus).
  if (CONTENT.partysel_focus or 0) > #cells then
    CONTENT.partysel_focus = 0
  end
  -- Scroll window: only 3 standby cells fit horizontally, but the roster
  -- can grow past 3 (4 recruits + displaced starters). Slide a scroll
  -- offset so the focused cell is always within the 3 drawn slots.
  local focus = CONTENT.partysel_focus or 0
  local scroll = CONTENT.partysel_scroll or 0
  scroll = math.min(scroll, math.max(0, #cells - 3))
  if focus > 0 then
    if focus <= scroll then scroll = focus - 1
    elseif focus > scroll + 3 then scroll = focus - 3 end
  end
  CONTENT.partysel_scroll = scroll
  for i = 1, 3 do
    local cell = cells[scroll + i]
    if not cell then break end
    local cx = (i - 1) * 43
    local focused = (focus == scroll + i)
    if focused then
      screen.level(2); screen.rect(cx, 45, 42, 13); screen.fill()
      screen.level(15); screen.rect(cx, 45, 42, 13); screen.stroke()
    end
    if cell.kind == "reserve" then
      local ch = cell.char
      local fn = SPRITE_BY_CLASS[ch.class]
      if fn then fn(cx + 2, 47) end
      screen.level(focused and 15 or 11)
      screen.move(cx + 12, 51); screen.text(CHAR_NAME[ch.class] or ch.class)
      screen.level(focused and 13 or 6)
      screen.move(cx + 12, 57); screen.text("LV " .. (ch.level or 1))
    else  -- locked
      local r = cell.recruit
      local fn = SPRITE_BY_CLASS[r.class]
      if fn then fn(cx + 2, 47) end
      screen.level(focused and 11 or 4)
      screen.move(cx + 12, 51); screen.text(CHAR_NAME[r.class] or r.class)
      screen.level(focused and 8 or 3)
      screen.move(cx + 12, 57); screen.text("(locked)")
    end
  end
  player.facing = saved_facing

  -- Footer (y=63 baseline; cells end at y=58 so glyphs at y=58..63 don't
  -- touch the cell borders).
  local focus_cell = cells[CONTENT.partysel_focus or 0]
  if focus_cell and focus_cell.kind == "reserve" then
    screen.level(11); screen.move(2, 63)
    screen.text("K3: " .. (CHAR_NAME[focus_cell.char.class] or focus_cell.char.class) .. " -> slot " .. active)
  elseif focus_cell and focus_cell.kind == "locked" then
    screen.level(8); screen.move(2, 63); screen.text("(not yet joined)")
  else
    screen.level(6); screen.move(2, 63); screen.text("L1/R1 slot  UD/E2 pick  B/K2 back")
  end
  screen.font_face(1); screen.font_size(8)
end

function redraw()
  screen.clear()
  screen.aa(0)
  -- Pass 53: screen shake — translate the entire frame by a small jittered
  -- offset for the duration of ANIM.shake_t. Reset at end of frame.
  local shake_dx, shake_dy = 0, 0
  if ANIM.shake_t > 0 then
    ANIM.shake_t = ANIM.shake_t - 1
    local m = ANIM.shake_mag
    shake_dx = math.random(-m, m)
    shake_dy = math.random(-m, m)
    screen.translate(shake_dx, shake_dy)
    if ANIM.shake_t == 0 then ANIM.shake_mag = 0 end
  end
  if game_state == "TITLE" then draw_title()
  elseif game_state == "CUTSCENE" then draw_cutscene()
  elseif game_state == "OVERWORLD" then draw_overworld()
  elseif game_state == "DIALOGUE" then draw_dialogue()
  elseif game_state == "BATTLE" then draw_battle()
  elseif game_state == "BATTLE_END" then draw_battle_end()
  elseif game_state == "GAME_OVER" then draw_game_over()
  elseif game_state == "MENU" then draw_menu()
  elseif game_state == "STATUS" then draw_status()
  elseif game_state == "EQUIP" then draw_equip()
  elseif game_state == "VOYAGE" then draw_voyage()
  elseif game_state == "ENDING" then draw_ending()
  elseif game_state == "SHOP" then draw_shop()
  elseif game_state == "JAM" then draw_jam()
  elseif game_state == "ITEMS" then UI.draw_items()
  elseif game_state == "QUESTS" then UI.draw_quests()
  elseif game_state == "MAP" then UI.draw_map()
  elseif game_state == "ACHIEVEMENTS" then UI.draw_achievements()
  elseif game_state == "BESTIARY" then UI.draw_bestiary()
  elseif game_state == "SHARDS" then UI.draw_shards()
  elseif game_state == "PARTYSEL" then UI.draw_partysel()
  elseif game_state == "CREDITS" then UI.draw_credits()
  end
  -- Pass 36: MIDI activity indicator. Tiny dot in the top-right corner
  -- that flickers when an event came in within the last few ticks.
  if (tick - (CONTENT.midi_active_t or -99)) < 6 then
    screen.level(15); screen.rect(125, 0, 3, 3); screen.fill()
    screen.level(8);  screen.pixel(124, 1); screen.fill()
  end
  -- (Pass 48 day/night stipple removed — the density math was inverted,
  --  flooding the screen with black pixels during transitions. If we
  --  bring this back later it should use a single 25%-coverage stipple
  --  pattern scaled by intensity instead of variable stride.)
  -- ── Pass 53 visual-effect overlays ───────────────────────────────────
  -- Particles: little expanding bursts. Lifespan ~12 ticks each.
  for i = #ANIM.particles, 1, -1 do
    local pcl = ANIM.particles[i]
    local age = tick - pcl.t
    local kind = pcl.kind or "spark"
    local dur  = pcl.dur or 12
    if age >= dur then
      table.remove(ANIM.particles, i)
    else
      if kind == "spark" then
        local px = math.floor(pcl.x + pcl.vx * age + 0.5)
        local py = math.floor(pcl.y + pcl.vy * age + 0.5)
        screen.level(math.max(2, pcl.lev - age))
        screen.pixel(px, py); screen.fill()
      elseif kind == "ghost_sprite" then
        -- Norns has no per-sprite brightness override, so we render a
        -- silhouette outline at the requested brightness — same shape as
        -- the 8x8 character sprite, dimmer over time.
        local b = math.max(2, (pcl.bright or 8) - math.floor(age / 2))
        screen.level(b)
        screen.rect(pcl.x, pcl.y, 8, 8); screen.stroke()
      elseif kind == "ring" then
        local r = (pcl.r0 or 1) + age
        if age >= 0 and r > 0 then
          screen.level(math.max(2, (pcl.lev or 15) - age))
          screen.circle(pcl.x, pcl.y, r); screen.stroke()
        end
      elseif kind == "mask_bar" then
        if age >= 0 then
          screen.level(math.max(2, (pcl.lev or 13) - age * 2))
          screen.rect(pcl.x, pcl.y, pcl.w or 6, pcl.h or 1); screen.fill()
        end
      elseif kind == "spring_line" then
        if age >= 0 then
          local x = math.floor(pcl.x + pcl.vx * age + 0.5)
          local y = math.floor(pcl.y + math.sin(age * 0.6) * 2 + 0.5)
          screen.level(math.max(2, (pcl.lev or 13) - age))
          screen.pixel(x, y); screen.fill()
        end
      elseif kind == "rotating_line" then
        if age >= 0 then
          local angle = age * (math.pi / 8)    -- ≈22.5° per tick
          local r = pcl.radius or 6
          local dx = math.cos(angle) * r
          local dy = math.sin(angle) * r
          screen.level(math.max(2, (pcl.lev or 13) - math.floor(age / 2)))
          screen.move(pcl.x - dx, pcl.y - dy)
          screen.line(pcl.x + dx, pcl.y + dy)
          screen.stroke()
        end
      end
    end
  end
  -- Footstep dust: 2 puff pixels behind player, fading. Lifespan ~10 ticks.
  for i = #ANIM.dust, 1, -1 do
    local d = ANIM.dust[i]
    local age = tick - d.t
    if age >= 10 then
      table.remove(ANIM.dust, i)
    else
      screen.level(math.max(2, 9 - age))
      screen.pixel(d.x - 1, d.y); screen.pixel(d.x + 1, d.y); screen.fill()
    end
  end
  -- Hit flash: invert all pixels for 1 frame. We approximate by drawing a
  -- bright translucent overlay (norns has no real invert; use level-15
  -- stipple). Triggered by ANIM.flash_hit().
  if (tick - ANIM.hit_flash_t) < 2 then
    screen.level(15)
    for y = 0, 63, 2 do
      for x = 0, 127, 2 do screen.pixel(x, y) end
    end
    screen.fill()
  end
  -- Critical-HP vignette: pulsing dark frame when ANY alive party member
  -- is below 25% HP during BATTLE.
  if game_state == "BATTLE" then
    local critical = false
    for _, p in ipairs(party) do
      if p.alive and p.hp_max > 0 and p.hp <= p.hp_max / 4 then critical = true; break end
    end
    -- (The old critical-HP full-edge border here fought draw_battle's
    -- corner accents — two vignettes at different blink rates repainting
    -- the same rows read as flicker. draw_battle's version stays.)
  end
  -- Story/gate/pickup banner — drawn here (not per-state) so it shows
  -- in every gameplay state; previously battle-only, which made every
  -- overworld banner invisible. Under the scene fade by design.
  if CONTENT.banner_ticks > 0
     and (game_state == "OVERWORLD" or game_state == "DIALOGUE"
          or game_state == "BATTLE" or game_state == "BATTLE_END") then
    screen.level(0); screen.rect(4, 18, 120, 12); screen.fill()
    screen.level(15); screen.rect(4, 18, 120, 12); screen.stroke()
    screen.font_face(25); screen.font_size(6)
    screen.move(64, 26); screen.text_center(scrub_text(CONTENT.banner_text or ""))
    screen.font_face(1); screen.font_size(8)
  end
  -- Level-up flash — same treatment (level-ups happen outside battle;
  -- its old only-in-draw_battle site never showed them).
  if levelup_flash_ticks > 0
     and (game_state == "OVERWORLD" or game_state == "DIALOGUE"
          or game_state == "BATTLE") then
    screen.level(0); screen.rect(40, 11, 48, 8); screen.fill()
    screen.level(15); screen.rect(40, 11, 48, 8); screen.stroke()
    screen.font_face(25); screen.font_size(6)
    screen.move(64, 17); screen.text_center((levelup_flash_who or "LEVEL") .. " UP!")
    screen.font_face(1); screen.font_size(8)
  end
  -- Save/load flash — visible outside the menu too ("Game Loaded" on
  -- Continue, autosave toasts; previously drawn only by draw_menu).
  if save_flash_ticks > 0 and game_state ~= "MENU" and game_state ~= "TITLE" then
    screen.font_face(25); screen.font_size(6)
    screen.level(12); screen.move(64, 8); screen.text_center(save_flash_text or "")
    screen.font_face(1); screen.font_size(8)
  end
  -- Scene fade overlay (covers HUD too — drawn last). No-op when fade==0.
  -- Letterbox bars sit ABOVE the world but BELOW the fade overlay,
  -- so a fade-to-black still covers them.
  if SCENE and SCENE.draw_letterbox then SCENE.draw_letterbox() end
  if SCENE and SCENE.draw_fade then SCENE.draw_fade() end
  -- (Weather particles moved into draw_overworld so they render UNDER
  -- dialogue boxes and scene fades instead of on top of them.)
  -- Reset shake translate so the next frame starts clean.
  if shake_dx ~= 0 or shake_dy ~= 0 then
    screen.translate(-shake_dx, -shake_dy)
  end
  screen.update()
end
